  `file` varchar(255) NOT NULL,
  `type` varchar(50) DEFAULT NULL,
  `size` int(10) unsigned NOT NULL DEFAULT '0',
  `createdon` datetime DEFAULT NULL,
  `createdby` int(10) unsigned NOT NULL DEFAULT '0',
  `url` varchar(255) NOT NULL,
  `thumb` varchar(255) NOT NULL,
  `thumbs` text,
  `deleted` tinyint(1) DEFAULT '0',
  `properties` text,
  `hash` char(40) DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Структура таблицы `modx_tickets_mail_queues`
--

CREATE TABLE IF NOT EXISTS `modx_tickets_mail_queues` (
  `id` int(10) unsigned NOT NULL,
  `timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `uid` int(10) unsigned NOT NULL DEFAULT '0',
  `subject` varchar(255) DEFAULT '',
  `body` text,
  `email` varchar(255) DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Структура таблицы `modx_tickets_stars`
--

CREATE TABLE IF NOT EXISTS `modx_tickets_stars` (
  `id` int(10) unsigned NOT NULL DEFAULT '0',
  `class` varchar(100) NOT NULL DEFAULT 'Ticket',
  `owner` int(10) unsigned NOT NULL DEFAULT '0',
  `createdon` datetime DEFAULT NULL,
  `createdby` int(10) unsigned NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Структура таблицы `modx_tickets_threads`
--

CREATE TABLE IF NOT EXISTS `modx_tickets_threads` (
  `id` int(10) unsigned NOT NULL,
  `resource` int(10) unsigned NOT NULL DEFAULT '0',
  `name` varchar(255) NOT NULL DEFAULT '',
  `subscribers` text NOT NULL,
  `createdon` datetime DEFAULT NULL,
  `createdby` int(10) unsigned NOT NULL DEFAULT '0',
  `closed` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `deleted` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `deletedon` datetime DEFAULT NULL,
  `deletedby` int(10) unsigned NOT NULL DEFAULT '0',
  `comment_last` int(10) unsigned NOT NULL DEFAULT '0',
  `comment_time` datetime DEFAULT NULL,
  `comments` int(10) unsigned DEFAULT '0',
  `properties` text
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;

--
-- Дамп данных таблицы `modx_tickets_threads`
--


-- --------------------------------------------------------

--
-- Структура таблицы `modx_tickets_totals`
--

CREATE TABLE IF NOT EXISTS `modx_tickets_totals` (
  `id` int(10) unsigned NOT NULL,
  `class` varchar(100) NOT NULL,
  `tickets` int(10) unsigned DEFAULT '0',
  `comments` int(10) unsigned DEFAULT '0',
  `views` int(10) unsigned DEFAULT '0',
  `stars` int(10) unsigned DEFAULT '0',
  `rating` smallint(5) DEFAULT '0',
  `rating_plus` smallint(5) unsigned DEFAULT '0',
  `rating_minus` smallint(5) unsigned DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Структура таблицы `modx_tickets_views`
--

CREATE TABLE IF NOT EXISTS `modx_tickets_views` (
  `parent` int(10) unsigned NOT NULL DEFAULT '0',
  `uid` int(10) unsigned NOT NULL DEFAULT '0',
  `guest_key` char(32) NOT NULL DEFAULT '',
  `timestamp` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Структура таблицы `modx_tickets_votes`
--

CREATE TABLE IF NOT EXISTS `modx_tickets_votes` (
  `id` int(10) unsigned NOT NULL DEFAULT '0',
  `class` varchar(100) NOT NULL,
  `owner` int(10) unsigned NOT NULL DEFAULT '0',
  `value` tinyint(1) NOT NULL DEFAULT '0',
  `createdon` datetime DEFAULT NULL,
  `createdby` int(10) unsigned NOT NULL DEFAULT '0',
  `ip` varchar(16) DEFAULT '0.0.0.0'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Структура таблицы `modx_transport_packages`
--

CREATE TABLE IF NOT EXISTS `modx_transport_packages` (
  `signature` varchar(255) NOT NULL,
  `created` datetime NOT NULL,
  `updated` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `installed` datetime DEFAULT NULL,
  `state` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `workspace` int(10) unsigned NOT NULL,
  `provider` int(10) unsigned NOT NULL,
  `disabled` tinyint(1) unsigned NOT NULL,
  `source` tinytext,
  `manifest` text,
  `attributes` mediumtext,
  `package_name` varchar(255) NOT NULL,
  `metadata` text,
  `version_major` smallint(5) unsigned NOT NULL,
  `version_minor` smallint(5) unsigned NOT NULL,
  `version_patch` smallint(5) unsigned NOT NULL,
  `release` varchar(100) NOT NULL,
  `release_index` smallint(5) unsigned NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

--
-- Дамп данных таблицы `modx_transport_packages`
--

