(36, 'document', 'text/html', 'Поиск по каталогу', '', '', 'catsearch', '', 1, 0, 0, 0, 1, '', '<div class="goods-list box inline">\r\n    [[!catSearch?\r\n        &elementClass=`modSnippet`\r\n        &element=`getResources`\r\n        &parents=`14`\r\n        &tpl=`product-search`\r\n        &tplid=`4`\r\n        &cattplid=`3`\r\n        &includeTVs=`1`\r\n        &includeTVList=`image,price,size`\r\n        &processTVs=`1`\r\n        &sortby=`menuindex`\r\n        &sortdir=`ASC`\r\n        &pageVarKey=`page`\r\n        &toPlaceholder=`search-result`\r\n        &tplPageWrapper=`@INLINE <ul class="pagination">[[+first]][[+prev]][[+pages]][[+next]][[+last]]</ul>`\r\n    ]]\r\n    [[+search-result:default=`По вашему запросу ничего не найдено. Попробуйте ввести похожие по смыслу слова, чтобы получить лучший результат.`]]\r\n</div>\r\n[[+page.nav]]', 0, 1, 19, 1, 1, 1, 1420807941, 1, 1475071365, 0, 0, 0, 1420807920, 1, '', 0, 0, 0, 0, 1, 'modDocument', 'web', 1, 'catsearch/', 0, 0, 1, ''),
