(237, 'document', 'text/html', 'Новый отзыв от ALI VELIYEV от 30.10.2018 - 03:41', '', '', '', '', 0, 0, 0, 21, 0, NULL, NULL, 1, 10, 0, 0, 1, 0, 1540860116, 0, 0, 0, 0, 0, 1540860116, 0, '', 0, 0, 0, 0, 1, 'modDocument', 'web', 1, 'replies/novyij-otzyiv-ot-ali-veliyev-ot-30.10.2018-0341/', 0, 0, 0, NULL),
