$(tabs).children("ul").children("li").eq(i).addClass("active");\n    			}\n    								\n    			showPage(0);				\n    			\n    			$(tabs).children("ul").children("li").each(function(index, element){\n    				$(element).attr("data-page", i);\n    				i++;                        \n    			});\n    			\n    			$(tabs).children("ul").children("li").click(function(){\n    				showPage(parseInt($(this).attr("data-page")));\n    			});				\n    		};		\n    		return this.each(createTabs);\n    	};	\n    })(jQuery);\n    \n    $(".tabs").lightTabs();\n    \n    $(''.slick-slider'').slick({autoplay: true, speed: 800, autoplaySpeed: 5000, fade: true, appendArrows: $(''.arrows .wrapper'')});\n});\n$(document).ready(function(){\n\n		$(''form.cleaning'').on(''submit'', function(e){\n\n			e.preventDefault();\n\n			$.ajax({\n				url: "[[!++site_url]]save_mail.php",\n				type: "POST",\n				data:  $(this).serialize(),\n				success: function(success){\n				    alert(''Спасибо, скоро с вами свяжется наш менеджер!'');	\n				},\n				error: function(error){\n					alert(''Ошибка, попробуйте еще раз, или позвоните нам!'');\n				}\n\n			});\n			\n		});\n\n	});\n\n\n\n\n</script>\n<script>// jQuery Mask Plugin v1.14.15\n// github.com/igorescobar/jQuery-Mask-Plugin\nvar $jscomp={scope:{},findInternal:function(a,l,d){a instanceof String&&(a=String(a));for(var p=a.length,h=0;h<p;h++){var b=a[h];if(l.call(d,b,h,a))return{i:h,v:b}}return{i:-1,v:void 0}}};$jscomp.defineProperty="function"==typeof Object.defineProperties?Object.defineProperty:function(a,l,d){if(d.get||d.set)throw new TypeError("ES3 does not support getters and setters.");a!=Array.prototype&&a!=Object.prototype&&(a[l]=d.value)};\n$jscomp.getGlobal=function(a){return"undefined"!=typeof window&&window===a?a:"undefined"!=typeof global&&null!=global?global:a};$jscomp.global=$jscomp.getGlobal(this);$jscomp.polyfill=function(a,l,d,p){if(l){d=$jscomp.global;a=a.split(".");for(p=0;p<a.length-1;p++){var h=a[p];h in d||(d[h]={});d=d[h]}a=a[a.le