(114, 2, 0, 'scripts-system', '', 0, 12, 0, '$(''.zoom'').magnificPopup({\n    type:''image'',\n    image: {\n        titleSrc: ''title''\n    }\n});\n$(''.zoom-gal'').magnificPopup({\n    type:''image'',\n    gallery: {enabled: true},\n    image: {\n        titleSrc: ''title''\n    }\n});\n$(''.modal-window'').magnificPopup({\n    type:''inline''\n});\n$.extend(true, $.magnificPopup.defaults, { // перевод для magnific-popup\n    tClose: ''Закрыть (Esc)'', // Alt text on close button\n    tLoading: ''Загрузка...'', // Text that is displayed during loading. Can contain %curr% and %total% keys\n    gallery: {\n        tPrev: ''Предыдущий'', // Alt text on left arrow\n        tNext: ''Следующий'', // Alt text on right arrow\n        tCounter: ''%curr% из %total%'' // Markup for "1 of 7" counter\n    },\n    image: {\n        tError: ''Не удалось загрузить <a href="%url%">изображение</a>.'' // Error message when image could not be loaded\n    },\n    ajax: {\n        tError: ''Не удалось загрузить <a href="%url%">содержимое</a>.'' // Error message when ajax request failed\n    }\n});\n', 0, 'a:0:{}', 0, ''),
(169, 0, 0, 'tplHead2', 'Header for calendars table.', 0, 56, 0, '<tr>\r\n	<td class="[[+ec.class_prev]]"><a href="[[+ec.link_prev]]">&larr;</a></td>\r\n	<td class="[[+ec.class_month]]" colspan="5" style="text-align:center;"><strong>[[+ec.month_name]] [[+ec.year]]</strong></td>\r\n	<td class="[[+ec.class_next]]"><a href="[[+ec.link_next]]">&rarr;</a></td>\r\n</tr>', 0, NULL, 0, ''),
(170, 0, 0, 'tplCell2', 'Chunk for table cell.', 0, 56, 0, '<td class="cell [[+ec.class]]" id="[[+ec.cell_id]]" data-fulldate="[[+ec.fulldate]]">\n	<div class="[[+ec.class_date]]">[[+ec.day]]</div>\n	<div class="[[+ec.class_event]]">[[+ec.events]]</div>\n</td>', 0, NULL, 0, ''),
(8, 0, 0, 'news-archive-list', 'Вывод архива новостей', 0, 13, 0, '[[!pdoPage? \n&elementClass=`modSnippet`\n&element=`pdoResources`\n&cache=`1`\n&parents=`[[*id]]`\n&limit=`10`\n&showHidden=`1`\n&includeTVs=`1`\n&includeTVList=`image`\n&tpl=`news-pre`\n&hideContainers =`1`\n&sortby=`publishedon`\n&sortdir=`DESC`\n&pageVarKey=`page`\n&toPlaceholder=`newsArchiveList`\n&tplPageWrapper=`@INLINE <div class="pagination"><ul>[[+first]][[+prev]][[+pages]][[+next]][[+last]]</ul></div>`\n]]\n[[+newsArchiveList:default=`<p>Архив пуст</p>`]]\n[[+page.nav]]', 0, 'a:0:{}', 0, ''),
(9, 0, 0, 'news-block', '', 0, 13, 0, '<div class="news-item">\n	[[+tv.image:ne=`/userfiles/images/no-photo.png`:and:ne=``:then=`\n	    <div class="leftimg">\n	        <a href="[[~[[+id]]]]" title="[[+pagetitle]]">\n	            <img src="[[phpthumbof? &input=`[[+tv.image]]` &options=`w=80&h=80&zc=1&fltr[]=size`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]">\n            </a>\n        </div>\n    `]]\n	<span class="date">[[+publishedon:date=`%d.%m.%Y`]]</span>\n	<h3>[[+pagetitle]]</h3>\n	<p>[[+introtext:nl2br]]</p>\n	<p><a class="readmore" href="[[~[[+id]]]]" title="[[+pagetitle:replace=`"==''`]]">читать полностью</a></p>\n</div>', 0, 'a:0:{}', 0, ''),
(10, 0, 0, 'news-list', 'Список новостей на странице "Новости"', 0, 13, 0, '[[!pdoPage? \n&elementClass=`modSnippet`\n&element=`pdoResources`\n&cache=`1`\n&parents=`[[*id]]` \n&limit=`10`\n&depth=`0`\n&includeTVs=`image`\n&tpl=`news-pre` \n&hideContainers =`1` \n&sortby=`publishedon` \n&sortdir=`DESC`\n&pageVarKey=`page`\n&toPlaceholder=`newsList`\n&tplPageWrapper=`@INLINE <div class="pagination"><ul>[[+first]][[+prev]][[+pages]][[+next]][[+last]]</ul></div>`\n]]\n[[+newsList:default=`<p>Раздел находится в стадии заполнения. Приносим свои извинения за возможные неудобства.</p>`]]\n[[+page.nav]]\n<div class="hr"></div>\n<p><a href="[[~9]]">Архив новостей</a></p>', 0, 'a:0:{}', 0, ''),
(11, 0, 0, 'news-pre', '', 0, 13, 0, '<div class="news_full_item">\r\n    [[+tv.image:ne=`/userfiles/images/no-photo.png`:and:ne=``:then=`\r\n        <div class="leftimg">\r\n            <a href="[[~[[+id]]]]" title="[[+pagetitle]]">\r\n                <img src="[[phpthumbof? &input=`[[+tv.image]]` &options=`w=200&h=130&zc=1&fltr[]=size`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]">\r\n            </a>\r\n        </div>\r\n    `]]\r\n    <p class="news_full_date"><i class="fa fa-calendar-o"></i> [[+publishedon:date=`%d.%m.%Y`]]</p>\r\n    <p class="news_full_title"><a href="[[~[[+id]]]]" title="[[+pagetitle:replace=`"==''`]]">[[+pagetitle]]</a></p>\r\n    <p>[[+introtext:nl2br]]</p>\r\n    <div class="clear"></div>\r\n</div>', 0, 'a:0:{}', 0, '');
INSERT INTO `modx_site_htmlsnippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `static`, `static_file`) VALUES
(18, 2, 0, 'category', '', 0, 17, 0, '<div class="sgrid-4">\n    <div class="category-s-item">\n        <div class="category-s-img">\n    	    [[+tv.image:ne=`/userfiles/images/no-photo.png`:and:ne=``:then=`\n    	        <a href="[[~[[+id]]]]" title="[[+pagetitle]]">\n    	            <img src="[[phpthumbof? &input=`[[+tv.image]]` &options=`w=270&h=270&zc=1&fltr[]=size`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]">\n                </a>\n            `]]\n        </div>\n    	<div class="category-s-title">\n    	    <a href="[[~[[+id]]]]" title="[[+pagetitle]]"><span>[[+pagetitle]]</span></a>\n    	</div>\n    </div>\n</div>', 0, 'a:0:{}', 0, ''),
(19, 2, 0, 'product', '', 0, 17, 0, '<div class="sgrid-4">\n    <div class="category-item-inner">\n        <div class="category-img">\n    	    [[+tv.image:ne=`/userfiles/images/no-photo.png`:and:ne=``:then=`\n    	        <a href="[[~[[+id]]]]" title="[[+pagetitle]]">\n    	            <img src="[[phpthumbof? &input=`[[+tv.image]]` &options=`w=120&h=120&zc=1`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]">\n                </a>\n            `]]\n        </div>\n    	<div class="category-title">\n    	    <a href="[[~[[+id]]]]" title="[[+pagetitle]]"><span>[[+pagetitle]]</span></a>\n    	</div>\n    </div>\n</div>\n\n[[-\n<div class="sgrid-4">\n    <div class="goods-list__item">\n        <div class="goods__image">\n            <a href="[[~[[+id]]]]" title="[[+pagetitle]]">\n                <img src="[[phpthumbof? &input=`[[+tv.image]]` &options=`w=270&h=223&zc=1&fltr[]=size`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]">                \n            </a>\n        </div>\n        <div class="goods-title">\n            <a href="[[~[[+id]]]]" title="[[+pagetitle]]">[[+pagetitle]]</a>\n        </div>\n        <div class="goods-intro">\n            [[+introtext]]\n        </div>\n        [[+tv.price:ne=``:then=`\n            <div class="goods__price">\n                    <span class="goods__price-now">[[+tv.price]]</span>\n            </div>\n        `]]\n    </div>\n</div>\n]]', 0, 'a:0:{}', 0, ''),
(20, 2, 0, 'FaqForm', '', 0, 11, 0, '<form class="form form-half" action="[[~[[*id]]]]" method="post">\n    <input type="hidden" name="nospam:blank" value="" />\n    \n    <div class="form-group">\n        <label for="name"> Ваше имя<span class="error">*</span>: <span class="error">[[!+fi.error.name]]</span> </label> \n        <input id="name" type="text" class="itext" name="name" value="[[!+fi.name]]" required placeholder="Ваше имя*"/>\n    </div>\n    <div class="form-group">\n        <label for="email"> E-mail<span class="error">*</span>: <span class="error">[[!+fi.error.email]]</span> </label> \n        <input id="email" type="email" class="itext" name="email" value="[[!+fi.email]]" required placeholder="E-mail*"/>\n    </div>\n    <div class="form-group">\n        <label for="text"> Ваш отзыв<span class="error">*</span>: <span class="error">[[!+fi.error.text]]</span> </label> \n        <textarea id="text" name="text" rows="4" cols="55" required placeholder="Ваш отзыв*">[[!+fi.text]]</textarea>\n    </div>\n    <div class="form-buttons">\n        <p><small>* Поля, обязательные для заполнения</small></p>\n        <input type="submit" onclick="yaCounter44950984.reachGoal(''ADD2''); return true;" class="isubmit button" value="Отправить" />\n    </div>\n   \n</form>', 0, 'a:0:{}', 0, ''),
(21, 2, 0, 'FaqTpl', '', 0, 11, 0, '<article class="view-list__item">\r\n    <blockquote class="view-text">\r\n        \r\n        <div class="view__info">\r\n                <cite class="view-author">[[+longtitle]]</cite>\r\n        </div>\r\n\r\n        <article class="view__answer message message--custom">\r\n            <q class="view__answer-text">[[+introtext]]</q>\r\n        </article>\r\n        \r\n        <div class="view-text-question">[[+content]]</div>\r\n    </blockquote>\r\n</article>', 0, 'a:0:{}', 0, ''),
(22, 0, 0, 'lgnLoginTpl', '', 0, 19, 0, '<div class="loginForm">\n    <div class="loginMessage">[[+errors]]</div>\n    <div class="loginLogin">\n        <form class="loginLoginForm" action="[[~[[*id]]]]" method="post">\n            <fieldset class="loginLoginFieldset">\n                <legend class="loginLegend">[[+actionMsg]]</legend>\n                <label class="loginUsernameLabel">[[%login.username]]\n                    <input class="loginUsername" type="text" name="username" required/>\n                </label>\n                \n                <label class="loginPasswordLabel">[[%login.password]]\n                    <input class="loginPassword" type="password" name="password" required/>\n                </label>\n                <input class="returnUrl" type="hidden" name="returnUrl" value="[[+request_uri]]" />\n\n                [[+login.recaptcha_html]]\n                \n                <input class="loginLoginValue" type="hidden" name="service" value="login" />\n                <span class="loginLoginButton"><input type="submit" name="Login" value="[[+actionMsg]]" /></span>\n            </fieldset>\n        </form>\n    </div>\n</div>', 0, 'a:0:{}', 0, ''),
(23, 0, 0, 'lgnLogoutTpl', '', 0, 19, 0, '<div class="loginMessage">[[+errors]]</div>\n<br />\n<div class="loginLogin">\n    <div class="loginRegister">\n        <a href="[[+logoutUrl]]" title="[[+actionMsg]]">[[+actionMsg]]</a>\n    </div>\n</div>', 0, 'a:0:{}', 0, ''),
(24, 0, 0, 'lgnErrTpl', '', 0, 19, 0, '<p class="error">[[+msg]]</p>', 0, 'a:0:{}', 0, ''),
(25, 0, 0, 'lgnForgotPassEmail', '', 0, 19, 0, '<p>[[+username]],</p>\n\n<p>Для активации вашего нового пароля, перейдите по ссылке:</p>\n\n<p><a href="[[+confirmUrl]]">[[+confirmUrl]]</a></p>\n\n<p>После этого вы сможете использовать для входа следующий пароль:</p>\n\n<p><strong>Пароль:</strong> [[+password]]</p>\n\n<p>Если вы не запрашивали данного письма, игнорируйте его.</p>\n\n<hr>\n\n<p>[[++site_name]]</p>', 0, 'a:0:{}', 0, ''),
(123, 0, 0, 'lgnRegisterFormTpl', '', 0, 19, 0, '<div class="register">\n    <div class="registerMessage">[[+error.message]]</div>\n    \n    <form class="form" action="[[~[[*id]]]]" method="post">\n        <input type="hidden" name="nospam:blank" value="" />\n        \n        <label for="username">[[%register.username? &namespace=`login` &topic=`register`]]\n            <span class="error">[[+error.username]]</span>\n        </label>\n        <input type="text" name="username:required:minLength=6" id="username" value="[[+username]]" />\n        \n        <label for="password">[[%register.password]]\n            <span class="error">[[+error.password]]</span>\n        </label>\n        <input type="password" name="password:required:minLength=6" id="password" value="[[+password]]" />\n        \n        <label for="password_confirm">[[%register.password_confirm]]\n            <span class="error">[[+error.password_confirm]]</span>\n        </label>\n        <input type="password" name="password_confirm:password_confirm=`password`" id="password_confirm" value="[[+password_confirm]]" />\n        \n        <label for="fullname">[[%register.fullname]]\n            <span class="error">[[+error.fullname]]</span>\n        </label>\n        <input type="text" name="fullname:required" id="fullname" value="[[+fullname]]" />\n        \n        <label for="email">[[%register.email]]\n            <span class="error">[[+error.email]]</span>\n        </label>\n        <input type="text" name="email:email" id="email" value="[[+email]]" />\n        \n        <br class="clear" />\n\n        [[+register.recaptcha_html]]\n        [[+error.recaptcha]]\n        \n        <div class="form-buttons">\n            <input type="submit" name="login-register-btn" value="Register" />\n        </div>\n    </form>\n</div>', 0, 'a:0:{}', 0, ''),
(26, 0, 0, 'lgnForgotPassSentTpl', '', 0, 19, 0, '<h2>Данные авторизации были отправлены</h2>\n\n<p>Ваши данные авторизации были отправлены на следующий адрес: [[+email]].</p>', 0, 'a:0:{}', 0, ''),
(27, 0, 0, 'lgnForgotPassTpl', '', 0, 19, 0, '<div class="loginFPErrors">[[+loginfp.errors]]</div>\n<div class="loginFP">\n    <form class="loginFPForm" action="[[~[[*id]]]]" method="post">\n        <fieldset class="loginFPFieldset">\n            <legend class="loginFPLegend">[[%login.forgot_password]]</legend>\n            <label class="loginFPUsernameLabel">[[%login.username]]\n                <input class="loginFPUsername" type="text" name="username" value="[[+loginfp.post.username]]" />\n            </label>\n            \n            <p>[[%login.or_forgot_username]]</p>\n            \n            <label class="loginFPEmailLabel">[[%login.email]]\n                <input class="loginFPEmail" type="text" name="email" value="[[+loginfp.post.email]]" />\n            </label>\n            \n            <input class="returnUrl" type="hidden" name="returnUrl" value="[[+loginfp.request_uri]]" />\n            \n            <input class="loginFPService" type="hidden" name="login_fp_service" value="forgotpassword" />\n            <span class="loginFPButton"><input type="submit" name="login_fp" value="[[%login.reset_password]]" /></span>\n        </fieldset>\n    </form>\n</div>', 0, 'a:0:{}', 0, ''),
(28, 0, 0, 'lgnResetPassTpl', '', 0, 19, 0, '<div class="loginResetPass">\n<p class="loginResetPassHeader">[[+username]],</p>\n\n<p class="loginResetPassText">Ваш пароль сброшен. Вы можете вернуться на <a href="[[+loginUrl]]">страницу входа</a>.</p>  \n</div>', 0, 'a:0:{}', 0, ''),
(29, 0, 0, 'lgnRegisterForm', '', 0, 19, 0, '<div class="register">\n    <div class="registerMessage">[[+error.message]]</div>\n    \n    <form class="form" action="[[~[[*id]]]]" method="post">\n        <input type="hidden" name="nospam:blank" value="" />\n        \n        <label for="username">[[%register.username? &namespace=`login` &topic=`register`]]\n            <span class="error">[[+error.username]]</span>\n        </label>\n        <input type="text" name="username:required:minLength=6" id="username" value="[[+username]]" />\n        \n        <label for="password">[[%register.password]]\n            <span class="error">[[+error.password]]</span>\n        </label>\n        <input type="password" name="password:required:minLength=6" id="password" value="[[+password]]" />\n        \n        <label for="password_confirm">[[%register.password_confirm]]\n            <span class="error">[[+error.password_confirm]]</span>\n        </label>\n        <input type="password" name="password_confirm:password_confirm=`password`" id="password_confirm" value="[[+password_confirm]]" />\n        \n        <label for="fullname">[[%register.fullname]]\n            <span class="error">[[+error.fullname]]</span>\n        </label>\n        <input type="text" name="fullname:required" id="fullname" value="[[+fullname]]" />\n        \n        <label for="email">[[%register.email]]\n            <span class="error">[[+error.email]]</span>\n        </label>\n        <input type="text" name="email:email" id="email" value="[[+email]]" />\n        \n        <br class="clear" />\n\n        [[+register.recaptcha_html]]\n        [[+error.recaptcha]]\n        \n        <div class="form-buttons">\n            <input type="submit" name="login-register-btn" value="Register" />\n        </div>\n    </form>\n</div>', 0, '', 0, ''),
(30, 0, 0, 'lgnActivateEmailTpl', '', 0, 19, 0, '<p>[[+username]],</p>\n\n<p>Спасибо за регистрацию на сайте <b>[[++site_name]]</b>! Для активации аккаунта, перейдите по следующей ссылке:</p>\n\n<p><a href="[[+confirmUrl]]">[[+confirmUrl]]</a></p>\n\n<p>После активации, вы сможете войти со следующими данными:</p>\n\n<p>\nИмя пользователя: <strong>[[+username]]</strong><br />\nПароль: <strong>[[+password]]</strong>\n</p>\n\n<p>Если вы не регистрировались на сайте <b>[[++site_name]]</b>, игнорируйте это письмо.</p>\n', 0, 'a:0:{}', 0, ''),
(31, 0, 0, 'lgnActiveUser', '', 0, 19, 0, '<li>[[+username]]</li>', 0, 'a:0:{}', 0, ''),
(32, 0, 0, 'lgnResetPassChangePassTpl', '', 0, 19, 0, '[[!+logcp.error_message:notempty=`<p style="color: red;">[[+logcp.error_message]]</p>`]]\n\n<form class="form inline" action="" method="post">\n    <input type="hidden" name="nospam:blank" value="" />\n\n    <div class="ff">\n        <label for="password_new">[[!%login.password_new]]\n            <span class="error">[[+logcp.error.password_new]]</span>\n        </label>\n        <input type="password" name="password_new:required" id="password_new" value="[[+logcp.password_new]]" />\n    </div>\n\n    <div class="ff">\n        <label for="password_new_confirm">[[!%login.password_new_confirm]]\n            <span class="error">[[+logcp.error.password_new_confirm]]</span>\n        </label>\n        <input type="password" name="password_new_confirm:required" id="password_new_confirm" value="[[+logcp.password_new_confirm]]" />\n    </div>\n\n    <br class="clear" />\n\n    <div class="form-buttons">\n        <input type="submit" name="logcp-submit" value="[[!%login.change_password]]" />\n    </div>\n</form>', 0, 'a:0:{}', 0, ''),
(33, 0, 0, 'lgnExpiredTpl', '', 0, 19, 0, '<p><strong>Информация о сбросе пароля</strong></p>\n<p>Ваш пароль уже был сброшен, либо ссылка недействительна. Если вам необходимо снова сбросить пароль, нажмите <a href="#">здесь</a>.</p>', 0, 'a:0:{}', 0, ''),
(47, 1, 0, 'shopOrderReport', '', 0, 22, 0, '<p><b>[[++site_name]]</b></p>\n\n<p>В интернет-магазине сделан заказ.</p>\n\n<div style="padding:15px 0; margin:15px 0; border-top:3px solid #BCBCBC; border-bottom:3px solid #BCBCBC;">\n\n    <p>Номер заказа: <b>[[+orderID]]</b> от <b>[[+orderDate]]</b></p>\n    \n    [[+orderOutputData]]\n\n</div>\n\n<table cellpadding="10" border="1">\n    <thead style="background: #ddd;">\n        <tr>\n            <th colspan="2">\n                <b>Данные покупателя:</b>\n            </th>\n        </tr>\n    </thead>\n    <tr>\n        <td>Адрес:</td>\n        <td>[[+address]]</td>\n    </tr>\n    <tr>\n        <td>Способ доставки:</td>\n        <td>[[+shk_delivery]]</td>\n    </tr>\n    <tr><td>Ф.И.О.:</td><td>[[+fullname]]</td></tr>\n    <tr><td>Адрес эл. почты:</td><td><a href="mailto:[[+email]]">[[+email]]</a></td></tr>\n    <tr><td>Телефон:</td><td>[[+phone]]</td></tr>\n    <tr><td>Комментарий:</td><td>[[+message]]</td></tr>\n</table>\n\n<p><a href="[[++site_url]]" target="_blank">[[++site_url]]</a></p>', 0, 'a:0:{}', 0, ''),
(94, 1, 0, 'userMail', '', 0, 22, 0, '<!DOCTYPE html>\n<html>\n\n<head>\n<style type="text/css">\nbody{background-color:#fff;}\ntable {width:650px; margin:10px 0; border:1px solid #BCBCBC; border-collapse:collapse;}\ntable td {padding:5px; border:1px solid #BCBCBC;}\n</style>\n</head>\n\n<body>\n\n<p><b>[[++site_name]]</b></p>\n\n<p>Изменен статус заказа.</p>\n\n<div style="padding:15px 0; margin:15px 0; border-top:3px solid #BCBCBC; border-bottom:3px solid #BCBCBC;">\n\n    <p>Номер заказа: [[+orderID]]</p>\n    \n    <p>Дата: [[+orderDate]].</p>\n    \n    <p>Ваш заказ переведен в статус: <b>[[+statusName]]</b>.</p>\n    \n    [[+orderOutputData]]\n\n</div>\n\n<a href="[[++site_url]]" target="_blank">[[++site_url]]</a>\n\n<br /><br />\n\n</body>\n</html>', 0, NULL, 0, ''),
(53, 2, 0, 'tagFilters', '', 0, 17, 0, '[[tmFilters?\n&filterOuterTpl=`tm2_filterOuterTpl`\n&filterTpl=`tm2_filterTpl`\n&filterNumericOuterTpl=`tm2_filterOuterTpl`\n&filterNumericTpl=`tm2_filterNumericTpl`\n&jsMap=`1`\n&toPlaceholder=`filters`\n]]\n<div id="filters">\n    <form action="[[~[[*id]]]]" method="get">\n      <input type="hidden" name="page_id" value="[[*id]]" disabled="disabled" />\n        [[+filters]]\n    </form>\n</div>\n<div id="products">\n   [[!tmCatalog]]\n</div>', 0, 'a:0:{}', 0, ''),
(46, 1, 0, 'shopOrderForm', '', 0, 22, 0, '<div id="order-list">\n    [[!Shopkeeper3@order_page?propertySetName=`order_page`]]\n</div>\n<script>\n    $(document).ready(function(){ \n        $(''select[name="shk_delivery"] option[value="''+SHK.data[''delivery_name'']+''"]'').attr(''selected'',''selected'');\n        $(''select[name="shk_delivery"]'').change(function(){\n            var shk_delivery = $(''select[name="shk_delivery"]'').val();\n            SHK.selectDelivery(shk_delivery);\n            return false;\n        });\n        $(''select[name="shk_delivery"]'').trigger(''change'');\n    });\n</script>\n\n[[!FormIt?\n    &hooks=`spam,shk_fihook,email,FormItAutoResponder,redirect`\n    &emailTpl=`shopOrderReport`\n    &emailSubject=`Заказ в магазине [[++site_url]]`\n    &emailTo=`[[+set.contacts.email1:default=`[[++emailsender]]`]]`\n    &emailFromName=`[[++site_name]]`\n    &emailFrom=`webmaster@[[domain]]`\n    &redirectTo=`25`\n    &fiarFrom =`webmaster@[[domain]]`\n    &fiarTpl=`shopOrderReportClient`\n    &fiarFromName=`[[++site_name]]`\n    &fiarSubject=`Вами сделан заказ на сайте [[++site_name]]`\n    &validate=`address:required,phone:required,email:email:required,fullname:required`\n    &errTpl=`<br/><span class="error">[[+error]]</span>`\n]]\n[[!shkOptions?\n    &get=`delivery`\n    &post_name=`shk_delivery`\n    &toPlaceholders=`1`\n    &pl_prefix=`shkopt_`\n    &tpl=`delivery_option`\n]]\n<p class="error">[[!+fi.error.error_message]]</p>\n\n<form method="post" action="[[~[[*id]]]]" id="shopOrderForm" class="form">\n    <input type="hidden" name="nospam:blank" value="" />\n    <input type="hidden" name="order" value="1" />\n\n    <div class="form-group">\n        <label>Выберите способы получения товара:</label>\n        <select name="shk_delivery" id="delivery_select" class="iselect">\n            [[!+shkopt_delivery]]\n        </select>\n    </div>\n    \n    [[-                \n    <div class="form-group">\n        <label>Выберите способ оплаты:</label>\n        [[!fcmspaymentList]]\n    </div>\n    ]]\n    \n    <div class="form-group">\n        <label>Ф.И.О.<span class="error">*</span>:</label>\n        <input required name="fullname" size="30" class="textfield itext" type="text" value="[[!+fi.fullname:default=`[[!+modx.user.id:userinfo=`fullname`]]`:ne=`0`:show]]" />\n        [[!+fi.error.fullname]]\n    </div>    \n    <div class="form-group">\n        <label>E-mail<span class="error">*</span>:</label>\n        <input required name="email" size="30" class="textfield itext" type="email" value="[[!+fi.email:default=`[[!+modx.user.id:userinfo=`email`]]`:ne=`0`:show]]" />\n        [[!+fi.error.email]]\n    </div>    \n    <div class="form-group">\n        <label>Телефон<span class="error">*</span>:</label>\n        <input required name="phone" size="30" class="textfield itext" type="tel" value="[[!+fi.phone:default=`[[!+modx.user.id:userinfo=`phone`]]`:ne=`0`:show]]" />\n        [[!+fi.error.phone]]\n    </div>    \n    <div class="form-group">\n        <label>Адрес<span class="error">*</span>:</label>\n        <input required name="address" size="30" class="textfield itext" type="text" value="[[!+fi.address:default=`[[!+modx.user.id:userinfo=`address`]]`:ne=`0`:show]]" />\n        [[!+fi.error.address]]\n    </div>    \n    <div class="form-group">\n        <label>Комментарий:</label>\n        <textarea name="message" class="textfield itext" rows="4" cols="30">[[!+fi.message]]</textarea>\n    </div>    \n    \n    <div class="form-buttons">\n        <input type="submit"  value="Отправить" class="button isubmit" name="submit_button" id="continue">\n    </div>\n\n    <p>* Поля, обязательные для заполнения</p>\n</form>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', 0, 'a:0:{}', 0, ''),
(44, 1, 0, 'shopCartRow', '', 0, 22, 0, '<tr class="cart-order">\n    <td><a href="[[+url]]"><img src="[[phpthumbof? &input=`/userfiles/[[+image]]` &options=`w=110&h=80`]]"></a></td>\n    <td align="left"><b><a href="[[+url]]">[[+name]]</a></b> [[+addit_data]]</td>\n    <td>[[+price]] [[+currency]]</td>\n    <td align="center">\n        <input class="shk-count" type="text" size="2" name="count[]" maxlength="3" title="изменить количество" value="[[+count]]" />\n    </td>\n    <td align="center">\n        <a href="[[+url_del_item]]" title="Удалить" class="shk-del"><i class="fa fa-trash"></i></a>\n    </td>\n</tr>', 0, 'a:0:{}', 0, ''),
(45, 1, 0, 'shopCart', '', 0, 22, 0, '<div id="shopCart" class="shop-cart" data-shopcart="1">\n    <div class="empty">\n        <div class="shop-cart-empty">Корзина пуста</div>\n    </div>\n    [[+plugin]]\n</div>\n\n<!--tpl_separator-->\n\n<div id="shopCart" class="shop-cart" data-shopcart="1">\n    <a name="shopCart"></a><h3>Корзина</h3>\n    <div class="full">\n        <form action="[[+this_page_url]]#shopCart" method="post">\n            <fieldset>\n                <div class="itogo">\n                    <b>[[+items_total]]</b> [[+plural]]<br />\n                    на сумму <b>[[+price_total]] [[+currency]]</b>        \n                </div>\n                <noscript>\n                    <div><input type="submit" class="isubmit" name="shk_recount" value="Пересчитать" /></div>\n                </noscript>\n                <div style="padding: 3px 0pt;">\n                    <noscript>\n                        <div><input type="submit" class="submit" name="shk_recount" value="Пересчитать" /></div>\n                    </noscript>\n                    <a  class="butOrder" href="[[~24]]" >Оформить</a>\n                    <a href="[[+empty_url]]" id="shk_butEmptyCart" class="butEmptyCart">Очистить</a>\n                </div>\n            </fieldset>\n        </form>\n    </div>\n    [[+plugin]]\n</div>\n', 0, 'a:0:{}', 0, ''),
(68, 0, 0, 'ditsnewssignup', 'Signup form', 0, 26, 0, '<form action="/" method="post" name="rassilka" class="form">\n    <input type="hidden" name="groups[]" value="1" />\n\n    <div class="form-group">\n        <label for="email">Введите Ваш email</label>\n        <input name="email" type="email" value="[[+ras.email]]" class="itext" required/>\n        <div class="errorMessage">[[!+ras.error.email]]</div>\n    </div>\n    <div class="form-buttons">\n        <input type="submit" value="Подписаться"  name="contactsubmit" class="contactsubmit isubmit" />\n        [[!+ras.successMessage]]\n    </div>\n</form>', 0, 'a:0:{}', 0, ''),
(43, 2, 0, 'sendtobasketinlist', '', 0, 22, 0, '<div class="shk-item"> \n    <form action="[[~[[*id]]]]" method="post">\n        [[+tv.size]]\n        <div class="order">\n            <div class="product-tocart">\n                <input type="hidden" name="shk-id" value="[[+id]]" />\n                <input type="hidden" name="shk-name" value="[[+pagetitle]]" />\n                <input type="hidden" name="shk-count" value="1" size="2" maxlength="3" />\n                [[+param]]\n                <span class="shk-price" id="stuff_[[+id]]_price">[[+tv.price]]</span> руб.\n                <button type="submit" class="isubmit" name="shk-submit" id="cartbasket_[[+id]]" class="shk-but">В корзину</button>\n            </div>\n        </div>\n    </form>\n</div>', 0, 'a:0:{}', 0, ''),
(48, 1, 0, 'mailContactsRow', '', 0, 22, 0, '<tr>\n    <td>[[+label]]:</td>\n    <td>[[+value]]</td>\n</tr>', 0, NULL, 0, ''),
(49, 2, 0, 'sendtobasket', '', 0, 22, 0, '<div class="shk-item"> \n    <form action="[[~[[*id]]]]" method="post">\n		[[!*size:notempty=`\n			<div class="variables">\n				<label>Размер:</label>\n				[[!*size:replace=`size__==size__[[*id]]`]]\n			</div>\n		`]]\n		<div class="order">\n            <div class="product-tocart ">\n                <input type="hidden" name="shk-id" value="[[*id]]" />\n                <input type="hidden" name="shk-name" value="[[*pagetitle]]" />\n                <input type="hidden" name="shk-count" value="1" size="2" maxlength="3" />\n				[[+param+]]\n                <span itemprop="offers" itemscope itemtype="http://schema.org/Offer">\n                    <span itemprop="priceCurrency" style="display: none;">RUR</span>\n                    <span class="shk-price" id="stuff_[[*id]]_price" itemprop="price">[[*price]]</span> руб.\n                </span>\n                <button type="submit" name="shk-submit" id="cartbasket_[[*id]]" class="shk-but isubmit">В корзину</button>\n            </div>\n        </div>\n    </form>\n</div>', 0, 'a:0:{}', 0, ''),
(50, 0, 0, 'editProfile', '', 0, 19, 0, '[[!UpdateProfile? &excludeExtended=`login-updprof-btn,email:required:email`]]\n<div class="update-profile">\n    <div class="updprof-error">[[+error.message]]</div>\n    [[+login.update_success:if=`[[+login.update_success]]`:is=`1`:then=`[[%login.profile_updated? &namespace=`login` &topic=`updateprofile`]]`]]\n \n    <form class="form" action="[[~[[*id]]]]" method="post">\n        <input type="hidden" name="nospam:blank" value="" />\n \n        <div class="form-group">\n            <label for="fullname">Полное имя: <span class="error">[[+error.fullname]]</span></label>\n            <input type="text" class="itext" name="fullname" id="fullname" value="[[+fullname]]" placeholder="Полное имя"/>\n        </div>\n \n        <div class="form-group">\n            <label for="email">Электронная почта: <span class="error">[[+error.email]]</span></label>\n            <input type="text" class="itext" name="email:required:email" id="email" value="[[+email]]" placeholder="Электронная почта"/>\n        </div>\n \n        <div class="form-group">\n            <label for="phone">Телефон: <span class="error">[[+error.phone]]</span></label>\n            <input type="text" class="itext" name="phone" id="phone" value="[[+phone]]" placeholder="Телефон"/>\n        </div>\n \n        <div class="form-group">\n            <label for="address">Адрес: <span class="error">[[+error.address]]</span></label>\n            <textarea name="address" cols="50" rows="3" id="address" class="itext" placeholder="Адрес">[[+address]]</textarea>\n        </div>\n \n        <div class="form-buttons">\n            <input type="submit" class="enter isubmit" name="login-updprof-btn" value="Сохранить настройки" />\n        </div>\n    </form>\n</div>', 0, 'a:0:{}', 0, ''),
(51, 0, 0, 'register-redirect', '', 0, 19, 0, '[[+shk.items_total:gt=`0`:then=`\r\n\r\n<script type="text/javascript">\r\nvar timetogo = 10;\r\nvar timer = window.setInterval(function()\r\n{\r\n    $(''#time-to-basket'').text(timetogo);\r\n    if (timetogo <= 0)\r\n    { \r\n         $(location).attr(''href'',''http://'' + window.location.hostname + ''/[[~24]]'');\r\n         window.clearInterval(timer);\r\n    }\r\n    timetogo--;\r\n}, 1000);\r\n</script>\r\n\r\n<p>Автоматическое перенаправление <a href="[[~24]]">на страницу оформления заказа</a> через <strong id="time-to-basket">10</strong> секунд.</p>\r\n`]]', 0, 'a:0:{}', 0, ''),
(52, 0, 0, 'registerForm', '', 0, 19, 0, '[[!Register?\n    &submitVar=`registerbtn`\n    &activationResourceId=`32`\n    &activationEmailTpl=`lgnActivateEmailTpl`\n    &activationEmailSubject=`Благодарим за регистрацию в нашем магазине!`\n    &submittedResourceId=`34`\n    &usergroups=`Покупатели`\n    &activation=`1` \n    &validate=`nospam:blank,\n        username:required:minLength=^3^,\n        password:required:minLength=^3^,\n        password_confirm:password_confirm=^password^,\n        fullname:required,\n        email:required:email`\n    &placeholderPrefix=`reg.`\n    &postHooks=`register-auto-login`\n]]\n \n<div class="register">\n    <div class="registerMessage">[[!+reg.error.message]]</div>\n \n    <form class="form" action="[[~[[*id]]]]" method="post">\n        <input type="hidden" name="nospam" value="[[!+reg.nospam]]" />\n        \n        <div class="form-group">\n            <label for="username">Имя пользователя<span class="error">*</span>: <span class="error">[[!+reg.error.username]]</span></label>\n            <input type="text" class="itext" name="username" id="username" value="[[!+reg.username]]" placeholder="Имя пользователя*" required/>\n        </div>\n        \n        <div class="form-group">\n            <label for="password">Пароль<span class="error">*</span>: <span class="error">[[!+reg.error.password]]</span></label>\n            <input type="password" class="itext" name="password" id="password" value="[[!+reg.password]]" placeholder="Пароль*" required/>\n        </div>\n        \n        <div class="form-group">\n            <label for="password_confirm">Подтвердите пароль<span class="error">*</span>: <span class="error">[[!+reg.error.password_confirm]]</span></label>\n            <input type="password" class="itext" name="password_confirm" id="password_confirm" value="[[!+reg.password_confirm]]" placeholder="Подтвердите пароль*" required/>\n        </div>\n        \n        <div class="form-group">\n            <label for="fullname">Полное имя<span class="error">*</span>: <span class="error">[[!+reg.error.fullname]]</span></label>\n            <input type="text" class="itext" name="fullname" id="fullname" value="[[!+reg.fullname]]" placeholder="Полное имя*" required/>\n        </div>\n        \n        <div class="form-group">\n            <label for="email">Адрес электронной почты<span class="error">*</span>: <span class="error">[[!+reg.error.email]]</span></label>\n            <input type="text" class="itext" name="email" id="email" value="[[!+reg.email]]" placeholder="Адрес электронной почты*" required/>\n        </div>\n        \n        <div class="form-group">\n            <label for="address">Адрес доставки: <span class="error">[[!+reg.error.address]]</span></label>\n            <textarea name="address" class="itext" id="address" placeholder="Адрес доставки">[[!+reg.address]]</textarea>\n        </div>\n \n        <div class="form-buttons">\n            <input type="submit" name="registerbtn" class="enter isubmit" value="Зарегистрироваться" />\n        </div>\n    </form>\n</div>', 0, 'a:0:{}', 0, ''),
(66, 0, 0, 'yandex_item', '', 0, 17, 0, '<offer id="[[+id]]" available="true">\n    <url>[[~[[+id]]?&scheme=`http`]]</url>\n    <price>[[+tv.price]]</price>\n    <currencyId>RUR</currencyId>\n    <categoryId>[[+parent:striptags:htmlentities]]</categoryId>\n    <picture>[[!urlcode?&baseurl=`[[++site_url]]`&url=`[[+tv.image]]`]]</picture>\n    <name>\n        <![CDATA[\n            [[+pagetitle:htmlentities]]\n        ]]>\n    </name>\n    <description>\n        <![CDATA[\n            [[!xmlreplace?&text=`[[+introtext]]`]]\n        ]]>\n    </description>\n</offer>', 0, 'a:0:{}', 0, ''),
(65, 2, 0, 'shopOrderReportClient', '', 0, 22, 0, '<p>Уважаемый (ая) <b>[[+fullname]]</b>, благодарим Вас за то, что Вы воспользовались услугами нашего интернет-магазина <a href="[[++site_url]]" target="blank">[[++site_name]]</a>.</p>\n\n<div style="padding:15px 0; margin:15px 0; border-top:3px solid #BCBCBC; border-bottom:3px solid #BCBCBC;">\n    <p>Номер заказа: <b>[[+orderID]]</b> от <b>[[+orderDate]]</b></p>\n    \n    [[+orderOutputData]]\n</div>\n\n<table cellpadding="10" border="1">\n    <thead style="background: #ddd;">\n        <tr>\n            <th colspan="2">\n                <b>Данные покупателя:</b>\n            </th>\n        </tr>\n    </thead>\n    <tr>\n        <td>Адрес:</td>\n        <td>[[+address]]</td>\n    </tr>\n    <tr>\n        <td>Способ доставки:</td>\n        <td>[[+shk_delivery]]</td>\n    </tr>\n    <tr><td>Ф.И.О.:</td><td>[[+fullname]]</td></tr>\n    <tr><td>Адрес эл. почты:</td><td><a href="mailto:[[+email]]">[[+email]]</a></td></tr>\n    <tr><td>Телефон:</td><td>[[+phone]]</td></tr>\n    <tr><td>Комментарий:</td><td>[[+message]]</td></tr>\n</table>\n\n<p>Спасибо за заказ!</p>\n<p>Интернет магазин <a href="[[++site_url]]" target="blank">[[++site_name]]</a></p>', 0, 'a:0:{}', 0, ''),
(117, 2, 0, 'share', '', 0, 36, 0, '<script src="https://cdn.jsdelivr.net/jquery.goodshare.js/3.2.3/goodshare.min.js"></script>\n<div class="social__buttons">\n    [[+set.social-buttons:replace=`||==`]]\n    [[+set.msg-buttons:replace=`||==`]]\n</div>', 0, 'a:0:{}', 0, ''),
(54, 0, 0, 'filterCheckboxItem', 'Chunk to draw filter parameter of type checkbox', 0, 5, 0, '<b>[[+caption]]: </b>\n[[+checkboxes]]\n', 0, '', 0, ''),
(55, 0, 0, 'filterListItem', 'Chunk to draw filter parameter of type listbox', 0, 5, 0, '<b>[[+caption]]: </b>\n<select style="width: 160px; font-size: 11px;" name="[[+name]]" class="iselect">\n	<option  value="">не выбрано</option>\n	[[+options]]\n</select>\n', 0, '', 0, ''),
(56, 0, 0, 'filterNumberItem', 'Chunk to draw filter parameter of type number', 0, 5, 0, '<div>\n	<b>[[+caption]]: </b>\n  	от: <input type="text" class="itext" value="[[+from]]" name="[[+name]]_from"/> \n  	до: <input type="text" class="itext" value="[[+to]]" name="[[+name]]_to"/>\n</div>', 0, '', 0, ''),
(57, 0, 0, 'filterTextItem', 'Chunk to draw filter parameter of type text', 0, 5, 0, '<div>\n	<b>[[+caption]]: </b>\n	<input type="text" class="itext" value="[[+value]]" name="[[+name]]" />\n</div>', 0, '', 0, ''),
(58, 0, 0, 'filterTemplate', 'Chunk to draw filter', 0, 5, 0, '<div class="filtr">\n	Фильтр:	\n  	<div>\n		[[+rows]]\n  		<input type="submit" class="isubmit" value="Фильтровать"/>\n	</div>\n</div>', 0, 'a:0:{}', 0, ''),
(59, 0, 0, 'catPageSize', 'Chunk to draw cat page size chunk', 0, 5, 0, '<div>\n	<span>Выводить по:</span><a href="[[+link10]]" class="[[+class10]]">10</a> <a href="[[+link20]]" class="[[+class20]]">20</a> <a href="[[+link50]]" class="[[+class50]]">50</a>\n</div>', 0, '', 0, ''),
(60, 0, 0, 'catSort', 'Chunk to draw category sort', 0, 5, 0, '<div class="sort">\n	Сортировка:	\n	<select style="width: 160px; font-size: 11px;" id="[[+sortListId]]" class="iselect">\n		<option value="">не выбрано</option>\n		<option value="[[+pagetitle_name_asc]]" [[+pagetitle_asc_selected]]>Наименование, от А-Я</option>\n		<option value="[[+pagetitle_name_desc]]" [[+pagetitle_desc_selected]]>Наименование, от Я-А</option>\n		<option value="[[+tv_price_name_asc]]" [[+tv_price_asc_selected]]>Цена, по возрастанию</option>\n		<option value="[[+tv_price_name_desc]]" [[+tv_price_desc_selected]]>Цена, по убыванию</option>\n	</select>\n</div>', 0, 'a:0:{}', 0, ''),
(95, 0, 0, 'paymentList', 'Payment list outer template', 0, 33, 0, '<fieldset>\n	[[+list]]\n</fieldset>\n', 0, '', 0, ''),
(96, 0, 0, 'paymentListItem', 'Payment list item template', 0, 33, 0, '<label><input type="radio" value="[[+id]]" name="[[+name]]" class="niceRadio" [[+checked:is=`1`:then=`checked="checked"`]] required> [[+title]]</label><br/>', 0, 'a:0:{}', 0, ''),
(97, 0, 0, 'paymentRobokassaFail', 'Robokassa fail text template', 0, 33, 0, '<h1>Оплата отменена</h1>\n<p>Оплата заказа [[+order_id]] отменена.</p>', 0, '', 0, ''),
(61, 0, 0, 'catSearchForm', 'Chunk to draw category search form', 0, 5, 0, '<form class="form" action="/catsearch/" method="get" id="catsearch">\n	[[+categories]]\n[[+searchText]]\n  	[[+tvs]]\n	<div class="form-buttons"><input type="submit" value="Искать" /></div>\n</form>', 0, '', 0, ''),
(62, 0, 0, 'checkAuthUser', 'Chunk displayed if user authenticated', 0, 5, 0, 'Авторизован', 0, '', 0, ''),
(63, 0, 0, 'checkAuthGuest', 'Chunk displayed if user is guest', 0, 5, 0, 'Гость', 0, '', 0, ''),
(64, 2, 0, 'delivery_option', '', 0, 22, 0, '<option value="[[+value]]">[[+label]] - [[+price]] руб.</option>', 0, 'a:0:{}', 0, ''),
(67, 0, 0, 'yandex_category', '', 0, 17, 0, '<category id="[[+id]]" parentId="[[+parent:is=`14`:then=`0`:else=`[[+parent]]`]]">\n    <![CDATA[ \n        [[+pagetitle:htmlentities]] \n    ]]>\n</category>', 0, 'a:0:{}', 0, ''),
(69, 0, 0, 'ditsnewssignupmail', 'Confirmation message after newsletter signup', 0, 26, 0, 'Дорогой [[+firstname:default=`Подписчик`]],<br />\r\n<br />\r\nСпасибо вам за использование нашей рассылки. Пожалуйста, нажмите <a href="[[+confirmUrl]]">здесь</a> для подтверждения подписки.', 0, 'a:0:{}', 0, ''),
(70, 2, 0, 'specialsGoods', '', 0, 17, 0, '[[!getResources?\n    &tpl=`product` \n    &includeTVs=`size,price` \n    &limit=`3` \n    &sortby=`RAND()`\n    &depth=`10` \n    &parents=`14` \n    &where=`{"template:=":4}` \n    &tvFilters=`special==1` \n    &sortbyTVType=`integer`\n    &toPlaceholder=`specialsGoods`\n]]\n\n[[!+specialsGoods:ne=``:then=`<p class="h1">Хиты продаж</p>`]]\n\n<div class="box inline goods-list">\n\n    [[+specialsGoods]]\n\n</div>', 0, 'a:0:{}', 0, ''),
(72, 1, 0, 'tpl.HybridAuth.login', 'Chunk for guest', 0, 28, 0, '[[%ha.login_intro]]\n<br/>\n[[+providers]]\n\n[[+error:notempty=`<div class="alert alert-block alert-error">[[+error]]</div>`]]', 0, '', 0, 'core/components/hybridauth/elements/chunks/chunk.login.tpl'),
(73, 1, 0, 'tpl.HybridAuth.logout', 'Chunk for logged in', 0, 28, 0, '<div class="hybridauth">\n	<img src="[[+gravatar]]?s=75" alt="[[+username]]" title="[[+fullname]]"  class="ha-avatar" />\n\n	<span class="ha-info">\n		[[%ha.greeting]] <b>[[+username]]</b> ([[+fullname]])! <a href="[[+logout_url]]">[[%ha.logout]]</a>\n		<br/><br/>\n		<small>[[%ha.providers_available]]</small><br/>\n		[[+providers]]\n	</span>\n\n</div>\n\n[[+error:notempty=`<div class="alert alert-block alert-error">[[+error]]</div>`]]\n', 0, '', 0, 'core/components/hybridauth/elements/chunks/chunk.logout.tpl'),
(74, 1, 0, 'tpl.HybridAuth.profile', 'Chunk for profile update', 0, 28, 0, '<form action="[[~[[*id]]]]" method="post" class="form-horizontal">\n\n	<div class="control-group">\n		<label class="control-label">[[%ha.gravatar]]</label>\n		<div class="controls">\n			<img src="[[+gravatar]]?s=100" alt="[[+email]]" title="[[+email]]"  style="margin-left:40px;" />\n			<br/><small>[[%ha.gravatar_desc]]</small>\n		</div>\n	</div>\n\n	<div class="control-group[[+error.username:notempty=` error`]]">\n		<label class="control-label">[[%ha.username]]</label>\n		<div class="controls">\n			<input type="text" name="username" value="[[+username]]" />\n			<span class="help-inline">[[+error.username]]</span>\n		</div>\n	</div>\n	\n	<div class="control-group[[+error.fullname:notempty=` error`]]">\n		<label class="control-label">[[%ha.fullname]]</label>\n		<div class="controls">\n			<input type="text" name="fullname" value="[[+fullname]]" />\n			<span class="help-inline">[[+error.fullname]]</span>\n		</div>\n	</div>\n	\n	<div class="control-group[[+error.email:notempty=` error`]]">\n		<label class="control-label">[[%ha.email]]</label>\n		<div class="controls">\n			<input type="text" name="email" value="[[+email]]" />\n			<span class="help-inline">[[+error.email]]</span>\n		</div>\n	</div>\n\n	<div class="control-group">\n		<label class="control-label">[[%ha.providers_available]]</label>\n		<div class="controls">\n			[[+providers]]\n		</div>\n	</div>\n\n	<input type="hidden" name="hauth_action" value="updateProfile" />\n	<div class="form-actions">\n		<button type="submit" class="btn btn-primary">[[%ha.save_profile]]</button>\n		&nbsp;&nbsp;\n		<a href="[[+logout_url]]" class="btn btn-danger">[[%ha.logout]]</a>\n	</div>\n</form>\n[[+success:is=`1`:then=`<div class="alert alert-block">[[%ha.profile_update_success]]</div>`]]\n[[+success:is=`0`:then=`<div class="alert alert-block alert-error">[[%ha.profile_update_error]] [[+error.message]]</div>`]]', 0, '', 0, 'core/components/hybridauth/elements/chunks/chunk.profile.tpl'),
(75, 1, 0, 'tpl.HybridAuth.provider', 'Chunk for authorization provider', 0, 28, 0, '<a href="[[+login_url]]&amp;provider=[[+title]]" class="ha-icon [[+provider]]" rel="nofollow" title="[[+title]]">[[+title]]</a>\n', 0, '', 0, 'core/components/hybridauth/elements/chunks/chunk.provider.tpl'),
(76, 1, 0, 'tpl.HybridAuth.provider.active', 'Chunk for active authorization provider', 0, 28, 0, '<span class="ha-icon active [[+provider]]" title="[[+title]]">[[+title]]</span>', 0, '', 0, 'core/components/hybridauth/elements/chunks/chunk.provider_active.tpl'),
(77, 1, 0, 'orderDataRow', '', 0, 22, 0, '<tr class="cart-order">\n    <td>\n        <b>[[+name]]</b>\n    </td>\n    <td>\n        [[+addit_data:default=`&mdash;`]]\n    </td>\n    <td>\n        [[+count]] шт.\n    </td>\n    <td>\n        [[+price]] [[+currency]]\n    </td>\n</tr>', 0, NULL, 0, ''),
(93, 1, 0, 'select_option', '', 0, 22, 0, '<option value="[[+value]]" [[+selected]]>[[+label]]</option>', 0, NULL, 0, ''),
(88, 2, 0, 'SimpleSearchForm', '', 0, 6, 0, '<form class="sisea-search-form" action="[[~[[+landing]]]]" method="[[+method]]">\r\n    <fieldset>\r\n        <div class="search_form">\r\n            <input type="hidden" name="id" value="[[+landing]]" /> \r\n            <input type="text" name="[[+searchIndex]]" id="[[+searchIndex]]" value="[[+searchValue]]" placeholder="Поиск по сайту..." autocomplete="off"/>\r\n            <span>\r\n                <button type="submit" value="[[%sisea.search? &namespace=`sisea` &topic=`default`]]"><i class="fa fa-search"></i></button>\r\n            </span>\r\n        </div>\r\n    </fieldset>\r\n</form>', 0, 'a:0:{}', 0, ''),
(89, 2, 0, 'SimpleSearchResults', '', 0, 6, 0, '<p class="sisea-results">[[+resultInfo]]</p>\n\n<div class="sisea-paging"><span class="sisea-result-pages">[[%sisea.result_pages? &namespace=`sisea` &topic=`default`]]</span>[[+paging]]</div>\n\n<div class="sisea-results-list box inline">\n    [[+results]]\n</div>\n\n<div class="sisea-paging"><span class="sisea-result-pages">[[%sisea.result_pages? &namespace=`sisea` &topic=`default`]]</span>[[+paging]]</div>', 0, 'a:0:{}', 0, ''),
(90, 2, 0, 'SimpleSearchResultLi', '', 0, 6, 0, '<li><a href="[[~[[+id]]]]" title="[[+longtitle]]">[[+pagetitle]]</a></li>', 0, 'a:0:{}', 0, ''),
(91, 2, 0, 'SimpleSearchResult', '', 0, 6, 0, '<div class="sgrid-4">\n    <div class="goods-item">\n        <div class="goods-title">[[+idx]]. <a href="[[+link:is=``:then=`[[~[[+id]]]]`:else=`[[+link]]`]]" title="[[+longtitle]]">[[+pagetitle]]</a></div>\n        <div class="goods-image">\n            [[+image:notempty=`\n                <a href="[[~[[+id]]]]" title="[[+pagetitle]]">\n                    <img src="[[phpthumbof? &input=`/userfiles/[[+image]]` &options=`w=200&h=130&zc=1`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]">\n                </a>\n            `]]\n        </div>\n        <div class="goods-descr">\n            [[+extract]]\n        </div>\n    </div>\n</div>', 0, 'a:0:{}', 0, ''),
(92, 1, 0, 'orderDataOuter', '', 0, 22, 0, '<p><b>Состав заказа:</b></p>\n\n<table cellpadding="10" border="1" style="width: 100%;">\n    <thead style="background: #ddd;">\n        <tr>\n            <th>Наименование</th>\n            <th>Параметры</th>\n            <th>Кол-во</th>\n            <th>Цена</th>\n        </tr>\n    </thead>\n    <tbody>\n        [[+purchases]]\n    </tbody>\n    <tfoot style="background: #eee;">\n        <tr>\n            <td colspan="3" style="text-align: right;">\n                Доставка: [[+delivery]]\n            </td>\n            <td>\n                <b>[[+delivery_price:num_format]] [[+currency]]</b>\n            </td>\n        </tr>\n        <tr>\n            <td colspan="3" style="text-align: right;">\n                <b>Итого:</b>\n            </td>\n            <td>\n                <b>[[+price:num_format]] [[+currency]]</b>\n            </td>\n        </tr>\n    </tfoot>\n</table>', 0, 'a:0:{}', 0, ''),
(98, 0, 0, 'paymentRobokassaSuccess', 'Robokassa success text template', 0, 33, 0, '<h1>Оплата успешно выполнена</h1>\n<p>Оплата заказа <b>[[+order_id]]</b> прошла успешно. Получено <b>[[+summ]]</b> рублей.</p>', 0, '', 0, ''),
(99, 0, 0, 'paymentRobokassaSuccessError', 'Robokassa success erro text template', 0, 33, 0, '<h1>Оплата не выполнена</h1>\n<p>При попытке обработки оплаты произошла следующая ошибка: [[+error_text]]</p>', 0, '', 0, ''),
(100, 0, 0, 'paymentCreate', 'Payment create form chunk', 0, 33, 0, '[[+error]]\n<form action="[[+url]]" method="[[+method]]">\n	<input type="text" name="[[+summName]]" value="[[+summ]]"/>\n	[[!fcmspaymentList]]\n	<input type="submit" name="[[+payName]]" value="Оплатить"/>\n</form>', 0, '', 0, ''),
(101, 0, 0, 'formRobokassa', 'Robokassa payment form template', 0, 33, 0, '<form action="[[+action]]" target="_blank">\n	[[+query]]\n	Сумма к оплате: <b>[[+summ]]</b> руб.<br>\n	<input type="submit" value="Оплатить в Robokassa"/>\n</form>', 0, 'a:0:{}', 0, ''),
(102, 0, 0, 'formCash', 'Cash payment form template', 0, 33, 0, '<form action="[[+action]]" target="_blank">\n	[[+query]]\n	Сумма к оплате: <b>[[+summ]]</b> руб.<br>\n	[[-<input type="submit" value="Оплатить наличными"/>]]\n</form>', 0, 'a:0:{}', 0, ''),
(103, 0, 0, 'formQiwi', 'Qiwi payment form template', 0, 33, 0, '<form action="[[+action]]" target="_blank">\n	[[+query]]\n	Сумма к оплате: <b>[[+summ]]</b>\n	<div>Телефон: [[+phone]]</div>\n	<input type="submit" value="Оплатить в Qiwi"/>\n</form>', 0, '', 0, ''),
(104, 0, 0, 'formQiwiField', 'Qiwi payment form template with vissible phone field', 0, 33, 0, '<form action="[[+action]]" method="POST">\n	[[+query]]\n	Сумма к оплате: <b>[[+summ]]</b>\n	<div>\n		<label for="[[+phoneVar]]">Телефон</label>\n		<input type="text" maxlength="10" name="[[+phoneVar]]" value="[[+phone]]"/>\n	</div>\n	<div class="error">[[+errorText]]</div>\n	<input type="submit" value="Оплатить в Qiwi" />\n</form>', 0, '', 0, ''),
(105, 0, 0, 'fcmspaymentInvoiceCash', 'Чанк с шаболоном накладной для курьера при оплате наличными', 0, 33, 0, '<html>\n<head>\n	<title>Накладная № [[+invoice_id]]</title>\n<head>\n	<style>\n		#date{text-align:right}\n		h1{text-align:center}\n		table{width:100%;border-collapse:collapse;margin-bottom:1em}\n		table, td, th{border: 1px solid #000;padding:5px}\n		th{background: #DDD;font-weight:bold}\n		#to,#from{margin-bottom:0.5em}\n		#th-num{width:7%}\n		#th-title{width:45%}\n		#th-count{width:8%}\n		#th-cost{width:20%}\n		#th-summ{width:20%}\n		.footer-block{float:left;width:50%;font-weight:bold}\n	</style>\n<body>\n<div id="invoice">\n	<div id="date">[[+date]]</div>\n	<h1>Накладная № [[+invoice_id]]</h1>\n	<div id="to"><strong>Кому: </strong>[[+to]]</div>\n	<div id="from"><strong>От: </strong>название организации заказчика</div>\n	<table>\n		<thead>\n		<tr>\n			<th id="th-num">№ п/п</th>\n			<th id="th-title">Наименование</th>\n			<th id="th-count">К-во</th>\n			<th id="th-cost">Цена</th>\n			<th id="th-summ">Сумма</th>\n		</tr>\n		</thead>\n		<tbody>[[+rows]]</tbody>\n	</table>\n	<div id="footer">\n		<div class="footer-block">Сдал:</div>\n		<div class="footer-block">Принял:</div>\n	</div>\n</div>\n</body>\n</html>', 0, '', 0, ''),
(106, 0, 0, 'fcmspaymentInvoiceCashItem', 'Шаблон строки таблицы накладной', 0, 33, 0, '<tr>\n	<td>[[+number]]</td>\n	<td>[[+title]]</td>\n	<td>[[+count]]</td>\n	<td>[[+cost]]</td>\n	<td>[[+summ]]</td>\n</tr>', 0, '', 0, ''),
(107, 0, 0, 'formRbk', 'Шаблон формы платежа RBK Money', 0, 33, 0, '<form action="[[+action]]" accept-charset="utf-8" target="_blank">\n	[[+query]]\n	Сумма к оплате: <b>[[+summ]]</b>\n	<input type="submit" value="Оплатить в RBK Money"/>\n</form>', 0, '', 0, ''),
(109, 2, 0, 'defaultFormAjax', '', 0, 11, 0, '[[!AjaxForm?\n    &snippet=`FormIt`\n    &form=`defaultForm`\n    &hooks=`spam,email`\n    &emailTpl=`defaultEmailReport` \n    &emailTo=`[[+set.contacts.email1:default=`[[++emailsender]]`]]` \n    &emailSubject=`Сообщение с сайта [[++site_name]]`\n    &emailFrom=`webmaster@[[domain]]`\n    &validate=`name:required, email:email:required, text:required:stripTags`\n    &validationErrorMessage=`В форме содержатся ошибки!`\n    &successMessage=`Сообщение успешно отправлено`\n]]', 0, 'a:0:{}', 0, ''),
(111, 2, 0, 'FaqFormAjax', '', 0, 11, 0, '[[!AjaxForm?\r\n    &snippet=`FormIt`\r\n    &form=`FaqForm`\r\n    &hooks=`spam,FaqHook`\r\n    &validate=`name:required, email:email:required, text:required:stripTags`\r\n    &validationErrorMessage=`В форме содержатся ошибки!`\r\n    &successMessage=`Сообщение успешно отправлено`\r\n]]', 0, 'a:0:{}', 0, ''),
(112, 2, 0, 'brand', '', 0, 17, 0, '<div class="brand">\n    <div class="brand__logo">\n        <a href="[[~[[+id]]]]"><img src="[[phpthumbof? &input=`[[+tv.image]]` &options=`w=200&h=130&zc=1`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]"></a>    \n    </div>\n    <div class="brand__title">\n        <a href="[[~[[+id]]]]">[[+pagetitle]]</a>\n    </div>\n</div>', 0, 'a:0:{}', 0, ''),
(113, 0, 0, 'siseaCurrentPageTpl', '', 0, 6, 0, '<li class="active"><a href="#">[[+text]]</a></li>', 0, '', 0, ''),
(115, 2, 0, 'ya-metrika', '', 0, 36, 0, '[[+set.ya-counter-id:notempty=`\n    <!-- Yandex.Metrika counter -->\n<script type="text/javascript" >\n   (function(m,e,t,r,i,k,a){m[i]=m[i]||function(){(m[i].a=m[i].a||[]).push(arguments)};\n   m[i].l=1*new Date();k=e.createElement(t),a=e.getElementsByTagName(t)[0],k.async=1,k.src=r,a.parentNode.insertBefore(k,a)})\n   (window, document, "script", "https://mc.yandex.ru/metrika/tag.js", "ym");\n \n   ym(44950984, "init", {\n        id:44950984,\n        clickmap:true,\n        trackLinks:true,\n        accurateTrackBounce:true,\n        webvisor:true,\n        trackHash:true,\n        ecommerce:"dataLayer"\n   });\n</script>\n<noscript><div><img src="https://mc.yandex.ru/watch/44950984" style="position:absolute; left:-9999px;" alt="" /></div></noscript>\n<!-- /Yandex.Metrika counter -->\n`]]\n', 0, 'a:0:{}', 0, ''),
(116, 2, 0, 'google-analytics', '', 0, 36, 0, '[[+set.ga-id:notempty=`\n    <script>\n      (function(i,s,o,g,r,a,m){i[''GoogleAnalyticsObject'']=r;i[r]=i[r]||function(){\n      (i[r].q=i[r].q||[]).push(arguments)},i[r].l=1*new Date();a=s.createElement(o),\n      m=s.getElementsByTagName(o)[0];a.async=1;a.src=g;m.parentNode.insertBefore(a,m)\n      })(window,document,''script'',''//www.google-analytics.com/analytics.js'',''ga'');\n    \n      ga(''create'', ''[[+set.ga-id]]'', ''auto'');\n      ga(''send'', ''pageview'');\n    \n    </script>\n`]]\n\n<!-- Global site tag (gtag.js) - Google Analytics -->\n<script async src="https://www.googletagmanager.com/gtag/js?id=UA-37591191-41"></script>\n<script>\n  window.dataLayer = window.dataLayer || [];\n  function gtag(){dataLayer.push(arguments);}\n  gtag(''js'', new Date());\n\n  gtag(''config'', ''UA-37591191-41'');\n</script>', 0, 'a:0:{}', 0, '');
INSERT INTO `modx_site_htmlsnippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `static`, `static_file`) VALUES
(130, 1, 0, 'mapex.Map21.Tpl', '', 0, 45, 0, '<div id="[[+mapId]]"[[+style]][[+class]]></div>\n<script type="text/javascript">\n    ymaps.ready(function(){\n        [[+mapId]] = new ymaps.Map("[[+mapId]]", {\n            center: [[+map.center]],\n            zoom: [[+map.zoom]],\n            controls: [[+controls21]]\n        });\n        [[+mapId]].setType("[[+map.type]]");\n[[+placemarks]]\n[[+polylines]]\n[[+polygons]]\n[[+routes]]\n    });\n</script>', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.map21.tpl'),
(131, 1, 0, 'mapex.Placemark21.Tpl', '', 0, 45, 0, '        [[+mapId]].geoObjects.add(new ymaps.Placemark([[+coords]], [[+properties]], [[+options21]]));', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.placemark21.tpl'),
(132, 1, 0, 'mapex.Polygon21.Tpl', '', 0, 45, 0, '        [[+mapId]].geoObjects.add(new ymaps.Polygon(\n            [[+coords]],\n            [[+properties]],\n            [[+options]]\n        ));', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.polygon21.tpl'),
(133, 1, 0, 'mapex.Polyline21.Tpl', '', 0, 45, 0, '        [[+mapId]].geoObjects.add(new ymaps.Polyline([[+coords]], [[+properties]], [[+options]]));', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.polyline21.tpl'),
(134, 1, 0, 'mapex.Route21.Tpl', '', 0, 45, 0, '        ymaps.route([[+coords]],{mapStateAutoApply: false}).then(function (route) {\n                [[+mapId]].geoObjects.add(route);\n            },\n            function (error) {\n                alert(error.message);\n        });', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.route21.tpl'),
(127, 1, 0, 'mapex.Polygon.Tpl', '', 0, 45, 0, '        [[+mapId]].geoObjects.add(new ymaps.Polygon(\n            [[+coords]],\n            [[+properties]],\n            [[+options]]\n        ));', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.polygon.tpl'),
(128, 1, 0, 'mapex.Polyline.Tpl', '', 0, 45, 0, '        [[+mapId]].geoObjects.add(new ymaps.Polyline([[+coords]], [[+properties]], [[+options]]));', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.polyline.tpl'),
(125, 1, 0, 'mapex.Map.Tpl', '', 0, 45, 0, '<div id="[[+mapId]]"[[+style]][[+class]]></div>\n<script type="text/javascript">\n    ymaps.ready(function(){\n        [[+mapId]] = new ymaps.Map("[[+mapId]]", {\n            center: [[+map.center]],\n            zoom: [[+map.zoom]]\n        });\n        [[+mapId]].setType("[[+map.type]]");\n        var [[+mapId]]Controls = "[[+controls]]".split('','');\n        for (var i = 0; i < [[+mapId]]Controls.length; i++){\n            [[+mapId]].controls.add([[+mapId]]Controls[i]);\n        }\n        [[+placemarks]]\n        [[+polylines]]\n        [[+polygons]]\n        [[+routes]]\n    });\n</script>', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.map.tpl'),
(126, 1, 0, 'mapex.Placemark.Tpl', '', 0, 45, 0, '        [[+mapId]].geoObjects.add(new ymaps.Placemark([[+coords]], [[+properties]], [[+options]]));', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.placemark.tpl'),
(121, 0, 0, 'map', '', 0, 12, 0, '[[!mapexMap? \n    &map=`[[+set.address-map]]`\n    &width=`100%`\n    &height=`300px`\n    [[+set.map-icon:notempty=`&placemarkIcon=`/userfiles/[[+set.map-icon]]``]]\n    &controls=`zoomControl,mapTools,typeSelector`\n]]', 0, 'a:0:{}', 0, ''),
(122, 1, 0, 'tpl.AjaxForm.example', '', 0, 34, 0, '<form action="" method="post" class="ajax_form af_example form-horizontal">\n\n	<div class="control-group">\n		<label class="control-label" for="af_name">[[%af_label_name]]</label>\n		<div class="controls">\n			<input type="text" id="af_name" name="name" value="[[+fi.name]]" placeholder="" class="span4" />\n			<span class="error_name">[[+fi.error.name]]</span>\n		</div>\n	</div>\n\n	<div class="control-group">\n		<label class="control-label" for="af_email">[[%af_label_email]]</label>\n		<div class="controls">\n			<input type="email" id="af_email" name="email" value="[[+fi.email]]" placeholder="" class="span4" />\n			<span class="error_email">[[+fi.error.email]]</span>\n		</div>\n	</div>\n\n	<div class="control-group">\n		<label class="control-label" for="af_message">[[%af_label_message]]</label>\n		<div class="controls">\n			<textarea id="af_message" name="message" class="span4" rows="5">[[+fi.message]]</textarea>\n			<span class="error_message">[[+fi.error.message]]</span>\n		</div>\n	</div>\n\n	<div class="control-group">\n		<div class="controls">\n			<button type="reset" class="btn btn-default">[[%af_reset]]</button>\n			<button type="submit" class="btn btn-primary">[[%af_submit]]</button>\n		</div>\n	</div>\n	\n	[[+fi.success:is=`1`:then=`\n		<div class="alert alert-success">[[+fi.successMessage]]</div>\n	`]]\n	[[+fi.validation_error:is=`1`:then=`\n		<div class="alert alert-danger">[[+fi.validation_error_message]]</div>\n	`]]\n</form>', 0, NULL, 0, 'core/components/ajaxform/elements/chunks/chunk.example.tpl'),
(129, 1, 0, 'mapex.Route.Tpl', '', 0, 45, 0, '        ymaps.route([[+coords]],{mapStateAutoApply: false}).then(function (route) {\n                [[+mapId]].geoObjects.add(route);\n                var points = route.getWayPoints();\n                points.get(0).options.set(''preset'', ''twirl#carIcon'');\n                points.get(1).options.set(''preset'', ''twirl#houseIcon'');\n            },\n            function (error) {\n                alert(error.message);\n        });', 0, NULL, 0, 'core/components/mapex2/elements/chunks/chunk.route.tpl'),
(124, 2, 0, 'db-info', '', 0, 12, 0, 'MySQL: [^qt^], [^q^] запросов, PHP: [^p^], всего: [^t^], откуда взят документ [^s^]', 0, 'a:0:{}', 0, ''),
(135, 1, 0, 'byAd', 'BannerY Ad', 0, 46, 0, '<p><a href="[[++bannery_click]]/[[+adposition]]"><img src="[[+image]]" alt="[[+name]]" title="[[+description]]"/></a></p>\n<p>Banner with extra params (available as placeholders in banner URL):<br />\n<a href="[[++bannery_click]]/[[+adposition]]?id=[[*id]]&amp;something=123"><img src="[[+image]]" alt="[[+name]]" /></a></p>\n', 0, NULL, 0, 'core/components/bannery/elements/chunks/chunk.byad.tpl'),
(136, 2, 0, 'slider', '', 0, 12, 0, '{assign var="current_page" value=$modx->resource->get(''id'')}\n{assign var="selected_pages_arr" value=explode('','', $selected_pages)}\n\n{if $slider_show_type == ''everywhere'' || ($slider_show_type == ''main-only'' && $current_page == 1) || ($slider_show_type == ''38'' && in_array($current_page, $selected_pages_arr))}\n\n    <section class="slider">\n        <div class="slick-slider">\n            [[!BannerY? \n                &position=`1` \n                &tpl=`slide`\n                &sortby=`id`\n                &sortdir=`ASC`\n                &limit=`0`\n            ]]\n             \n        </div>\n        <div class="arrows"><div class="wrapper"></div></div>\n        <style>@media (min-width: 768px) { .header-main { margin-top: 275px; position: absolute; } }</style>\n    </section>\n   \n{/if}', 0, 'a:0:{}', 0, ''),
(137, 2, 0, 'slide', '', 0, 12, 0, '<div>\n    <div style="background-image: url(''[[!phpthumbof? &input=`[[+image]]` &options=`w=1920&h=641&zc=1`]]'')" class="slide-item">\n        [[-<img data-lazy="[[!phpthumbof? &input=`[[+image]]` &options=`w=1920&h=641&zc=1`]]" alt="[[+name]]" title="[[+description]]"/>]]\n        <div class="banner_description">\n            <div class="banner_wrapper">\n                [[-<p class="banner_name">[[+name]]</p>]]\n                \n                [[+description:notempty=`\n                    <p class="banner_name">[[+description:nl2br]]</p>\n                `]]\n                \n                [[+url:notempty=`\n                    <p class="banner_btn"><a href="[[+url]]">Перейти</a></p>\n                `]]\n            \n            </div>\n            \n        </div>\n    </div>\n</div>', 0, 'a:0:{}', 0, ''),
(156, 2, 0, 'product-search', '', 0, 17, 0, '<div class="sgrid-4">\n    <div class="goods-item">\n        <div class="goods-title"><a href="[[~[[+id]]]]" title="[[+pagetitle]]">[[+pagetitle]]</a></div>\n        <div class="goods-image">\n            <a href="[[~[[+id]]]]" title="[[+pagetitle]]">\n                <img src="[[phpthumbof? &input=`[[+tv.image]]` &options=`w=200&h=130&zc=1&fltr[]=size`]]" alt="[[+pagetitle]]" title="[[+pagetitle]]">\n            </a>\n        </div>\n        <div class="goods-descr">\n            <p>Бренд: [[+tv.brand:pdofield=`pagetitle`]]</p>\n            [[+tv.sku:notempty=`<div class="goods-sku">Артикул: <b>[[+tv.sku]]</b></div>`]]\n            [[+introtext:notempty=`<div class="goods-intro">[[+introtext:nl2br]]</div>`]]\n    		<p>[[$sendtobasketinlist?&id=`[[+id]]`&pagetitle=`[[+pagetitle]]`&tv.price=`[[+tv.price]]`]]</p>\n        </div>\n    </div>\n</div>', 0, 'a:0:{}', 0, ''),
