(163, 2, 0, 'defaultForm2', '', 0, 11, 0, '<form class="form form-custom" action="[[~[[*id]]]]" method="post"><input type="hidden" name="nospam:blank" value="" />\n    <div class="form-group">\n        [[!+fi.error.name]]\n        <input id="name" type="text" name="name" value="[[!+fi.name]]" placeholder="Ваше имя" required>\n    </div>\n\n    <div class="form-group">\n        [[!+fi.error.contact]]\n        <input id="contact"  type="text" name="contact" value="[[!+fi.contact]]" placeholder="Телефон или e-mail" required>\n    </div>\n\n    <div>\n       <input class="button" type="submit" value="Отправить" />\n    </div>\n</form>', 0, 'a:0:{}', 0, ''),
