INSERT INTO `modx_site_htmlsnippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `static`, `static_file`) VALUES
(211, 2, 0, 'Копия header', '', 0, 12, 0, '<!DOCTYPE html>\n<html> \n<head>  \n    <base href="[[!++site_url]]">\n    <title>[[*meta_title:default=`[[*pagetitle]]`]] | [[++site_name]] </title>\n    \n    <style>\n    \n     \n   .ya-phone a {\n    font-size: 28px !important;\n}\n        \n   .contacts a {\n    font-size: 22px;\n}\n\n\n@-webkit-keyframes blink6 {\n 10% { transform: scale(1, 1) rotate(80deg); }\n 20% { transform: scale(0, 0) rotate(160deg); }\n 100% { transform: scale(0, 0) rotate(0deg); }\n}\n@keyframes blink6 {\n 10% { transform: scale(1, 1) rotate(80deg); }\n 20% { transform: scale(0, 0) rotate(160deg); }\n 100% { transform: scale(0, 0) rotate(0deg); }\n}\n#blink6 {\n  position: relative;\n  display: inline-block;\n  color: #139df2;\n  \n  \n}\n#blink6:after, #blink6:before {\n  content: "";\n  position: absolute; top: 0; left: 0;\n  display: block;\n  width: 100px;\n  height: 100px;\n  background-image: \n    radial-gradient(rgba(255,255,255,1), rgba(255,255,255,0) 30%),\n    linear-gradient(45deg, rgba(0,0,0,0) 49%, rgba(255,255,255,.4) 50%, rgba(0,0,0,0) 51%),\n    linear-gradient(135deg, rgba(0,0,0,0) 49%, rgba(255,255,255,.4) 50%, rgba(0,0,0,0) 51%);\n  -webkit-animation: blink6 10s linear infinite;\n  animation: blink6 10s linear infinite;\n  transform: scale(0, 0) rotate(0deg);\n}\n#blink6:before {\n  top: -30%;\n  right: 0; left: auto;\n  -webkit-animation-delay: 5s;\n  animation-delay: 5s;\n}\n\n\n\n\n\n@-webkit-keyframes blink7 {\n 10% { transform: scale(1, 1) rotate(80deg); }\n 20% { transform: scale(0, 0) rotate(160deg); }\n 100% { transform: scale(0, 0) rotate(0deg); }\n}\n@keyframes blink7 {\n 10% { transform: scale(1, 1) rotate(80deg); }\n 20% { transform: scale(0, 0) rotate(160deg); }\n 100% { transform: scale(0, 0) rotate(0deg); }\n}\n#blink7 {\n  position: relative;\n  display: inline-block;\n  color: #139df2;\n  \n  \n}\n#blink7:after, #blink7:before {\n  content: "";\n  position: absolute; top: 0; left: 0;\n  display: block;\n  width: 100px;\n  height: 100px;\n  background-image: \n    radial-gradient(rgba(255,255,255,1), rgba(255,255,255,0) 30%),\n    linear-gradient(45deg, rgba(0,0,0,0) 49%, rgba(255,255,255,.4) 50%, rgba(0,0,0,0) 51%),\n    linear-gradient(135deg, rgba(0,0,0,0) 49%, rgba(255,255,255,.4) 50%, rgba(0,0,0,0) 51%);\n  -webkit-animation: blink6 10s linear infinite;\n  animation: blink6 10s linear infinite;\n  transform: scale(0, 0) rotate(0deg);\n}\n#blink7:before {\n  top: -30%;\n  right: 0; left: auto;\n  -webkit-animation-delay: 3s;\n  animation-delay: 7s;\n}\n\n\n\n    </style>\n    \n   <!--[if IE]>\n        <style type="text/css">\n                .full-wrapper {flex:none !importants}\n                </style>\n<![endif]-->\n    \n    <!-- [if gt IE 7]>\n    <link rel="stylesheet" type="text/css" href="[[!++site_url]]ie.css" />\n<![endif]-->\n    \n   \n    \n  \n    <meta http-equiv="Content-Type" content="text/html; charset=[[++modx_charset]] " />\n    <meta name="description" content="[[*description]]"/>\n    <meta name="keywords" content="[[*keywords]]"/>\n    <meta http-equiv="X-UA-Compatible" content="IE=edge">\n    <meta name="yandex-verification" content="52ffb590fc6f4f67" />\n    <meta name="google-site-verification" content="fu2vyUqwhYpCLBE3c35xiUTpmFKPBRa0TfPTPWZ9XAc" />\n    <meta name="yandex-verification" content="66fde7d2662ed2e8" />\n    <meta name="viewport" content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0">\n    <meta http-equiv="X-UA-Compatible" content="ie=edge">\n    <link href="https://fonts.googleapis.com/css?family=Open+Sans:400,600&amp;subset=cyrillic" rel="stylesheet">\n    <link rel="stylesheet" type="text/css" href="[[!++site_url]]assets/templates/default/css/normalize.css" />\n    <link rel="stylesheet" type="text/css" href="[[!++site_url]]assets/templates/default/css/style.css" />\n    <link rel="stylesheet" href="[[!++site_url]]assets/templates/default/css/font-awesome.min.css">\n    <link rel="stylesheet" href="[[!++site_url]]assets/extra/magnific-popup/magnific-popup.css" />\n    <link rel="stylesheet" type="text/css" href="[[!++site_url]]assets/extra/slick/slick.css" />\n    <link rel="stylesheet" type="text/css" href="[[!++site_url]]assets/templates/default/css/adapt.css" />\n    <link rel="icon" href="[[!++site_url]]favicon.png">\n    <!--[if IE]><link rel="shortcut icon" href="[[!++site_url]]favicon.ico"><![endif]-->\n    [[getSiteSettings? &contactTpl=`@INLINE <p>[[+icon]] [[+value]] [[+text]]</p>`]]\n[[$scripts]]\n\n<style>\n   \n    \n</style>\n \n<script>\n  (function(i,s,o,g,r,a,m){i[''GoogleAnalyticsObject'']=r;i[r]=i[r]||function(){\n  (i[r].q=i[r].q||[]).push(arguments)},i[r].l=1*new Date();a=s.createElement(o),\n  m=s.getElementsByTagName(o)[0];a.async=1;a.src=g;m.parentNode.insertBefore(a,m)\n  })(window,document,''script'',''https://www.google-analytics.com/analytics.js'',''ga'');\n\n  ga(''create'', ''UA-87786776-8'', ''auto'');\n  ga(''send'', ''pageview'');\n\n</script>\n</head>\n<body>\n    <!-- Yandex.Metrika counter -->\n<script type="text/javascript">\n    (function (d, w, c) {\n        (w[c] = w[c] || []).push(function() {\n            try {\n                w.yaCounter42493949 = new Ya.Metrika({\n                    id:42493949,\n                    clickmap:true,\n                    trackLinks:true,\n                    accurateTrackBounce:true,\n                    webvisor:true\n                });\n            } catch(e) { }\n        });\n\n        var n = d.getElementsByTagName("script")[0],\n            s = d.createElement("script"),\n            f = function () { n.parentNode.insertBefore(s, n); };\n        s.type = "text/javascript";\n        s.async = true;\n        s.src = "https://mc.yandex.ru/metrika/watch.js";\n\n        if (w.opera == "[object Opera]") {\n            d.addEventListener("DOMContentLoaded", f, false);\n        } else { f(); }\n    })(document, window, "yandex_metrika_callbacks");\n$(document).ready(function(){\n  $(''#prices'').addClass(''in'');\n});\n</script>\n<noscript><div><img src="https://mc.yandex.ru/watch/42493949" style="position:absolute; left:-9999px;" alt="" /></div></noscript>\n<!-- /Yandex.Metrika counter -->\n    <div class="full-wrapper">\n        <header class="header">\n            [[smarty? &tpl=`slider` &slider_show_type=`[[+set.slider-show-type]]` &selected_pages=`[[+set.slider-pages]]`]]\n            <div class="header-wrapper">\n                <div class="wrapper">\n                    <div class="header-top">\n                        <div class="box float">\n                            <div class="sgrid-10">\n                                <div class="contacts">\n                                    \n                                    <p>\n<i class="fa fa-fw fa-envelope"></i>\n<noindex>\n<a rel="nofollow" href="mailto:info@uborka-kvartir-msk.ru" style="font-size:14px;">info@uborka-kvartir-msk.ru</a>\n</noindex>\n</p>\n                                    \n                                    \n                                    \n                                    <div><span style="display: block;\n    font-size: 26px;\n    margin-bottom: 5px !important;\n    padding-left: 5px; font-weight:bold;"><i class="fa fa-fw fa-phone"></i> Позвоните нам:\n</span><br>\n\n<div class="ya-phone"><a href="tel:+74952263474" id="blink6">+7 (495) 226-34-74</a></div>\n</div>\n<!--<p>\n<i class="fa fa-fw fa-phone"></i>\n<a href="tel:+79160622358">+7 (916) 062-23-58</a>\n</p>-->\n\n                                    \n                                    \n                                    \n                                    <!--[[+set.contacts.header]]-->\n                                </div>\n                                <br>\n                                <div style="font-size:18px; text-align:right;"><strong>Заявки на уборку</strong> принимаются <strong>с 9 до 23 часов ежедневно</strong> без выходных и праздничных дней. <!--[[+set.contacts.text1]]--></div>\n                            </div>\n                            <div class="sgrid-2" id="blink6">\n                                <div class="write-us"><a href="[[~2]]#write_us"><i class="fa fa-paper-plane"></i>Свяжитесь с нами</a></div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class="header-main">\n                        <div class="box float">\n                            <div class="sgrid-2">\n                                <div class="logo-block" id="blink7">\n                                    <a href="[[!++site_url]]" class="logo">[[+set.logo:ne=``:then=`<img src="userfiles/[[+set.logo]]" alt="">`:else=`[[+set.site-name]]`]]</a>\n                                </div>\n                            </div>\n                            <div class="sgrid-8">\n                                <div class="mobile-menu">\n                                    <div>\n                                        <i></i>\n                                        Наши услуги\n                                    </div>\n                                    <div>\n                                        <i></i>\n                                        Меню\n                                    </div>\n                                </div>\n                                <nav class="main-menu">\n                                    [[- меню ]] \n                                    [[pdoMenu?  \n                                        &startId=`0` \n                                        &level=`1`\n                                        &outerClass=`menu--horizontal`\n                                        &levelClass=`menu--horizontal_item`\n        			                    &where=`{"template:!=":2}`\n        			                    &tpl=`@INLINE <li[[+classes]]><a href="[[+link]]" [[+attributes]] title="[[+menutitle]]">[[+menutitle]]</a>[[+wrapper]]</li>`\n                                    ]]\n                                </nav>\n                            </div>\n                            <div class="sgrid-2">\n                                [[$share]]\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                \n            </div>\n        </header>\n        \n        <div class="main">\n            [[- хлебные крошки ]] \n           \n            \n            <div class="wrapper">\n                [[*id:is=`1`:then=`[[$cats]]`]]\n                \n                [[pdoCrumbs? &showHome=`1` &showAtHome=`0`]]\n                \n                <div class="box float">\n                    \n                    [[*id:ne=`8`:and:if=`[[*id]]`:ne=`9`:then=`\n                        <aside class="sgrid-3">\n                		    [[$sidebar]]\n                		</aside>\n                	`]]\n                    \n                    <main class="[[*id:ne=`8`:and:if=`[[*id]]`:ne=`9`:then=`sgrid-9`:else=`sgrid-12`]]">\n                        \n                        <div class="box inline">\n                            <div class="[[*title2:is=``:then=`sgrid-12`:else=`sgrid-6`]] marbot">\n                                <h1>[[!*longtitle:default=`[[!*pagetitle]]`]]</h1>\n                            </div>\n                            [[*title2:notempty=`\n                                <div class="sgrid-6 marbot">\n                                    <p class="block_title">[[*title2]]</p>\n                                </div>\n                            `]]\n                        </div>\n                        \n                        <div class="content">', 0, 'a:0:{}', 0, ''),
(212, 2, 0, 'Копия footer', '', 0, 12, 0, '           			</div>\n        			\n        			<div class="clear"></div>\n                    <div class="no__decor">[[!showImages? page_image1=`[[*footer-image1]]` &page_image2=`[[*footer-image2]]` &thumbOptionsBig=`w=980&h=350&zc=1&fltr[]=size` &thumbOptionsSmall=`w=480&h=280&zc=1&fltr[]=size`]]</div>\n            		</main>\n                </div>\n            </div>\n        </div>\n        [[*id:ne=`2`:then=`[[$fos]]`]]\n    </div>\n    <footer>\n        <div class="wrapper">\n            <div class="footer">\n                <div class="box inline">\n\n                    <div class="sgrid-6">\n                        <p class="copy">\n                        <a style="color:#fff;" href="[[!++site_url]]stati/">Статьи</a> <br />    \n                        &copy; [[currentYear]] [[+set.site-name:default=`[[++site_name]]`]]<br/>+7 (495) 226-34-74 ; +7 (916) 062-23-58</p>\n                       \n                    </div>\n                    \n                    <div class="sgrid-6">\n                        <div class="footer_fabrica">\n                            <noindex></noindex><a href="http://www.fabricasaitov.ru" target="_blank" class="fabrica_logo"><img src="[[!++site_url]]assets/templates/default/images/fabrica3.png" alt="Fabrica Saitov"></a>    </noindex>\n                            <noindex>[[$lirucounter]]</noindex>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </footer>\n    [[$ya-metrika]]\n    [[$google-analytics]]\n    [[-!viewCounter]]\n<!-- {literal} -->\n        <script type=''text/javascript''>\n        window[''li''+''veT''+''e''+''x''] = true,\n        window[''liv''+''e''+''TexI''+''D''] = 135507,\n        window[''liveT''+''ex_obje''+''ct''] = true;\n        (function() {\n        var t = document[''cre''+''a''+''te''+''El''+''e''+''ment''](''script'');\n        t.type =''text/javascript'';\n        t.async = true;\n        t.src = ''//cs1''+''5.li''+''vetex.ru''+''/js/''+''clien''+''t.''+''js'';\n        var c = document[''getEle''+''mentsB''+''yTagNam''+''e''](''script'')[0];\n        if ( c ) c[''p''+''ar''+''ent''+''Node''][''inse''+''rtB''+''efore''](t, c);\n        else document[''doc''+''ument''+''E''+''l''+''e''+''ment''][''first''+''Chi''+''ld''][''appe''+''nd''+''C''+''hil''+''d''](t);\n        })();\n        </script>\n        <!-- {/literal} -->\n        \n<div class="fon"></div>\n\n<!-- атрибут required говорит, что заполнение поля обязательно -->\n<form method="POST" id="feedback-form">\n    <h2 class="block_title">Онлайн заказ</h2>\n<input type="text" name="nameFF" required placeholder="Ваше имя">\n<input type="text" name="contactFF" required placeholder="Телефон">\n<input type="submit" value="отправить">\n</form>\n\n<script>\ndocument.getElementById(''feedback-form'').addEventListener(''submit'', function(evt){\n  var http = new XMLHttpRequest(), f = this;\n  evt.preventDefault();\n  http.open("POST", "contacts.php", true);\n  http.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");\n  http.send("nameFF=" + f.nameFF.value + "&contactFF=" + f.contactFF.value);\n  http.onreadystatechange = function() {\n    if (http.readyState == 4 && http.status == 200) {\n      alert(http.responseText + '', Ваше сообщение получено.\\nМы свяжемся с Вами в ближайшее время.'');    \n        $(''.fon'').hide(''slow'');\n        $(''#feedback-form'').hide(''slow'');\n    }\n  }\n  http.onerror = function() {\n    alert(''Извините, данные не были переданы'');\n  }\n}, false);\n$( document ).ready(function() {\n    $(''.floating-right'').on(''click'',function(){\n        $(''.fon'').show(''slow'');\n        $(''#feedback-form'').show(''slow'');\n    });\n    $(''.fon'').on(''click'',function(){\n        $(''.fon'').hide(''slow'');\n        $(''#feedback-form'').hide(''slow'');\n    });\n});\n</script>\n<script src="[[!++site_url]]assets/templates/default/js/mobile.js"></script>\n\n\n<!-- Yandex.Metrika counter -->\n<script type="text/javascript">\n    (function (d, w, c) {\n        (w[c] = w[c] || []).push(function() {\n            try {\n                w.yaCounter44950984 = new Ya.Metrika({\n                    id:44950984,\n                    clickmap:true,\n                    trackLinks:true,\n                    accurateTrackBounce:true,\n                    webvisor:true,\n                    trackHash:true,\n                    ecommerce:"dataLayer"\n                });\n            } catch(e) { }\n        });\n\n        var n = d.getElementsByTagName("script")[0],\n            s = d.createElement("script"),\n            f = function () { n.parentNode.insertBefore(s, n); };\n        s.type = "text/javascript";\n        s.async = true;\n        s.src = "https://mc.yandex.ru/metrika/watch.js";\n\n        if (w.opera == "[object Opera]") {\n            d.addEventListener("DOMContentLoaded", f, false);\n        } else { f(); }\n    })(document, window, "yandex_metrika_callbacks");\n</script>\n<noscript><div><img src="https://mc.yandex.ru/watch/44950984" style="position:absolute; left:-9999px;" alt="" /></div></noscript>\n<!-- /Yandex.Metrika counter -->\n\n\n<script type="text/javascript" id="meedget_script" src="https://meedget.ru/js/client.min.js?meedget_id=5419"></script>\n        \n</body>\n</html>', 0, 'a:0:{}', 0, ''),
(213, 0, 0, 'comment_auth_tpl', 'This tpl for displaying information not authorized users.', 0, 58, 0, '<div id="mt_cf_conversationReply">\n	<form action="" method="post" enctype="multipart/form-data">\n		<input type="hidden" name="token" value="3fffcee5f7d88">\n		<div class="mt_post mt_hasControls mt_logInToReply" id="reply">\n			<div class="mt_avatar"><img src="[[+avatar]]" alt="" class="mt_avatar_img"></div>\n			<div class="mt_postContent mt_thing">\n				<div class="mt_postBody">\n					[[+noLogin]]\n				</div>\n			</div>\n		</div>\n	</form>\n</div>', 0, NULL, 0, ''),
(214, 1, 0, 'tpl.ecMessages.Row', '', 0, 59, 0, '<div id="ec-[[+thread_name]]-message-[[+id]]" class="ec-message">\n    <p><strong>[[+user_name]]</strong><span class="ec-message__date"> [[+date:dateAgo]]</span></p>\n    <div class="ec-stars">\n        <span class="rating-[[+rating]]"></span>\n    </div>\n    <p>[[+text]]</p>\n    [[+reply_text]]\n</div>\n\n<!--ec_reply_text <div class="ec-message__reply">[[+reply_author]]<p>[[+reply_text]]</p></div>-->\n<!--ec_reply_author <p><strong>[[+reply_author]]</strong></p>-->', 0, NULL, 0, 'core/components/easycomm/elements/chunks/chunk.ec_messages_row.tpl'),
(215, 1, 0, 'tpl.ecForm', '', 0, 59, 0, '<h2>Оставить отзыв<!--[[%ec_fe_message_add]]--></h2>\n<form class="form well ec-form" method="post" role="form" id="ec-form-[[+fid]]" data-fid="[[+fid]]" action="">\n    <input type="hidden" name="thread" value="[[+thread]]">\n\n    <div class="form-group ec-antispam">\n        <label for="ec-[[+antispam_field]]-[[+fid]]" class="control-label">[[%ec_fe_message_antismap]]</label>\n        <input type="text" name="[[+antispam_field]]" class="form-control" id="ec-[[+antispam_field]]-[[+fid]]" value="" />\n    </div>\n\n    <div class="form-group">\n        <label for="ec-user_name-[[+fid]]" class="control-label">[[%ec_fe_message_user_name]]</label>\n        <input type="text" name="user_name" class="form-control" id="ec-user_name-[[+fid]]" value="[[+user_name]]" />\n        <span class="ec-error help-block" id="ec-user_name-error-[[+fid]]"></span>\n    </div>\n\n    <!--<div class="form-group">\n        <label for="ec-user_email-[[+fid]]" class="control-label">[[%ec_fe_message_user_email]]</label>\n        <input type="text" name="user_email" class="form-control" id="ec-user_email-[[+fid]]" value="[[+user_email]]" />\n        <span class="ec-error help-block" id="ec-user_email-error-[[+fid]]"></span>\n    </div>-->\n\n    <div class="form-group">\n        <label for="ec-user_contacts-[[+fid]]" class="control-label">Телефон<!--[[%ec_fe_message_user_contacts]]--></label>\n        <input type="text" name="user_contacts" class="form-control" id="ec-user_contacts-[[+fid]]" value="[[+user_contacts]]" />\n        <span class="ec-error help-block" id="ec-user_contacts-error-[[+fid]]"></span>\n    </div>\n\n    <div class="form-group">\n        <label for="ec-subject-[[+fid]]" class="control-label">[[%ec_fe_message_subject]]</label>\n        <input type="text" name="subject" class="form-control" id="ec-subject-[[+fid]]" value="[[+subject]]" />\n        <span class="ec-error help-block" id="ec-subject-error-[[+fid]]"></span>\n    </div>\n\n    <div class="form-group">\n        <label for="ec-rating-[[+fid]]" class="control-label">[[%ec_fe_message_rating]]</label>\n        <input type="hidden" name="rating" id="ec-rating-[[+fid]]" value="[[+rating]]" />\n        <div class="ec-rating ec-clearfix" data-storage-id="ec-rating-[[+fid]]">\n            <div class="ec-rating-stars">\n                <span data-rating="1" data-description="[[%ec_fe_message_rating_1]]"></span>\n                <span data-rating="2" data-description="[[%ec_fe_message_rating_2]]"></span>\n                <span data-rating="3" data-description="[[%ec_fe_message_rating_3]]"></span>\n                <span data-rating="4" data-description="[[%ec_fe_message_rating_4]]"></span>\n                <span data-rating="5" data-description="[[%ec_fe_message_rating_5]]"></span>\n            </div>\n            <div class="ec-rating-description">[[%ec_fe_message_rating_0]]</div>\n        </div>\n        <span class="ec-error help-block" id="ec-rating-error-[[+fid]]"></span>\n    </div>\n\n    <div class="form-group">\n        <label for="ec-text-[[+fid]]" class="control-label">Ваш отзыв<!--[[%ec_fe_message_text]]--></label>\n        <textarea type="text" name="text" class="form-control" rows="5" id="ec-text-[[+fid]]">[[+text]]</textarea>\n        <span class="ec-error help-block" id="ec-text-error-[[+fid]]"></span>\n    </div>\n\n    [[+recaptcha]]\n\n    <div class="form-actions">\n        <input type="submit" onclick="yaCounter44950984.reachGoal(''ADD2''); return true;" class="btn btn-primary" name="send" value="[[%ec_fe_send]]" />\n    </div>\n</form>\n<div id="ec-form-success-[[+fid]]"></div>', 0, 'a:0:{}', 0, 'core/components/easycomm/elements/chunks/chunk.ec_form.tpl'),
(216, 1, 0, 'tpl.ecForm.ReCaptcha', '', 0, 59, 0, '<div class="form-group">\r\n    <div class="ec-captcha" id="ec-captcha-[[+fid]]"></div>\r\n    <span class="ec-error help-block" id="ec-captcha-error-[[+fid]]"></span>\r\n</div>', 0, NULL, 0, 'core/components/easycomm/elements/chunks/chunk.ec_form_recaptcha.tpl'),
