  <tr>\n          <td>\n            <p><em>Вискоза</em></p>\n          </td>\n          <td>\n            <p><em>с кистями</em></p>\n          </td>\n          <td>\n            <p><em>970</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td></td>\n          <td>\n            <p><em>без кистей</em></p>\n          </td>\n          <td>\n            <p><em>895</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Шелк</em></p>\n          </td>\n          <td>\n            <p><em>с кистями</em></p>\n          </td>\n          <td>\n            <p><em>1 290</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td></td>\n          <td>\n            <p><em>без кистей</em></p>\n          </td>\n          <td>\n            <p><em>1 195</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Хлопок</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>945</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td colspan="3"><b>Shaggy с длинным ворсом</b></td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Синтетика</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>580</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Шерсть</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>630</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Синтетический ковер на клееной основе</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>680</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Шерстяное изделие на клееной основе</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>750</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td colspan="3"><b>Ковры ручной работы</b></td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Шерсть</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>2 600</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Шелк</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>2 900</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Шерстяной безворсовый ковер</em></p>\n          </td>\n          <td>\n            <p><em>—</em></p>\n          </td>\n          <td>\n            <p><em>2 160</em></p>\n          </td>\n        </tr>\n      </tbody>\n    </table>\n    [[-<p>\n      <mark><strong>Внимание!</strong></mark> Мы снизили цены <strong>до 20 января 2018.</strong><strong>Закажите сегодня, до 20 января, предложение ограниченно! </strong>\n    </p>]]\n    <p><a href="[[!++site_url]]novosti/">Не забудьте посмотреть все наши Акции и Предложения</a></p>\n  </div>\n</section>', 0, 'a:0:{}', 0, '');
INSERT INTO `modx_site_htmlsnippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `static`, `static_file`) VALUES
(236, 2, 0, 'Популярные позиции', '', 0, 0, 0, '<section class="recommended">\n  <h2 class="block_title recommended__heading">Популярные позиции</h2>\n  <div class="popular recommended__popular">\n    <div class="popular__row">\n      <div class="popular__col">\n        <div class="pr-card popular__card">\n          <div class="pr-card__head">\n            <figure class="pr-card__figure"><img src="/assets/templates/default/images/recommended/1.jpg" alt="Стирка вискозного ковра" class="pr-card__img img-fluid"/></figure>\n          </div>\n          <div class="pr-card__body">\n            <h4 class="pr-card__heading pr-heading"><span class="pr-heading__mark">Стирка </span>вискозного ковра</h4>\n            <ul class="pr-options pr-card__options">\n              <li class="pr-options__item">Размер: 2 х 3 метра</li>\n              <li class="pr-options__item">Цена: 5&nbsp;370 Р.</li>\n            </ul>\n            <div class="pr-card__btn-group">\n              <button type="button" class="pr-card__btn b-btn b-btn--primary" data-envybox-trigger="open">Заказать</button>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div class="popular__col">\n        <div class="pr-card popular__card">\n          <div class="pr-card__head">\n            <figure class="pr-card__figure"><img src="/assets/templates/default/images/recommended/2.jpg" alt="Стирка синтетического ковра" class="pr-card__img img-fluid"/></figure>\n          </div>\n          <div class="pr-card__body">\n            <h4 class="pr-card__heading pr-heading"><span class="pr-heading__mark">Стирка </span>синтетического ковра</h4>\n            <ul class="pr-options pr-card__options">\n              <li class="pr-options__item">Размер: 2 х 3 метра</li>\n              <li class="pr-options__item">Цена: 1&nbsp;680 Р.</li>\n            </ul>\n            <div class="pr-card__btn-group">\n              <button type="button" class="pr-card__btn b-btn b-btn--primary" data-envybox-trigger="open">Заказать</button>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div class="popular__col">\n        <div class="pr-card popular__card">\n          <div class="pr-card__head">\n            <figure class="pr-card__figure"><img src="/assets/templates/default/images/recommended/3.jpg" alt="Стирка Shaggy ковра" class="pr-card__img img-fluid"/></figure>\n          </div>\n          <div class="pr-card__body">\n            <h4 class="pr-card__heading pr-heading"><span class="pr-heading__mark">Стирка </span>Shaggy ковра</h4>\n            <ul class="pr-options pr-card__options">\n              <li class="pr-options__item">Размер: 2 х 3 метра</li>\n              <li class="pr-options__item">Цена: 3&nbsp;480 Р.</li>\n            </ul>\n            <div class="pr-card__btn-group">\n              <button type="button" class="pr-card__btn b-btn b-btn--primary" data-envybox-trigger="open">Заказать</button>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div class="popular__col">\n        <div class="pr-card popular__card">\n          <div class="pr-card__head">\n            <figure class="pr-card__figure"><img src="/assets/templates/default/images/recommended/4.jpg" alt="Стирка шерстяного ковра" class="pr-card__img img-fluid"/></figure>\n          </div>\n          <div class="pr-card__body">\n            <h4 class="pr-card__heading pr-heading"><span class="pr-heading__mark">Стирка </span>шерстяного ковра</h4>\n            <ul class="pr-options pr-card__options">\n              <li class="pr-options__item">Размер: 2 х 3 метра</li>\n              <li class="pr-options__item">Цена: 2&nbsp;160 Р.</li>\n            </ul>\n            <div class="pr-card__btn-group">\n              <button type="button" class="pr-card__btn b-btn b-btn--primary" data-envybox-trigger="open">Заказать</button>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div class="popular__col">\n        <div class="pr-card popular__card">\n          <div class="pr-card__head">\n            <figure class="pr-card__figure"><img src="/assets/templates/default/images/recommended/5.jpg" alt="Стирка шерстяного ковра" class="pr-card__img img-fluid"/></figure>\n          </div>\n          <div class="pr-card__body">\n            <h4 class="pr-card__heading pr-heading"><span class="pr-heading__mark">Стирка </span>шерстяного ковра</h4>\n            <ul class="pr-options pr-card__options">\n              <li class="pr-options__item">Размер: 2.5 х 3.5 метра</li>\n              <li class="pr-options__item">Цена: 3&nbsp;150 Р.</li>\n            </ul>\n            <div class="pr-card__btn-group">\n              <button type="button" class="pr-card__btn b-btn b-btn--primary" data-envybox-trigger="open">Заказать</button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(237, 2, 0, 'дополнительные услуги страница химчистка стирка', '', 0, 0, 0, '<section class="in-price">\n  <h2>Дополнительные услуги по чистке ковров</h2>\n  <div class="table-responsive in-price__table-responsive">\n    <table class="in-price__table table table--bordered table--center table--head-bg">\n      <thead>\n        <tr>\n          <th nowrap="nowrap">Наименование</th>\n          <th nowrap="nowrap">Стоимость</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td>\n            <p><em>Вывоз ковра в день приема заявки</em></p>\n          </td>\n          <td>\n            <p><em>1000 руб.</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Срочная чистка за 24 часа</em></p>\n          </td>\n          <td>\n            <p><em>100% от стоимости по прайсу</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Доставка тяжелых ковров: более 15 м<sup>2</sup>, тяжелее 40 кг или шириной свыше 4 м</em></p>\n          </td>\n          <td>\n            <p><em>+30%</em></p>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <p><em>Минимальный заказ	</em></p>\n          </td>\n          <td>\n            <p><em>1900 руб.</em></p>\n          </td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n</section>', 0, 'a:0:{}', 0, ''),
(238, 2, 0, 'Форма с калькулятором', '', 0, 0, 0, '<!-- Калькулятор начало -->\n[[$calcScript]]\n<script id="calc-pricelist" type="text/json">\n    [[getCleaningPriceList]]\n</script><a name="kalkylator"></a>\n<div data-overflow data-overflow-text="Калькулятор" class="b-calculate">\n    <h3 class="block_title">Калькулятор</h3>\n    <div class="b-calculate__inner">\n        \n        <div class="form-block">\n            <a name="zakaz1"></a>\n            <h2>Закажите уборку в течение 15 минут и получите скидку в 10%</h2>\n            <br/>\n            <form class="cleaning" onsubmit="ym(44950984, ''reachGoal'', ''zakazformatest''); return true;">\n                <input type="text" placeholder="Имя" name="name" required />            \n                <input type="text" placeholder="Телефон" name="phone" required />\n                <button>Заказать уборку со скидкой</button>          \n            </form>\n            <p style="font-size:12px; color:#fff;">* Нажимая на кнопку "Заказать уборку со скидкой", вы даете согласие на обработку своих персональных данных. <a href="[[!++site_url]]politika-konfidenczialnosti/"  target="_blank">Пользовательское соглашение</a> на обработку персональных данных</p>\n            <script src="http://megatimer.ru/s/074a500a55083d6d151f3c101ec07914.js"></script><br>\n        </div>\n        <div class="box inline calculator-wrapper form-block" style="display: block !important;">\n            <h6 class="block_title2">ИЛИ</h6>\n            <h2 class="block_title1" id="calc-block" style="content: none !important;"><a href="[[~[[*id]]]]#">Расчет стоимости уборки [[*nameprise]]</a></h2>\n                \n            <div class="sgrid-4 calculator-item hidden">\n                <h4 style="color:#fff;">Тип помещения:</h4>\n                <label for="flat">\n                    <input class="js-place-type" name="place-type" id="flat" type="radio" value="flat" checked>\n                    <div class="input-block">\n                        <span class="icon-block">\n                            <img src="userfiles/images/icons/room.png" alt="Квартира">\n                        </span>\n                        <span style="color:#fff;" >Квартира</span>\n                    </div>\n                </label>\n                <label for="cottage">\n                    <input class="js-place-type" name="place-type" id="cottage" type="radio" value="cottage">\n                    <div class="input-block">\n                        <span class="icon-block">\n                            <img src="userfiles/images/icons/house.png" alt="Коттедж">\n                        </span>\n                        <span style="color:#fff;" >Коттедж</span>\n                    </div>\n                </label>\n            </div>\n            <div class="sgrid-4 calculator-item hidden">\n                <h4 style="color:#fff;" >Тип уборки:</h4>\n                <label>\n                    <input type="radio" class="js-cleaning-type" name="cleaning-type" value="supporting" checked>\n                    <div class="input-block">\n                        <span class="icon-block">\n                            <img src="userfiles/images/icons/oil.png" alt="Поддерживающая">\n                        </span>\n                        <span style="color:#fff;" >Поддерживающая</span>\n                    </div>\n                </label>\n                <label>\n                    <input type="radio" class="js-cleaning-type" name="cleaning-type" value="general">\n                    <div class="input-block">\n                        <span class="icon-block">\n                            <img src="userfiles/images/icons/oil.png" alt="Генеральная">\n                            <img src="userfiles/images/icons/oil.png" alt="Генеральная">\n                        </span>\n                        <span style="color:#fff;" >Генеральная</span>\n                    </div>\n                </label>\n                <label>\n                    <input type="radio" class="js-cleaning-type" name="cleaning-type" value="afterBuilding">\n                    <div class="input-block">\n                        <span class="icon-block">\n                            <img src="userfiles/images/icons/oil.png" alt="Послестроительная">\n                            <img src="userfiles/images/icons/oil.png" alt="Послестроительная">\n                            <img src="userfiles/images/icons/oil.png" alt="Послестроительная">\n                        </span>\n                        <span style="color:#fff;" >Послестроительная</span>\n                    </div>\n                </label>\n            </div>\n            <div class="sgrid-4 calculator-item hidden">\n                <h4 style="color:#fff;" >Общая площадь помещения для уборки (м²):</h4>\n                <input type="number" class="js-place-area">\n            </div>\n            <div class="sgrid-12 hidden">\n                <h2 class="block_title js-slide-toggle" data-toggle-id="2" style="color:#fff;" > Дополнительные услуги</h2>\n                <div class="js-sliding-block" data-toggle-id="2" style="display:none;">\n                    <h3 class="block_title js-slide-toggle" data-toggle-id="2" style="color:#fff;" ><img src="userfiles/images/icons/sponge.png" alt="Услуги"> Услуги </h3>\n                    <div class="js-sliding-block" data-toggle-id="1" >\n                        <small class="small-text" style="color:#fff;" >\n                            Также мы готовы по вашей заявке выполнить работы которые необходимы Вам, но не включенные в список услуг*.<br>\n                            Стоимость услуг устанавливается в соответствии с прайс-листом по строке дополнительные работы.\n                        </small>\n                        <div class="box inline services-list">\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="duhShkaf">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--1">\n                                        <img src="userfiles/images/icons/oven.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Очистка духового шкафа</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Количество шт.:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="microwave">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--2">\n                                        <img src="userfiles/images/icons/microwave-oven.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Очистка микроволновой печи</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Количество шт.:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="holod">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--3">\n                                        <img src="userfiles/images/icons/fridge-1.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Очистка холодильника изнутри, без разморозки</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Количество шт.:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="holodRazmor">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--4">\n                                        <img src="userfiles/images/icons/fridge.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Очистка холодильника изнутри, с разморозкой</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Количество шт.:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="posuda">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--5">\n                                        <img src="userfiles/images/icons/dishes.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Мойка посуды</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Одна наполненная мойка:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="glazhka">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--6">\n                                        <img src="userfiles/images/icons/iron.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Глажка белья</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >30 минут:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="zhaluzi">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--7">\n                                        <img src="userfiles/images/icons/blinds.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Чистка жалюзи</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Количество шт.:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="okna">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--8">\n                                        <img src="userfiles/images/icons/windows.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Мойка окон</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Количество створок:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="setka">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--8">\n                                        <img src="userfiles/images/icons/moskito.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Мойка москитных сеток</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >Количество шт.:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4 js-service-block calculator-item" data-service-key="extraWork">\n                                <div class="services-item">\n                                    <div class="service-icon service-icon--8">\n                                        <img src="userfiles/images/icons/gloves.png" alt="">\n                                    </div>\n                                    <h4><span style="color:#fff;" >Дополнительные работы по заявке клиента</span></h4>\n                                    <span class="service-block__measure" style="color:#fff;" >1 чел./час:</span>\n                                    <div class="js-spin-wrapper">\n                                        <div class="js-spin-minus spin-item">-</div>\n                                        <input type="text" class="js-spin-value" value="0">\n                                        <div class="js-spin-plus spin-item">+</div>                \n                                    </div>\n                                    <div class="js-service-subprice"></div>\n                                </div>\n                            </div>\n                            <div class="sgrid-4">\n                                <div class="services-sum">\n                                    <h4 style="color:#fff;" >Общая стоимость дополнительных услуг:</h4>\n                                    \n                                    <div class="services-sum-price" style="color:#fff;" >\n                                        <span class="js-service-total-price" style="color:#fff;" ></span> руб.\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <p style="color:#fff;" ><b>Химчистка оплачивается дополнительно согласно прайсу</b></p>\n           \n                    </div>\n               </div>\n               \n                      <div class="total-sum-wrapper" style="background: none !important;">\n                            <h4 style="color:#fff;" >Общая стоимость уборки</h4>\n                            [[-<h4 style="color:#fff;" >закажите сейчас онлайн и получите скидку 5%</h4>]]\n                            <div class="total-price">\n                                <span class="js-total-price"></span> руб.\n                            </div>\n                            <br>\n                            <p class="js-afterBuilding-show" style="display: none;">Цена является ориентировочной и для определения окончательной стоимости работ требуется выезд менеджера</p>\n                            <a class="button js-calc-open-modal" href="#calc-modal" style="font-size: 17px !important; font-weight: bold !important;">Рассчитать и заказать</a>\n                        </div>\n               \n               \n            </div>\n            <div style="display: none;">\n                <div id="calc-modal">\n                    [[!FormIt?\n                        &hooks=`spam,saveOrderId,email,FormItAutoResponder,redirect`\n                        &emailTpl=`calcEmailReport` \n                        &emailTo=`[[+set.contacts.email1:default=`[[++emailsender]]`]]` \n                        &emailSubject=`Заявка на оказание клининговых услуг с сайта [[++site_name]]`\n                        &emailFrom=`webmaster@[[domain]]`\n                        &emailFromName=`[[++site_name]]`\n                        &fiarFrom =`webmaster@[[domain]]`\n                        &fiarTpl=`calcEmailReportClient`\n                        &fiarFromName=`[[++site_name]]`\n                        &fiarSubject=`Вами сделан заказ на сайте [[++site_name]]`\n                        &redirectTo=`81`\n                    ]]\n                    \n                    <div class="popap-title">Заявка на оказание клининговых услуг</div>\n                    \n                    <form action="" method="post" class="js-calc-order-form ob-form">\n                        <input type="hidden" name="nospam:blank" value="" />\n                    \n                        <input type="hidden" class="js-object-to-clean-input" name="object-to-clean">\n                        <input type="hidden" class="js-cleaning-type-input" name="cleaning-type">\n                        <input type="hidden" class="js-area-input" name="area">\n                        <input type="hidden" class="js-cleaning-price-input" name="cleaning-price">\n                        <input type="hidden" class="js-extra-services-input" name="extra-services">\n                        <input type="hidden" class="js-total-price-input" name="total-price">\n                        \n                        <ul class="ob-list ob-form__list">\n                            <li class="ob-list__item"><p class="object-item"><b>Объект:</b> <span class="js-object-to-clean-element"></span></p></li>\n                            <li class="ob-list__item"><p class="object-item"><b>Тип уборки:</b> <span class="js-cleaning-type-element"></span></p></li>\n                            <li class="ob-list__item"><p class="object-item"><b>Площадь:</b> <span class="js-area-element"></span> м²</p></li>\n                            <li class="ob-list__item"><p class="object-item"><b>Стоимость уборки:</b> <span class="js-cleaning-price-element"></span> руб.</p></li>\n                            <li class="ob-list__item"><p class="object-item"><b>Дополнительные услуги:</b> <span class="js-extra-services-element"></span></p></li>\n                            <li class="ob-list__item"><p class="object-item"><b>Общая стоимость:</b> <span class="js-total-price-element"></span> руб.</p></li>\n                            <li class="ob-list__item"></li>\n                            <li class="ob-list__item"></li>\n                            <li class="ob-list__item"></li>\n                            <li class="ob-list__item"></li>\n                        </ul>\n                        <div class="clearfix ob-form__row">\n                            <div class="form-group ob-form__group">\n                                <label class="js-afterBuilding-hide">Дата и время начала оказания услуг:*</label>\n                                <label class="js-afterBuilding-show" style="display: none;">Время для осмотра объекта уборки менеджером компании:</label>\n                                <div class="box float">\n                                    <div class="sgrid-6">\n                                        <input type="text" name="date" placeholder="Дата" required>\n                                    </div>\n                                    <div class="sgrid-6">\n                                        <input type="text" name="time" placeholder="Время" required>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="form-group ob-form__group ob-form__group--half">\n                                <label>Адрес объекта, метро:*</label>\n                                <input type="text" name="address" placeholder="Адрес" required />\n                            </div>\n                            <div class="form-group ob-form__group ob-form__group--half">\n                                <label>Ф.И.О.:*</label>\n                                <input type="text" name="fio" required>\n                            </div>\n                            <div class="form-group ob-form__group ob-form__group--half">\n                                <label>Телефон:*</label>\n                                <input type="text" name="phone" required>\n                            </div>\n                            <div class="form-group ob-form__group ob-form__group--half">\n                                <label>Email:*</label>\n                                <input type="email" name="email" required>\n                            </div>\n                            <div class="form-group ob-form__group">\n                                <label>Пожелания:</label>\n                                <textarea name="suggestions"></textarea>\n                            </div>\n                        </div>\n                        <div class="form-group checkbox-block">\n                            <label><input type="checkbox" name="hoover" class="js-hoover-checkbox" value="1"><span class="checkbox-icon"></span> <span>Требуется пылесос</span></label>\n                        </div>\n                        <div class="form-group checkbox-block">\n                            <label><input type="checkbox" name="oferta" checked="checked" class="js-oferta-checkbox" required><span class="checkbox-icon"></span> <span>Я согласен с публичной офертой</span></label> \n                            <p><a href="[[~82]]" target="_blank">Публичная оферта</a></p>\n                        </div>\n                        <div class="form-group">\n                            <input type="submit" value="Отправить" class="button">\n                        </div>\n                    </form>\n                </div>\n            </div>\n        </div>\n    </div>\n    <p style="font-size:12px; color:#000;">* Нажимая на кнопку "заказать", вы даете согласие на обработку своих персональных данных. <a href="[[!++site_url]]politika-konfidenczialnosti/"  target="_blank">Пользовательское соглашение</a> на обработку персональных данных.</p>\n</div>\n<!-- Калькулятор конец -->', 0, 'a:0:{}', 0, ''),
(239, 2, 0, 'Форма без калькулятора', '', 0, 0, 0, '<!-- Калькулятор начало -->\n<a name="kalkylator"></a>\n<div data-overflow data-overflow-text="Калькулятор" class="b-calculate">\n    <h3 class="block_title">Форма обратной связи</h3>\n    <div class="b-calculate__inner">\n        \n        <div class="form-block">\n            <a name="zakaz1"></a>\n            <h2>Закажите уборку в течение 15 минут и получите скидку в 10%</h2>\n            <br/>\n            <form class="cleaning" onsubmit="ym(44950984, ''reachGoal'', ''zakazformatest''); return true;">\n                <input type="text" placeholder="Имя" name="name" required />            \n                <input type="text" placeholder="Телефон" name="phone" required />\n                <button>Заказать уборку со скидкой</button>          \n            </form>\n            <p style="font-size:12px; color:#fff;">* Нажимая на кнопку "Заказать уборку со скидкой", вы даете согласие на обработку своих персональных данных. <a href="[[!++site_url]]politika-konfidenczialnosti/"  target="_blank">Пользовательское соглашение</a> на обработку персональных данных</p>\n            <script src="http://megatimer.ru/s/074a500a55083d6d151f3c101ec07914.js"></script><br>\n        </div>\n    </div>\n</div>\n<!-- Калькулятор конец -->', 0, 'a:0:{}', 0, ''),
(240, 2, 0, 'commentsWrapperTpl', '', 0, 12, 0, '<section class="inner-bottom-xs comments">\n		  <h3><span id="comment-total">[[+total]]</span> коммент.</h3>\n		  <div id="comments-wrapper">\n			<div class="comment-list" id="comments">\n			  [[+comments]]\n			</div>	\n		  </div>\n		  <div id="comments-tpanel">\n			<div id="tpanel-refresh"></div>\n			<div id="tpanel-new"></div>\n		  </div>\n		</section>', 0, 'a:0:{}', 0, ''),
(241, 2, 0, 'commentTpl', '', 0, 12, 0, '<div class="comment-item ticket-comment" id="comment-[[+id]]" data-parent="[[+parent]]" data-newparent="[[+new_parent]]" data-id="[[+id]]">\n			  <div class="row no-margin ticket-comment-body[[+bad]]">\n				<div class="col-lg-1 col-xs-12 col-sm-2 no-margin">\n				  <div class="avatar">\n					<img src="[[+avatar]]" alt="avatar">\n				  </div>\n				</div>\n				<div class="col-xs-12 col-lg-11 col-sm-10 no-margin-right">\n				  <div class="comment-body">\n					<div class="meta-info">\n					  <header class="row no-margin">\n						<div class="pull-left ticket-comment-rating inactive">\n						  <h4 class="author"><a href="[[+url]]#comment-[[+id]]">[[+fullname]]</a></h4>\n						  <span class="date">- [[+date_ago]]</span>\n						  <span class="likes plus"><span class="likes-count rating[[+rating_positive]][[+rating_negative]]">[[+rating]]</span><i class="icon fa fa-thumbs-up"></i></span>\n						  <span class="dislikes minus"><i class="icon fa fa-thumbs-down"></i></span>\n						  [[+has_parent]]\n						  <span class="ticket-comment-down"><a href="#" data-child="">&darr;</a></span>\n						</div>\n					  </header>\n					</div>\n					<div class="comment-content">[[+text]]</div>\n				  </div>\n				</div>\n			  </div>\n			  <div class="comments-list">[[+children]]</div>\n			</div>', 0, 'a:0:{}', 0, ''),
(242, 2, 0, 'commentFormTpl', '', 0, 12, 0, '<section id="reply-block" class="leave-reply">\n			  <h4 id="comment-new-link">\n				<a href="#" class="btn btn-default">[[%ticket_comment_create]]</a>\n			  </h4>\n			  <h3>Написать комментарий</h3>\n			  <p>Ваш email не будет опубликован. Обязательные поля отмечени символом <abbr class="required">*</abbr> </p>\n			  <div id="comment-form-placeholder">\n			  <form role="form" id="comment-form" action="" method="post" class="reply-form cf-style-1">\n				<div id="comment-preview-placeholder"></div>\n				<input type="hidden" name="thread" value="[[+thread]]"/>\n				<input type="hidden" name="parent" value="0"/>\n				<input type="hidden" name="id" value="0"/>\n				<div class="row field-row">\n				  <div class="col-xs-12 col-sm-6">\n					<label>[[%ticket_comment_name]]*</label>\n					<input class="le-input" name="name" value="[[+name]]" id="comment-name">\n					<span class="error"></span>\n				  </div>\n				  <div class="col-xs-12 col-sm-6">\n					<label>[[%ticket_comment_email]]*</label>\n					<input class="le-input" name="email" value="[[+email]]" id="comment-email">\n					<span class="error"></span>\n				  </div>\n				</div>\n				\n				<div class="row field-row">\n				  <div class="col-xs-12">\n					<label for="comment-editor"></label>\n					<textarea name="text" id="comment-editor" cols="30" rows="10" class="form-control"></textarea>\n				  </div>\n				</div>\n				<div class="row field-row">\n				  <div class="col-xs-12">\n					[[+captcha]]\n				  </div>\n				</div>\n				<button class="le-button big post-comment-button submit" type="submit" value="[[%ticket_comment_save]]" title="Ctrl + Shift + Enter">Написать</button>\n			  </form>\n			  </div>\n			</section>', 0, 'a:0:{}', 0, ''),
(243, 1, 0, 'tpl.Tickets.form.create', '', 0, 61, 0, '<form class="well create" method="post" action="" id="ticketForm">\n    <div id="ticket-preview-placeholder"></div>\n\n    <input type="hidden" name="tid" value="0"/>\n\n    <div class="form-group">\n        <label for="ticket-sections">[[%tickets_section]]</label>\n        <select name="parent" class="form-control" id="ticket-sections">[[+sections]]</select>\n        <span class="error"></span>\n    </div>\n\n    <div class="form-group">\n        <label for="ticket-pagetitle">[[%ticket_pagetitle]]</label>\n        <input type="text" class="form-control" placeholder="[[%ticket_pagetitle]]" name="pagetitle" value=""\n               maxlength="50" id="ticket-pagetitle"/>\n        <span class="error"></span>\n    </div>\n\n    <div class="form-group">\n        <textarea class="form-control" placeholder="[[%ticket_content]]" name="content" id="ticket-editor"\n                  rows="10"></textarea>\n        <span class="error"></span>\n    </div>\n\n    <div class="ticket-form-files">\n        [[+files]]\n    </div>\n\n    <div class="form-actions row">\n        <div class="col-md-6">\n            <input type="button" class="btn btn-default preview" value="[[%ticket_preview]]" title="Ctrl + Enter"/>\n        </div>\n        <div class="col-md-6 move-right">\n            <input type="button" class="btn btn-primary publish" name="publish" value="[[%ticket_publish]]" title=""/>\n            <input type="submit" class="btn btn-danger draft" name="draft" value="[[%ticket_draft]]"\n                   title="Ctrl + Shift + Enter"/>\n        </div>\n    </div>\n</form>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.form_create.tpl'),
(244, 1, 0, 'tpl.Tickets.form.update', '', 0, 61, 0, '<form class="well update" method="post" action="" id="ticketForm">\n    <div id="ticket-preview-placeholder"></div>\n\n    <input type="hidden" name="tid" value="[[+id]]"/>\n\n    <div class="form-group">\n        <label for="ticket-sections">[[%tickets_section]]</label>\n        <select name="parent" class="form-control" id="ticket-sections">[[+sections]]</select>\n        <span class="error"></span>\n    </div>\n\n    <div class="form-group">\n        <label for="ticket-pagetitle">[[%ticket_pagetitle]]</label>\n        <input type="text" class="form-control" placeholder="[[%ticket_pagetitle]]" name="pagetitle"\n               value="[[+pagetitle]]" maxlength="50" id="ticket-pagetitle"/>\n        <span class="error"></span>\n    </div>\n\n    <div class="form-group">\n        <textarea class="form-control" placeholder="[[%ticket_content]]" name="content" id="ticket-editor" rows="10">[[+content]]</textarea>\n        <span class="error"></span>\n    </div>\n\n    <div class="ticket-form-files">\n        [[+files]]\n    </div>\n\n    <div class="form-actions row">\n        <div class="col-md-6">\n            <input type="button" class="btn btn-default preview" value="[[%ticket_preview]]" title="Ctrl + Enter"/>\n        </div>\n        <div class="col-md-6 move-right">\n            [[!+published:is=`1`:then=`\n            <a href="[[~[[+id]]?scheme=`full`]]" class="btn btn-default btn-xs" target="_blank">[[%ticket_open]]</a>\n            <input type="button" class="btn btn-danger draft" name="draft" value="[[%ticket_draft]]" title=""/>\n            `:else=`\n            <input type="button" class="btn btn-primary publish" name="publish" value="[[%ticket_publish]]" title=""/>\n            `]]\n            <input type="submit" class="btn btn-default save" name="save" value="[[%ticket_save]]"\n                   title="Ctrl + Shift + Enter"/>\n        </div>\n    </div>\n</form>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.form_update.tpl'),
(245, 1, 0, 'tpl.Tickets.form.preview', '', 0, 61, 0, '<h3 class="title">[[+pagetitle]]</h3>\n<div class="content">[[+content]]</div>\n<h5 class="author">[[+modx.user.id:userinfo=`username`]]</h5>\n', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.form_preview.tpl'),
(246, 1, 0, 'tpl.Tickets.form.files', '', 0, 61, 0, '<div id="ticket-files-list">\n    [[+files]]\n    <div class="clearfix"></div>\n</div>\n\n<div id="ticket-files-container" data-action="ticket/file/upload">\n    <a id="ticket-files-select" href="javascript:;">[[%ticket_file_select]]</a>\n    <div id="ticket-files-progress">\n        <span id="ticket-files-progress-count">0/0</span>\n        <span id="ticket-files-progress-percent">0%</span>\n        <div id="ticket-files-progress-bar"></div>\n    </div>\n</div>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.form_files.tpl'),
(247, 1, 0, 'tpl.Tickets.form.file', '', 0, 61, 0, '<div class="ticket-file[[+deleted]][[+new]]" data-id="[[+id]]">\n    <a href="[[+url]]" class="ticket-file-link" title="[[+file]]" target="_blank">\n        <div class="ticket-file-image-wrapper">\n            [[+file]]\n        </div>\n    </a>\n    <div class="ticket-file-meta">\n        <a href="#" class="ticket-file-delete">[[%ticket_file_delete]]</a>\n        <a href="#" class="ticket-file-restore">[[%ticket_file_restore]]</a>\n        <br/>\n        <a href="#" class="ticket-file-insert">[[%ticket_file_insert]]</a>\n        <br/>\n        <span class="ticket-file-size">[[+size]] Kb</span>\n    </div>\n    <div class="ticket-file-template">\n        <a href="[[+url]]">\n            [[+name]]\n        </a>\n    </div>\n</div>\n<!--tickets_thumb <img src="[[+thumb]]" class="ticket-file-image" />-->\n<!--tickets_deleted  deleted-->\n<!--tickets_new  new-->', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.form_file.tpl'),
(248, 1, 0, 'tpl.Tickets.form.image', '', 0, 61, 0, '<div class="ticket-file[[+deleted]][[+new]]" data-id="[[+id]]">\n    <a href="[[+url]]" class="ticket-file-link" title="[[+file]]" target="_blank">\n        <div class="ticket-file-image-wrapper">\n            <img src="[[+thumb]]" class="ticket-file-image"/>\n        </div>\n    </a>\n    <div class="ticket-file-meta">\n        <a href="#" class="ticket-file-delete">[[%ticket_file_delete]]</a>\n        <a href="#" class="ticket-file-restore">[[%ticket_file_restore]]</a>\n        <br/>\n        <a href="#" class="ticket-file-insert">[[%ticket_file_insert]]</a>\n        <br/>\n        <span class="ticket-file-size">[[+size]] Kb</span>\n    </div>\n    <div class="ticket-file-template">\n        <a href="[[+url]]" title="[[+name]]">\n            <img src="[[+thumb]]"/>\n        </a>\n    </div>\n</div>\n<!--tickets_deleted  deleted-->\n<!--tickets_new  new-->', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.form_image.tpl'),
(249, 1, 0, 'tpl.Tickets.ticket.latest', '', 0, 61, 0, '<div class="tickets-latest-row">\n    <span class="user"><i class="glyphicon glyphicon-user"></i> [[+fullname]]</span> <span\n            class="date">[[+date_ago]]</span>\n    <br/>\n    <span class="section">\n        <i class="glyphicon glyphicon-folder-open"></i> <a href="[[~[[+section.id]]]]">[[+section.pagetitle]]</a> <span\n                class="arrow">&rarr;</span>\n    </span>\n    <span class="ticket">\n        <a href="[[~[[+id]]]]">[[+pagetitle]]</a>\n    </span>\n    <nobr><i class="glyphicon glyphicon-comment"></i> <span class="comments">[[+comments]]</span></nobr>\n</div>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.ticket_latest.tpl'),
(250, 1, 0, 'tpl.Tickets.ticket.email.bcc', '', 0, 61, 0, '[[%ticket_email_bcc_intro?\n&fullname=`[[+user.fullname]]`\n&email=`[[+user.email]]`\n&id=`[[+id]]`\n&pagetitle=`[[+pagetitle]]`\n]]\n\n<pre style="background-color:#efefef;">[[+introtext]]</pre>\n<br/><br/>\n\n<a href="[[~[[+id]]?scheme=`full`]]">[[%ticket_email_view]]</a>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.ticket_email_bcc.tpl'),
(251, 1, 0, 'tpl.Tickets.ticket.email.subscription', '', 0, 61, 0, '[[%ticket_email_subscribed_intro?\n&id=`[[+id]]`\n&fullname=`[[+user.fullname]]`\n&section=`[[+section.id]]`\n&section_title=`[[+section.pagetitle]]`\n&pagetitle=`[[+pagetitle]]`\n]]\n\n<pre style="background-color:#efefef;">[[+introtext]]</pre>\n<br/><br/>\n\n<a href="[[~[[+id]]?scheme=`full`]]">[[%ticket_email_view]]</a>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.ticket_email_subscription.tpl'),
(252, 1, 0, 'tpl.Tickets.comment.form', '', 0, 61, 0, '<h4 id="comment-new-link">\n    <a href="#" class="btn btn-default">[[%ticket_comment_create]]</a>\n</h4>\n\n<div id="comment-form-placeholder">\n    <form id="comment-form" action="" method="post" class="well">\n        <div id="comment-preview-placeholder"></div>\n        <input type="hidden" name="thread" value="[[+thread]]"/>\n        <input type="hidden" name="parent" value="0"/>\n        <input type="hidden" name="id" value="0"/>\n\n        <div class="form-group">\n            <label for="comment-editor"></label>\n            <textarea name="text" placeholder="Ваш комментарий..." id="comment-editor" cols="30" rows="10" class="form-control"></textarea>\n        </div>\n\n        <div class="form-actions">\n            <input type="button" class="btn btn-default preview" value="[[%ticket_comment_preview]]"\n                   title="Ctrl + Enter"/>\n            <input type="submit" class="btn btn-primary submit" value="Отправить"\n                   title="Ctrl + Shift + Enter"/>\n            <span class="time"></span>\n        </div>\n    </form>\n</div>\n<style>.preview { background: none !important;\n    color: #000;\n    border: 0; }</style>', 0, 'a:0:{}', 0, 'core/components/tickets/elements/chunks/chunk.comment_form.tpl'),
(253, 1, 0, 'tpl.Tickets.comment.form.guest', '', 0, 61, 0, '<h4 id="comment-new-link">\n    <a href="#" class="btn btn-default">[[%ticket_comment_create]]</a>\n</h4>\n\n<div id="comment-form-placeholder">\n    <form id="comment-form" action="" method="post" class="well">\n        <div id="comment-preview-placeholder"></div>\n        <input type="hidden" name="thread" value="[[+thread]]"/>\n        <input type="hidden" name="parent" value="0"/>\n        <input type="hidden" name="id" value="0"/>\n\n        <div class="form-group">\n            <label for="comment-name">[[%ticket_comment_name]]</label>\n            <input type="text" name="name" value="[[+name]]" id="comment-name" class="form-control"/>\n            <span class="error"></span>\n        </div>\n\n        <div class="form-group">\n            <label for="comment-email">[[%ticket_comment_email]]</label>\n            <input type="text" name="email" value="[[+email]]" id="comment-email" class="form-control"/>\n            <span class="error"></span>\n        </div>\n\n        <div class="form-group">\n            <label for="comment-editor"></label>\n            <textarea name="text" id="comment-editor" placeholder="Ваш комментарий..." cols="30" rows="10" class="form-control"></textarea>\n        </div>\n\n        [[+captcha]]\n\n        <div class="form-actions">\n            <input type="button" class="btn btn-default preview" value="[[%ticket_comment_preview]]"\n                   title="Ctrl + Enter"/>\n            <input type="submit" class="btn btn-primary submit" value="Отправить"\n                   title="Ctrl + Shift + Enter"/>\n            <span class="time"></span>\n        </div>\n    </form>\n</div>\n<style>.preview { background: none !important;\n    color: #000;\n    border: 0; }</style>\n\n<!--tickets_captcha\n<div class="form-group">\n    <label for="comment-captcha" id="comment-captcha">[[+captcha]]</label>\n    <input type="text" name="captcha" value="" id="comment-captcha" class="form-control" />\n    <span class="error"></span>\n</div>\n-->', 0, 'a:0:{}', 0, 'core/components/tickets/elements/chunks/chunk.comment_form_guest.tpl');
INSERT INTO `modx_site_htmlsnippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `static`, `static_file`) VALUES
(254, 1, 0, 'tpl.Tickets.comment.one.auth', '', 0, 61, 0, '<li class="ticket-comment[[+comment_new]]" id="comment-[[+id]]" data-parent="[[+parent]]"\n    data-newparent="[[+new_parent]]" data-id="[[+id]]">\n    <div class="ticket-comment-body[[+guest]][[+bad]]">\n        <div class="ticket-comment-header">\n            <div class="ticket-comment-dot-wrapper">\n                <div class="ticket-comment-dot"></div>\n            </div>\n            <img src="[[+avatar]]" class="ticket-avatar" alt=""/>\n            <span class="ticket-comment-author">[[+fullname]]</span>\n            <span class="ticket-comment-createdon">[[+date_ago]]</span>[[+comment_was_edited]]\n            <span class="ticket-comment-link"><a href="[[+url]]#comment-[[+id]]">#</a></span>\n            <span class="ticket-comment-star[[+can_star]]">[[+stared]][[+unstared]]</span>\n            [[+has_parent]]\n            <span class="ticket-comment-down"><a href="#" data-child="">&darr;</a></span>\n            <span class="ticket-comment-rating[[+can_vote]][[+cant_vote]]">\n                <span class="rating[[+rating_positive]][[+rating_negative]]"\n                      title="[[%ticket_rating_total]] [[+rating_total]]: ↑[[+rating_plus]] [[%ticket_rating_and]] ↓[[+rating_minus]]">[[+rating]]</span>\n                <span class="vote plus[[+voted_plus]]" title="[[%ticket_like]]"><i\n                            class="glyphicon glyphicon-arrow-up"></i></span>\n                <span class="vote minus[[+voted_minus]]" title="[[%ticket_dislike]]"><i\n                            class="glyphicon glyphicon-arrow-down"></i></span>\n            </span>\n        </div>\n        <div class="ticket-comment-text">\n            [[+text]]\n        </div>\n    </div>\n    <div class="comment-reply">\n        <a href="#" class="reply">[[%ticket_comment_reply]]</a>\n        [[+comment_edit_link]]\n    </div>\n    <ol class="comments-list">[[+children]]</ol>\n</li>\n<!--tickets_comment_edit_link <a href="#" class="edit">[[%ticket_comment_edit]]</a>-->\n<!--tickets_comment_was_edited <span class="ticket-comment-edited">([[%ticket_comment_was_edited]])</span>-->\n<!--tickets_comment_new  ticket-comment-new-->\n<!--tickets_can_vote  active-->\n<!--tickets_cant_vote  inactive-->\n<!--tickets_rating_positive  positive-->\n<!--tickets_rating_negative  negative-->\n<!--tickets_voted_plus  voted-->\n<!--tickets_voted_minus  voted-->\n<!--tickets_guest  ticket-comment-guest-->\n<!--tickets_has_parent <span class="ticket-comment-up"><a href="[[+url]]#comment-[[+parent]]" data-id="[[+id]]" data-parent="[[+parent]]">&uarr;</a></span>-->\n<!--tickets_can_star  active-->\n<!--tickets_stared <i class="glyphicon glyphicon-star stared star"></i>-->\n<!--tickets_unstared <i class="glyphicon glyphicon-star unstared star"></i>-->\n', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_one_auth.tpl'),
(255, 1, 0, 'tpl.Tickets.comment.one.guest', '', 0, 61, 0, '<li class="ticket-comment" id="comment-[[+id]]">\n    <div class="ticket-comment-body[[+bad]]">\n        <div class="ticket-comment-header">\n            <div class="ticket-comment-dot-wrapper">\n                <div class="ticket-comment-dot"></div>\n            </div>\n            <img src="[[+avatar]]" class="ticket-avatar" alt=""/>\n            <span class="ticket-comment-author">[[+fullname]]</span>\n            <span class="ticket-comment-createdon">[[+date_ago]]</span>\n            <span class="ticket-comment-link"><a href="[[+url]]#comment-[[+id]]">#</a></span>\n\n            [[+has_parent]]\n            <span class="ticket-comment-down"><a href="#" data-child="">&darr;</a></span>\n\n            <span class="ticket-comment-rating inactive">\n                <span class="rating[[+rating_positive]][[+rating_negative]]">\n                    [[+rating]]\n                </span>\n                <span class="plus" title="[[%ticket_like]]">\n                    <i class="glyphicon glyphicon-arrow-up"></i>\n                </span>\n                <span class="minus" title="[[%ticket_dislike]]">\n                    <i class="glyphicon glyphicon-arrow-down"></i>\n                </span>\n            </span>\n        </div>\n        <div class="ticket-comment-text">\n            [[+text]]\n        </div>\n    </div>\n    <ol class="comments-list">[[+children]]</ol>\n</li>\n<!--tickets_rating_positive  positive-->\n<!--tickets_rating_negative  negative-->\n<!--tickets_has_parent <span class="ticket-comment-up"><a href="[[+url]]#comment-[[+parent]]" data-id="[[+id]]" data-parent="[[+parent]]">&uarr;</a></span>-->', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_one_guest.tpl'),
(256, 1, 0, 'tpl.Tickets.comment.one.deleted', '', 0, 61, 0, '<li class="ticket-comment" id="comment-[[+id]]">\n    <div class="ticket-comment-body alert alert-warning">\n        [[%ticket_comment_deleted_text]]\n    </div>\n    <ol class="comments-list">[[+children]]</ol>\n</li>\n', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_one_deleted.tpl'),
(257, 1, 0, 'tpl.Tickets.comment.wrapper', '', 0, 61, 0, '<div class="comments">\n    [[+modx.user.id:isloggedin:is=`1`:then=`\n    <span class="comments-subscribe pull-right">\n        <label for="comments-subscribe" class="checkbox">\n            <input type="checkbox" name="" id="comments-subscribe" value="1" [[+subscribed]]/> [[%ticket_comment_notify]]\n        </label>\n    </span>\n    `:else=``]]\n\n    <h2 class="title" style="color: #139DF2!important; font-weight: bold;">Оставьте здесь свои вопросы, комментарии, отзывы о нашей работе (<span id="comment-total">[[+total]]</span>)</h2>\n\n    <div id="comments-wrapper">\n        <ol class="comment-list" id="comments">[[+comments]]</ol>\n    </div>\n\n    <div id="comments-tpanel">\n        <div id="tpanel-refresh"></div>\n        <div id="tpanel-new"></div>\n    </div>\n</div>\n\n<!--tickets_subscribed checked-->\n<style>#comment-form .submit { background-color: #ff413d;}</style>', 0, 'a:0:{}', 0, 'core/components/tickets/elements/chunks/chunk.comment_wrapper.tpl'),
(258, 1, 0, 'tpl.Tickets.comment.login', '', 0, 61, 0, '<div class="ticket-comments alert alert-warning">\n    <p>[[%ticket_comment_err_no_auth]]</p>\n</div>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_login.tpl'),
(259, 1, 0, 'tpl.Tickets.comment.latest', '', 0, 61, 0, '<div class="tickets-latest-row[[+guest]]">\n    <span class="user"><i class="glyphicon glyphicon-user"></i> [[+fullname]]</span> <span\n            class="date">[[+date_ago]]</span>\n    <br/>\n    <span class="ticket">\n        <a href="[[~[[+ticket.id]]]]#comment-[[+id]]">[[+ticket.pagetitle]]</a>\n    </span>\n    <nobr><i class="glyphicon glyphicon-comment"></i> <span class="comments">[[+comments]]</span></nobr>\n</div>\n<!--tickets_guest  ticket-comment-guest-->', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_latest.tpl'),
(260, 1, 0, 'tpl.Tickets.comment.email.owner', '', 0, 61, 0, '[[%ticket_comment_email_owner_intro?\n&name=`[[+name]]`\n&resource=`[[+resource]]`\n&pagetitle=`[[+pagetitle]]`\n]]\n\n<pre>[[+text]]</pre>\n<br/><br/>\n\n<a href="[[~[[+resource]]?scheme=`full`]]#comment-[[+id]]">[[%ticket_email_reply]]</a>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_email_owner.tpl'),
(261, 1, 0, 'tpl.Tickets.comment.email.reply', '', 0, 61, 0, '[[%ticket_comment_email_reply_intro?\n&name=`[[+name]]`\n&resource=`[[+resource]]`\n&pagetitle=`[[+pagetitle]]`\n]]\n\n<pre>[[+text]]</pre>\n<br/><br/>\n<a href="[[~[[+resource]]?scheme=`full`]]#comment-[[+id]]">[[%ticket_email_reply]]</a>\n<br/><br/>\n\n[[%ticket_comment_email_reply_text]]\n<pre>[[+parent_text]]</pre>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_email_reply.tpl'),
(262, 1, 0, 'tpl.Tickets.comment.email.subscription', '', 0, 61, 0, '[[%ticket_comment_email_subscription_intro?\n&name=`[[+name]]`\n&resource=`[[+resource]]`\n&pagetitle=`[[+pagetitle]]`\n]]\n\n<pre>[[+text]]</pre>\n<br/><br/>\n\n<a href="[[~[[+resource]]?scheme=`full`]]#comment-[[+id]]">[[%ticket_email_view]]</a>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_email_subscription.tpl'),
(263, 1, 0, 'tpl.Tickets.comment.email.bcc', '', 0, 61, 0, '[[%ticket_comment_email_bcc_intro?\n&name=`[[+name]]`\n&resource=`[[+resource]]`\n&pagetitle=`[[+pagetitle]]`\n]]\n\n<pre>[[+text]]</pre>\n<br/><br/>\n\n<a href="[[~[[+resource]]?scheme=`full`]]#comment-[[+id]]">[[%ticket_email_view]]</a>\n', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_email_bcc.tpl'),
(264, 1, 0, 'tpl.Tickets.comment.email.unpublished', '', 0, 61, 0, '[[%ticket_comment_email_unpublished_intro?\n&name=`[[+name]]`\n&resource=`[[+resource]]`\n&pagetitle=`[[+pagetitle]]`\n]]\n\n<pre>[[+text]]</pre>\n<br/><br/>\n\n<a href="[[+manager_url]]">[[%ticket_email_all_comments]]</a>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_email_unpublished.tpl'),
(265, 1, 0, 'tpl.Tickets.comment.list.row', '', 0, 61, 0, '<div class="ticket-comment-row ticket-comment" id="comment-[[+id]]" data-id="[[+id]]">\n    <div class="ticket-comment-body[[+guest]]">\n        <div class="ticket-comment-header">\n            <img src="[[+avatar]]" class="ticket-avatar" alt=""/>\n            <span class="ticket-comment-author">[[+fullname]]</span>\n            <span class="ticket-comment-createdon">[[+date_ago]]</span>[[+comment_was_edited]]\n            <span class="ticket-comment-link"><a href="[[+url]]#comment-[[+id]]">#</a></span>\n            <span class="ticket-comment-star[[+can_star]]">[[+stared]][[+unstared]]</span>\n\n            <span class="ticket-comment-rating[[+can_vote]][[+cant_vote]]">\n                <span class="rating[[+rating_positive]][[+rating_negative]]"\n                      title="[[%ticket_rating_total]] [[+rating_total]]: ↑[[+rating_plus]] [[%ticket_rating_and]] ↓[[+rating_minus]]">[[+rating]]</span>\n                <span class="vote plus[[+voted_plus]]" title="[[%ticket_like]]"><i\n                            class="glyphicon glyphicon-arrow-up"></i></span>\n                <span class="vote minus[[+voted_minus]]" title="[[%ticket_dislike]]"><i\n                            class="glyphicon glyphicon-arrow-down"></i></span>\n            </span>\n        </div>\n        <div class="ticket-comment-text">\n            [[+text]]\n        </div>\n    </div>\n\n    <a href="[[~[[+section.id]]]]" class="ticket-comment-section"><i class="glyphicon glyphicon-folder-open"></i>\n        [[+section.pagetitle]]</a> &rarr;\n    <a href="[[~[[+ticket.id]]]]" class="ticket-comment-ticket">[[+ticket.pagetitle]]</a> &nbsp;\n    <span class="ticket-comment-comments"><i class="glyphicon glyphicon-comment"></i> [[+comments]]</span>\n</div>\n<!--tickets_comment_was_edited <span class="ticket-comment-edited">([[%ticket_comment_was_edited]])</span>-->\n<!--tickets_can_vote  active-->\n<!--tickets_cant_vote  inactive-->\n<!--tickets_rating_positive  positive-->\n<!--tickets_rating_negative  negative-->\n<!--tickets_voted_plus  voted-->\n<!--tickets_voted_minus  voted-->\n<!--tickets_guest  ticket-comment-guest-->\n<!--tickets_can_star  active-->\n<!--tickets_stared <i class="glyphicon glyphicon-star stared star"></i>-->\n<!--tickets_unstared <i class="glyphicon glyphicon-star unstared star"></i>-->', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.comment_list_row.tpl'),
(266, 1, 0, 'tpl.Tickets.list.row', '', 0, 61, 0, '<div class="tickets-row">\n    <h3 class="title"><a href="[[~[[+id]]]]">[[+pagetitle]]</a></h3>\n    <div class="content">\n        [[+introtext]]<br/>\n        <a href="[[~[[+id]]]]#cut" class="btn btn-default ticket-read-more">[[%ticket_read_more]]</a>\n    </div>\n    <div class="ticket-meta row" data-id="[[+id]]">\n        <span class="col-md-5">\n            <i class="glyphicon glyphicon-calendar"></i> [[+date_ago]]\n            &nbsp;&nbsp;\n            <i class="glyphicon glyphicon-user"></i> [[+fullname]]\n        </span>\n        <span class="col-md-2"><a href="[[~[[+section.id]]]]"><i class="glyphicon glyphicon-folder-open"></i> [[+section.pagetitle]]</a></span>\n        <span class="col-md-3">\n            <span class="ticket-star[[+can_star]]">[[+stared]][[+unstared]] <span\n                        class="ticket-star-count">[[+stars]]</span></span>\n            &nbsp;&nbsp;\n            <i class="glyphicon glyphicon-eye-open"></i> [[+views]]\n            &nbsp;&nbsp;\n            <i class="glyphicon glyphicon-comment"></i> [[+comments]]  [[+new_comments]]\n        </span>\n        <span class="col-md-2 pull-right ticket-rating[[+active]][[+inactive]]">\n            <span class="vote plus[[+voted_plus]]" title="[[%ticket_like]]"><i class="glyphicon glyphicon-arrow-up"></i></span>\n            [[+can_vote]][[+cant_vote]]\n            <span class="vote minus[[+voted_minus]]" title="[[%ticket_dislike]]"><i\n                        class="glyphicon glyphicon-arrow-down"></i></span>\n        </span>\n    </div>\n</div>\n<!--tickets_can_vote <span class="vote rating" title="[[%ticket_refrain]]"><i class="glyphicon glyphicon-minus"></i></span>-->\n<!--tickets_cant_vote <span class="rating[[+rating_positive]][[+rating_negative]]" title="[[%ticket_rating_total]] [[+rating_total]]: ↑[[+rating_plus]] [[%ticket_rating_and]] ↓[[+rating_minus]]">[[+rating]]</span>-->\n<!--tickets_new_comments <span class="ticket-new-comments">+[[+new_comments]]</span>-->\n<!--tickets_active  active-->\n<!--tickets_inactive  inactive-->\n<!--tickets_voted_plus  voted-->\n<!--tickets_voted_minus  voted-->\n<!--tickets_rating_positive  positive-->\n<!--tickets_rating_negative  negative-->\n<!--tickets_can_star  active-->\n<!--tickets_stared <i class="glyphicon glyphicon-star stared star"></i>-->\n<!--tickets_unstared <i class="glyphicon glyphicon-star unstared star"></i>-->', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.ticket_list_row.tpl'),
(267, 1, 0, 'tpl.Tickets.sections.row', '', 0, 61, 0, '<div class="section-row">\n    <h3 class="title"><a href="[[~[[+id]]]]">[[+pagetitle]]</a></h3>\n    <div class="content">\n        [[+introtext]]\n    </div>\n    <div class="section-meta row">\n        <div class="col-md-1"><i class="glyphicon glyphicon-th-list"></i> [[+tickets]]</div>\n        <div class="col-md-1"><i class="glyphicon glyphicon-eye-open"></i> [[+views]]</div>\n        <div class="col-md-1"><i class="glyphicon glyphicon-comment"></i> [[+comments]]</div>\n    </div>\n</div>', 0, NULL, 0, 'core/components/tickets/elements/chunks/chunk.ticket_sections_row.tpl'),
