INSERT INTO `modx_site_htmlsnippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `static`, `static_file`) VALUES
(271, 2, 0, 'carrot_popup', '', 0, 0, 0, '<div class="flame_box">\n        <div class="flame_inner">\n            <a href="javascript:void(0)" class="close"><img src="/userfiles/union-1.png"></a>\n            <div class="flame_image">\n                <img src="/userfiles/wrappedgift.png">\n            </div>\n            <div class="flame_text">\n                <h3>Привет, дорогой друг!</h3>\n                <p>Ищите качественную химчистку? Специально для Вас мы подготовили памятку о том, какая должна быть правильная химчистка.</p>\n                <p class="give">Оставьте свой e-mail и мы отправим Вам памятку в подарок!</p>\n                <form>\n                    <input type="text" id="carrot_email" placeholder="Ваша электронная почта">\n                    <button type="submit">Отправить</button>\n                </form>\n            </div>\n        </div>\n    </div>\n    <link href="https://fonts.googleapis.com/css?family=Comfortaa|Oswald:300,400" rel="stylesheet">\n    <style>\n        @media (min-width: 768px) {\n            .flame_box {\n                width: 100%;\n                height: 100vh;\n                background: rgba(0,0,0,.3);\n                position: fixed;\n                z-index: 100000;\n                display: flex;\n                flex-direction: column;\n                justify-content: center;\n                align-items: center;\n            }\n            .flame_inner {\n                width: 760px;\n                background: #fff;\n                padding: 30px 15px;\n                box-sizing: border-box;\n                display: flex;\n                position: relative;\n                box-shadow: 0 0 8px 5px #4242427a;\n                flex-direction: row;\n                align-items: center;\n                justify-content: center;\n            }\n            .flame_image {\n                width: 50%;\n                padding: 15px;\n                display: flex;\n                flex-direction: column;\n                align-items: center;\n                justify-content: center;\n            }\n            .flame_image img {\n                width: 100%;\n            }\n            .flame_text {\n                padding: 15px;\n                color: #00528b;\n                width: 50%;\n                display: block;\n            }\n            .flame_text h3 {\n                font-size: 26px;\n                font-family: ''Comfortaa'', cursive;\n            }\n            .flame_text p {\n                font-size: 15px;\n                margin-bottom: 30px;\n                margin-top: 10px;\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n                color: #00528b9c;\n            }\n            .flame_text button {\n                background: #00528b;\n                color: #fff;\n                width: 125px;\n                text-transform: uppercase;\n                float: left;\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n            }\n            .flame_text input {\n                float: left;\n                color: #00528b;\n                width: calc(100% - 125px);\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n                border: 1px solid #00528b;\n            }\n            .flame_text input::placeholder {\n                color: #00528b9c;\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n            }\n            .flame_text .give {\n                font-weight: 400;\n            }\n            .flame_inner .close {\n                color: #00528b;\n                position: absolute;\n                right: 20px;\n                top: 20px;\n            }\n            .flame_inner .close img {\n                width: 30px;\n                height: 30px;\n            }\n        }\n        @media (max-width: 767px) {\n            .flame_box {\n                width: 100%;\n                height: 100vh;\n                background: rgba(0,0,0,.3);\n                position: fixed;\n                z-index: 10000000000;\n                display: flex;\n                flex-direction: column;\n                justify-content: center;\n                align-items: center;\n            }\n            .flame_inner {\n                width: 97%;\n                background: #fff;\n                padding: 30px 15px;\n                box-sizing: border-box;\n                display: flex;\n                position: relative;\n                box-shadow: 0 0 8px 5px #4242427a;\n                flex-direction: column;\n                align-items: center;\n                justify-content: center;\n            }\n            .flame_image {\n                width: 100%;\n                padding: 15px;\n                display: flex;\n                flex-direction: column;\n                align-items: center;\n                justify-content: center;\n            }\n            .flame_image img {\n                width: 100%;\n            }\n            .flame_text {\n                padding: 15px;\n                color: #00528b;\n                width: 100%;\n                display: block;\n            }\n            .flame_text h3 {\n                font-size: 26px;\n                font-family: ''Comfortaa'', cursive;\n            }\n            .flame_text p {\n                font-size: 15px;\n                margin-bottom: 30px;\n                margin-top: 10px;\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n                color: #00528b9c;\n            }\n            .flame_text button {\n                background: #00528b;\n                color: #fff;\n                width: 125px;\n                text-transform: uppercase;\n                float: left;\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n            }\n            .flame_text input {\n                float: left;\n                color: #00528b;\n                width: calc(100% - 125px);\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n                border: 1px solid #00528b;\n            }\n            .flame_text input::placeholder {\n                color: #00528b9c;\n                font-family: ''Oswald'', sans-serif;\n                font-weight: 300;\n            }\n            .flame_text .give {\n                font-weight: 400;\n            }\n            .flame_inner .close {\n                color: #00528b;\n                position: absolute;\n                right: 20px;\n                top: 20px;\n            }\n            .flame_inner .close img {\n                width: 30px;\n                height: 30px;\n            }\n        }\n        .fr-dib {\n            float: left;\n            \n        }\n        .flame_box { display: none !important; }\n        #carrotquest-messenger-body-big-cont { max-width: 800px !important; }\n    </style>\n    <script>\n        $(function(){\n            $(''.flame_inner .close'').click(function(){\n                $(''.flame_box'').hide();\n            });\n        });\n        \n    </script>', 0, 'a:0:{}', 0, ''),
