;s:25:"prop_formit.fiarhtml_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:12:"mathMinRange";a:7:{s:4:"name";s:12:"mathMinRange";s:4:"desc";s:29:"prop_formit.mathminrange_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:2:"10";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:12:"mathMaxRange";a:7:{s:4:"name";s:12:"mathMaxRange";s:4:"desc";s:29:"prop_formit.mathmaxrange_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:3:"100";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:9:"mathField";a:7:{s:4:"name";s:9:"mathField";s:4:"desc";s:26:"prop_formit.mathfield_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:4:"math";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:12:"mathOp1Field";a:7:{s:4:"name";s:12:"mathOp1Field";s:4:"desc";s:29:"prop_formit.mathop1field_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:3:"op1";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:12:"mathOp2Field";a:7:{s:4:"name";s:12:"mathOp2Field";s:4:"desc";s:29:"prop_formit.mathop2field_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:3:"op2";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:17:"mathOperatorField";a:7:{s:4:"name";s:17:"mathOperatorField";s:4:"desc";s:34:"prop_formit.mathoperatorfield_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:8:"operator";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}}', '', 0, ''),
(3, 0, 0, 'FormItAutoResponder', 'Custom hook for FormIt to handle Auto-Response emails.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * A custom FormIt hook for auto-responders.\r\n *\r\n * @var modX $modx\r\n * @var array $scriptProperties\r\n * @var FormIt $formit\r\n * @var fiHooks $hook\r\n * \r\n * @package formit\r\n */\r\n/* setup default properties */\r\n$tpl = $modx->getOption(''fiarTpl'',$scriptProperties,''fiarTpl'');\r\n$mailFrom = $modx->getOption(''fiarFrom'',$scriptProperties,$modx->getOption(''emailsender''));\r\n$mailFromName = $modx->getOption(''fiarFromName'',$scriptProperties,$modx->getOption(''site_name''));\r\n$mailSender = $modx->getOption(''fiarSender'',$scriptProperties,$modx->getOption(''emailsender''));\r\n$mailSubject = $modx->getOption(''fiarSubject'',$scriptProperties,''[[++site_name]] Auto-Responder'');\r\n$mailSubject = str_replace(array(''[[++site_name]]'',''[[++emailsender]]''),array($modx->getOption(''site_name''),$modx->getOption(''emailsender'')),$mailSubject);\r\n$fiarFiles = $modx->getOption(''fiarFiles'',$scriptProperties,false);\r\n$isHtml = $modx->getOption(''fiarHtml'',$scriptProperties,true);\r\n$toField = $modx->getOption(''fiarToField'',$scriptProperties,''email'');\r\n$multiSeparator = $modx->getOption(''fiarMultiSeparator'',$formit->config,"\\n");\r\n$multiWrapper = $modx->getOption(''fiarMultiWrapper'',$formit->config,"[[+value]]");\r\n$required = $modx->getOption(''fiarRequired'',$scriptProperties,true);\r\nif (empty($fields[$toField])) {\r\n    if ($required) {\r\n        $modx->log(modX::LOG_LEVEL_ERROR,''[FormIt] Auto-responder could not find field `''.$toField.''` in form submission.'');\r\n        return false;\r\n    } else {\r\n        return true;\r\n    }\r\n}\r\n\r\n/* handle checkbox and array fields */\r\nforeach ($fields as $k => &$v) {\r\n    if (is_array($v) && !empty($v[''name'']) && isset($v[''error'']) && $v[''error''] == UPLOAD_ERR_OK) {\r\n        $fields[$k] = $v[''name''];\r\n    } else if (is_array($v)) {\r\n        $vOpts = array();\r\n        foreach ($v as $vKey => $vValue) {\r\n            if (is_string($vKey) && !empty($vKey)) {\r\n                $vKey = $k.''.''.$vKey;\r\n                $fields[$vKey] = $vValue;\r\n            } else {\r\n                $vOpts[] = str_replace(''[[+value]]'',$vValue,$multiWrapper);\r\n            }\r\n        }\r\n        $newValue = implode($multiSeparator,$vOpts);\r\n        if (!empty($vOpts)) {\r\n            $fields[$k] = $newValue;\r\n        }\r\n    }\r\n}\r\n\r\n/* setup placeholders */\r\n$placeholders = $fields;\r\n$mailTo= $fields[$toField];\r\n\r\n$message = $formit->getChunk($tpl,$placeholders);\r\n$modx->parser->processElementTags('''',$message,true,false);\r\n\r\n$modx->getService(''mail'', ''mail.modPHPMailer'');\r\n$modx->mail->reset();\r\n$modx->mail->set(modMail::MAIL_BODY,$message);\r\n$modx->mail->set(modMail::MAIL_FROM,$hook->_process($mailFrom,$placeholders));\r\n$modx->mail->set(modMail::MAIL_FROM_NAME,$hook->_process($mailFromName,$placeholders));\r\n$modx->mail->set(modMail::MAIL_SENDER,$hook->_process($mailSender,$placeholders));\r\n$modx->mail->set(modMail::MAIL_SUBJECT,$hook->_process($mailSubject,$placeholders));\r\n$modx->mail->address(''to'',$mailTo);\r\n$modx->mail->setHTML($isHtml);\r\n\r\n/* add attachments */\r\nif($fiarFiles){\r\n    $fiarFiles = explode('','', $fiarFiles);\r\n    foreach($fiarFiles AS $file){\r\n        $modx->mail->mailer->AddAttachment($file);\r\n    }\r\n}\r\n\r\n/* reply to */\r\n$emailReplyTo = $modx->getOption(''fiarReplyTo'',$scriptProperties,$mailFrom);\r\n$emailReplyTo = $hook->_process($emailReplyTo,$fields);\r\n$emailReplyToName = $modx->getOption(''fiarReplyToName'',$scriptProperties,$mailFromName);\r\n$emailReplyToName = $hook->_process($emailReplyToName,$fields);\r\nif (!empty($emailReplyTo)) {\r\n    $modx->mail->address(''reply-to'',$emailReplyTo,$emailReplyToName);\r\n}\r\n\r\n/* cc */\r\n$emailCC = $modx->getOption(''fiarCC'',$scriptProperties,'''');\r\nif (!empty($emailCC)) {\r\n    $emailCCName = $modx->getOption(''fiarCCName'',$scriptProperties,'''');\r\n    $emailCC = explode('','',$emailCC);\r\n    $emailCCName = explode('','',$emailCCName);\r\n    $numAddresses = count($emailCC);\r\n    for ($i=0;$i<$numAddresses;$i++) {\r\n        $etn = !empty($emailCCName[$i]) ? $emailCCName[$i] : '''';\r\n        if (!empty($etn)) $etn = $hook->_process($etn,$fields);\r\n        $emailCC[$i] = $hook->_process($emailCC[$i],$fields);\r\n        if (!empty($emailCC[$i])) {\r\n            $modx->mail->address(''cc'',$emailCC[$i],$etn);\r\n        }\r\n    }\r\n}\r\n\r\n/* bcc */\r\n$emailBCC = $modx->getOption(''fiarBCC'',$scriptProperties,'''');\r\nif (!empty($emailBCC)) {\r\n    $emailBCCName = $modx->getOption(''fiarBCCName'',$scriptProperties,'''');\r\n    $emailBCC = explode('','',$emailBCC);\r\n    $emailBCCName = explode('','',$emailBCCName);\r\n    $numAddresses = count($emailBCC);\r\n    for ($i=0;$i<$numAddresses;$i++) {\r\n        $etn = !empty($emailBCCName[$i]) ? $emailBCCName[$i] : '''';\r\n        if (!empty($etn)) $etn = $hook->_process($etn,$fields);\r\n        $emailBCC[$i] = $hook->_process($emailBCC[$i],$fields);\r\n        if (!empty($emailBCC[$i])) {\r\n            $modx->mail->address(''bcc'',$emailBCC[$i],$etn);\r\n        }\r\n    }\r\n}\r\n\r\nif (!$formit->inTestMode) {\r\n    if (!$modx->mail->send()) {\r\n        $modx->log(modX::LOG_LEVEL_ERROR,''[FormIt] An error occurred while trying to send the auto-responder email: ''.$modx->mail->mailer->ErrorInfo);\r\n        return false;\r\n    }\r\n}\r\n$modx->mail->reset();\r\nreturn true;', 0, 'a:0:{}', '', 0, ''),
(4, 0, 0, 'FormItRetriever', 'Fetches a form submission for a user for displaying on a thank you page.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * FormItRetriever\r\n *\r\n * Retrieves a prior form submission that was stored with the &store property\r\n * in a FormIt call.\r\n *\r\n * @var modX $modx\r\n * @var array $scriptProperties\r\n *\r\n * @package formit\r\n */\r\n\r\n$modelPath = $modx->getOption(''formit.core_path'', null, $modx->getOption(''core_path'', null, MODX_CORE_PATH) . ''components/formit/'') . ''model/formit/'';\r\n$modx->loadClass(''FormIt'', $modelPath, true, true);\r\n\r\n$fi = new FormIt($modx,$scriptProperties);\r\n\r\n/* setup properties */\r\n$placeholderPrefix = $modx->getOption(''placeholderPrefix'',$scriptProperties,''fi.'');\r\n$eraseOnLoad = $modx->getOption(''eraseOnLoad'',$scriptProperties,false);\r\n$redirectToOnNotFound = $modx->getOption(''redirectToOnNotFound'',$scriptProperties,false);\r\n\r\n/* fetch data from cache and set to placeholders */\r\n$fi->loadRequest();\r\n$fi->request->loadDictionary();\r\n$data = $fi->request->dictionary->retrieve();\r\nif (!empty($data)) {\r\n    /* set data to placeholders */\r\n    foreach ($data as $k=>$v) {\r\n        /*checkboxes & other multi-values are stored as arrays, must be imploded*/\r\n        if (is_array($v)) {\r\n            $data[$k] = implode('','',$v);\r\n        }\r\n    }\r\n    $modx->toPlaceholders($data,$placeholderPrefix,'''');\r\n    \r\n    /* if set, erase the data on load, otherwise depend on cache expiry time */\r\n    if ($eraseOnLoad) {\r\n        $fi->request->dictionary->erase();\r\n    }\r\n/* if the data''s not found, and we want to redirect somewhere if so, do here */\r\n} else if (!empty($redirectToOnNotFound)) {\r\n    $url = $modx->makeUrl($redirectToOnNotFound);\r\n    $modx->sendRedirect($url);\r\n}\r\nreturn '''';', 0, 'a:4:{s:17:"placeholderPrefix";a:7:{s:4:"name";s:17:"placeholderPrefix";s:4:"desc";s:31:"prop_fir.placeholderprefix_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:3:"fi.";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:20:"redirectToOnNotFound";a:7:{s:4:"name";s:20:"redirectToOnNotFound";s:4:"desc";s:34:"prop_fir.redirecttoonnotfound_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:11:"eraseOnLoad";a:7:{s:4:"name";s:11:"eraseOnLoad";s:4:"desc";s:25:"prop_fir.eraseonload_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:13:"storeLocation";a:7:{s:4:"name";s:13:"storeLocation";s:4:"desc";s:27:"prop_fir.storelocation_desc";s:4:"type";s:4:"list";s:7:"options";a:2:{i:0;a:2:{s:5:"value";s:5:"cache";s:4:"text";s:16:"formit.opt_cache";}i:1;a:2:{s:5:"value";s:7:"session";s:4:"text";s:18:"formit.opt_session";}}s:5:"value";s:5:"cache";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}}', '', 0, ''),
(5, 0, 0, 'FormItIsChecked', 'A custom output filter used with checkboxes/radios for checking checked status.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * FormItIsChecked\r\n *\r\n * Custom output filter that returns checked="checked" if the value is set\r\n *\r\n * @var string $input\r\n * @var string $options\r\n * @var modX $modx\r\n *\r\n * @package formit\r\n */\r\n$output = '' '';\r\nif ($input == $options) {\r\n    $output = '' checked="checked"'';\r\n}\r\n$input = $modx->fromJSON($input);\r\nif (!empty($input) && is_array($input) && in_array($options,$input)) {\r\n  $output = '' checked="checked"'';\r\n}\r\nreturn $output;', 0, 'a:0:{}', '', 0, ''),
(6, 0, 0, 'FormItIsSelected', 'A custom output filter used with dropdowns for checking selected status.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * FormItIsChecked\r\n *\r\n * Custom output filter that returns checked="checked" if the value is set\r\n *\r\n * @var string $input\r\n * @var string $options\r\n * @var modX $modx\r\n *\r\n * @package formit\r\n */\r\n$output = '' '';\r\nif ($input == $options) {\r\n    $output = '' selected="selected"'';\r\n}\r\n$input = $modx->fromJSON($input);\r\nif (!empty($input) && is_array($input) && in_array($options,$input)) {\r\n  $output = '' selected="selected"'';\r\n}\r\nreturn $output;', 0, 'a:0:{}', '', 0, ''),
(7, 0, 0, 'FormItCountryOptions', 'A utility snippet for generating a dropdown list of countries.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * FormItCountryOptions\r\n *\r\n * Automatically generates and outputs a country list for usage in forms\r\n *\r\n * @var modX $modx\r\n * @var array $scriptProperties\r\n *\r\n * @package formit\r\n */\r\n\r\n$modelPath = $modx->getOption(''formit.core_path'', null, $modx->getOption(''core_path'', null, MODX_CORE_PATH) . ''components/formit/'') . ''model/formit/'';\r\n$modx->loadClass(''FormIt'', $modelPath, true, true);\r\n\r\n$fi = new FormIt($modx,$scriptProperties);\r\n\r\n/** @var fiCountryOptions $co */\r\n$co = $fi->loadModule(''fiCountryOptions'',''countryOptions'',$scriptProperties);\r\n$co->initialize();\r\n$co->getData();\r\n$co->loadPrioritized();\r\n$co->iterate();\r\nreturn $co->output();', 0, 'a:10:{s:8:"selected";a:7:{s:4:"name";s:8:"selected";s:4:"desc";s:23:"prop_fico.selected_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:18:"prop_fico.tpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:6:"option";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:10:"useIsoCode";a:7:{s:4:"name";s:10:"useIsoCode";s:4:"desc";s:25:"prop_fico.useisocode_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:11:"prioritized";a:7:{s:4:"name";s:11:"prioritized";s:4:"desc";s:26:"prop_fico.prioritized_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:11:"optGroupTpl";a:7:{s:4:"name";s:11:"optGroupTpl";s:4:"desc";s:26:"prop_fico.optgrouptpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:8:"optgroup";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:20:"prioritizedGroupText";a:7:{s:4:"name";s:20:"prioritizedGroupText";s:4:"desc";s:35:"prop_fico.prioritizedgrouptext_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:12:"allGroupText";a:7:{s:4:"name";s:12:"allGroupText";s:4:"desc";s:27:"prop_fico.allgrouptext_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:17:"selectedAttribute";a:7:{s:4:"name";s:17:"selectedAttribute";s:4:"desc";s:32:"prop_fico.selectedattribute_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:20:" selected="selected"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:13:"toPlaceholder";a:7:{s:4:"name";s:13:"toPlaceholder";s:4:"desc";s:28:"prop_fico.toplaceholder_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:7:"country";a:7:{s:4:"name";s:7:"country";s:4:"desc";s:22:"prop_fico.country_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:16:"[[++cultureKey]]";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}}', '', 0, ''),
(8, 0, 0, 'FormItStateOptions', 'A utility snippet for generating a dropdown list of U.S. states.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * FormItStateOptions\r\n *\r\n * Automatically generates and outputs a U.S. state list for usage in forms\r\n *\r\n * @var modX $modx\r\n * @var array $scriptProperties\r\n *\r\n * @package formit\r\n */\r\n\r\n$modelPath = $modx->getOption(''formit.core_path'', null, $modx->getOption(''core_path'', null, MODX_CORE_PATH) . ''components/formit/'') . ''model/formit/'';\r\n$modx->loadClass(''FormIt'', $modelPath, true, true);\r\n\r\n$fi = new FormIt($modx,$scriptProperties);\r\n\r\n/** @var fiStateOptions $so */\r\n$so = $fi->loadModule(''fiStateOptions'',''stateOptions'',$scriptProperties);\r\n$so->initialize();\r\n$so->getData();\r\n$so->iterate();\r\nreturn $so->output();', 0, 'a:6:{s:8:"selected";a:7:{s:4:"name";s:8:"selected";s:4:"desc";s:23:"prop_fiso.selected_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:18:"prop_fiso.tpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:6:"option";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:7:"useAbbr";a:7:{s:4:"name";s:7:"useAbbr";s:4:"desc";s:22:"prop_fiso.useabbr_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:17:"selectedAttribute";a:7:{s:4:"name";s:17:"selectedAttribute";s:4:"desc";s:32:"prop_fiso.selectedattribute_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:20:" selected="selected"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:13:"toPlaceholder";a:7:{s:4:"name";s:13:"toPlaceholder";s:4:"desc";s:28:"prop_fiso.toplaceholder_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}s:7:"country";a:7:{s:4:"name";s:7:"country";s:4:"desc";s:22:"prop_fiso.country_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:16:"[[++cultureKey]]";s:7:"lexicon";s:17:"formit:properties";s:4:"area";s:0:"";}}', '', 0, '');
INSERT INTO `modx_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(12, 0, 0, 'SimpleSearch', '', 0, 6, 0, '/**\n * SimpleSearch\n *\n * Copyright 2010-11 by Shaun McCormick <shaun+sisea@modx.com>\n *\n * This file is part of SimpleSearch, a simple search component for MODx\n * Revolution. It is loosely based off of AjaxSearch for MODx Evolution by\n * coroico/kylej, minus the ajax.\n *\n * SimpleSearch is free software; you can redistribute it and/or modify it under\n * the terms of the GNU General Public License as published by the Free Software\n * Foundation; either version 2 of the License, or (at your option) any later\n * version.\n *\n * SimpleSearch is distributed in the hope that it will be useful, but WITHOUT\n * ANY WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS\n * FOR A PARTICULAR PURPOSE. See the GNU General Public License for more\n * details.\n *\n * You should have received a copy of the GNU General Public License along with\n * SimpleSearch; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\n * Suite 330, Boston, MA 02111-1307 USA\n *\n * @package simplesearch\n */\n/**\n * SimpleSearch snippet\n *\n * @var modX $modx\n * @var array $scriptProperties\n * @package simplesearch\n */\nrequire_once $modx->getOption(''sisea.core_path'',null,$modx->getOption(''core_path'').''components/simplesearch/'').''model/simplesearch/simplesearch.class.php'';\n$search = new SimpleSearch($modx,$scriptProperties);\n\n/* find search index and toplaceholder setting */\n$searchIndex = $modx->getOption(''searchIndex'',$scriptProperties,''search'');\n$toPlaceholder = $modx->getOption(''toPlaceholder'',$scriptProperties,false);\n$noResultsTpl = $modx->getOption(''noResultsTpl'',$scriptProperties,''SearchNoResults'');\n\n/* get search string */\nif (empty($_REQUEST[$searchIndex])) {\n    $output = $search->getChunk($noResultsTpl,array(\n        ''query'' => '''',\n    ));\n    return $search->output($output,$toPlaceholder);\n}\n$searchString = $search->parseSearchString($_REQUEST[$searchIndex]);\nif (!$searchString) {\n    $output = $search->getChunk($noResultsTpl,array(\n        ''query'' => $searchString,\n    ));\n    return $search->output($output,$toPlaceholder);\n}\n\n/* setup default properties */\n$tpl = $modx->getOption(''tpl'',$scriptProperties,''SearchResult'');\n$containerTpl = $modx->getOption(''containerTpl'',$scriptProperties,''SearchResults'');\n$showExtract = $modx->getOption(''showExtract'',$scriptProperties,true);\n$extractSource = $modx->getOption(''extractSource'',$scriptProperties,''content'');\n$extractLength = $modx->getOption(''extractLength'',$scriptProperties,200);\n$extractEllipsis = $modx->getOption(''extractEllipsis'',$scriptProperties,''...'');\n$highlightResults = $modx->getOption(''highlightResults'',$scriptProperties,true);\n$highlightClass = $modx->getOption(''highlightClass'',$scriptProperties,''sisea-highlight'');\n$highlightTag = $modx->getOption(''highlightTag'',$scriptProperties,''span'');\n$perPage = $modx->getOption(''perPage'',$scriptProperties,10);\n$pagingSeparator = $modx->getOption(''pagingSeparator'',$scriptProperties,'' | '');\n$placeholderPrefix = $modx->getOption(''placeholderPrefix'',$scriptProperties,''sisea.'');\n$includeTVs = $modx->getOption(''includeTVs'',$scriptProperties,'''');\n$processTVs = $modx->getOption(''processTVs'',$scriptProperties,'''');\n$tvPrefix = $modx->getOption(''tvPrefix'',$scriptProperties,'''');\n$offsetIndex = $modx->getOption(''offsetIndex'',$scriptProperties,''sisea_offset'');\n$idx = isset($_REQUEST[$offsetIndex]) ? intval($_REQUEST[$offsetIndex]) + 1 : 1;\n$postHooks = $modx->getOption(''postHooks'',$scriptProperties,'''');\n$activeFacet = $modx->getOption(''facet'',$_REQUEST,$modx->getOption(''activeFacet'',$scriptProperties,''default''));\n$activeFacet = $modx->sanitizeString($activeFacet);\n$facetLimit = $modx->getOption(''facetLimit'',$scriptProperties,5);\n$outputSeparator = $modx->getOption(''outputSeparator'',$scriptProperties,"\\n");\n$addSearchToLink = intval($m