(17, 2, 0, 'sitemap', '', 0, 5, 0, 'ini_set(''max_execution_time'', 0);\n\n$options = array(\n  xPDO::OPT_CACHE_KEY => ''sitemap'',\n);\n$output = $modx->cacheManager->get(''sitemap'', $options);\n\nif ($output == null) {\n    $output = ''<?xml version="1.0" encoding="UTF-8"?>\n    <urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n    '';\n\n    $stmt = $modx->query("\n        SELECT\n            GROUP_CONCAT(\n                ''<url>'',        \n                CONCAT(''<loc>" . MODX_SITE_URL . "'',uri,''</loc>''),\n                CONCAT(''<lastmod>'',FROM_UNIXTIME(IF(editedon=0,createdon,editedon),''%Y-%m-%d''),''</lastmod>''),\n                ''</url>''\n                SEPARATOR ''''\n            ) AS node\n        FROM modx_site_content AS s\n        WHERE s.deleted = 0 AND s.published = 1 AND s.searchable = 1 AND context_key=''web''\n        GROUP BY s.id\n        ORDER BY s.id ASC\n    ");\n\n    if ($stmt) {\n        $rows = $stmt->fetchAll(PDO::FETCH_COLUMN);\n		$count = count($rows);\n        $output .= implode('''', $rows);\n    }\n\n    $output .= ''</urlset>'';\n\n    $modx->cacheManager->set(''sitemap'', $output, 86400, $options);\n}\n\nreturn $output;', 0, 'a:0:{}', '', 0, ''),
(20, 1, 0, 'pdoResources', '', 0, 7, 0, '/** @var array $scriptProperties */\nif (isset($parents) && $parents === '''') {\n    $scriptProperties[''parents''] = $modx->resource->id;\n}\nif (!empty($returnIds)) {\n    $scriptProperties[''return''] = ''ids'';\n}\n\n// Adding extra parameters into special place so we can put them in a results\n/** @var modSnippet $snippet */\n$additionalPlaceholders = $properties = array();\nif (isset($this) && $this instanceof modSnippet) {\n    $properties = $this->get(''properties'');\n}\nelseif ($snippet = $modx->getObject(''modSnippet'', array(''name'' => ''pdoResources''))) {\n    $properties = $snippet->get(''properties'');\n}\nif (!empty($properties)) {\n    foreach ($scriptProperties as $k => $v) {\n        if (!isset($properties[$k])) {\n            $additionalPlaceholders[$k] = $v;\n        }\n    }\n}\n$scriptProperties[''additionalPlaceholders''] = $additionalPlaceholders;\n\n/** @var pdoFetch $pdoFetch */\n$fqn = $modx->getOption(''pdoFetch.class'', null, ''pdotools.pdofetch'', true);\n$path = $modx->getOption(''pdofetch_class_path'', null, MODX_CORE_PATH . ''components/pdotools/model/'', true);\nif ($pdoClass = $modx->loadClass($fqn, $path, false, true)) {\n    $pdoFetch = new $pdoClass($modx, $scriptProperties);\n} else {\n    return false;\n}\n$pdoFetch->addTime(''pdoTools loaded'');\n$output = $pdoFetch->run();\n\n$log = '''';\nif ($modx->user->hasSessionContext(''mgr'') && !empty($showLog)) {\n    $log .= ''<pre class="pdoResourcesLog">'' . print_r($pdoFetch->getTime(), 1) . ''</pre>'';\n}\n\n// Return output\nif (!empty($returnIds)) {\n    $modx->setPlaceholder(''pdoResources.log'', $log);\n    if (!empty($toPlaceholder)) {\n        $modx->setPlaceholder($toPlaceholder, $output);\n    } else {\n        return $output;\n    }\n} elseif (!empty($toSeparatePlaceholders)) {\n    $output[''log''] = $log;\n    $modx->setPlaceholders($output, $toSeparatePlaceholders);\n} else {\n    $output .= $log;\n\n    if (!empty($tplWr