INSERT INTO `modx_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(21, 1, 0, 'pdoUsers', '', 0, 7, 0, '/** @var array $scriptProperties */\n/** @var pdoFetch $pdoFetch */\n$fqn = $modx->getOption(''pdoFetch.class'', null, ''pdotools.pdofetch'', true);\n$path = $modx->getOption(''pdofetch_class_path'', null, MODX_CORE_PATH . ''components/pdotools/model/'', true);\nif ($pdoClass = $modx->loadClass($fqn, $path, false, true)) {\n    $pdoFetch = new $pdoClass($modx, $scriptProperties);\n} else {\n    return false;\n}\n$pdoFetch->addTime(''pdoTools loaded'');\n\n$class = ''modUser'';\n$profile = ''modUserProfile'';\n$member = ''modUserGroupMember'';\n\n// Start building "Where" expression\n$where = array();\nif (empty($showInactive)) {\n    $where[$class . ''.active''] = 1;\n}\nif (empty($showBlocked)) {\n    $where[$profile . ''.blocked''] = 0;\n}\n\n// Add users profiles and groups\n$innerJoin = array(\n    $profile => array(''alias'' => $profile, ''on'' => "$class.id = $profile.internalKey"),\n);\n\n// Filter by users, groups and roles\n$tmp = array(\n    ''users'' => array(\n        ''class'' => $class,\n        ''name'' => ''username'',\n        ''join'' => $class . ''.id'',\n    ),\n    ''groups'' => array(\n        ''class'' => ''modUserGroup'',\n        ''name'' => ''name'',\n        ''join'' => $member . ''.user_group'',\n    ),\n    ''roles'' => array(\n        ''class'' => ''modUserGroupRole'',\n        ''name'' => ''name'',\n        ''join'' => $member . ''.role'',\n    ),\n);\nforeach ($tmp as $k => $p) {\n    if (!empty($$k)) {\n        $$k = array_map(''trim'', explode('','', $$k));\n        ${$k . ''_in''} = ${$k . ''_out''} = $fetch_in = $fetch_out = array();\n        foreach ($$k as $v) {\n            if (is_numeric($v)) {\n                if ($v[0] == ''-'') {\n                    ${$k . ''_out''}[] = abs($v);\n                } else {\n                    ${$k . ''_in''}[] = abs($v);\n                }\n            } else {\n                if ($v[0] == ''-'') {\n                    $fetch_out[] = $v;\n                } else {\n                    $fetch_in[] = $v;\n                }\n            }\n        }\n\n        if (!empty($fetch_in) || !empty($fetch_out)) {\n            $q = $modx->newQuery($p[''class''], array($p[''name''] . '':IN'' => array_merge($fetch_in, $fetch_out)));\n            $q->select(''id,'' . $p[''name'']);\n            $tstart = microtime(true);\n            if ($q->prepare() && $q->stmt->execute()) {\n                $modx->queryTime += microtime(true) - $tstart;\n                $modx->executedQueries++;\n                while ($row = $q->stmt->fetch(PDO::FETCH_ASSOC)) {\n                    if (in_array($row[$p[''name'']], $fetch_in)) {\n                        ${$k . ''_in''}[] = $row[''id''];\n                    } else {\n                        ${$k . ''_out''}[] = $row[''id''];\n                    }\n                }\n            }\n        }\n\n        if (!empty(${$k . ''_in''})) {\n            $where[$p[''join''] . '':IN''] = ${$k . ''_in''};\n        }\n        if (!empty(${$k . ''_out''})) {\n            $where[$p[''join''] . '':NOT IN''] = ${$k . ''_out''};\n        }\n    }\n}\n\nif (!empty($groups_in) || !empty($groups_out) || !empty($roles_in) || !empty($roles_out)) {\n    $innerJoin[$member] = array(''alias'' => $member, ''on'' => "$class.id = $member.member");\n}\n\n// Fields to select\n$select = array(\n    $profile => implode('','', array_keys($modx->getFieldMeta($profile))),\n    $class => implode('','', array_keys($modx->getFieldMeta($class))),\n);\n\n// Add custom parameters\nforeach (array(''where'', ''innerJoin'', ''select'') as $v) {\n    if (!empty($scriptProperties[$v])) {\n        $tmp = $modx->fromJSON($scriptProperties[$v]);\n        if (is_array($tmp)) {\n            $$v = array_merge($$v, $tmp);\n        }\n    }\n    unset($scriptProperties[$v]);\n}\n$pdoFetch->addTime(''Conditions prepared'');\n\n$default = array(\n    ''class'' => $class,\n    ''innerJoin'' => $modx->toJSON($innerJoin),\n    ''where'' => $modx->toJSON($where),\n    ''select'' => $modx->toJSON($select),\n    ''groupby'' => $class . ''.id'',\n    ''sortby'' => $class . ''.id'',\n    ''sortdir'' => ''ASC'',\n    ''fastMode'' => false,\n    ''return'' => !empty($returnIds) ? ''ids'' : ''chunks'',\n    ''disableConditions'' => true,\n);\n\nif (!empty($users_in) && (empty($scriptProperties[''sortby'']) || $scriptProperties[''sortby''] == $class . ''.id'')) {\n    $scriptProperties[''sortby''] = "find_in_set(`$class`.`id`,''" . implode('','', $users_in) . "'')";\n    $scriptProperties[''sortdir''] = '''';\n}\n\n// Merge all properties and run!\n$pdoFetch->addTime(''Query parameters ready'');\n$pdoFetch->setConfig(array_merge($default, $scriptProperties), false);\n$output = $pdoFetch->run();\n\n$log = '''';\nif ($modx->user->hasSessionContext(''mgr'') && !empty($showLog)) {\n    $log .= ''<pre class="pdoUsersLog">'' . print_r($pdoFetch->getTime(), 1) . ''</pre>'';\n}\n\n// Return output\nif (!empty($returnIds)) {\n    $modx->setPlaceholder(''pdoUsers.log'', $log);\n    if (!empty($toPlaceholder)) {\n        $modx->setPlaceholder($toPlaceholder, $output);\n    } else {\n        return $output;\n    }\n} elseif (!empty($toSeparatePlaceholders)) {\n    $output[''log''] = $log;\n    $modx->setPlaceholders($output, $toSeparatePlaceholders);\n} else {\n    $output .= $log;\n\n    if (!empty($tplWrapper) && (!empty($wrapIfEmpty) || !empty($output))) {\n        $output = $pdoFetch->getChunk($tplWrapper, array(''output'' => $output), $pdoFetch->config[''fastMode'']);\n    }\n\n    if (!empty($toPlaceholder)) {\n        $modx->setPlaceholder($toPlaceholder, $output);\n    } else {\n        return $output;\n    }\n}', 0, 'a:30:{s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:17:"pdotools_prop_tpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:9:"returnIds";a:7:{s:4:"name";s:9:"returnIds";s:4:"desc";s:23:"pdotools_prop_returnIds";s:4:"type";s:13:"