(29, 2, 0, 'FaqHook', '', 0, 5, 0, '\r\n/*\r\nv. 1.3 (17.10.2016)\r\n*/\r\n\r\n$name = $hook->getValue(''name'');\r\n$email = $hook->getValue(''email'');\r\n$text = $hook->getValue(''text'');\r\n\r\n$product = $modx->newObject( ''modResource'' );\r\n$product->fromArray(\r\n    array(\r\n        ''pagetitle'' => "Новый отзыв от ".$name." от " . date("d.m.Y - H:i"),  //название страницы\r\n        ''parent''    => $scriptProperties[''parent''], // id родителя\r\n        ''published'' => 0,   //публикация\r\n        ''publishedon'' => time(),\r\n        ''show_in_tree'' => 0,\r\n        ''hidemenu'' => 1,\r\n        ''searchable'' => 0,\r\n        ''template'' => $scriptProperties[''template''],\r\n    )\r\n);\r\n$product->save();\r\n\r\n$product->setTVValue(''faq-name'', $name);\r\n$product->setTVValue(''faq-email'', $email);\r\n$product->setTVValue(''faq-text'', $text);\r\n\r\n// обработка прикреплённых файлов\r\n$allowed_exts = $modx->getOption(''allowedFileExt'', $scriptProperties, '''');\r\n$file_dir = $modx->getOption(''fileDir'', $scriptProperties, ''/userfiles/files'');\r\n$file_tv_name = $modx->getOption(''fileTVName'', $scriptProperties, ''file'');\r\nif (!preg_match(''/\\/$/'', $file_dir)) {\r\n    $file_dir .= ''/'';\r\n}\r\nif (isset($_FILES[''file''])) {\r\n    $file = $_FILES[''file''];\r\n    preg_match(''/(.*)\\.(.*)/'', $file[''name''], $matches);\r\n    if (count($matches) >= 3) {\r\n        $orig_file_name = $matches[1];\r\n        $orig_file_ext = $matches[2];\r\n        if (in_array($orig_file_ext, explode('','', $allowed_exts))) {\r\n            // транслитерация имени файла\r\n            $translit_class = $_SERVER[''DOCUMENT_ROOT''] . ''/core/components/translit/model/modx/translit/modtransliterate.class.php'';\r\n            if (file_exists($translit_class)) {\r\n                require_once $translit_class;\r\n                $t = new modTransliterate($modx);\r\n                $file_name = $t->translate($orig_file_name, ''russian'') . "." . $orig_file_ext;\r\n                $file_name = preg_replace(''/[^A-Za-z-_.0-9()]/'', '''', $file_name);\r\n            } else {\r\n                $n = 0;\r\n                do {\r\n                    $n++;\r\n                    $file_name = $n . "." . $orig_file_ext;\r\n                } while(file_exists($file_dir . $file_name));\r\n            }\r\n            $file_path = $file_dir . $file_name;\r\n            if (move_uploaded_file($file[''tmp_name''], $_SERVER[''DOCUMENT_ROOT''] . $file_path)) {\r\n                // получаем путь до источника файлов этой тв-шки\r\n                $tv = $modx->getObject(''modTemplateVar'', array(''name'' => $file_tv_name));\r\n                $source_id = $tv->get(''source'');\r\n                $source = $modx->getObject(''modMediaSource'', $source_id);\r\n                $properties = $source->getProperties();\r\n                $source_path = $properties[''basePath''][''value''];\r\n                \r\n                // убираем путь до источника файлов и ведущий слеш\r\n                $file_path = str_replace($source_path, '''', $file_path);\r\n                $file_path = preg_replace(''/^\\//'', '''', $file_path);\r\n                \r\n                $product->setTVValue($file_tv_name, $file_path);\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\nreturn true;', 0, 'a:2:{s:6:"parent";a:7:{s:4:"name";s:6:"parent";s:4:"desc";s:0:"";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:2:"21";s:7:"lexicon";N;s:4:"area";s:0:"";}s:8:"template";a:7:{s:4:"name";s:8:"template";s:4:"desc";s:0:"";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:2:"10";s:7:"lexicon";N;s:4:"area";s:0:"";}}', '', 0, ''),
(30, 0, 0, 'getSelections', '', 0, 18, 0, '/**\n * getSelections\n *\n * DESCRIPTION\n *\n * This snippet is a helper for getResources call.\n * It will allows you to select all linked resources under specific Selection with a usage of getResources snippet.\n * Returns distinct list of linked Resources for given Selections\n *\n * getResources are required\n *\n * PROPERTIES:\n *\n * &sortdir                 string  optional    Direction of sorting by linked resource''s menuindex. Default: ASC\n * &selections              string  optional    Comma separated list of Selection IDs for which should be retrieved linked resources. Default: empty string\n * &getResourcesSnippet     string  optional    Name of getResources snippet. Default: getResources\n * &excludeResources        string  optional    Comma separated list of Resources to exclude, even though they are in the Selection\n *\n * USAGE:\n *\n * [[getSelections? &selections=`1` &tpl=`rowTpl`]]\n * [[getSelections? &selections=`1` &tpl=`rowTpl` &sortby=`RAND()`]]\n *\n * @var modX $modx\n * @var array $scriptProperties\n */\n\n$corePath = $modx->getOption(''collections.core_path'', null, $modx->getOption(''core_path'', null, MODX_CORE_PATH) . ''components/collections/'');\n\n/** @var Collections $collections */\n$collections = $modx->getService(\n    ''collections'',\n    ''Collections'',\n    $corePath . ''model/collections/'',\n    array(\n        ''core_path'' => $corePath\n    )\n);\nif (!($collections instanceof Collections)) return '''';\n\n$getResourcesSnippet = $modx->getOption(''getResourcesSnippet'', $scriptProperties, ''getResources'');\n\n$getResourcesExists = $modx->getCount(''modSnippet'', array(''name'' => $getResourcesSnippet));\nif ($getResourcesExists == 0) return ''getResources not found'';\n\n$sortDir = strtolower($modx->getOption(''sortdir'', $scriptProperties, ''asc''));\n$selections = $modx->getOption(''selections'', $scriptProperties, '''');\n$sortBy = $modx->getOption(''sortby'', $scriptProperties, '''');\n\n$selections = $collections->explodeAndClean($selections);\n\nif ($sortDir != ''asc'') {\n    $sortDir = ''desc'';\n}\n\n$linkedResourcesQuery = $modx->newQuery(''CollectionSelection'');\n\nif (!empty($selections)) {\n    $linkedResourcesQuery->where(array(\n        ''collection:IN'' => $selections\n    ));\n}\n\nif ($sortBy == '''') {\n    $linkedResourcesQuery->sortby(''menuindex'', $sortDir);\n}\n\n$linkedResourcesQuery->select(array(\n    ''resource'' => ''DISTINCT(resource)''\n));\n\n$linkedResourcesQuery->prepare();\n\n$linkedResourcesQuery->stmt->execute();\n\n$linkedResources = $linkedResourcesQuery->stmt->fetchAll(PDO::FETCH_COLUMN, 0);\n\n$excludedResources = $modx->getOption(''excludeResources'', $scriptProperties, '''');\n$excludedResources = $collections->explodeAndClean($excludedResources);\n\nif (!empty($excludedResources)) {\n    $linkedResources = array_diff($linkedResources, $excludedResources);\n}\n\n$linkedResources = implode('','', $linkedResources);\n\n$properties = $scriptProperties;\nunset($properties[''selections'']);\n\n$properties[''resources''] = $linkedResources;\n$properties[''parents''] = ($properties[''getResourcesSnippet''] == ''pdoResources'') ? 0 : -1;\n\nif ($sortBy == '''') {\n    $properties[''sortby''] = ''FIELD(modResource.id, '' . $linkedResources . '' )'';\n    $properties[''sortdir''] = ''asc'';\n}\n\nreturn $modx->runSnippet($getResourcesSnippet, $properties);', 0, 'a:0:{}', '', 0, ''),
(31, 0, 0, 'Login', 'Displays a login and logout form.', 0, 19, 0, '/**\n * Login\n *\n * Copyright 2010 by Jason Coward <jason@modx.com> and Shaun McCormick\n * <shaun@modx.com>\n *\n * Login is free software; you can redistribute it and/or modify it\n * under the terms of the GNU General Public License as published by the Free\n * Software Foundation; either version 2 of the License, or (at your option) any\n * later version.\n *\n * Login is distributed in the hope that it will be useful, but WITHOUT ANY\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License along with\n * Login; if not, write to the Free Software Foundation, Inc., 59 Temple\n * Place, Suite 330, Boston, MA 02111-1307 USA\n *\n * @package login\n */\n/**\n * MODx Login Snippet\n *\n * This snippet handles login POSTs, sending the user back to where they came from or to a specific\n * location if specified in the POST.\n *\n * @package login\n *\n * @property textfield actionKey The REQUEST variable containing the action to take.\n * @property textfield loginKey The actionKey for login.\n * @property textfield logoutKey The actionKey for logout.\n * @property list tplType The type of template to expect for the views:\n *  modChunk - name of chunk to use\n *  file - full path to file to use as tpl\n *  embedded - the tpl is embedded in the page content\n *  inline - the tpl is inline content provided directly\n * @property textfield loginTpl The template for the login view (content based on tplType)\n * @property textfield logoutTpl The template for the logout view (content based on tplType)\n * @property textfield errTpl The template for any errors that occur when processing an view\n * @property list errTplType The type of template to expect for the error messages:\n *  modChunk - name of chunk to use\n *  file - full path to file to use as tpl\n *  inline - the tpl is inline content provided directly\n * @property integer logoutResourceId An explicit resource id to redirect users to on logout\n * @property string loginMsg The string to use for the login action. Defaults to\n * the lexicon string "login".\n * @property string logoutMsg The string to use for the logout action. Defaults\n * to the lexicon string "login.logout"\n */\nrequire_once $modx->getOption(''login.core_path'',null,$modx->getOption(''core_path'').''components/login/'').''model/login/login.class.php'';\n$login = new Login($modx,$scriptProperties);\nif (!is_object($login) || !($login instanceof Login)) return '''';\n\n$controller = $login->loadController(''Login'');\n$output = $controller->run($scriptProperties);\nreturn $output;', 0, 'a:22:{s:9:"actionKey";a:7:{s:4:"name";s:9:"actionKey";s:4:"desc";s:25:"prop_login.actionkey_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:7:"service";s:7:"lexicon";s:16:"login:properties";s:4:"area";s:0:"";}s:8:"loginKey";a:7:{s:4:"name";s:8:"loginKey";s:4:"desc";s:24:"prop_login.loginkey_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:5:"login";s:7:"lexicon";s:16:"login:properties";s:4:"area";s:0:"";}s:9:"logoutKey";a:7:{s:4:"name";s:9:"logoutKey";s:4:"desc";s:25:"prop_login.logoutkey_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:6:"logout";s:7:"lexicon";s:16:"login:properties";s:4:"area";s:0:"";}s:7:"tplType";a:7:{s:4:"name";s:7:"tplType";s:4:"desc";s:23:"prop_login.tpltype_desc";s:4:"type";s:4:"list";s:7:"options";a:4:{i:0;a:2:{s:5:"value";s:8:"modChunk";s:4:"text";s:18:"opt_register.chunk";}i:1;a:2:{s:5:"value";s:4:"file";s:4:"text";s:17:"opt_register.file";}i:2;a:2:{s:5:"value";s:6:"inline";s:4:"text";s:19:"opt_register.inline";}i:3;a:2:{s:5:"value";s:8:"embedded";s:4:"text";s:21:"opt_register.embedded";}}s:5:"value";s:8:"modChunk";s:7:"lexicon";s:16:"login:properties";s:4:"area";s:0:"";}s:8:"loginTpl";a:7:{s:4:"n