(79, 0, 0, 'ditsnewsunsubscribe', 'Removes subscriber', 0, 26, 0, 'require_once MODX_CORE_PATH.''/components/ditsnews/model/ditsnews/ditsnews.class.php'';\n$ditsnews = new Ditsnews($modx);\n\nif( $ditsnews->unsubscribe() )\n{\n return $modx->lexicon(''ditsnews.subscribers.unsubscribe.success'');\n}\nelse\n{\n return $modx->lexicon(''ditsnews.subscribers.unsubscribe.err'');\n}', 0, '', '', 0, ''),
(76, 0, 0, 'ditsnewsconfirm', 'Confirm (opt-in) newsletter subscription', 0, 26, 0, 'require_once MODX_CORE_PATH.''/components/ditsnews/model/ditsnews/ditsnews.class.php'';\n$ditsnews = new Ditsnews($modx);\n\nif( $ditsnews->confirmSignup() )\n{\n return $modx->lexicon(''ditsnews.subscribers.confirm.success'');\n}\nelse\n{\n return $modx->lexicon(''ditsnews.subscribers.confirm.err'');\n}', 0, '', '', 0, ''),
(77, 0, 0, 'ditsnewsPlaceholders', 'Use this snippet in your newsletter template to convert placeholders', 0, 26, 0, 'if (!isset($modx->ditsnews)) {\n    $modx->addPackage(''ditsnews'', $modx->getOption(''core_path'').''components/ditsnews/model/'');\n    $modx->ditsnews = $modx->getService(''ditsnews'', ''DitsNews'', $modx->getOption(''core_path'').''components/ditsnews/model/ditsnews/'');\n}\n \n$dn =& $modx->ditsnews;\nreturn $dn->setPlaceholders($scriptProperties);', 0, '', '', 0, ''),
(78, 0, 0, 'ditsnewssignup', 'Add newsletter subscriber (or return error)', 0, 26, 0, 'require_once MODX_CORE_PATH.''/components/ditsnews/model/ditsnews/ditsnews.class.php'';\n$ditsnews = new Ditsnews($modx);\n\nif( $ditsnews->signup($scriptProperties[''fields''], $scriptProperties[''confirmPage'']) ) {\n  return true;\n}\nelse {\n  $scriptProperties[''hook'']->errors[''signup''] = $ditsnews->errormsg;\n  return false;\n}', 0, '', '', 0, ''),
(60, 0, 0, 'brandList', 'Shorter version of getResources just to draw list of categories.', 0, 5, 0, '/**\n * brandList\n *\n *\n * @author Egor Bolgov\n * @version 1.0\n *\n *\n */\n$output = '''';\n\n/* set default properties */\n$parent = intval($parent);\n//$tvFilters = !empty($tvFilters) ? explode(''||'', $tvFilters) : array();\n$showUnpublished = !empty($showUnpublished) ? true : false;\n$showDeleted = !empty($showDeleted) ? true : false;\n\n$includeTVs = !empty($includeTVs) ? true : false;\n$includeTVList = !empty($includeTVList) ? explode('','', $includeTVList) : array();\n\n$sortby = isset($sortby) ? $sortby : ''publishedon'';\n//$sortbyTV = isset($sortbyTV) ? $sortbyTV : '''';\n$sortbyAlias = isset($sortbyAlias) ? $sortbyAlias : ''modResource'';\n$sortbyEscaped = !empty($sortbyEscaped) ? true : false;\n$sortdir = isset($sortdir) ? $sortdir : ''DESC'';\n//$sortdirTV = isset($sortdirTV) ? $sortdirTV : ''DESC'';\n$limit = isset($limit) ? (integer) $limit : 5;\n$offset = isset($offset) ? (integer) $offset : 0;\n$itemtemplate=isset($itemtemplate)? $itemtemplate: ''<li><a href="catalog/brendyi/#alias#.html">#pagetitle#</a>[[Pic?src=#tv.image#]]</li>'';\n\n/* multiple context support */\n$contextArray = array();\n$contextSpecified = false;\nif (!empty($context)) {\n	$contextArray = explode('','',$context);\n	array_walk($contextArray, ''trim'');\n	$contexts = array();\n	foreach ($contextArray as $ctx) {\n		$contexts[] = $modx->quote($ctx);\n	}\n	$context = implode('','',$contexts);\n	$contextSpecified = true;\n	unset($contexts,$ctx);\n} else {\n	$context = $modx->quote($modx->context->get(''key''));\n}\n\n/* build query */\n$criteria = array("modResource.parent=$parent");\nif ($contextSpecified) {\n    $contextResourceTbl = $modx->getTableName(''modContextResource'');\n    $criteria[] = "(modResource.context_key IN ({$context}) OR EXISTS(SELECT 1 FROM {$contextResourceTbl} ctx WHERE ctx.resource = modResource.id AND ctx.context_key IN ({$context}) LIMIT 1))";\n}\nif (empty($showDeleted)) {\n    $criteria[''deleted''] = ''0'';\n}\nif (empty($showUnpublished)) {\n    $criteria[''published''] = ''1'';\n}\n\n$criteria = $modx->newQuery(''modResource'', $criteria);\n\n\n\n\nif (!empty($sortby)) {\n    if (strpos($sortby, ''{'') === 0) {\n        $sorts = $modx->fromJSON($sortby);\n    } else {\n        $sorts = array($sortby => $sortdir);\n    }\n    if (is_array($sorts)) {\n        while (list($sort, $dir) = each($sorts)) {\n            if ($sortbyEscaped) $sort = $modx->escape($sort);\n            if (!empty($sortbyAlias)) $sort = $modx->escape($sortbyAlias) . ".{$sort}";\n            $criteria->sortby($sort, $dir);\n        }\n    }\n}\nif (!empty($limit)) $criteria->limit($limit, $offset);\n\n$columns = $modx->getSelectColumns(''modResource'', ''modResource'', '''', array(''content''), true);\n$criteria->select($columns);\n\n$criteria->prepare();\n//return $criteria->toSQL();\n$result = $modx->query($criteria->toSQL());\n$collection=$result->fetchAll(PDO::FETCH_ASSOC);\n\n\n\n$tvDefaultValues=array();\n$resourcesTVs=array();\n\nif (!empty($includeTVList)){\n\n	$resourcesIds=array();\n	foreach ($collection as $resource) {\n		$resourcesIds[]=$resource[''id''];\n	}\n\n\n	$tvDefaultQuery= $modx->newQuery(''modTemplateVar'');\n	$tvDefaultQuery->select(array(''modTemplateVar.name'',''modTemplateVar.default_text''));\n	$tvDefaultQuery->where(array (''modTemplateVar.name:IN'' => $includeTVList));\n	$tvDefaultQuery->prepare();\n	$result = $modx->query($tvDefaultQuery->toSQL());\n	foreach ($result->fetchAll(PDO::FETCH_ASSOC) as  $value){\n		$tvDefaultValues[''tv.''.$value[''name'']]=$value[''default_text''];\n	}\n\n\n\n	$tvValuesQuery = $modx->newQuery(''modTemplateVarResource'');\n	$tvValuesQuery->select(array(\n		''modTemplateVarResource.contentid'',\n		''modTemplateVarResource.tmplvarid'',\n		''modTemplateVarResource.value'',\n		''modTemplateVar.name''\n	));\n\n	$tvValuesQuery->leftJoin(''modTemplateVar'',''modTemplateVar'',array(''`modTemplateVar`.`id` = `modTemplateVarResource`.`tmplvarid`''));\n	$tvValuesQuery->where(array (''modTemplateVarResource.contentid:IN'' => $resourcesIds));\n	$tvValuesQuery->where(array (''modTemplateVar.name:IN'' => $includeTVList));\n	$tvValuesQuery->prepare();\n	$result = $modx->query($tvValuesQuery->toSQL());\n	$tvValues=$result->fetchAll(PDO::FETCH_ASSOC);\n\n	foreach ($tvValues as $value){\n		$resourcesTVs[$value[''contentid'']][''tv.''.$value[''name'']]=$value[''value''];\n	}\n\n}\n\n\nforeach ($collection as $resource) {\n  $arItem=array();\n  $resource=array_merge($resource,$tvDefaultValues,(array)$resourcesTVs[$resource[''id'']]);\n  foreach($resource as $key=>$value){\n      $arItem[''#''.$key.''#'']=$value;\n    }\n  $output.= str_replace(array_keys($arItem),array_values($arItem),$itemtemplate);\n}\n\n$toPlaceholder = $modx->getOption(''toPlaceholder'',$scriptProperties,false);\nif (!empty($toPlaceholder)) {\n    $modx->setPlaceholder($toPlaceholder,$output);\n    return '''';\n}\nreturn $output;', 0, '', '', 0, ''),
(61, 0, 0, 'catFilter', 'Snippet to prepare and draw category filter', 0, 5, 0, '/**\n * Сниппет обеспечивает генерацию фильтра вывода списка товаров\n * @var array $scriptProperties\n * @var modX $modx\n */\n$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\nif(!class_exists(''RequestParser'')) {\n	include_once $modelPath.''request.class.php'';\n}\nif(!class_exists(''catFilter'')) {\n	include_once $modelPath.''catfilter.class.php'';\n}\n$iStart=microtime(true);\n$modx->lexicon->load(''fcms:default'');\n\n//Обрабатываем входные значения\n$scriptProperties[''hideOnEmpty'']=$modx->getOption(''hideOnEmpty'',$scriptProperties,''N'');\n$scriptProperties[''parentId'']=$modx->getOption(''parentId'',$scriptProperties,$modx->resource->get(''id''));\n$scriptProperties[''itemsTpl'']=$modx->getOption(''itemsTpl'',$scriptProperties,3);\n$scriptProperties[''tvs'']=$modx->getOption(''tvs'',$scriptProperties,$modx->getOption(''filtred_tvs'',$scriptProperties,$modx->getOption(''fields'',$scriptProperties,'''')));\n//Параметры шаблонов\n$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,''filterTemplate'');\n$scriptProperties[''tplListItem'']=$modx->getOption(''tplListItem'',$scriptProperties,''filterListItem'');\n$scriptProperties[''tplNumberItem'']=$modx->getOption(''tplNumberItem'',$scriptProperties,''filterNumberItem'');\n$scriptProperties[''tplTextItem'']=$modx->getOption(''tplTextItem'',$scriptProperties,''filterTextItem'');\n$scriptProperties[''tplColorsItem'']=$modx->getOption(''tplColorsItem'',$scriptProperties,''filterColorsItem'');\n$scriptProperties[''tplCheckboxItem'']=$modx->getOption(''tplCheckboxItem'',$scriptProperties,''filterCheckboxItem'');\n\n$obCatFilter=new catFilter($modx,''GET'',$scriptProperties[''tvs''],$scriptProperties[''itemsTpl'']);\n\n//Смотрим, если товаров нет, то вместо результата вернём пустоту\nif($scriptProperties[''hideOnEmpty'']==''Y'') {\n	if(!RequestParser::hasItems($obCatFilter->getTemplates(), $scriptProperties[''parentId''])) return '''';\n}\n\n$sResult='''';\nif($obCatFilter->hasFields()) {\n	$arFields=$obCatFilter->getData();\n	$arResult=array();\n	foreach ($arFields as $field=>$arField) {\n		switch ($arField[''type'']) {\n			case catFilter::TYPE_LISTBOX:\n				$arResult[$field]=$modx->getChunk($scriptProperties[''tplListItem''],$arField);\n				break;\n			case catFilter::TYPE_NUMBER:\n				$arResult[$field]=$modx->getChunk($scriptProperties[''tplNumberItem''],$arField);\n				break;\n			case catFilter::TYPE_TEXT:\n				$arResult[$field]=$modx->getChunk($scriptProperties[''tplTextItem''],$arField);\n				break;\n			case catFilter::TYPE_COLORS:\n				$arResult[$field]='''';\n				foreach($arField[''colors''] as $arColor) {\n					$arResult[$field].=$modx->getChunk($scriptProperties[''tplColorsItem''],array_merge($arField,$arColor));\n				}\n				break;\n			case catFilter::TYPE_PARAM_EDIT:\n				$arResult[$field]='''';\n				foreach($arField[''values''] as $arColor) {\n					$arResult[$field].=$modx->getChunk($scriptProperties[''tplColorsItem''],array_merge($arField,$arColor));\n				}\n				break;\n			case catFilter::TYPE_CHECKBOX:\n				$arResult[$field]=$modx->getChunk($scriptProperties[''tplCheckboxItem''],$arField);\n				break;\n			default:\n				$arResult[$field]=''Unrendarable parameter'';\n		}\n		$sResult.=$arResult[$field];\n	}\n\n	$arResult[''rows'']=$sResult;\n	$arResult[''isFilled'']=$obCatFilter->isFilled();\n	$filtred_list_chunk=$modx->getChunk($scriptProperties[''tpl''],$arResult);\n	if(defined(''FS_DEBUG''))\n		echo "Общее время подготовки фильтра: ".(microtime(true)-$iStart);\n	return $filtred_list_chunk;\n}\nreturn '''';', 0, '', '', 0, ''),
(62, 0, 0, 'catList', 'Snippet to show records using getPages (getResources) with filter, pagination and sort set.', 0, 5, 0, '/**\n * Сниппет обеспечивает вывод списка элементов с учётом сортировки и фильтра\n * @var array $scriptProperties\n */\n$iStart=microtime(true);\nif(!class_exists(''RequestParser'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''request.class.php'';\n}\n$tmplId=$modx->getOption(''tmplId'',$scriptProperties,3);\n//Размер страницы\n$scriptProperties[''limit'']=RequestParser::pageSize($modx->getOption(''limit'',$scriptProperties,10));\n//Сортировка\nRequestParser::setSort($scriptProperties);\n//Фильтрация\n//Включаем фильтр\nif(isset($scriptProperties[''where'']))\n	$arWhere=@json_decode($scriptProperties[''where'']);\nif(!isset($arWhere) || !is_array($arWhere))\n	$arWhere=array(\n		''template:IN''=>explode('','',$tmplId)\n	);\nif($tvfiltres=RequestParser::getTVFilter($tmplId))\n	$scriptProperties["tvFilters"]=$tvfiltres;\n//Фильтр по полю pagetitle и longtitle\nif(isset($_GET["pagetitle"]) && $_GET[''pagetitle'']!='''') {\n	$sQ=''%''.$_GET[''pagetitle''].''%'';\n	$arWhere[]=array(\n		''pagetitle:LIKE''=>$sQ,\n	);\n}\nif(isset($_GET["longtitle"]) && $_GET[''longtitle'']!='''') {\n	$sQ=''%''.$_GET[''longtitle''].''%'';\n	$arWhere[]=array(\n		''longtitle:LIKE''=>$sQ,\n	);\n}\nif(is_array($arWhere) && count($arWhere)>0)\n	$scriptProperties[''where'']=json_encode($arWhere);\n\n$getpage=$modx->runSnippet("pdoPage",$scriptProperties);\nif(defined(''FS_DEBUG''))\n	echo "Общее время генерации списка: ".(microtime(true)-$iStart);\nreturn $getpage;', 0, 'a:0:{}', '', 0, ''),
(63, 0, 0, 'catPageSize', 'Snippet to switch amount of elements on one page', 0, 5, 0, '/**\n * Сниппет обеспечивает переключение количества выводимых страниц\n * @since 26.06.2012\n * @author Egor Bolgov <egor.b@fabricasaitov.ru>\n *\n * @var array $scriptProperties\n */\n$itemsTpl=$modx->getOption(''itemsTpl'',$scriptProperties,0);\n\nif(!class_exists(''RequestParser'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''request.class.php'';\n}\n$iStart=microtime(true);\n\nif(isset($scriptProperties[''hideOnEmpty'']) && $scriptProperties[''hideOnEmpty'']==''Y'') {\n	if(isset($scriptProperties[''parentId''])) {\n		$iParentId=$scriptProperties[''parentId''];\n	} else {\n		$iParentId=$modx->resource->get(''id'');\n	}\n	if(!RequestParser::hasItems($itemsTpl, $iParentId)) return '''';\n}\n\nif(!isset($scriptProperties[''tpl'']))\n	$scriptProperties[''tpl'']=''catPageSize'';\nif(!isset($scriptProperties[''cssItem'']))\n	$scriptProperties[''cssItem'']=''fcps-item'';\nif(!isset($scriptProperties[''cssItemActive'']))\n	$scriptProperties[''cssItemActive'']=''fcps-item-active'';\nif(!isset($scriptProperties[''cssItemDisabled'']))\n	$scriptProperties[''cssItemDisabled'']=''fcps-item-disabled'';\nif(!isset($scriptProperties[''num'']))\n	$scriptProperties[''num'']=''10,20,50'';\nif(!isset($scriptProperties[''default'']))\n	$scriptProperties[''default'']=RequestParser::pageSizeDefault();\nif(!isset($scriptProperties[''stripQ'']))\n	$scriptProperties[''stripQ'']=1;\n\n$arCounts=explode('','',$scriptProperties[''num'']);\nif(count($arCounts)>0) {\n	$iCurrent=RequestParser::pageSize($scriptProperties[''default'']);\n	if(isset($_REQUEST[''n'']) && in_array($_REQUEST[''n''],$arCounts)) {\n		$_SESSION[''f_N'']=$_REQUEST[''n''];\n		$iCurrent=$_REQUEST[''n''];\n	} elseif(isset($_SESSION[''f_N'']) && in_array($_SESSION[''f_N''],$arCounts)) {\n		$iCurrent=$_SESSION[''f_N''];\n	}\n	$arResult=array();\n	//TODO Не самое лучшее место, но в modX нет способа разобрать текущий урл\n	$sUrl=$_SERVER[''REQUEST_URI''];\n	$arUrl=explode(''?'',$sUrl);\n	if(count($arUrl)>1)\n		$sUrl=$arUrl[0];\n	$sUrl.=''?'';\n	if(count($_GET)>0)\n		foreach($_GET as $key=>$value) {\n			if($key==''q'' && $scriptProperties[''stripQ'']==1) continue;\n			if($key==''n'') continue;\n			if(is_array($value)) {\n				foreach($value as $ind=>$val) {\n					$sUrl.=urlencode($key).''[''.$ind.'']=''.urlencode($val).''&'';\n				}\n			} else {\n				$sUrl.=urlencode($key).''=''.urlencode($value).''&'';\n			}\n		}\n	foreach($arCounts as $iCount) {\n		$arResult[''link''.$iCount]=$sUrl.''n=''.$iCount;\n		$arResult[''class''.$iCount]=$scriptProperties[''cssItem''];\n		if($iCurrent==$iCount)\n			$arResult[''class''.$iCount].='' ''.$scriptProperties[''cssItemActive''];\n	}\n	$output=$modx->getChunk($scriptProperties[''tpl''],$arResult);\n	if(defined(''FS_DEBUG''))\n		echo "Время подготовки переключателя: ".(microtime(true)-$iStart);\n	return $output;\n}\nreturn ''Неверный параметр num'';', 0, '', '', 0, ''),
(64, 0, 0, 'catSearch', 'Snippet to prepare search data using searchForm, filter, pageSize', 0, 5, 0, '/**\n * Snippet perfoms catalog search using parameters passed to $_GET\n * @var array $scriptProperties\n */\n$iStart=microtime(true);\nif(!class_exists(''sfResourceTree'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''sfResourceTree.class.php'';\n}\nif(!class_exists(''RequestParser'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''request.class.php'';\n}\n$tplid = $modx->getOption(''tplid'',$scriptProperties,''3'');\n$cattplid = $modx->getOption(''cattplid'',$scriptProperties,''2'');\n$scriptProperties[''limit''] = $modx->getOption(''limit'',$scriptProperties,false);\n$iPageSize=RequestParser::pageSize($scriptProperties[''limit'']);\n$scriptProperties[''limit'']=$iPageSize;\n//Сортировка\nif(isset($_GET[''sort'']) && preg_match(''#^(tv_)?\\w+_\\w+_(asc|desc)$#'',$_GET[''sort''])) {\n  	$sort_param=explode(''_'',$_GET[''sort'']);\n	if (count($sort_param)==''3'') {\n		$scriptProperties[''sortby'']=$sort_param[0];\n		$scriptProperties[''sortdir'']=strtoupper($sort_param[2]);\n		$scriptProperties[''sortbyTV'']='''';\n		$scriptProperties[''sortdirTV'']='''';\n		$scriptProperties[''sortbyTVType'']='''';\n	} elseif (count($sort_param)==''4'') {\n		$scriptProperties[''sortby'']='''';\n		$scriptProperties[''sortdir'']='''';\n		$scriptProperties[''sortbyTV'']=$sort_param[1];\n		$scriptProperties[''sortdirTV'']=strtoupper($sort_param[3]);\n		$scriptProperties[''sortbyTVType'']=$sort_param[2];\n  	}\n}\n//Включаем фильтр\nif(isset($scriptProperties[''where'']))\n	$arWhere=@json_decode($scriptProperties[''where'']);\nif(!isset($arWhere) || !is_array($arWhere))\n	$arWhere=array(\n		''template:IN''=>explode('','',$tplid)\n	);\n	\n//Фильтр по категории\nif(isset($_GET["qwe"]) && $_GET[''qwe'']!='''') {\n	$obResourcesTree=new sfResourceTree($modx,$cattplid);\n	$childsArr=$obResourcesTree->getChildren(intval($_GET[''qwe'']));\n	$childsArr[]=intval($_GET[''qwe'']);\n	$scriptProperties[''parents'']=join('','',$childsArr);\n}\n//Фильтр по названию\nif(isset($_GET["keyword"]) && $_GET[''keyword'']!='''') {\n	$sQ=''%''.$_GET[''keyword''].''%'';\n	$arWhere[]=array(\n		''pagetitle:LIKE''=>$sQ,\n		''OR:longtitle:LIKE''=>$sQ,\n  		''OR:description:LIKE''=>$sQ,\n  		''OR:introtext:LIKE''=>$sQ,\n  		''OR:content:LIKE''=>$sQ,\n	);\n}\n//Фильтрация\n$tvfiltres=RequestParser::getTVFilter($tplid);\nif($tvfiltres!='''')\n	$scriptProperties["tvFilters"]=$tvfiltres;\nif(is_array($arWhere) && count($arWhere)>0) \n	$scriptProperties[''where'']=json_encode($arWhere);\n$scriptProperties[''showHidden''] = true;\n$output=$modx->runSnippet("pdoPage",$scriptProperties);\nif(defined(''FS_DEBUG''))\n	echo "Общее время генерации списка через getPage: ".(microtime(true)-$iStart);\nreturn $output;', 0, 'a:0:{}', '', 0, ''),
(65, 0, 0, 'catSort', 'Snippet to switch catalog elements sort order', 0, 5, 0, '/**\n * Сниппет обеспечивает генерацию фильтра вывода списка товаров\n * @var array $scriptProperties\n */\nif(!class_exists(''RequestParser'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''request.class.php'';\n}\n$iStart=microtime(true);\n$scriptProperties[''useJS'']=$modx->getOption(''useJS'',$scriptProperties,1);\n$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,''catSort'');\n$sort_tvs=$modx->getOption(''sort_tvs'',$scriptProperties,array());\n$sort_fields=$modx->getOption(''sort_fields'',$scriptProperties,array());\n//Код не мой и не доделанный\n$bSortTVs=!empty($sort_tvs)?$sort_tvs:false;\n$bSortFields=!empty($sort_fields)?$sort_fields:false;\n$arSortTV=explode('','',$sort_tvs);\n$arSortFields=explode('','',$sort_fields);\n$itemsTpl=!empty($itemsTpl)?$itemsTpl:3;\nif (strpos($itemsTpl, '','') !== false) {\n    $itemsTpl = explode('','', $itemsTpl);\n}\n//вывод списка сортировки\n$arSort=array();\n\n//Проверяем надо ли прятать\nif(isset($scriptProperties[''hideOnEmpty'']) && $scriptProperties[''hideOnEmpty'']==''Y'') {\n	if(isset($scriptProperties[''parentId''])) {\n		$iParentId=$scriptProperties[''parentId''];\n	} else {\n		$iParentId=$modx->resource->get(''id'');\n	}\n	if(!RequestParser::hasItems($itemsTpl, $iParentId)) return ''''; \n}\n\nif($bSortTVs) \n	foreach ($arSortFields as $field) \n		$arSort[]=array(''name''=>$field,''type''=>''text'');\nif($bSortTVs) \n	if($arTVs=array_values(RequestParser::getTVsFilter($itemsTpl, $arSortTV))) {\n		foreach($arTVs as &$arTV)\n			$arTV[''name'']=''tv_''.$arTV[''name''];\n		$arSort=array_merge($arSort,$arTVs);\n	}\n$arResult=array();\n$arResult[''sortListId'']=''sort''.md5(join(''|'',$scriptProperties));\nforeach ($arSort as $arItem) {\n	$arItem[''type'']=($arItem[''type'']==''number''?''decimal'':$arItem[''type'']);\n	$key=$arItem[''name''];\n	//$arResult[$key.''_caption'']=$arItem[''caption'']; //TODO Разобраться что это означает\n	$arResult[$key.''_name_asc'']=$key.''_''.$arItem[''type''].''_asc'';\n	$arResult[$key.''_name_desc'']=$key.''_''.$arItem[''type''].''_desc'';\n	$arResult[$key.''_asc_selected'']='''';\n	$arResult[$key.''_desc_selected'']='''';\n	if(isset($_GET[''sort''])) {\n  		if($arResult[$key.''_name_asc'']==$_GET[''sort''])\n			$arResult[$key.''_asc_selected'']=''selected="selected"'';\n        if($arResult[$key.''_name_desc'']==$_GET[''sort''])\n			$arResult[$key.''_desc_selected'']=''selected="selected"'';\n	}\n}\n\nif(count($arResult)>0) {\n	$sResult=$modx->getChunk($scriptProperties[''tpl''],$arResult);\n	if($scriptProperties[''useJS'']==1) {\n		$jsscript="\n		    <script type=''text/javascript''>\n		        jQuery(document).ready(function(){\n		                jQuery(''#".$arResult[''sortListId'']."'').bind(''change'', function(){\n		                    var param = jQuery(''#".$arResult[''sortListId'']." :selected'').val();\n		                    //$(window.location).attr(''href'', window.location.pathname+''?sort=''+param);\n		                    $(this).parents(''form'').trigger(''submit'');\n		                });\n		        });\n		    </script>\n		";\n	} else {\n		$jsscript='''';\n	}\n	if(defined(''FS_DEBUG''))\n		echo "Общее время подготовки сортировки: ".(microtime(true)-$iStart);\n	return $jsscript.$sResult;\n}\nreturn '''';', 0, 'a:0:{}', '', 0, ''),
(66, 0, 0, 'searchForm', 'Snippet to draw and prepare search form', 0, 5, 0, '/**\n * Сниппет выполняет построение дополнительного фильтра по категории, названию и другим дополнительным полям.\n * @var array $scriptProperties\n */\n$iStart=microtime(true);\nif(!class_exists(''sfResourceTree'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''sfResourceTree.class.php'';\n}\nif(!class_exists(''RequestParser'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''request.class.php'';\n}\n\n$cattpl = $modx->getOption(''cattpl'',$scriptProperties,2);\n$prodtpl = $modx->getOption(''prodtpl'',$scriptProperties,3);\n$tpl = $modx->getOption(''tpl'',$scriptProperties,''catSearchForm'');\n//Дерево разделов\n$obResourcesTree=new sfResourceTree($modx,$cattpl);\n$cats = $obResourcesTree->getResourceTree($cattpl, ''web'');\nif(isset($_GET[''qwe''])) {\n	$catPars=$obResourcesTree->getParents($_GET[''qwe'']);\n} else {\n	$catPars=array();\n}\n$catList = ''<div><label for="qwe">Категория</label><select name="qwe" id="qwe" class="iselect">'';\nforeach($cats as $cat) {\n	if(isset($_GET[''qwe'']) && !empty($_GET["qwe"]) && in_array($cat["id"],$catPars)) {\n		$catList .= ''<option value="''.$cat["id"].''" label="'' .$cat["name"]. ''" rel="selected">'' .$cat["name"]. ''</option>'';\n	} else {\n		$catList .= ''<option value="''.$cat["id"].''" label="'' .$cat["name"]. ''">'' .$cat["name"]. ''</option>'';\n	}\n}\n$catList .= "</select></div>";\n$arResult[''categories'']=$catList;\n$searchText=''<div id="search_name"><label for="name">Ключевое слово</label> <input class="itext" id="name" type="text" name="keyword"'';\nif(!empty($_GET["keyword"]))\n	$searchText .= ''value="''.$_GET["keyword"].''"'';\n$searchText .= ''/></div>'';\n$arResult[''searchText'']=$searchText;\n\n$output = '''';\n$modx->regClientCSS(''/assets/components/catSearch/catsearch.css'');\n$modx->regClientStartupScript(''/assets/components/catSearch/catsearch.js'');\n$modx->regClientCSS(''/assets/extra/jquery-ui/jquery-ui.min.css'');\n$modx->regClientStartupScript(''/assets/extra/jquery-ui/jquery-ui.min.js'');\n\nif(!isset($scriptProperties[''hideTVs'']) || $scriptProperties[''hideTVs'']==0) {\n	//Дополнительные поля\n	$arAvailableFields=false;\n	if(isset($scriptProperties[''tvList'']))\n		$arAvailableFields=explode('','',$scriptProperties[''tvList'']);\n	$arTVs=RequestParser::getTVs($prodtpl);\n	if($arAvailableFields) {\n		$arTmp=$arTVs;\n		$arTVs=array();\n		foreach($arAvailableFields as $sField)\n			$arTVs[$sField]=$arTmp[$sField];\n	}\n	$ranges = array();\n	foreach($arTVs as $tv) {\n		$tv[''name'']=''tv_''.$tv[''name''];\n		if($tv["type"]=="number") {\n			$smin = 0;\n			$smax = $tv["max"];\n			if(!empty($_GET[$tv["name"]."_from"]))\n				$smin = $_GET[$tv["name"]."_from"];\n			if(!empty($_GET[$tv["name"]."_to"]))\n				$smax = $_GET[$tv["name"]."_to"];\n			$output .= ''<div id="search_''.$tv[''name''].''">\n			<label for="''.$tv["name"].''_f">''.$tv["caption"].''</label>\n			от <input class="input-range itext" type="text" id="''.$tv["name"].''_f" name="''.$tv["name"].''_from" value="''.$smin.''"/>\n			до <input class="input-range itext" type="text" id="''.$tv["name"].''_t" name="''.$tv["name"].''_to" value="''.$smax.''"/>\n			</div><div class="range" id="''.$tv["name"].''-range"></div>'';\n			$ranges[] = array("name" => $tv["name"], "max" => $tv[''max'']);\n		} elseif($tv["type"]=="listbox") {\n			if(strpos($tv[''elements''],''@EVAL'')===0) {\n				$sQuery=substr($tv[''elements''],6);\n				$tv[''elements'']=eval(''global $modx; ''.$sQuery);\n			}\n			$sOptions = explode("||",$tv[''elements'']);\n			$output .= ''\n				<div id="search_''.$tv[''name''].''">\n				<label for="''.$tv["name"].''">''.$tv["caption"].''</label>\n				<select name="''.$tv["name"].''" id="''.$tv["name"].''" class="iselect">\n				<option value="">-- не важно --</option>'';\n			foreach($sOptions as $sOption) {\n				$arOption=explode(''=='',$sOption);\n				if(!isset($arOption[1])) $arOption[1]=$arOption[0];\n				if(!empty($_GET[$tv["name"]]) && $_GET[$tv["name"]]==$arOption[1])\n					$output .= ''<option value="''.$arOption[1].''" selected>''.$arOption[0].''</option>'';\n				else\n					$output .= ''<option value="''.$arOption[1].''">''.$arOption[0].''</option>'';\n			}\n			$output .= ''</select></div>'';\n		} elseif($tv["type"]=="text") {\n			$value='''';\n			if (isset($_GET[$tv[''name'']]))\n				$value=htmlspecialchars($_GET[$tv[''name'']],ENT_COMPAT,''utf-8'');\n			$output.=''<div id="search_''.$tv[''name''].''"><label for="''.$tv["name"].''">''.$tv["caption"].''</label><input type="text" value="''.$value.''" name="''.$tv[''name''].''" class="itext"/></div>'';\n		} elseif($tv["type"]=="checkbox") {\n			if(strpos($tv[''elements''],''@EVAL'')===0) {\n				$sQuery=substr($tv[''elements''],6);\n				$tv[''elements'']=eval(''global $modx; ''.$sQuery);\n			}\n			$arItems=explode(''||'',$tv[''elements'']);\n			$sCheckboxes=''<div id="search_''.$tv[''name''].''"><label for="''.$tv["name"].''">''.$tv["caption"].''</label>'';\n			foreach ($arItems as $value) {\n				$checkbox_tv=explode(''=='',$value);\n				if (!isset($checkbox_tv[1]))\n					$checkbox_tv[1]=$checkbox_tv[0];\n				if(isset($_GET[$tv[''name'']]) && is_array($_GET[$tv[''name'']])&& in_array($checkbox_tv[1],$_GET[$tv[''name'']]))\n					$sCheckboxes.=''<label class="chkbox"><input class="icheckbox" type="checkbox" name="''.$tv[''name''].''[]" value="''.$checkbox_tv[1].''" checked="checked" /> ''.$checkbox_tv[0].''</label>'';\n				else\n					$sCheckboxes.=''<label class="chkbox"><input class="icheckbox" type="checkbox" name="''.$tv[''name''].''[]" value="''.$checkbox_tv[1].''" /> ''.$checkbox_tv[0].''</label>'';\n			}\n			$output.=$sCheckboxes.''</div>'';\n		}\n	}\n\n	if(!isset($scriptProperties[''noScroller''])) {\n		foreach($ranges as $range) {\n			$smin = 0;\n			$smax = $range["max"];\n			if(!empty($_GET[$range["name"]."_from"]))\n				$smin = $_GET[$range["name"]."_from"];\n			if(!empty($_GET[$range["name"]."_to"]))\n				$smax = $_GET[$range["name"]."_to"];\n			$output.=''\n			<script type="text/javascript">\n				jQuery(document).ready(function() {\n				''.$range["name"].''_slider = jQuery( "#''.$range["name"].''-range" ).slider({\n				range: true,\n				min: 0,\n				max: ''.$range["max"].'',\n				values: [ ''.$smin.'', ''.$smax.'' ],\n				slide: function( event, ui ) {\n					jQuery( "#''.$range["name"].''_f" ).val(ui.values[ 0 ]);\n					jQuery( "#''.$range["name"].''_t" ).val(ui.values[ 1 ]);\n				}\n				});\n				jQuery( "#''.$range["name"].''_f" ).val( jQuery( "#''.$range["name"].''-range" ).slider( "values", 0 ));\n				jQuery( "#''.$range["name"].''_t" ).val( jQuery( "#''.$range["name"].''-range" ).slider( "values", 1 ));\n\n				jQuery( "#''.$range["name"].''_f" ).change(function(){\n				v0 = jQuery( "#''.$range["name"].''_f" ).val();\n				v1 = jQuery( "#''.$range["name"].''-range" ).slider( "values", 1 );\n				''.$range["name"].''_slider.slider({values: [v0, v1]});\n				});\n				jQuery( "#''.$range["name"].''_t" ).change(function(){\n				v0 = jQuery( "#''.$range["name"].''-range" ).slider( "values", 0 );\n				v1 = jQuery( "#''.$range["name"].''_t" ).val();\n				''.$range["name"].''_slider.slider({values: [v0, v1]});\n				});\n				});\n			</script>\n			'';\n		}\n	}\n	$arResult[''tvs'']=$output;\n}\n$output=$modx->getChunk($tpl,$arResult);\nif(defined(''FS_DEBUG''))\n	echo "Общее время подготовки поиска: ".(microtime(true)-$iStart);\nreturn $output;', 0, 'a:0:{}', '', 0, '');
INSERT INTO `modx_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(67, 0, 0, 'countChildren', 'Snippet that counts number of children in particular resource', 0, 5, 0, '/**\n * Сниппет обеспечивает подсчёт вложенных в ресурс ресурсов. Допускается фильтрация по типу\n * (страница или контейнер), по шаблону (один или массив шаблонов)\n * &parent - ID родительского контейнера, если пустой - текущий родитель;\n * &itemTpl - ID шаблонов, ресурсов которые необходимо посчитать, через ",";\n * &type - page или container, если не указан, фильтр не применяется;\n * &showOnEmpty - Y|N показывать результат, если результат сниппета 0;\n * &tpl - чанк для декорирования вывода, если не указан, сниппет возвращает просто число;\n *\n * @var array $scriptProperties\n */\n\n$scriptProperties[''parent'']=$modx->getOption(''parent'',$scriptProperties,$modx->resource->get(''id''));\n$scriptProperties[''itemTpl'']=$modx->getOption(''itemTpl'',$scriptProperties,'''');\n$scriptProperties[''type'']=$modx->getOption(''type'',$scriptProperties,'''');\n$scriptProperties[''showOnEmpty'']=$modx->getOption(''showOnEmpty'',$scriptProperties,''Y'');\n$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,'''');\n\n//Подготовка шаблонов товаров\n$arItemsTpl=array();\nif($scriptProperties[''itemTpl'']!='''') {\n	$arItemsTplTmp=explode('','',$scriptProperties[''itemTpl'']);\n	if(is_array($arItemsTplTmp) && count($arItemsTplTmp)>1) {\n		foreach($arItemsTplTmp as $iTpl) {\n			$arItemsTpl[]=intval($iTpl);\n		}\n	} else {\n		$arItemsTpl=array($scriptProperties[''itemsTpl'']);\n	}\n}\n\n$arWhere=array(\n	''parent''=>intval($scriptProperties[''parent''])\n);\nif(count($arItemsTpl)>0) {\n	$arWhere[''template:IN'']=$arItemsTpl;\n}\nif($scriptProperties[''type'']==''page'') {\n	$arWhere[''isfolder'']=0;\n}\nif($scriptProperties[''type'']==''container'') {\n	$arWhere[''isfolder'']=1;\n}\n\n$c = $modx->newQuery(''modResource'');\n$c->select(''count(`modResource`.`id`) as `cnt`'');\n$c->where($arWhere);\n$rows= xPDOObject::_loadRows($modx, ''modResource'', $c);\n$res='''';\nif($obRes=$rows->fetch()) {\n	if($obRes[''cnt'']==0 && $scriptProperties[''showOnEmpty'']==''N'') {\n		return '''';\n	}\n	$res=$obRes[''cnt''];\n}\nif($scriptProperties[''tpl'']!='''') {\n	$arResult=$scriptProperties;\n	$arResult[''count'']=$res;\n	return $modx->getChunk($scriptProperties[''tpl''],$arResult);\n} else {\n	return $res;\n}', 0, '', '', 0, ''),
(68, 0, 0, 'checkAuth', 'Snippet that shows one of two chunks depending on user auth', 0, 5, 0, '/**\n * Сниппет обеспечивает вывод одного из двух чанков в зависимости от авторизованности пользователя\n * &user - чанк, который будет выведен в результатах в случае, если пользователь авторизован;\n * &guest - чанк, который будет выведен в результать, если пользователь гость;\n * &context - контекст (или контексты) для которых проверять авторизацию, по умолчанию web;\n *\n * @var array $scriptProperties\n */\n\n$scriptProperties[''user'']=$modx->getOption(''user'',$scriptProperties,''checkAuthUser'');\n$scriptProperties[''guest'']=$modx->getOption(''guest'',$scriptProperties,''checkAuthGuest'');\n$scriptProperties[''context'']=trim($modx->getOption(''context'',$scriptProperties,$modx->context->key));\n\n$arContextsTmp=explode('','',$scriptProperties[''context'']);\nif(is_array($arContextsTmp) && count($arContextsTmp)>1) {\n	foreach($arContextsTmp as $sTmp) {\n		$arContexts[]=trim($sTmp);\n	}\n} else {\n	$arContexts=array($scriptProperties[''context'']);\n}\n\n$bAuth=true;\nforeach($arContexts as $sContext) {\n	$bAuth&=$modx->user->isAuthenticated($sContext);\n}\n\nif($bAuth) {\n	return $scriptProperties[''user'']!=''''?$modx->getChunk($scriptProperties[''user''],$scriptProperties):'''';\n}\nreturn $scriptProperties[''guest'']!=''''?$modx->getChunk($scriptProperties[''guest''],$scriptProperties):'''';', 0, '', '', 0, ''),
(69, 0, 0, 'priceFormat', 'Snippet that formats numbers according set format', 0, 5, 0, '/**\n * Сниппет обеспечивает форматирование числа с использованием функции number_format. Можно вызывать как сниппет\n * и как фильтр.\n * &input - входное значение, по умолчанию 0\n * &options - параметры форматирования, по умолчанию строка "2|,| ". Означает - 2 знака дробной части|разделитель дробной части ","|Разделитель тысяч - пробел\n *\n * @var array $scriptProperties\n */\n$scriptProperties[''input'']=$modx->getOption(''input'',$scriptProperties,0);\n$scriptProperties[''options'']=$modx->getOption(''options'',$scriptProperties,''2|,| '');\nif($scriptProperties[''options'']=='''') $scriptProperties[''options'']=''2|,| '';\n\n$arNumberFormat=explode(''|'',$scriptProperties[''options'']);\nreturn number_format($scriptProperties[''input''],intval($arNumberFormat[0]),$arNumberFormat[1],$arNumberFormat[2]);', 0, '', '', 0, ''),
(70, 0, 0, 'tvValue', 'TV value for list and checkbox type tvs', 0, 5, 0, '/**\n * Сниппет выполняет конвертацию значения поля из значения представленного в базе данных для поля типа "список" в текстовое представление\n * &val - значение\n * &tv - название ТВ\n *\n * @var array $scriptProperties\n */\nif(!class_exists(''RequestParser'')) {\n	$modelPath = $modx->getOption(''core_path'').''components/fcms/model/'';\n	include_once $modelPath.''request.class.php'';\n}\n\n$scriptProperties[''val'']=trim($modx->getOption(''val'',$scriptProperties,''''));\n$arValues=RequestParser::getTVData($scriptProperties[''tv'']);\n\nif(isset($arValues[$scriptProperties[''val'']])) {\n	return $arValues[$scriptProperties[''val'']];\n}\nreturn $scriptProperties[''val''];', 0, '', '', 0, ''),
(71, 0, 0, 'getResources', '<strong>1.6.1-pl</strong> A general purpose Resource listing and summarization snippet for MODX Revolution', 0, 0, 0, '/**\n * getResources\n *\n * A general purpose Resource listing and summarization snippet for MODX 2.x.\n *\n * @author Jason Coward\n * @copyright Copyright 2010-2013, Jason Coward\n *\n * TEMPLATES\n *\n * tpl - Name of a chunk serving as a resource template\n * [NOTE: if not provided, properties are dumped to output for each resource]\n *\n * tplOdd - (Opt) Name of a chunk serving as resource template for resources with an odd idx value\n * (see idx property)\n * tplFirst - (Opt) Name of a chunk serving as resource template for the first resource (see first\n * property)\n * tplLast - (Opt) Name of a chunk serving as resource template for the last resource (see last\n * property)\n * tpl_{n} - (Opt) Name of a chunk serving as resource template for the nth resource\n *\n * tplCondition - (Opt) Defines a field of the resource to evaluate against keys defined in the\n * conditionalTpls property. Must be a resource field; does not work with Template Variables.\n * conditionalTpls - (Opt) A JSON object defining a map of field values and the associated tpl to\n * use when the field defined by tplCondition matches the value. [NOTE: tplOdd, tplFirst, tplLast,\n * and tpl_{n} will take precedence over any defined conditionalTpls]\n *\n * tplWrapper - (Opt) Name of a chunk serving as a wrapper template for the output\n * [NOTE: Does not work with toSeparatePlaceholders]\n *\n * SELECTION\n *\n * parents - Comma-delimited list of ids serving as parents\n *\n * context - (Opt) Comma-delimited list of context keys to limit results by; if empty, contexts for all specified\n * parents will be used (all contexts if 0 is specified) [default=]\n *\n * depth - (Opt) Integer value indicating depth to search for resources from each parent [default=10]\n *\n * tvFilters - (Opt) Delimited-list of TemplateVar values to filter resources by. Supports two\n * delimiters and two value search formats. The first delimiter || represents a logical OR and the\n * primary grouping mechanism.  Within each group you can provide a comma-delimited list of values.\n * These values can be either tied to a specific TemplateVar by name, e.g. myTV==value, or just the\n * value, indicating you are searching for the value in any TemplateVar tied to the Resource. An\n * example would be &tvFilters=`filter2==one,filter1==bar%||filter1==foo`\n * [NOTE: filtering by values uses a LIKE query and % is considered a wildcard.]\n * [NOTE: this only looks at the raw value set for specific Resource, i. e. there must be a value\n * specifically set for the Resource and it is not evaluated.]\n *\n * tvFiltersAndDelimiter - (Opt) Custom delimiter for logical AND, default '','', in case you want to\n * match a literal comma in the tvFilters. E.g. &tvFiltersAndDelimiter=`&&`\n * &tvFilters=`filter1==foo,bar&&filter2==baz` [default=,]\n *\n * tvFiltersOrDelimiter - (Opt) Custom delimiter for logical OR, default ''||'', in case you want to\n * match a literal ''||'' in the tvFilters. E.g. &tvFiltersOrDelimiter=`|OR|`\n * &tvFilters=`filter1==foo||bar|OR|filter2==baz` [default=||]\n *\n * where - (Opt) A JSON expression of criteria to build any additional where clauses from. An example would be\n * &where=`{{"alias:LIKE":"foo%", "OR:alias:LIKE":"%bar"},{"OR:pagetitle:=":"foobar", "AND:description:=":"raboof"}}`\n *\n * sortby - (Opt) Field to sort by or a JSON array, e.g. {"publishedon":"ASC","createdon":"DESC"} [default=publishedon]\n * sortbyTV - (opt) A Template Variable name to sort by (if supplied, this precedes the sortby value) [default=]\n * sortbyTVType - (Opt) A data type to CAST a TV Value to in order to sort on it properly [default=string]\n * sortbyAlias - (Opt) Query alias for sortby field [default=]\n * sortbyEscaped - (Opt) Escapes the field name(s) specified in sortby [default=0]\n * sortdir - (Opt) Order which to sort by [default=DESC]\n * sortdirTV - (Opt) Order which to sort by a TV [default=DESC]\n * limit - (Opt) Limits the number of resources returned [default=5]\n * offset - (Opt) An offset of resources returned by the criteria to skip [default=0]\n * dbCacheFlag - (Opt) Controls caching of db queries; 0|false = do not cache result set; 1 = cache result set\n * according to cache settings, any other integer value = number of seconds to cache result set [default=0]\n *\n * OPTIONS\n *\n * includeContent - (Opt) Indicates if the content of each resource should be returned in the\n * results [default=0]\n * includeTVs - (Opt) Indicates if TemplateVar values should be included in the properties available\n * to each resource template [default=0]\n * includeTVList - (Opt) Limits the TemplateVars that are included if includeTVs is true to those specified\n * by name in a comma-delimited list [default=]\n * prepareTVs - (Opt) Prepares media-source dependent TemplateVar values [default=1]\n * prepareTVList - (Opt) Limits the TVs that are prepared to those specified by name in a comma-delimited\n * list [default=]\n * processTVs - (Opt) Indicates if TemplateVar values should be rendered as they would on the\n * resource being summarized [default=0]\n * processTVList - (opt) Limits the TemplateVars that are processed if included to those specified\n * by name in a comma-delimited list [default=]\n * tvPrefix - (Opt) The prefix for TemplateVar properties [default=tv.]\n * idx - (Opt) You can define the starting idx of the resources, which is an property that is\n * incremented as each resource is rendered [default=1]\n * first - (Opt) Define the idx which represents the first resource (see tplFirst) [default=1]\n * last - (Opt) Define the idx which represents the last resource (see tplLast) [default=# of\n * resources being summarized + first - 1]\n * outputSeparator - (Opt) An optional string to separate each tpl instance [default="\\n"]\n * wrapIfEmpty - (Opt) Indicates if the tplWrapper should be applied if the output is empty [default=0]\n *\n */\n$output = array();\n$outputSeparator = isset($outputSeparator) ? $outputSeparator : "\\n";\n\n/* set default properties */\n$tpl = !empty($tpl) ? $tpl : '''';\n$includeContent = !empty($includeContent) ? true : false;\n$includeTVs = !empty($includeTVs) ? true : false;\n$includeTVList = !empty($includeTVList) ? explode('','', $includeTVList) : array();\n$processTVs = !empty($processTVs) ? true : false;\n$processTVList = !empty($processTVList) ? explode('','', $processTVList) : array();\n$prepareTVs = !empty($prepareTVs) ? true : false;\n$prepareTVList = !empty($prepareTVList) ? explode('','', $prepareTVList) : array();\n$tvPrefix = isset($tvPrefix) ? $tvPrefix : ''tv.'';\n$parents = (!empty($parents) || $parents === ''0'') ? explode('','', $parents) : array($modx->resource->get(''id''));\narray_walk($parents, ''trim'');\n$parents = array_unique($parents);\n$depth = isset($depth) ? (integer) $depth : 10;\n\n$tvFiltersOrDelimiter = isset($tvFiltersOrDelimiter) ? $tvFiltersOrDelimiter : ''||'';\n$tvFiltersAndDelimiter = isset($tvFiltersAndDelimiter) ? $tvFiltersAndDelimiter : '','';\n$tvFilters = !empty($tvFilters) ? explode($tvFiltersOrDelimiter, $tvFilters) : array();\n\n$where = !empty($where) ? $modx->fromJSON($where) : array();\n$showUnpublished = !empty($showUnpublished) ? true : false;\n$showDeleted = !empty($showDeleted) ? true : false;\n\n$sortby = isset($sortby) ? $sortby : ''publishedon'';\n$sortbyTV = isset($sortbyTV) ? $sortbyTV : '''';\n$sortbyAlias = isset($sortbyAlias) ? $sortbyAlias : ''modResource'';\n$sortbyEscaped = !empty($sortbyEscaped) ? true : false;\n$sortdir = isset($sortdir) ? $sortdir : ''DESC'';\n$sortdirTV = isset($sortdirTV) ? $sortdirTV : ''DESC'';\n$limit = isset($limit) ? (integer) $limit : 5;\n$offset = isset($offset) ? (integer) $offset : 0;\n$totalVar = !empty($totalVar) ? $totalVar : ''total'';\n\n$dbCacheFlag = !isset($dbCacheFlag) ? false : $dbCacheFlag;\nif (is_string($dbCacheFlag) || is_numeric($dbCacheFlag)) {\n    if ($dbCacheFlag == ''0'') {\n        $dbCacheFlag = false;\n    } elseif ($dbCacheFlag == ''1'') {\n        $dbCacheFlag = true;\n    } else {\n        $dbCacheFlag = (integer) $dbCacheFlag;\n    }\n}\n\n/* multiple context support */\n$contextArray = array();\n$contextSpecified = false;\nif (!empty($context)) {\n    $contextArray = explode('','',$context);\n    array_walk($contextArray, ''trim'');\n    $contexts = array();\n    foreach ($contextArray as $ctx) {\n        $contexts[] = $modx->quote($ctx);\n    }\n    $context = implode('','',$contexts);\n    $contextSpecified = true;\n    unset($contexts,$ctx);\n} else {\n    $context = $modx->quote($modx->context->get(''key''));\n}\n\n$pcMap = array();\n$pcQuery = $modx->newQuery(''modResource'', array(''id:IN'' => $parents), $dbCacheFlag);\n$pcQuery->select(array(''id'', ''context_key''));\nif ($pcQuery->prepare() && $pcQuery->stmt->execute()) {\n    foreach ($pcQuery->stmt->fetchAll(PDO::FETCH_ASSOC) as $pcRow) {\n        $pcMap[(integer) $pcRow[''id'']] = $pcRow[''context_key''];\n    }\n}\n\n$children = array();\n$parentArray = array();\nforeach ($parents as $parent) {\n    $parent = (integer) $parent;\n    if ($parent === 0) {\n        $pchildren = array();\n        if ($contextSpecified) {\n            foreach ($contextArray as $pCtx) {\n                if (!in_array($pCtx, $contextArray)) {\n                    continue;\n                }\n                $options = $pCtx !== $modx->context->get(''key'') ? array(''context'' => $pCtx) : array();\n                $pcchildren = $modx->getChildIds($parent, $depth, $options);\n                if (!empty($pcchildren)) $pchildren = array_merge($pchildren, $pcchildren);\n            }\n        } else {\n            $cQuery = $modx->newQuery(''modContext'', array(''key:!='' => ''mgr''));\n            $cQuery->select(array(''key''));\n            if ($cQuery->prepare() && $cQuery->stmt->execute()) {\n                foreach ($cQuery->stmt->fetchAll(PDO::FETCH_COLUMN) as $pCtx) {\n                    $options = $pCtx !== $modx->context->get(''key'') ? array(''context'' => $pCtx) : array();\n                    $pcchildren = $modx->getChildIds($parent, $depth, $options);\n                    if (!empty($pcchildren)) $pchildren = array_merge($pchildren, $pcchildren);\n                }\n            }\n        }\n        $parentArray[] = $parent;\n    } else {\n        $pContext = array_key_exists($parent, $pcMap) ? $pcMap[$parent] : false;\n        if ($debug) $modx->log(modX::LOG_LEVEL_ERROR, "context for {$parent} is {$pContext}");\n        if ($pContext && $contextSpecified && !in_array($pContext, $contextArray, true)) {\n            $parent = next($parents);\n            continue;\n        }\n        $parentArray[] = $parent;\n        $options = !empty($pContext) && $pContext !== $modx->context->get(''key'') ? array(''context'' => $pContext) : array();\n        $pchildren = $modx->getChildIds($parent, $depth, $options);\n    }\n    if (!empty($pchildren)) $children = array_merge($children, $pchildren);\n    $parent = next($parents);\n}\n$parents = array_merge($parentArray, $children);\n\n/* build query */\n$criteria = array("modResource.parent IN (" . implode('','', $parents) . ")");\nif ($contextSpecified) {\n    $contextResourceTbl = $modx->getTableName(''modContextResource'');\n    $criteria[] = "(modResource.context_key IN ({$context}) OR EXISTS(SELECT 1 FROM {$contextResourceTbl} ctx WHERE ctx.resource = modResource.id AND ctx.context_key IN ({$context})))";\n}\nif (empty($showDeleted)) {\n    $criteria[''deleted''] = ''0'';\n}\nif (empty($showUnpublished)) {\n    $criteria[''published''] = ''1'';\n}\nif (empty($showHidden)) {\n    $criteria[''hidemenu''] = ''0'';\n}\nif (!empty($hideContainers)) {\n    $criteria[''isfolder''] = ''0'';\n}\n$criteria = $modx->newQuery(''modResource'', $criteria);\nif (!empty($tvFilters)) {\n    $tmplVarTbl = $modx->getTableName(''modTemplateVar'');\n    $tmplVarResourceTbl = $modx->getTableName(''modTemplateVarResource'');\n    $conditions = array();\n    $operators = array(\n        ''<=>'' => ''<=>'',\n        ''==='' => ''='',\n        ''!=='' => ''!='',\n        ''<>'' => ''<>'',\n        ''=='' => ''LIKE'',\n        ''!='' => ''NOT LIKE'',\n        ''<<'' => ''<'',\n        ''<='' => ''<='',\n        ''=<'' => ''=<'',\n        ''>>'' => ''>'',\n        ''>='' => ''>='',\n        ''=>'' => ''=>''\n    );\n    foreach ($tvFilters as $fGroup => $tvFilter) {\n        $filterGroup = array();\n        $filters = explode($tvFiltersAndDelimiter, $tvFilter);\n        $multiple = count($filters) > 0;\n        foreach ($filters as $filter) {\n            $operator = ''=='';\n            $sqlOperator = ''LIKE'';\n            foreach ($operators as $op => $opSymbol) {\n                if (strpos($filter, $op, 1) !== false) {\n                    $operator = $op;\n                    $sqlOperator = $opSymbol;\n                    break;\n                }\n            }\n            $tvValueField = ''tvr.value'';\n            $tvDefaultField = ''tv.default_text'';\n            $f = explode($operator, $filter);\n            if (count($f) >= 2) {\n                if (count($f) > 2) {\n                    $k = array_shift($f);\n                    $b = join($operator, $f);\n                    $f = array($k, $b);\n                }\n                $tvName = $modx->quote($f[0]);\n                if (is_numeric($f[1]) && !in_array($sqlOperator, array(''LIKE'', ''NOT LIKE''))) {\n                    $tvValue = $f[1];\n                    if ($f[1] == (integer)$f[1]) {\n                        $tvValueField = "CAST({$tvValueField} AS SIGNED INTEGER)";\n                        $tvDefaultField = "CAST({$tvDefaultField} AS SIGNED INTEGER)";\n                    } else {\n                        $tvValueField = "CAST({$tvValueField} AS DECIMAL)";\n                        $tvDefaultField = "CAST({$tvDefaultField} AS DEC