conTpls = $modx->fromJSON($conditionalTpls);\n        $subject = $properties[$tplCondition];\n        $tplOperator = !empty($tplOperator) ? $tplOperator : ''='';\n        $tplOperator = strtolower($tplOperator);\n        $tplCon = '''';\n        foreach ($conTpls as $operand => $conditionalTpl) {\n            switch ($tplOperator) {\n                case ''!='':\n                case ''neq'':\n                case ''not'':\n                case ''isnot'':\n                case ''isnt'':\n                case ''unequal'':\n                case ''notequal'':\n                    $tplCon = (($subject != $operand) ? $conditionalTpl : $tplCon);\n                    break;\n                case ''<'':\n                case ''lt'':\n                case ''less'':\n                case ''lessthan'':\n                    $tplCon = (($subject < $operand) ? $conditionalTpl : $tplCon);\n                    break;\n                case ''>'':\n                case ''gt'':\n                case ''greater'':\n                case ''greaterthan'':\n                    $tplCon = (($subject > $operand) ? $conditionalTpl : $tplCon);\n                    break;\n                case ''<='':\n                case ''lte'':\n                case ''lessthanequals'':\n                case ''lessthanorequalto'':\n                    $tplCon = (($subject <= $operand) ? $conditionalTpl : $tplCon);\n                    break;\n                case ''>='':\n                case ''gte'':\n                case ''greaterthanequals'':\n                case ''greaterthanequalto'':\n                    $tplCon = (($subject >= $operand) ? $conditionalTpl : $tplCon);\n                    break;\n                case ''isempty'':\n                case ''empty'':\n                    $tplCon = empty($subject) ? $conditionalTpl : $tplCon;\n                    break;\n                case ''!empty'':\n                case ''notempty'':\n                case ''isnotempty'':\n                    $tplCon = !empty($subject) && $subject != '''' ? $conditionalTpl : $tplCon;\n                    break;\n                case ''isnull'':\n                case ''null'':\n                    $tplCon = $subject == null || strtolower($subject) == ''null'' ? $conditionalTpl : $tplCon;\n                    break;\n                case ''inarray'':\n                case ''in_array'':\n                case ''ia'':\n                    $operand = explode('','', $operand);\n                    $tplCon = in_array($subject, $operand) ? $conditionalTpl : $tplCon;\n                    break;\n                case ''between'':\n                case ''range'':\n                case ''>=<'':\n                case ''><'':\n                    $operand = explode('','', $operand);\n                    $tplCon = ($subject >= min($operand) && $subject <= max($operand)) ? $conditionalTpl : $tplCon;\n                    break;\n                case ''=='':\n                case ''='':\n                case ''eq'':\n                case ''is'':\n                case ''equal'':\n                case ''equals'':\n                case ''equalto'':\n                default:\n                    $tplCon = (($subject == $operand) ? $conditionalTpl : $tplCon);\n                    break;\n            }\n        }\n        if (!empty($tplCon)) {\n            $resourceTpl = parseTpl($tplCon, $properties);\n        }\n    }\n    if (!empty($tpl) && empty($resourceTpl)) {\n        $resourceTpl = parseTpl($tpl, $properties);\n    }\n    if ($resourceTpl === false && !empty($debug)) {\n        $chunk = $modx->newObject(''modChunk'');\n        $chunk->setCacheable(false);\n        $output[]= $chunk->process(array(), ''<pre>'' . print_r($properties, true) .''</pre>'');\n    } else {\n        $output[]= $resourceTpl;\n    }\n    $idx++;\n}\n\n/* output */\n$toSeparatePlaceholders = $modx->getOption(''toSeparatePlaceholders'', $scriptProperties, false);\nif (!empty($toSeparatePlaceholders)) {\n    $modx->setPlaceholders($output, $toSeparatePlaceholders);\n    return '''';\n}\n\n$output = implode($outputSeparator, $output);\n\n$tplWrapper = $modx->getOption(''tplWrapper'', $scriptProperties, false);\n$wrapIfEmpty = $modx->getOption(''wrapIfEmpty'', $scriptProperties, false);\nif (!empty($tplWrapper) && ($wrapIfEmpty || !empty($output))) {\n    $output = parseTpl($tplWrapper, array_merge($scriptProperties, array(''output'' => $output)));\n}\n\n$toPlaceholder = $modx->getOption(''toPlaceholder'', $scriptProperties, false);\nif (!empty($toPlaceholder)) {\n    $modx->setPlaceholder($toPlaceholder, $output);\n    return '''';\n}\nreturn $output;', 0, 'a:44:{s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:121:"Name of a chunk serving as a resource template. NOTE: if not provided, properties are dumped to output for each resource.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:6:"tplOdd";a:7:{s:4:"name";s:6:"tplOdd";s:4:"desc";s:100:"Name of a chunk serving as resource template for resources with an odd idx value (see idx property).";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:8:"tplFirst";a:7:{s:4:"name";s:8:"tplFirst";s:4:"desc";s:89:"Name of a chunk serving as resource template for the first resource (see first property).";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:7:"tplLast";a:7:{s:4:"name";s:7:"tplLast";s:4:"desc";s:87:"Name of a chunk serving as resource template for the last resource (see last property).";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"tplWrapper";a:7:{s:4:"name";s:10:"tplWrapper";s:4:"desc";s:115:"Name of a chunk serving as wrapper template for the Snippet output. This does not work with toSeparatePlaceholders.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"wrapIfEmpty";a:7:{s:4:"name";s:11:"wrapIfEmpty";s:4:"desc";s:95:"Indicates if empty output should be wrapped by the tplWrapper, if specified. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:6:"sortby";a:7:{s:4:"name";s:6:"sortby";s:4:"desc";s:153:"A field name to sort by or JSON object of field names and sortdir for each field, e.g. {"publishedon":"ASC","createdon":"DESC"}. Defaults to publishedon.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:11:"publishedon";s:7:"lexicon";N;s:4:"area";s:0:"";}s:8:"sortbyTV";a:7:{s:4:"name";s:8:"sortbyTV";s:4:"desc";s:65:"Name of a Template Variable to sort by. Defaults to empty string.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:12:"sortbyTVType";a:7:{s:4:"name";s:12:"sortbyTVType";s:4:"desc";s:72:"An optional type to indicate how to sort on the Template Variable value.";s:4:"type";s:4:"list";s:7:"options";a:4:{i:0;a:2:{s:4:"text";s:6:"string";s:5:"value";s:6:"string";}i:1;a:2:{s:4:"text";s:7:"integer";s:5:"value";s:7:"integer";}i:2;a:2:{s:4:"text";s:7:"decimal";s:5:"value";s:7:"decimal";}i:3;a:2:{s:4:"text";s:8:"datetime";s:5:"value";s:8:"datetime";}}s:5:"value";s:6:"string";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"sortbyAlias";a:7:{s:4:"name";s:11:"sortbyAlias";s:4:"desc";s:58:"Query alias for sortby field. Defaults to an empty string.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"sortbyEscaped";a:7:{s:4:"name";s:13:"sortbyEscaped";s:4:"desc";s:82:"Determines if the field name specified in sortby should be escaped. Defaults to 0.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:7:"sortdir";a:7:{s:4:"name";s:7:"sortdir";s:4:"desc";s:41:"Order which to sort by. Defaults to DESC.";s:4:"type";s:4:"list";s:7:"options";a:2:{i:0;a:2:{s:4:"text";s:3:"ASC";s:5:"value";s:3:"ASC";}i:1;a:2:{s:4:"text";s:4:"DESC";s:5:"value";s:4:"DESC";}}s:5:"value";s:4:"DESC";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"sortdirTV";a:7:{s:4:"name";s:9:"sortdirTV";s:4:"desc";s:61:"Order which to sort a Template Variable by. Defaults to DESC.";s:4:"type";s:4:"list";s:7:"options";a:2:{i:0;a:2:{s:4:"text";s:3:"ASC";s:5:"value";s:3:"ASC";}i:1;a:2:{s:4:"text";s:4:"DESC";s:5:"value";s:4:"DESC";}}s:5:"value";s:4:"DESC";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"limit";a:7:{s:4:"name";s:5:"limit";s:4:"desc";s:55:"Limits the number of resources returned. Defaults to 5.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"5";s:7:"lexicon";N;s:4:"area";s:0:"";}s:6:"offset";a:7:{s:4:"name";s:6:"offset";s:4:"desc";s:56:"An offset of resources returned by the criteria to skip.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"tvFilters";a:7:{s:4:"name";s:9:"tvFilters";s:4:"desc";s:778:"Delimited-list of TemplateVar values to filter resources by. Supports two delimiters and two value search formats. THe first delimiter || represents a logical OR and the primary grouping mechanism.  Within each group you can provide a comma-delimited list of values. These values can be either tied to a specific TemplateVar by name, e.g. myTV==value, or just the value, indicating you are searching for the value in any TemplateVar tied to the Resource. An example would be &tvFilters=`filter2==one,filter1==bar%||filter1==foo`. <br />NOTE: filtering by values uses a LIKE query and % is considered a wildcard. <br />ANOTHER NOTE: This only looks at the raw value set for specific Resource, i. e. there must be a value specifically set for the Resource and it is not evaluated.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:21:"tvFiltersAndDelimiter";a:7:{s:4:"name";s:21:"tvFiltersAndDelimiter";s:4:"desc";s:83:"The delimiter to use to separate logical AND expressions in tvFilters. Default is ,";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:",";s:7:"lexicon";N;s:4:"area";s:0:"";}s:20:"tvFiltersOrDelimiter";a:7:{s:4:"name";s:20:"tvFiltersOrDelimiter";s:4:"desc";s:83:"The delimiter to use to separate logical OR expressions in tvFilters. Default is ||";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:2:"||";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"depth";a:7:{s:4:"name";s:5:"depth";s:4:"desc";s:88:"Integer value indicating depth to search for resources from each parent. Defaults to 10.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:2:"10";s:7:"lexicon";N;s:4:"area";s:0:"";}s:7:"parents";a:7:{s:4:"name";s:7:"parents";s:4:"desc";s:57:"Optional. Comma-delimited list of ids serving as parents.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:14:"includeContent";a:7:{s:4:"name";s:14:"includeContent";s:4:"desc";s:95:"Indicates if the content of each resource should be returned in the results. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"includeTVs";a:7:{s:4:"name";s:10:"includeTVs";s:4:"desc";s:124:"Indicates if TemplateVar values should be included in the properties available to each resource template. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"includeTVList";a:7:{s:4:"name";s:13:"includeTVList";s:4:"desc";s:96:"Limits included TVs to those specified as a comma-delimited list of TV names. Defaults to empty.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"showHidden";a:7:{s:4:"name";s:10:"showHidden";s:4:"desc";s:85:"Indicates if Resources that are hidden from menus should be shown. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:15:"showUnpublished";a:7:{s:4:"name";s:15:"showUnpublished";s:4:"desc";s:79:"Indicates if Resources that are unpublished should be shown. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"showDeleted";a:7:{s:4:"name";s:11:"showDeleted";s:4:"desc";s:75:"Indicates if Resources that are deleted should be shown. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"resources";a:7:{s:4:"name";s:9:"resources";s:4:"desc";s:177:"A comma-separated list of resource IDs to exclude or include. IDs with a - in front mean to exclude. Ex: 123,-456 means to include Resource 123, but always exclude Resource 456.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"processTVs";a:7:{s:4:"name";s:10:"processTVs";s:4:"desc";s:117:"Indicates if TemplateVar values should be rendered as they would on the resource being summarized. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"processTVList";a:7:{s:4:"name";s:13:"processTVList";s:4:"desc";s:166:"Limits processed TVs to those specified as a comma-delimited list of TV names; note only includedTVs will be available for processing if specified. Defaults to empty.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"prepareTVs";a:7:{s:4:"name";s:10:"prepareTVs";s:4:"desc";s:120:"Indicates if TemplateVar values that are not processed fully should be prepared before being returned. Defaults to true.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"prepareTVList";a:7:{s:4:"name";s:13:"prepareTVList";s:4:"desc";s:164:"Limits prepared TVs to those specified as a comma-delimited list of TV names; note only includedTVs will be available for preparing if specified. Defaults to empty.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:8:"tvPrefix";a:7:{s:4:"name";s:8:"tvPrefix";s:4:"desc";s:55:"The prefix for TemplateVar properties. Defaults to: tv.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:3:"tv.";s:7:"lexicon";N;s:4:"area";s:0:"";}s:3:"idx";a:7:{s:4:"name";s:3:"idx";s:4:"desc";s:120:"You can define the starting idx of the resources, which is an property that is incremented as each resource is rendered.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"first";a:7:{s:4:"name";s:5:"first";s:4:"desc";s:81:"Define the idx which represents the first resource (see tplFirst). Defaults to 1.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:4:"last";a:7:{s:4:"name";s:4:"last";s:4:"desc";s:129:"Define the idx which represents the last resource (see tplLast). Defaults to the number of resources being summarized + first - 1";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"toPlaceholder";a:7:{s:4:"name";s:13:"toPlaceholder";s:4:"desc";s:85:"If set, will assign the result to this placeholder instead of outputting it directly.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:22:"toSeparatePlaceholders";a:7:{s:4:"name";s:22:"toSeparatePlaceholders";s:4:"desc";s:130:"If set, will assign EACH result to a separate placeholder named by this param suffixed with a sequential number (starting from 0).";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"debug";a:7:{s:4:"name";s:5:"debug";s:4:"desc";s:68:"If true, will send the SQL query to the MODX log. Defaults to false.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"where";a:7:{s:4:"name";s:5:"where";s:4:"desc";s:193:"A JSON expression of criteria to build any additional where clauses from, e.g. &where=`{{"alias:LIKE":"foo%", "OR:alias:LIKE":"%bar"},{"OR:pagetitle:=":"foobar", "AND:description:=":"raboof"}}`";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"dbCacheFlag";a:7:{s:4:"name";s:11:"dbCacheFlag";s:4:"desc";s:218:"Determines how result sets are cached if cache_db is enabled in MODX. 0|false = do not cache result set; 1 = cache result set according to cache settings, any other integer value = number of seconds to cache result set";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:7:"context";a:7:{s:4:"name";s:7:"context";s:4:"desc";s:116:"A comma-delimited list of context keys for limiting results. Default is empty, i.e. do not limit results by context.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:12:"tplCondition";a:7:{s:4:"name";s:12:"tplCondition";s:4:"desc";s:129:"A condition to compare against the conditionalTpls property to map Resources to different tpls based on custom conditional logic.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"tplOperator";a:7:{s:4:"name";s:11:"tplOperator";s:4:"desc";s:125:"An optional operator to use for the tplCondition when comparing against the conditionalTpls operands. Default is == (equals).";s:4:"type";s:4:"list";s:7:"options";a:10:{i:0;a:2:{s:4:"text";s:11:"is equal to";s:5:"value";s:2:"==";}i:1;a:2:{s:4:"text";s:15:"is not equal to";s:5:"value";s:2:"!=";}i:2;a:2:{s:4:"text";s:9:"less than";s:5:"value";s:1:"<";}i:3;a:2:{s:4:"text";s:21:"less than or equal to";s:5:"value";s:2:"<=";}i:4;a:2:{s:4:"text";s:24:"greater than or equal to";s:5:"value";s:2:">=";}i:5;a:2:{s:4:"text";s:8:"is empty";s:5:"value";s:5:"empty";}i:6;a:2:{s:4:"text";s:12:"is not empty";s:5:"value";s:6:"!empty";}i:7;a:2:{s:4:"text";s:7:"is null";s:5:"value";s:4:"null";}i:8;a:2:{s:4:"text";s:11:"is in array";s:5:"value";s:7:"inarray";}i:9;a:2:{s:4:"text";s:10:"is between";s:5:"value";s:7:"between";}}s:5:"value";s:2:"==";s:7:"lexicon";N;s:4:"area";s:0:"";}s:15:"conditionalTpls";a:7:{s:4:"name";s:15:"conditionalTpls";s:4:"desc";s:121:"A JSON map of conditional operands and tpls to compare against the tplCondition property using the specified tplOperator.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}}', '', 0, '');
INSERT INTO `modx_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(80, 0, 0, 'getPage', '<b>1.2.4-pl</b> A generic wrapper snippet for returning paged results and navigation from snippets that return limitable collections.', 0, 0, 0, '/**\n * @package getpage\n */\n$output = '''';\n\n$properties =& $scriptProperties;\n$properties[''page''] = (isset($_GET[$properties[''pageVarKey'']]) && ($page = intval($_GET[$properties[''pageVarKey'']]))) ? $page : null;\nif ($properties[''page''] === null) {\n    $properties[''page''] = (isset($_REQUEST[$properties[''pageVarKey'']]) && ($page = intval($_REQUEST[$properties[''pageVarKey'']]))) ? $page : 1;\n}\n$properties[''limit''] = (isset($_GET[''limit''])) ? intval($_GET[''limit'']) : null;\nif ($properties[''limit''] === null) {\n    $properties[''limit''] = (isset($_REQUEST[''limit''])) ? intval($_REQUEST[''limit'']) : intval($limit);\n}\n$properties[''offset''] = (!empty($properties[''limit'']) && !empty($properties[''page''])) ? ($properties[''limit''] * ($properties[''page''] - 1)) : 0;\n$properties[''totalVar''] = empty($totalVar) ? "total" : $totalVar;\n$properties[$properties[''totalVar'']] = !empty($properties[$properties[''totalVar'']]) && $total = intval($properties[$properties[''totalVar'']]) ? $total : 0;\n$properties[''pageOneLimit''] = (!empty($pageOneLimit) && $pageOneLimit = intval($pageOneLimit)) ? $pageOneLimit : $properties[''limit''];\n$properties[''actualLimit''] = $properties[''limit''];\n$properties[''pageLimit''] = isset($pageLimit) && is_numeric($pageLimit) ? intval($pageLimit) : 5;\n$properties[''element''] = empty($element) ? '''' : $element;\n$properties[''elementClass''] = empty($elementClass) ? ''modChunk'' : $elementClass;\n$properties[''pageNavVar''] = empty($pageNavVar) ? ''page.nav'' : $pageNavVar;\n$properties[''pageNavTpl''] = !isset($pageNavTpl) ? "<li[[+classes]]><a[[+classes]][[+title]] href=\\"[[+href]]\\">[[+pageNo]]</a></li>" : $pageNavTpl;\n$properties[''pageNavOuterTpl''] = !isset($pageNavOuterTpl) ? "[[+first]][[+prev]][[+pages]][[+next]][[+last]]" : $pageNavOuterTpl;\n$properties[''pageActiveTpl''] = !isset($pageActiveTpl) ? "<li[[+activeClasses:default=` class=\\"active\\"`]]><a[[+activeClasses:default=` class=\\"active\\"`]][[+title]] href=\\"[[+href]]\\">[[+pageNo]]</a></li>" : $pageActiveTpl;\n$properties[''pageFirstTpl''] = !isset($pageFirstTpl) ? "<li class=\\"control\\"><a[[+title]] href=\\"[[+href]]\\">First</a></li>" : $pageFirstTpl;\n$properties[''pageLastTpl''] = !isset($pageLastTpl) ? "<li class=\\"control\\"><a[[+title]] href=\\"[[+href]]\\">Last</a></li>" : $pageLastTpl;\n$properties[''pagePrevTpl''] = !isset($pagePrevTpl) ? "<li class=\\"control\\"><a[[+title]] href=\\"[[+href]]\\">&lt;&lt;</a></li>" : $pagePrevTpl;\n$properties[''pageNextTpl''] = !isset($pageNextTpl) ? "<li class=\\"control\\"><a[[+title]] href=\\"[[+href]]\\">&gt;&gt;</a></li>" : $pageNextTpl;\n$properties[''toPlaceholder''] = !empty($toPlaceholder) ? $toPlaceholder : '''';\n$properties[''cache''] = isset($cache) ? (boolean) $cache : (boolean) $modx->getOption(''cache_resource'', null, false);\nif (empty($cache_key)) $properties[xPDO::OPT_CACHE_KEY] = $modx->getOption(''cache_resource_key'', null, ''resource'');\nif (empty($cache_handler)) $properties[xPDO::OPT_CACHE_HANDLER] = $modx->getOption(''cache_resource_handler'', null, ''xPDOFileCache'');\nif (empty($cache_expires)) $properties[xPDO::OPT_CACHE_EXPIRES] = (integer) $modx->getOption(''cache_resource_expires'', null, 0);\n\nif ($properties[''page''] == 1 && $properties[''pageOneLimit''] !== $properties[''actualLimit'']) {\n    $properties[''limit''] = $properties[''pageOneLimit''];\n}\n\nif ($properties[''cache'']) {\n    $properties[''cachePageKey''] = $modx->resource->getCacheKey() . ''/'' . $properties[''page''] . ''/'' . md5(http_build_query($modx->request->getParameters()) . http_build_query($scriptProperties));\n    $properties[''cacheOptions''] = array(\n        xPDO::OPT_CACHE_KEY => $properties[xPDO::OPT_CACHE_KEY],\n        xPDO::OPT_CACHE_HANDLER => $properties[xPDO::OPT_CACHE_HANDLER],\n        xPDO::OPT_CACHE_EXPIRES => $properties[xPDO::OPT_CACHE_EXPIRES],\n    );\n}\n$cached = false;\nif ($properties[''cache'']) {\n    if ($modx->getCacheManager()) {\n        $cached = $modx->cacheManager->get($properties[''cachePageKey''], $properties[''cacheOptions'']);\n    }\n}\nif (empty($cached) || !isset($cached[''properties'']) || !isset($cached[''output''])) {\n    $elementObj = $modx->getObject($properties[''elementClass''], array(''name'' => $properties[''element'']));\n    if ($elementObj) {\n        $elementObj->setCacheable(false);\n        if (!empty($properties[''toPlaceholder''])) {\n            $elementObj->process($properties);\n            $output = $modx->getPlaceholder($properties[''toPlaceholder'']);\n        } else {\n            $output = $elementObj->process($properties);\n        }\n    }\n\n    include_once $modx->getOption(''getpage.core_path'',$properties,$modx->getOption(''core_path'', $properties, MODX_CORE_PATH) . ''components/getpage/'').''include.getpage.php'';\n\n    $qs = $modx->request->getParameters();\n    $properties[''qs''] =& $qs;\n\n    $totalSet = $modx->getPlaceholder($properties[''totalVar'']);\n    $properties[$properties[''totalVar'']] = (($totalSet = intval($totalSet)) ? $totalSet : $properties[$properties[''totalVar'']]);\n    if (!empty($properties[$properties[''totalVar'']]) && !empty($properties[''actualLimit''])) {\n        if ($properties[''pageOneLimit''] !== $properties[''actualLimit'']) {\n            $adjustedTotal = $properties[$properties[''totalVar'']] - $properties[''pageOneLimit''];\n            $properties[''pageCount''] = $adjustedTotal > 0 ? ceil($adjustedTotal / $properties[''actualLimit'']) + 1 : 1;\n        } else {\n            $properties[''pageCount''] = ceil($properties[$properties[''totalVar'']] / $properties[''actualLimit'']);\n        }\n    } else {\n        $properties[''pageCount''] = 1;\n    }\n    if (empty($properties[$properties[''totalVar'']]) || empty($properties[''actualLimit'']) || $properties[$properties[''totalVar'']] <= $properties[''actualLimit''] || ($properties[''page''] == 1 && $properties[$properties[''totalVar'']] <= $properties[''pageOneLimit''])) {\n        $properties[''page''] = 1;\n    } else {\n        $pageNav = getpage_buildControls($modx, $properties);\n        $properties[$properties[''pageNavVar'']] = $modx->newObject(''modChunk'')->process(array_merge($properties, $pageNav), $properties[''pageNavOuterTpl'']);\n        if ($properties[''page''] > 1) {\n            $qs[$properties[''pageVarKey'']] = $properties[''page''];\n        }\n    }\n\n    $properties[''firstItem''] = $properties[''offset''] + 1;\n    $properties[''lastItem''] = ($properties[''offset''] + $properties[''limit'']) < $totalSet ? ($properties[''offset''] + $properties[''limit'']) : $totalSet;\n\n    $properties[''pageUrl''] = $modx->makeUrl($modx->resource->get(''id''), '''', $qs);\n    if ($properties[''cache''] && $modx->getCacheManager()) {\n        $cached = array(''properties'' => $properties, ''output'' => $output);\n        $modx->cacheManager->set($properties[''cachePageKey''], $cached, $properties[xPDO::OPT_CACHE_EXPIRES], $properties[''cacheOptions'']);\n    }\n} else {\n    $properties = $cached[''properties''];\n    $output = $cached[''output''];\n}\n$modx->setPlaceholders($properties, $properties[''namespace'']);\nif (!empty($properties[''toPlaceholder''])) {\n    $modx->setPlaceholder($properties[''toPlaceholder''], $output);\n    $output = '''';\n}\n\nreturn $output;', 0, 'a:21:{s:9:"namespace";a:7:{s:4:"name";s:9:"namespace";s:4:"desc";s:114:"An execution namespace that serves as a prefix for placeholders set by a specific instance of the getPage snippet.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"limit";a:7:{s:4:"name";s:5:"limit";s:4:"desc";s:62:"The result limit per page; can be overridden in the $_REQUEST.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:2:"10";s:7:"lexicon";N;s:4:"area";s:0:"";}s:6:"offset";a:7:{s:4:"name";s:6:"offset";s:4:"desc";s:171:"The offset, or record position to start at within the collection for rendering results for the current page; should be calculated based on page variable set in pageVarKey.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:4:"page";a:7:{s:4:"name";s:4:"page";s:4:"desc";s:136:"The page to display; this is determined based on the value indicated by the page variable set in pageVarKey, typically in the $_REQUEST.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"pageVarKey";a:7:{s:4:"name";s:10:"pageVarKey";s:4:"desc";s:54:"The key of a property that indicates the current page.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:4:"page";s:7:"lexicon";N;s:4:"area";s:0:"";}s:8:"totalVar";a:7:{s:4:"name";s:8:"totalVar";s:4:"desc";s:101:"The key of a placeholder that must contain the total records in the limitable collection being paged.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:5:"total";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"pageLimit";a:7:{s:4:"name";s:9:"pageLimit";s:4:"desc";s:69:"The maximum number of pages to display when rendering paging controls";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"5";s:7:"lexicon";N;s:4:"area";s:0:"";}s:12:"elementClass";a:7:{s:4:"name";s:12:"elementClass";s:4:"desc";s:73:"The class of element that will be called by the getPage snippet instance.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:10:"modSnippet";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"pageNavVar";a:7:{s:4:"name";s:10:"pageNavVar";s:4:"desc";s:71:"The key of a placeholder to be set with the paging navigation controls.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:8:"page.nav";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"pageNavTpl";a:7:{s:4:"name";s:10:"pageNavTpl";s:4:"desc";s:54:"Content representing a single page navigation control.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:78:"<li[[+classes]]><a[[+classes]][[+title]] href="[[+href]]">[[+pageNo]]</a></li>";s:7:"lexicon";N;s:4:"area";s:0:"";}s:15:"pageNavOuterTpl";a:7:{s:4:"name";s:15:"pageNavOuterTpl";s:4:"desc";s:64:"Content representing the layout of the page navigation controls.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:47:"[[+first]][[+prev]][[+pages]][[+next]][[+last]]";s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"pageActiveTpl";a:7:{s:4:"name";s:13:"pageActiveTpl";s:4:"desc";s:57:"Content representing the current page navigation control.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:116:"<li[[+activeClasses]]><a[[+activeClasses:default=` class="active"`]][[+title]] href="[[+href]]">[[+pageNo]]</a></li>";s:7:"lexicon";N;s:4:"area";s:0:"";}s:12:"pageFirstTpl";a:7:{s:4:"name";s:12:"pageFirstTpl";s:4:"desc";s:55:"Content representing the first page navigation control.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:83:"<li class="control"><a[[+classes]][[+title]] href="[[+href]]">Первая</a></li>";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"pageLastTpl";a:7:{s:4:"name";s:11:"pageLastTpl";s:4:"desc";s:54:"Content representing the last page navigation control.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:89:"<li class="control"><a[[+classes]][[+title]] href="[[+href]]">Последняя</a></li>";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"pagePrevTpl";a:7:{s:4:"name";s:11:"pagePrevTpl";s:4:"desc";s:58:"Content representing the previous page navigation control.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:79:"<li class="control"><a[[+classes]][[+title]] href="[[+href]]">&lt;&lt;</a></li>";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"pageNextTpl";a:7:{s:4:"name";s:11:"pageNextTpl";s:4:"desc";s:54:"Content representing the next page navigation control.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:79:"<li class="control"><a[[+classes]][[+title]] href="[[+href]]">&gt;&gt;</a></li>";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"cache";a:7:{s:4:"name";s:5:"cache";s:4:"desc";s:84:"If true, unique page requests will be cached according to addition cache properties.";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"cache_key";a:7:{s:4:"name";s:9:"cache_key";s:4:"desc";s:120:"The key of the cache provider to use; leave empty to use the cache_resource_key cache partition (default is "resource").";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"cache_handler";a:7:{s:4:"name";s:13:"cache_handler";s:4:"desc";s:99:"The cache provider implementation to use; leave empty unless you are caching to a custom cache_key.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"cache_expires";a:7:{s:4:"name";s:13:"cache_expires";s:4:"desc";s:141:"The number of seconds before the cached pages expire and must be regenerated; leave empty to use the cache provider option for cache_expires.";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"pageNavScheme";a:7:{s:4:"name";s:13:"pageNavScheme";s:4:"desc";s:145:"Optionally specify a scheme for use when generating page navigation links; will use link_tag_scheme if empty or not specified (default is empty).";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}}', '', 0, ''),
(81, 2, 0, 'recentlyViewed', 'Сниппет вывода ранее просмотренных товаров (работает через сессии)', 0, 5, 0, '/**\n * recentlyViewed ver. 05.05.2016\n * \n * Сниппет запоминает посещенную страницу и может выводить ранее просмотренные товары\n * \n * Параметры:\n * &limit - количество запоминаемых страниц, по умолчанию 4\n * &returnViewed - если не null, то выводит ранее просмотренные товары, иначе - просто сохраняет в сессию просмотренный товар\n * &tpl - имя чанка товара (по умолчанию - product)\n * &toPlaceholder - как везде\n * \n */\n \n$tpl = $modx->getOption(''tpl'', $scriptProperties, ''product'');\n \nif (!isset($limit)) {\n    $limit = 4;\n}\n\n// Добавляем просмотренную страницу в сессию\n$page_id = $modx->resource->id;\nif (!isset($_SESSION[''viewed''])) {\n    $_SESSION[''viewed''] = array();\n}\nif (in_array($page_id, $_SESSION[''viewed''])) {\n    $key = array_search($page_id, $_SESSION[''viewed'']);\n    unset($_SESSION[''viewed''][$key]);\n}\n\nif (count($_SESSION[''viewed'']) > $limit) {\n    array_shift($_SESSION[''viewed'']);\n}\n\n$_SESSION[''viewed''][] = $page_id;\n\n// Выводим просмотренные товары\nif (isset($returnViewed)) {\n    $ids = array_reverse($_SESSION[''viewed'']);\n    \n    if (empty($ids)) {\n        return;\n    }\n    \n    $output = '''';\n    foreach ($ids as $id) {\n        if ($id != $page_id) {\n            $idx++;\n            $resource = $modx->getObject(''modResource'', $id);\n            if (!$resource) {\n                continue;\n            }\n            \n            $output .= $modx->getChunk($tpl, array(\n                ''id'' => $id,\n                ''pagetitle'' => $resource->get(''pagetitle''),\n                ''tv.image''  => $resource->getTVValue(''image''),\n                ''tv.sku''    => $resource->getTVValue(''sku''),\n                ''introtext'' => $resource->get(''introtext''),\n                ''tv.price''  => $resource->getTVValue(''price''),\n                ''currency''  => $resource->getTVValue(''currency''),\n                ''idx'' => $idx,\n            ));\n        }\n    }\n\n    $toPlaceholder = $modx->getOption(''toPlaceholder'', $scriptProperties, false);\n    if ($toPlaceholder) {\n        $modx->setPlaceholder($toPlaceholder, $output);\n    } else {\n        return $output;\n    }\n}', 0, 'a:0:{}', '', 0, ''),
(86, 1, 0, 'HybridAuth', 'Social authorization', 0, 28, 0, '/** @var array $scriptProperties */\n\n$modx->error->message = null;\nif (!$modx->loadClass(''hybridauth'', MODX_CORE_PATH . ''components/hybridauth/model/hybridauth/'', false, true)) {\n	return;\n}\n$HybridAuth = new HybridAuth($modx, $scriptProperties);\n$HybridAuth->initialize($modx->context->key);\n\nif ($modx->error->hasError()) {\n	return $modx->error->message;\n}\n// For compatibility with old snippet\nelseif (!empty($action)) {\n	$tmp = strtolower($action);\n	if ($tmp == ''getprofile'' || $tmp == ''updateprofile'') {\n		return $modx->runSnippet(''haProfile'', $scriptProperties);\n	}\n}\n\nif (empty($loginTpl)) {\n	$loginTpl = ''tpl.HybridAuth.login'';\n}\nif (empty($logoutTpl)) {\n	$logoutTpl = ''tpl.HybridAuth.logout'';\n}\nif (empty($providerTpl)) {\n	$providerTpl = ''tpl.HybridAuth.provider'';\n}\nif (empty($activeProviderTpl)) {\n	$activeProviderTpl = ''tpl.HybridAuth.provider.active'';\n}\n\n$url = $HybridAuth->getUrl();\n$error = '''';\nif (!empty($_SESSION[''HA''][''error''])) {\n	$error = $_SESSION[''HA''][''error''];\n	unset($_SESSION[''HA''][''error'']);\n}\n\nif ($modx->user->isAuthenticated($modx->context->key)) {\n	$add = array();\n	if ($services = $modx->user->getMany(''Services'')) {\n		/* @var haUserService $service */\n		foreach ($services as $service) {\n			$add = array_merge($add, $service->toArray(strtolower($service->get(''provider'') . ''.'')));\n		}\n	}\n\n	$user = $modx->user->toArray();\n	$profile = $modx->user->Profile->toArray();\n	unset($profile[''id'']);\n	$arr = array_merge(\n		$user,\n		$profile,\n		$add,\n		array(\n			''login_url'' => $url . ''login'',\n			''logout_url'' => $url . ''logout'',\n			''providers'' => $HybridAuth->getProvidersLinks($providerTpl, $activeProviderTpl),\n			''error'' => $error,\n			''gravatar'' => ''https://gravatar.com/avatar/'' . md5(strtolower($profile[''email''])),\n		)\n	);\n\n	return $modx->getChunk($logoutTpl, $arr);\n}\nelse {\n	$arr = array(\n		''login_url'' => $url . ''login'',\n		''logout_url'' => $url . ''logout'',\n		''providers'' => $HybridAuth->getProvidersLinks($providerTpl, $activeProviderTpl),\n		''error'' => $error,\n	);\n\n	return $modx->getChunk($loginTpl, $arr);\n}', 0, 'a:12:{s:9:"providers";a:7:{s:4:"name";s:9:"providers";s:4:"desc";s:12:"ha.providers";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:10:"rememberme";a:7:{s:4:"name";s:10:"rememberme";s:4:"desc";s:13:"ha.rememberme";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:1;s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:8:"loginTpl";a:7:{s:4:"name";s:8:"loginTpl";s:4:"desc";s:11:"ha.loginTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:20:"tpl.HybridAuth.login";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:9:"logoutTpl";a:7:{s:4:"name";s:9:"logoutTpl";s:4:"desc";s:12:"ha.logoutTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:21:"tpl.HybridAuth.logout";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:11:"providerTpl";a:7:{s:4:"name";s:11:"providerTpl";s:4:"desc";s:14:"ha.providerTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:23:"tpl.HybridAuth.provider";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:17:"activeProviderTpl";a:7:{s:4:"name";s:17:"activeProviderTpl";s:4:"desc";s:20:"ha.activeProviderTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:30:"tpl.HybridAuth.provider.active";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:6:"groups";a:7:{s:4:"name";s:6:"groups";s:4:"desc";s:9:"ha.groups";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:12:"loginContext";a:7:{s:4:"name";s:12:"loginContext";s:4:"desc";s:15:"ha.loginContext";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:11:"addContexts";a:7:{s:4:"name";s:11:"addContexts";s:4:"desc";s:14:"ha.addContexts";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:15:"loginResourceId";a:7:{s:4:"name";s:15:"loginResourceId";s:4:"desc";s:18:"ha.loginResourceId";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:0;s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:16:"logoutResourceId";a:7:{s:4:"name";s:16:"logoutResourceId";s:4:"desc";s:19:"ha.logoutResourceId";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:0;s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:11:"redirectUri";a:7:{s:4:"name";s:11:"redirectUri";s:4:"desc";s:14:"ha.redirectUri";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}}', '', 0, 'core/components/hybridauth/elements/snippets/snippet.hybridauth.php'),
(87, 1, 0, 'haProfile', 'Update your profile', 0, 28, 0, '/** @var array $scriptProperties */\n\n$modx->error->message = null;\nif (!$modx->loadClass(''hybridauth'', MODX_CORE_PATH . ''components/hybridauth/model/hybridauth/'', false, true)) {\n	return;\n}\n$HybridAuth = new HybridAuth($modx, $scriptProperties);\n$HybridAuth->initialize($modx->context->key);\n\nif ($modx->error->hasError()) {\n	return $modx->error->message;\n}\nelseif (!$modx->user->isAuthenticated($modx->context->key)) {\n	return $modx->lexicon(''ha_err_not_logged_in'');\n}\n\nif (empty($profileTpl)) {\n	$profileTpl = ''tpl.HybridAuth.profile'';\n}\nif (empty($profileFields)) {\n	$profileFields = ''username:25,email:50,fullname:50,phone:12,mobilephone:12,dob:10,gender,address,country,city,state,zip,fax,photo,comment,website'';\n}\nif (empty($requiredFields)) {\n	$requiredFields = ''username,email,fullname'';\n}\nif (empty($providerTpl)) {\n	$providerTpl = ''tpl.HybridAuth.provider'';\n}\nif (empty($activeProviderTpl)) {\n	$activeProviderTpl = ''tpl.HybridAuth.provider.active'';\n}\n$data = array();\n\n// Update of profile\nif ((!empty($_REQUEST[''action'']) && strtolower($_REQUEST[''action'']) == ''updateprofile'') || (!empty($_REQUEST[''hauth_action'']) && strtolower($_REQUEST[''hauth_action'']) == ''updateprofile'')) {\n	$profileFields = array_map(''trim'', explode('','', $profileFields));\n	foreach ($profileFields as $field) {\n		if (strpos($field, '':'') !== false) {\n			list($key, $length) = explode('':'', $field);\n		}\n		else {\n			$key = $field;\n			$length = 0;\n		}\n\n		if (isset($_REQUEST[$key])) {\n			if ($key == ''comment'') {\n				$data[$key] = empty($length) ? $_REQUEST[$key] : substr($_REQUEST[$key], $length);\n			}\n			else {\n				$data[$key] = $HybridAuth->Sanitize($_REQUEST[$key], $length);\n			}\n		}\n	}\n\n	$data[''requiredFields''] = array_map(''trim'', explode('','', $requiredFields));\n\n	/** @var modProcessorResponse $response */\n	$response = $HybridAuth->runProcessor(''web/user/update'', $data);\n	if ($response->isError()) {\n		$data[''error.message''] = $response->getMessage();\n		foreach ($response->errors as $error) {\n			$data[''error.'' . $error->field] = $error->message;\n		}\n	}\n	$data[''success''] = (integer)!$response->isError();\n}\n\n$add = array();\nif ($services = $modx->user->getMany(''Services'')) {\n	/* @var haUserService $service */\n	foreach ($services as $service) {\n		$add = array_merge($add, $service->toArray(strtolower($service->get(''provider'') . ''.'')));\n	}\n}\n\n$url = $HybridAuth->getUrl();\n$user = $modx->user->toArray();\n$profile = $modx->user->Profile->toArray();\n$data = array_merge(\n	$user,\n	$profile,\n	$add,\n	$data,\n	array(\n		''login_url'' => $url . ''login'',\n		''logout_url'' => $url . ''logout'',\n		''providers'' => $HybridAuth->getProvidersLinks($providerTpl, $activeProviderTpl),\n		''gravatar'' => ''https://gravatar.com/avatar/'' . md5(strtolower($profile[''email''])),\n	)\n);\n\nreturn $modx->getChunk($profileTpl, $data);', 0, 'a:5:{s:10:"profileTpl";a:7:{s:4:"name";s:10:"profileTpl";s:4:"desc";s:13:"ha.profileTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:22:"tpl.HybridAuth.profile";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:13:"profileFields";a:7:{s:4:"name";s:13:"profileFields";s:4:"desc";s:16:"ha.profileFields";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:127:"username:25,email:50,fullname:50,phone:12,mobilephone:12,dob:10,gender,address,country,city,state,zip,fax,photo,comment,website";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:14:"requiredFields";a:7:{s:4:"name";s:14:"requiredFields";s:4:"desc";s:17:"ha.requiredFields";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:23:"username,email,fullname";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:11:"providerTpl";a:7:{s:4:"name";s:11:"providerTpl";s:4:"desc";s:14:"ha.providerTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:23:"tpl.HybridAuth.provider";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}s:17:"activeProviderTpl";a:7:{s:4:"name";s:17:"activeProviderTpl";s:4:"desc";s:20:"ha.activeProviderTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:30:"tpl.HybridAuth.provider.active";s:7:"lexicon";s:21:"hybridauth:properties";s:4:"area";s:0:"";}}', '', 0, 'core/components/hybridauth/elements/snippets/snippet.haprofile.php'),
(88, 0, 0, 'FormItSaveForm', 'Custom hook for FormIt to save the form.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2011-12 by SCHERP Ontwikkeling <info@scherpontwikkeling.nl>\r\n * Copyright 2015 by Wieger Sloot <modx@sterc.nl>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * A custom FormIt hook for saving filled-in forms. - Based on FormSave\r\n *\r\n * @var modX $modx\r\n * @var array $scriptProperties\r\n * @var FormIt $formit\r\n * @var fiHooks $hook\r\n * \r\n * @package formit\r\n */\r\n/* setup default properties */\r\n$values = $hook->getValues();\r\n$formName = $modx->getOption(''formName'', $formit->config, ''form-''.$modx->resource->get(''id''));\r\n// process formName. Pick a value from the form\r\n// Inspired from the email''s hook of formit (fihooks.class.php)\r\nif (is_string($formName)) {\r\n    foreach ($fields as $k => $v) {\r\n        if (is_scalar($k) && is_scalar($v)) {\r\n            $formName = str_replace(''[[+''.$k.'']]'',$v,$formName);\r\n        }\r\n    }\r\n}\r\n\r\n$formEncrypt = $modx->getOption(''formEncrypt'', $formit->config, false);\r\n$formFields = $modx->getOption(''formFields'', $formit->config, false);\r\n$fieldNames = $modx->getOption(''fieldNames'', $formit->config, false);\r\n$updateSavedForm = $modx->getOption(''updateSavedForm'', $formit->config, false); // true, false, ''1'', ''0'', or ''values''\r\n// In order to use update process, you need to provide the hash key to the user somehow\r\n// Usually with [[!FormItRetriever]] to populate this form field:\r\n$formHashKeyField = $modx->getOption(''savedFormHashKeyField'', $formit->config, ''savedFormHashKey'');\r\n// Disable if you want to use the session_id() in your hash, like FormIt does\r\n// WARNING: this can cause potential hash key collisions and overwriting of the wrong form record!!\r\n$formHashKeyRandom = $modx->getOption(''formHashKeyRandom'', $formit->config, true);\r\n// process formHashKeyField into variable for later use\r\n$formHashKey = (isset($values[$formHashKeyField])) ? (string) $values[$formHashKeyField] : '''';\r\n// our hashing methods return 32 chars\r\nif (strlen($formHashKey) !== 32) $formHashKey = '''';\r\nunset($values[$formHashKeyField]);\r\n\r\nif ($formFields) {\r\n    $formFields = explode('','', $formFields);\r\n    foreach($formFields as $k => $v) {\r\n        $formFields[$k] = trim($v);\r\n    }\r\n}\r\n// Build the data array\r\n$dataArray = array();\r\nif($formFields){\r\n    foreach($formFields as $field) {\r\n        $dataArray[$field] = (!isset($values[$field])) ? '''' : $values[$field];\r\n    }\r\n}else{\r\n    $dataArray = $values;\r\n}\r\n//Change the fieldnames\r\nif($fieldNames){\r\n    $newDataArray = array();\r\n    $fieldLabels = array();\r\n    $formFieldNames = explode('','', $fieldNames);\r\n    foreach($formFieldNames as $formFieldName){\r\n        list($name, $label) = explode(''=='', $formFieldName);\r\n        $fieldLabels[trim($name)] = trim($label);\r\n    }\r\n    foreach ($dataArray as $key => $value) {\r\n        if($fieldLabels[$key]){\r\n            $newDataArray[$fieldLabels[$key]] = $value;\r\n        }else{\r\n            $newDataArray[$key] = $value;\r\n        }\r\n    }\r\n    $dataArray = $newDataArray;\r\n}\r\n// We only enter update mode if we already have a valid formHashKey (tested above)\r\n// AND the updateSavedForm param was set to a truth-y value.\r\n$mode = ($updateSavedForm && $formHashKey) ? ''update'' : ''create'';\r\n// Create/get obj\r\n$newForm = null;\r\nif ($mode === ''update'') {\r\n    $newForm = $modx->getObject(''FormItForm'', array(''hash'' => $formHashKey));\r\n}\r\nif ($newForm === null) $newForm = $modx->newObject(''FormItForm'');\r\n\r\n// Handle encryption\r\nif($formEncrypt){\r\n    $dataArray = $newForm->encrypt($modx->toJSON($dataArray));\r\n}else{\r\n    $dataArray = $modx->toJSON($dataArray);\r\n}\r\n\r\n// Create new hash key on create mode, and handle invalid hash keys. \r\nif ($mode === ''create'') {\r\n    $formHashKey = ($formHashKeyRandom) ? $newForm->generatePseudoRandomHash() : pathinfo($formit->getStoreKey(), PATHINFO_BASENAME);\r\n}\r\n\r\n// Array from which to populate form record\r\n$newFormArray = array();\r\n\r\n// Special case: if updateSavedForm has the flag ''values'' we only merge in\r\n// the form values, not the other stuff\r\nif ($mode === ''update'' && $updateSavedForm === ''values'') {\r\n    $newFormArray = $newForm->toArray();\r\n    $newFormArray = array_merge($newFormArray, array(\r\n        ''values'' => $dataArray,\r\n    ));       \r\n} else {\r\n    // In all other cases, we overwrite the record completely!\r\n    // In create mode we must save the hash. In update mode, the \r\n    // formHashKey will be valid so we can also save it, again.\r\n    $newFormArray = array(\r\n        ''form'' => $formName,\r\n        ''date'' => time(),\r\n        ''values'' => $dataArray,\r\n        ''ip'' => $modx->getOption(''REMOTE_ADDR'', $_SERVER, ''''),\r\n        ''context_key'' => $modx->resource->get(''context_key''),\r\n        ''encrypted'' => $formEncrypt,\r\n        ''hash'' => $formHashKey,\r\n    );\r\n}\r\n// Convert to object\r\n$newForm->fromArray($newFormArray);\r\n// Attempt to save\r\nif (!$newForm->save()) {\r\n    $modx->log(modX::LOG_LEVEL_ERROR, ''[FormItSaveForm] An error occurred while trying to save the submitted form: '' . print_r($newForm->toArray(), true));\r\n    return false;\r\n}\r\n// Pass the hash and form data back to the user\r\n$hook->setValue(''savedForm'', $newForm->toArray());\r\n$hook->setValue($formHashKeyField, $newForm->get(''hash''));\r\nreturn true;', 0, 'a:0:{}', '', 0, ''),
(89, 1, 0, 'pdoTitle', '', 0, 7, 0, '/** @var array $scriptProperties */\nif (empty($outputSeparator)) {\n    $outputSeparator = '' / '';\n}\nif (empty($titleField)) {\n    $titleField = ''longtitle'';\n}\nif (!isset($pageVarKey)) {\n    $pageVarKey = ''page'';\n}\nif (!isset($queryVarKey)) {\n    $queryVarKey = ''query'';\n}\nif (empty($tplPages)) {\n    $tplPages = ''@INLINE [[%pdopage_page]] [[+page]] [[%pdopage_from]] [[+pageCount]]'';\n}\nif (empty($tplSearch)) {\n    $tplSearch = ''@INLINE «[[+mse2_query]]»'';\n}\nif (empty($minQuery)) {\n    $minQuery = 3;\n}\nif (empty($id)) {\n    $id = $modx->resource->id;\n}\nif (empty($cacheKey)) {\n    $cacheKey = ''title_crumbs'';\n}\nif (!isset($cacheTime)) {\n    $cacheTime = 0;\n}\n/** @var pdoTools $pdoTools */\n$fqn = $modx->getOption(''pdoTools.class'', null, ''pdotools.pdotools'', true);\n$path = $modx->getOption(''pdotools_class_path'', null, MODX_CORE_PATH . ''components/pdotools/model/'', true);\nif ($pdoClass = $modx->loadClass($fqn, $path, false, true)) {\n    $pdoTools = new $pdoClass($modx, $scriptProperties);\n} else {\n    return false;\n}\n$modx->lexicon->load(''pdotools:pdopage'');\n\n/** @var modResource $resource */\n$resource = ($id == $modx->resource->id)\n    ? $modx->resource\n    : $modx->getObject(''modResource'', $id);\nif (!$resource) {\n    return '''';\n}\n\n$title = array();\n$pagetitle = trim($resource->get($titleField));\nif (empty($pagetitle)) {\n    $pagetitle = $resource->get(''pagetitle'');\n}\n\n// Add search request if exists\nif (!empty($_GET[$queryVarKey]) && strlen($_GET[$queryVarKey]) >= $minQuery && !empty($tplSearch)) {\n    $pagetitle .= '' '' . $pdoTools->getChunk($tplSearch, array(\n            $queryVarKey => $modx->stripTags($_GET[$queryVarKey]),\n        ));\n}\n$title[] = $pagetitle;\n\n// Add pagination if exists\nif (!empty($_GET[$pageVarKey]) && !empty($tplPages)) {\n    $title[] = $pdoTools->getChunk($tplPages, array(\n        ''page'' => intval($_GET[$pageVarKey]),\n    ));\n}\n\n// Add parents\n$cacheKey = $resource->getCacheKey() . ''/'' . $cacheKey;\n$cacheOptions = array(''cache_key'' => $modx->getOption(''cache_resource_key'', null, ''resource''));\n$crumbs = '''';\nif (empty($cache) || !$crumbs = $modx->cacheManager->get($cacheKey, $cacheOptions)) {\n    $crumbs = $modx->runSnippet(''pdoCrumbs'', array_merge(\n        array(\n            ''to'' => $resource->id,\n            ''outputSeparator'' => $outputSeparator,\n            ''showHome'' => 0,\n            ''showAtHome'' => 0,\n            ''showCurrent'' => 0,\n            ''direction'' => ''rtl'',\n            ''tpl'' => ''@INLINE [[+menutitle]]'',\n            ''tplCurrent'' => ''@INLINE [[+menutitle]]'',\n            ''tplWrapper'' => ''@INLINE [[+output]]'',\n            ''tplMax'' => '''',\n            ''tplHome'' => '''',\n        ), $scriptProperties\n    ));\n}\nif (!empty($crumbs)) {\n    if (!empty($cache)) {\n        $modx->cacheManager->set($cacheKey, $crumbs, $cacheTime, $cacheOptions);\n    }\n    $title[] = $crumbs;\n}\n\nif (!empty($registerJs)) {\n    $config = array(\n        ''separator'' => $outputSeparator,\n        ''tpl'' => str_replace(array(''[[+'', '']]''), array(''{'', ''}''), $pdoTools->getChunk($tplPages)),\n    );\n    $modx->regClientStartupScript(''<script type="text/javascript">pdoTitle = '' . $modx->toJSON($config) . '';</script>'',\n        true);\n}\n\nreturn implode($outputSeparator, $title);', 0, 'a:13:{s:2:"id";a:7:{s:4:"name";s:2:"id";s:4:"desc";s:16:"pdotools_prop_id";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:7:"exclude";a:7:{s:4:"name";s:7:"exclude";s:4:"desc";s:21:"pdotools_prop_exclude";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:5:"limit";a:7:{s:4:"name";s:5:"limit";s:4:"desc";s:25:"pdotools_prop_title_limit";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:3;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:10:"titleField";a:7:{s:4:"name";s:10:"titleField";s:4:"desc";s:24:"pdotools_prop_titleField";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:9:"longtitle";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:5:"cache";a:7:{s:4:"name";s:5:"cache";s:4:"desc";s:25:"pdotools_prop_title_cache";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:9:"cacheTime";a:7:{s:4:"name";s:9:"cacheTime";s:4:"desc";s:23:"pdotools_prop_cacheTime";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:8:"tplPages";a:7:{s:4:"name";s:8:"tplPages";s:4:"desc";s:22:"pdotools_prop_tplPages";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:68:"@INLINE [[%pdopage_page]] [[+page]] [[%pdopage_from]] [[+pageCount]]";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:10:"pageVarKey";a:7:{s:4:"name";s:10:"pageVarKey";s:4:"desc";s:24:"pdotools_prop_pageVarKey";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:4:"page";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:9:"tplSearch";a:7:{s:4:"name";s:9:"tplSearch";s:4:"desc";s:23:"pdotools_prop_tplSearch";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:27:"@INLINE «[[+mse2_query]]»";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:11:"queryVarKey";a:7:{s:4:"name";s:11:"queryVarKey";s:4:"desc";s:25:"pdotools_prop_queryVarKey";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:5:"query";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:8:"minQuery";a:7:{s:4:"name";s:8:"minQuery";s:4:"desc";s:22:"pdotools_prop_minQuery";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:3;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:15:"outputSeparator";a:7:{s:4:"name";s:15:"outputSeparator";s:4:"desc";s:35:"pdotools_prop_title_outputSeparator";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:3:" / ";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:10:"registerJs";a:7:{s:4:"name";s:10:"registerJs";s:4:"desc";s:24:"pdotools_prop_registerJs";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}}', '', 0, 'core/components/pdotools/elements/snippets/snippet.pdotitle.php'),
(91, 0, 0, 'fcmspayment', 'FormIt hook performing invoice creation and payment redirect', 0, 33, 0, '$orderId=$hook->getValue(''orderID'');\n$arData=$hook->getValue(''orderData'');\n$payment=$hook->getValue(''payment'');\n\n$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\nif (!($obManager instanceof fcmsPaymentManager)) {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Could not find fcmsPaymentManager class'');\n	return false;\n}\n\n$obShopkeeper = $modx->getService(''shopkeeper'',''Shopkeeper'',$modx->getOption(''core_path'').''components/shopkeeper3/model/'');\nif (!($obShopkeeper instanceof Shopkeeper)) {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Could not find Shopkeeper class'');\n	return false;\n}\n\nif($obOrder=$modx->getObject(''shk_order'',$orderId)) {\n	if($obPayment=$obManager->createPayment($orderId,$payment,$obOrder->price)) {\n		$arInfo=$obManager->getPaymethod($payment);\n		if($arInfo[''link'']>0) {\n			$modx->sendRedirect($modx->makeUrl($arInfo[''link''],'''',''orderId=''.intval($orderId).''&paymentId=''.intval($obPayment->id)));\n		} else {\n			return true;\n		}\n	} else {\n		$modx->log(modX::LOG_LEVEL_ERROR,''Payment create error'');\n		return false;\n	}\n} else {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Order not found'');\n	return false;\n}', 0, 'a:0:{}', '', 0, ''),
(92, 0, 0, 'fcmspaymentForm', 'Snippet performing basic payment form rendering', 0, 33, 0, '/**\n * @var array $scriptProperties\n */\n$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\nif (!($obManager instanceof fcmsPaymentManager)) return '''';\n\n$scriptProperties[''paymentId'']=$modx->getOption(''paymentId'',$scriptProperties,$modx->getOption(''paymentId'',$_GET,0));\n\nif($obPayment=$obManager->getPayment($scriptProperties[''paymentId''])) {\n	if($obPayment->isNotClosed()) {\n		$arForm=$obPayment->getMethod()->getForm();\n		$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,$obPayment->getMethod()->getFormChunkName());\n\n		$arResult=array();\n		if(isset($arForm[''query''])) {\n			$arResult[''query'']='''';\n			foreach($arForm[''query''] as $key=>$value) {\n				$arResult[''query''].=''<input type="hidden" name="''.urlencode($key).''" value="''.htmlspecialchars($value,ENT_QUOTES,''utf-8'').''"/>'';\n			}\n		} else {\n			$arResult[''query'']='''';\n		}\n		if(isset($arForm[''action''])) {\n			$arResult[''action'']=$arForm[''action''];\n		}  else {\n			$arResult[''action'']='''';\n		}\n		$arResult[''summ'']=$obPayment->summ;\n		$arResult[''errorText''] = !empty($arForm[''errorText'']) ? $arForm[''errorText''] : '''';\n		$arResult[''phone''] = !empty($arForm[''phone'']) ? $arForm[''phone''] : '''';\n		$arResult[''phoneVar''] = !empty($arForm[''phoneVar'']) ? $arForm[''phoneVar''] : '''';\n		return $modx->getChunk($scriptProperties[''tpl''],$arResult);\n	}\n}\nreturn '''';', 0, '', '', 0, ''),
(93, 0, 0, 'fcmspaymentList', 'Snippet rendering paymethod list', 0, 33, 0, '/**\n * Snippet performs listing of pay methods\n * @var array $scriptProperties\n */\n$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,''paymentList'');\n$scriptProperties[''itemtpl'']=$modx->getOption(''itemtpl'',$scriptProperties,''paymentListItem'');\n$scriptProperties[''name'']=$modx->getOption(''name'',$scriptProperties,''payment'');\n\n$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\nif (!($obManager instanceof fcmsPaymentManager)) return '''';\n\n$arList=$obManager->getPaymethodList();\n$sList='''';\n\nforeach($arList as $arMethod) {\n	if(isset($_POST[$scriptProperties[''name'']]) && $_POST[$scriptProperties[''name'']]==$arMethod[''id'']) {\n		$arMethod[''checked'']=true;\n	} else {\n		$arMethod[''checked'']=false;\n	}\n	$arMethod[''name'']=$scriptProperties[''name''];\n	$sList.=$modx->getChunk($scriptProperties[''itemtpl''],$arMethod);\n}\n\nreturn $modx->getChunk($scriptProperties[''tpl''],array(''list''=>$sList,''name''=>$scriptProperties[''name'']));', 0, '', '', 0, ''),
(94, 0, 0, 'fcmspaymentRFail', 'Snippet performing invoice cancel on Robokassa payment fail', 0, 33, 0, '/**\n * @var array $scriptProperties\n */\n\n$scriptProperties[''method'']=$modx->getOption(''method'',$scriptProperties,''GET'');\n$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,''paymentRobokassaFail'');\n$scriptProperties[''tplError'']=$modx->getOption(''tplError'',$scriptProperties,''paymentRobokassaFail'');\n\nif($scriptProperties[''method'']==''GET'' && $_SERVER[''REQUEST_METHOD'']==''GET'') {\n	$arData=$_GET;\n} elseif($scriptProperties[''method'']==''POST'' && $_SERVER[''REQUEST_METHOD'']==''POST'') {\n	$arData=$_POST;\n} else {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Wrong request method'');\n	return '''';\n}\n\nif(!isset($arData[''InvId''])) {\n	return $modx->getChunk($scriptProperties[''tplError''],array(''error''=>''3'',''error_text''=>''Ошибка: не удалось найти указанный счёт''));\n}\n\n$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\nif (!($obManager instanceof fcmsPaymentManager)) {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Could not find fcmsPaymentManager class'');\n	return false;\n}\n\nif($obPayment=$obManager->getPayment($arData[''InvId''])) {\n	$arResult=$obPayment->toArray();\n	return $modx->getChunk($scriptProperties[''tpl''],$arResult);\n} else {\n	return $modx->getChunk($scriptProperties[''tplError''],array(''error''=>''3'',''error_text''=>''Ошибка: не удалось найти указанный счёт''));\n}', 0, '', '', 0, ''),
(95, 0, 0, 'fcmspaymentRResult', 'Snippet performing invoice submission on result from robokassa. Can automatically change order status', 0, 33, 0, '/**\n * This snippet perform system function for Robokassa payment interface. It should return\n * ''OK''.$InvId if everything is ok, or some error text.\n * @var array $scriptProperties\n */\n\n$scriptProperties[''method'']=$modx->getOption(''method'',$scriptProperties,''GET'');\n\nif($scriptProperties[''method'']==''GET'' && $_SERVER[''REQUEST_METHOD'']==''GET'') {\n	$arData=$_GET;\n} elseif($scriptProperties[''method'']==''POST'' && $_SERVER[''REQUEST_METHOD'']==''POST'') {\n	$arData=$_POST;\n} else {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Wrong request method'');\n	return '''';\n}\n\nif(!isset($arData[''InvId''])) return '''';\n\n$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\nif (!($obManager instanceof fcmsPaymentManager)) {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Could not find fcmsPaymentManager class'');\n	return false;\n}\n\n$arData[''InvId'']=$modx->getOption(''InvId'',$arData,0);\n$arData[''SignatureValue'']=$modx->getOption(''SignatureValue'',$arData,'''');\n$arData[''OutSum'']=$modx->getOption(''OutSum'',$arData,0);\n\nif($obPayment=$obManager->getPayment($arData[''InvId''])) {\n	if($obPayment->isNotClosed()) {\n		if($obMethod=$obPayment->getMethod()) {\n			$obMethod->setCheckData($arData);\n			if($obMethod->checkResultSign($arData[''SignatureValue'']) && $obPayment->checkSumm($arData[''OutSum''])) {\n				$obPayment->closeWithoutConfirm();\n				return ''OK''.$obPayment->id;\n			} else {\n				return ''ERROR - sign'';\n			}\n		} else {\n			return ''ERROR - no method'';\n		}\n	} else {\n		return ''OK''.$obPayment->id;\n	}\n} else {\n	return ''ERROR - no payment'';\n}', 0, '', '', 0, ''),
(96, 0, 0, 'fcmspaymentRSuccess', 'Snippet performing invoice submition and showing text information', 0, 33, 0, '/**\n * @var array $scriptProperties\n */\n\n$scriptProperties[''method'']=$modx->getOption(''method'',$scriptProperties,''GET'');\n$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,''paymentRobokassaSuccess'');\n$scriptProperties[''tplError'']=$modx->getOption(''tplError'',$scriptProperties,''paymentRobokassaSuccessError'');\n\nif($scriptProperties[''method'']==''GET'' && $_SERVER[''REQUEST_METHOD'']==''GET'') {\n	$arData=$_GET;\n} elseif($scriptProperties[''method'']==''POST'' && $_SERVER[''REQUEST_METHOD'']==''POST'') {\n	$arData=$_POST;\n} else {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Wrong request method'');\n	return '''';\n}\n\nif(!isset($arData[''InvId''])) {\n	return $modx->getChunk($scriptProperties[''tplError''],array(''error''=>''3'',''error_text''=>''Ошибка: не удалось найти указанный счёт''));\n}\n\n$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\nif (!($obManager instanceof fcmsPaymentManager)) {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Could not find fcmsPaymentManager class'');\n	return false;\n}\n\n$arData[''InvId'']=$modx->getOption(''InvId'',$arData,0);\n$arData[''SignatureValue'']=$modx->getOption(''SignatureValue'',$arData,'''');\n$arData[''OutSum'']=$modx->getOption(''OutSum'',$arData,0);\n\nif($obPayment=$obManager->getPayment($arData[''InvId''])) {\n	if($obMethod=$obPayment->getMethod()) {\n		$obMethod->setCheckData($arData);\n		if($obMethod->checkSuccessSign($arData[''SignatureValue'']) && $obPayment->checkSumm($arData[''OutSum''])) {\n			if($obPayment->isNotClosed()) {\n				$obPayment->closeWithoutConfirm();\n			}\n			$arResult=$obPayment->toArray();\n			return $modx->getChunk($scriptProperties[''tpl''],$arResult);\n		} else {\n			return $modx->getChunk($scriptProperties[''tplError''],array(''error''=>''1'',''error_text''=>''Ошибка при проверке подписи данных''));\n		}\n	} else {\n		return $modx->getChunk($scriptProperties[''tplError''],array(''error''=>''2'',''error_text''=>''Ошибка при определении способа оплаты счёта''));\n	}\n} else {\n	return $modx->getChunk($scriptProperties[''tplError''],array(''error''=>''3'',''error_text''=>''Ошибка: не удалось найти указанный счёт''));\n}', 0, '', '', 0, '');
INSERT INTO `modx_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(97, 0, 0, 'fcmspaymentCreate', 'Snippet performing user payment creation', 0, 33, 0, '/**\n * Snippet performs display of form that makes payment creation without shopkeeper\n * @var array $scriptProperties\n */\n$scriptProperties[''tpl'']=$modx->getOption(''tpl'',$scriptProperties,''paymentCreate'');\n$scriptProperties[''payName'']=$modx->getOption(''payName'',$scriptProperties,''payName'');\n$scriptProperties[''summName'']=$modx->getOption(''summName'',$scriptProperties,''summ'');\n$scriptProperties[''paymentName'']=$modx->getOption(''paymentName'',$scriptProperties,''payment'');\n$scriptProperties[''method'']=$modx->getOption(''method'',$scriptProperties,''POST'');\nif(isset($modx->resource)) {\n	$scriptProperties[''url'']=$modx->getOption(''url'',$scriptProperties,$modx->makeurl($modx->resource->id));\n} else {\n	$scriptProperties[''url'']=$modx->getOption(''url'',$scriptProperties,'''');\n}\n\n$arResult=$scriptProperties;\n$arData=array();\n\nif($scriptProperties[''method'']==''POST'') {\n	$arData=$_POST;\n} elseif($scriptProperties[''method'']==''GET'') {\n	$arData=$_GET;\n}\n\nif(isset($scriptProperties[''summ''])) {\n	$arResult[''summ'']=floatval($scriptProperties[''summ'']);\n} elseif(isset($arData[$scriptProperties[''summName'']])) {\n	$arResult[''summ'']=floatval($arData[$scriptProperties[''summName'']]);\n} else {\n	$arResult[''summ'']=0;\n}\n\nif($_SERVER[''REQUEST_METHOD'']==$scriptProperties[''method''] &&\n	isset($arData[$scriptProperties[''payName'']]) &&\n	isset($arData[$scriptProperties[''summName'']]) &&\n	isset($arData[$scriptProperties[''paymentName'']])) {\n\n	$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\n	if (!($obManager instanceof fcmsPaymentManager)) {\n		$modx->log(modX::LOG_LEVEL_ERROR,''Could not find fcmsPaymentManager class'');\n		return false;\n	}\n\n	$payment=$arData[$scriptProperties[''paymentName'']];\n	if($obPayment=$obManager->createPayment(0,$payment,$arResult[''summ''])) {\n		$arInfo=$obManager->getPaymethod($payment);\n		if($arInfo[''link'']>0) {\n			$modx->sendRedirect($modx->makeUrl($arInfo[''link''],'''',''paymentId=''.intval($obPayment->id)));\n		} else {\n			$arResult=array_merge($arResult,$obPayment->toArray(''payment.''));\n		}\n	} else {\n		$modx->log(modX::LOG_LEVEL_ERROR,''Payment create error'');\n		$arResult[''error'']=$modx->lexicon(''fcmspayment.payment_create_error'');\n	}\n}\n\nreturn $modx->getChunk($scriptProperties[''tpl''],$arResult);', 0, '', '', 0, ''),
(98, 0, 0, 'fcmspaymentRBKMoneyResult', 'Сниппет выполняет обработку оповещения о платеже от RBK Money', 0, 33, 0, '/**\n * Сниппет выполняет обработку оповещения о платеже от RBK Money\n */\nif (empty($_REQUEST)) {\n	 exit;\n}\n\n// проверка существования fcmsPayment\n$obManager = $modx->getService(''fcmsPayment'',''fcmsPaymentManager'',$modx->getOption(''core_path'').''components/fcmspayment/model/fcmspayment/'');\nif (!($obManager instanceof fcmsPaymentManager)) {\n	$modx->log(modX::LOG_LEVEL_ERROR,''Could not find fcmsPaymentManager class'');\n	return false;\n}\n\n$arData = $_REQUEST;\n\nif(isset($arData[''orderId'']) && $obPayment=$obManager->getPayment($arData[''orderId''])) {\n	if($obPayment->isNotClosed()) {\n		if($obMethod=$obPayment->getMethod()) {\n			if ($obMethod->isSignEnabled() && (empty($arData[''hash'']) || !$obMethod->checkNotificationSign($arData, $arData[''hash'']))) {\n				throw new Exception(''RBK callback error: sign corrupted'',500);\n			}\n			if ($obMethod->processNotification($arData)) {\n				if ($obMethod->isSignEnabled()) {\n					$obPayment->close();\n				} else {\n					$obPayment->closeWithoutConfirm();\n				}\n				header("HTTP/1.0 200 OK");\n				echo "OK";\n			} else {\n				throw new Exception(''RBK callback error: error processing payment'',500);\n			}\n		} else {\n			throw new Exception(''RBK callback error: method not found'',500);\n		}\n	} else {\n		return ''OK'';\n	}\n} else {\n	throw new Exception(''RBK callback error: payment not found'',500);\n}', 0, '', '', 0, ''),
(99, 1, 0, 'AjaxForm', '', 0, 34, 0, '/** @var array $scriptProperties */\n/** @var AjaxForm $AjaxForm */\nif (!$modx->loadClass(''ajaxform'', MODX_CORE_PATH . ''components/ajaxform/model/ajaxform/'', false, true)) {\n    return false;\n}\n$AjaxForm = new AjaxForm($modx, $scriptProperties);\n\n$snippet = $modx->getOption(''snippet'', $scriptProperties, ''FormIt'', true);\n$tpl = $modx->getOption(''form'', $scriptProperties, ''tpl.AjaxForm.example'', true);\n$formSelector = $modx->getOption(''formSelector'', $scriptProperties, ''ajax_form'', true);\n$objectName = $modx->getOption(''objectName'', $scriptProperties, ''AjaxForm'', true);\n$AjaxForm->loadJsCss($objectName);\n\n/** @var pdoTools $pdo */\nif (class_exists(''pdoTools'') && $pdo = $modx->getService(''pdoTools'')) {\n    $content = $pdo->getChunk($tpl, $scriptProperties);\n} else {\n    $content = $modx->getChunk($tpl, $scriptProperties);\n}\nif (empty($content)) {\n    return $modx->lexicon(''af_err_chunk_nf'', array(''name'' => $tpl));\n}\n\n// Add selector to tag form\nif (preg_match(''#<form.*?class=(?:"|\\'')(.*?)(?:"|\\'')#i'', $content, $matches)) {\n    $classes = explode('' '', $matches[1]);\n    if (!in_array($formSelector, $classes)) {\n        $classes[] = $formSelector;\n        $classes = preg_replace(\n            ''#class=(?:"|\\'')'' . $matches[1] . ''(?:"|\\'')#i'',\n            ''class="'' . implode('' '', $classes) . ''"'',\n            $matches[0]\n        );\n        $content = str_ireplace($matches[0], $classes, $content);\n    }\n} else {\n    $content = str_ireplace(''<form'', ''<form class="'' . $formSelector . ''"'', $content);\n}\n\n// Add method = post\nif (preg_match(''#<form.*?method=(?:"|\\'')(.*?)(?:"|\\'')#i'', $content)) {\n    $content = preg_replace(''#<form(.*?)method=(?:"|\\'')(.*?)(?:"|\\'')#i'', ''<form\\\\1method="post"'', $content);\n} else {\n    $content = str_ireplace(''<form'', ''<form method="post"'', $content);\n}\n\n// Add action for form processing\n$hash = md5(http_build_query($scriptProperties));\n$action = ''<input type="hidden" name="af_action" value="'' . $hash . ''" />'';\nif ((stripos($content, ''</form>'') !== false)) {\n    if (preg_match(''#<input.*?name=(?:"|\\'')af_action(?:"|\\'').*?>#i'', $content, $matches)) {\n        $content = str_ireplace($matches[0], '''', $content);\n    }\n    $content = str_ireplace(''</form>'', "\\n\\t$action\\n</form>", $content);\n}\n\n// Save settings to user`s session\n$_SESSION[''AjaxForm''][$hash] = $scriptProperties;\n\n// Call snippet for preparation of form\n$action = !empty($_REQUEST[''af_action''])\n    ? $_REQUEST[''af_action'']\n    : $hash;\n\n$AjaxForm->process($action, $_REQUEST);\n\n// Return chunk\nreturn $content;', 0, 'a:7:{s:9:"actionUrl";a:7:{s:4:"name";s:9:"actionUrl";s:4:"desc";s:23:"ajaxform_prop_actionUrl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:24:"[[+assetsUrl]]action.php";s:7:"lexicon";s:19:"ajaxform:properties";s:4:"area";s:0:"";}s:4:"form";a:7:{s:4:"name";s:4:"form";s:4:"desc";s:18:"ajaxform_prop_form";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:20:"tpl.AjaxForm.example";s:7:"lexicon";s:19:"ajaxform:properties";s:4:"area";s:0:"";}s:12:"formSelector";a:7:{s:4:"name";s:12:"formSelector";s:4:"desc";s:26:"ajaxform_prop_formSelector";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:9:"ajax_form";s:7:"lexicon";s:19:"ajaxform:properties";s:4:"area";s:0:"";}s:12:"frontend_css";a:7:{s:4:"name";s:12:"frontend_css";s:4:"desc";s:26:"ajaxform_prop_frontend_css";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:35:"/assets/extra/ajax-form/default.css";s:7:"lexicon";s:19:"ajaxform:properties";s:4:"area";s:0:"";}s:11:"frontend_js";a:7:{s:4:"name";s:11:"frontend_js";s:4:"desc";s:25:"ajaxform_prop_frontend_js";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:34:"/assets/extra/ajax-form/default.js";s:7:"lexicon";s:19:"ajaxform:properties";s:4:"area";s:0:"";}s:10:"objectName";a:7:{s:4:"name";s:10: