(131, 1, 0, 'mapexMap21', '', 0, 45, 0, '/* @var array $scriptProperties */\n/* @var mapex2 $mapex2 */\n$mapex2 = $modx->getService(''mapex2'', ''mapex2'', MODX_CORE_PATH . ''components/mapex2/model/mapex2/'');\n\n$map = $modx->getOption(''map'', $scriptProperties, '''');\n\nif(empty($map)) {\n    $tvName = $modx->getOption(''tvName'', $scriptProperties, '''');\n    if(empty($tvName)) {\n        return '''';\n    }\n    $resource = intval($modx->getOption(''resource'', $scriptProperties, 0));\n    if($resource == $modx->resource->get(''id'') || $resource == 0) {\n        $resource = $modx->resource;\n    }\n    else {\n        $resource = $modx->getObject(''modResource'', $resource);\n    }\n    if(empty($resource)) {\n        return '''';\n    }\n    $map = $resource->getTVValue($tvName);\n}\nif(empty($map)) {\n    return '''';\n}\n\n/* templates */\n$mapTpl = $modx->getOption(''mapTpl'', $scriptProperties, ''mapex.Map.Tpl'');\n$placemarkTpl = $modx->getOption(''placemarkTpl'', $scriptProperties, ''mapex.Placemark.Tpl'');\n$polygonTpl = $modx->getOption(''polygonTpl'', $scriptProperties, ''mapex.Polygon.Tpl'');\n$polylineTpl = $modx->getOption(''polylineTpl'', $scriptProperties, ''mapex.Polyline.Tpl'');\n$routeTpl = $modx->getOption(''routeTpl'', $scriptProperties, ''mapex.Route.Tpl'');\n\n$map = json_decode($map);\n\n// Map controls, can be: smallMapDefaultSet, mediumMapDefaultSet (default), largeMapDefaultSet\n// or individual: geolocationControl, searchControl, routeEditor, trafficControl, typeSelector, fullscreenControl, zoomControl, rulerControl\n$controls = $modx->getOption(''controls'', $scriptProperties, '''');\n\n$mapId = $modx->getOption(''mapId'', $scriptProperties, ''mapexMap'');\n$width = $modx->getOption(''width'', $scriptProperties, ''500px'');\n$height = $modx->getOption(''height'', $scriptProperties, ''400px'');\n\n$includeJs = $modx->getOption(''includeJs'', $scriptProperties, 1);\nif(!empty($includeJs)) {\n    $lang = $modx->getOption(''lang'', $scriptProperties, ''ru-RU'');\n    $modx->regClientStartupScript(''https://api-maps.yandex.ru/2.1/?lang=''.$lang);\n}\n\n$mapCss = $modx->getOption(''containerCssClass'', $scriptProperties, '''');\n\nreturn $mapex2->drawMap($map, $controls, $mapId, $mapCss, $mapTpl, $placemarkTpl, $polygonTpl, $polylineTpl, $routeTpl, $width, $height);', 0, 'a:14:{s:17:"containerCssClass";a:7:{s:4:"name";s:17:"containerCssClass";s:4:"desc";s:29:"mapex2_prop_containerCssClass";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:8:"controls";a:7:{s:4:"name";s:8:"controls";s:4:"desc";s:20:"mapex2_prop_controls";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:7:"default";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:6:"height";a:7:{s:4:"name";s:6:"height";s:4:"desc";s:18:"mapex2_prop_height";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:5:"400px";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:9:"includeJs";a:7:{s:4:"name";s:9:"includeJs";s:4:"desc";s:21:"mapex2_prop_includeJs";s:4:"type";s:4:"list";s:7:"options";a:2:{i:0;a:2:{s:4:"text";s:1:"1";s:5:"value";s:1:"1";}i:1;a:2:{s:4:"text";s:1:"0";s:5:"value";s:1:"0";}}s:5:"value";s:1:"1";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:3:"map";a:7:{s:4:"name";s:3:"map";s:4:"desc";s:15:"mapex2_prop_map";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:5:"mapId";a:7:{s:4:"name";s:5:"mapId";s:4:"desc";s:17:"mapex2_prop_mapId";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:8:"mapexMap";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:6:"mapTpl";a:7:{s:4:"name";s:6:"mapTpl";s:4:"desc";s:18:"mapex2_prop_mapTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:15:"mapex.Map21.Tpl";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:12:"placemarkTpl";a:7:{s:4:"name";s:12:"placemarkTpl";s:4:"desc";s:24:"mapex2_prop_placemarkTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:21:"mapex.Placemark21.Tpl";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:10:"polygonTpl";a:7:{s:4:"name";s:10:"polygonTpl";s:4:"desc";s:22:"mapex2_prop_polygonTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:19:"mapex.Polygon21.Tpl";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:11:"polylineTpl";a:7:{s:4:"name";s:11:"polylineTpl";s:4:"desc";s:23:"mapex2_prop_polylineTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:20:"mapex.Polyline21.Tpl";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:8:"resource";a:7:{s:4:"name";s:8:"resource";s:4:"desc";s:20:"mapex2_prop_resource";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:8:"routeTpl";a:7:{s:4:"name";s:8:"routeTpl";s:4:"desc";s:20:"mapex2_prop_routeTpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:17:"mapex.Route21.Tpl";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:6:"tvName";a:7:{s:4:"name";s:6:"tvName";s:4:"desc";s:18:"mapex2_prop_tvName";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}s:5:"width";a:7:{s:4:"name";s:5:"width";s:4:"desc";s:17:"mapex2_prop_width";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:5:"500px";s:7:"lexicon";s:17:"mapex2:properties";s:4:"area";s:0:"";}}', '', 0, 'core/components/mapex2/elements/snippets/snippet.mapexMap21.php'),
(105, 2, 0, 'getSiteSettings', '', 0, 5, 0, '\r\n\r\n/*\r\ngetSiteSettings ver: 1.8\r\nIgor Siluyanov, 17.10.2016\r\n\r\nСкрипт получает все значения доп. полей ресурса, содержащего настройки, и создаёт одноимённые плейсхолдеры с префиксом "set.", пример:\r\n[[+set.site-slogan]]\r\nКонтакты хранятся в migx-е, поэтому для них предусмотрена обработка и вывод сразу с иконками и ссылками. \r\nВыводятся 2 списка контактов: [[+set.contacts.header]] и [[+set.contacts.all]] (если у контакта стоит галка dont_show, то он не появится в этих списках)\r\nА также каждый контакт выводится в таком виде: [[+set.contacts.email1]] и в таком: [[+set.unique_name]] (если у контакта установлено unique_name)\r\nАдрес почты в списках "всех контактов" и "для хедера" выводятся через сниппет botaway\r\n\r\nПараметры:\r\n    contactTpl - шаблон для каждого контакта (нужно указать имя чанка, либо html код с префиксом "@INLINE "), \r\n        значение по умолчанию: ''<p class="[[+class]]"><span>[[+icon]] <strong>[[+text]]</strong> [[+value]]</span></p>''\r\n    settings_res_id - id ресурса, содержащего настройки\r\n*/\r\n\r\nclass GetSiteSettings\r\n{\r\n    private $default_contact_tpl = ''<p class="[[+class]]"><span>[[+icon]] <strong>[[+text]]</strong> [[+value]]</span></p>'';\r\n    \r\n    public function __construct($modx, $scriptProperties)\r\n    {\r\n        $this->modx = $modx;\r\n        $this->settings_res_id = $scriptProperties[''settings_res_id''];\r\n        \r\n        // устанавливаем шаблон контакта (из чанка, из инлайна или дефолтный)\r\n        if (isset($scriptProperties[''contactTpl''])) {\r\n            if (strpos($scriptProperties[''contactTpl''], ''@INLINE'') === 0) { \r\n                $this->contact_tpl = substr($scriptProperties[''contactTpl''], 8);\r\n            } else {\r\n                $this->contact_tpl = $this->modx->getChunk($scriptProperties[''contactTpl'']);\r\n            }\r\n        } else {\r\n            $this->contact_tpl = $this->default_contact_tpl;\r\n        }\r\n        \r\n        // получаем все "настройки сайта"\r\n        $stmt = $this->modx->query("\r\n            SELECT tv.name, tv_c.value\r\n            FROM modx_site_tmplvars as tv\r\n            \r\n            LEFT JOIN modx_site_tmplvar_contentvalues as tv_c\r\n            ON tv.id = tv_c.tmplvarid and tv_c.contentid = " . $this->settings_res_id . "\r\n        ");\r\n        \r\n        $placeholders = array();\r\n        while ($row = $stmt->fetch()) {\r\n            if ($row[''name''] == ''contacts'') { // для тв-поля contacts - особая обработка:\r\n                $contacts = $this->processContacts($row[''value'']);\r\n                $placeholders = array_merge($placeholders, $contacts);\r\n            } else { // важно: если значение пустое, то присваиваем ему пустую строку\r\n                $pl_name = ''set.'' . $row[''name'']; \r\n                $placeholders[$pl_name] = $row[''value''] ? $row[''value''] : '''';\r\n            }\r\n        }\r\n        $modx->setPlaceholders($placeholders); // установка плейсхолдеров - весь результат работы скрипта\r\n    }\r\n\r\n    private function fixLink($link)\r\n    {\r\n        if (strpos($link, ''http'') !== 0) {\r\n            $link = ''http://'' . $link;\r\n        }\r\n        return $link;\r\n    }\r\n    \r\n    private function clearPhone($input)\r\n    {\r\n        return preg_replace(array(''/[^\\d]/u'', ''/^[7|8]/u''), array('''', ''+7''), $input);\r\n    }\r\n    \r\n    private function processContacts($json_str)\r\n    {\r\n        $contacts_arr = json_decode($json_str);\r\n        $result = array();\r\n        $item_counter = array(); // счётчик для каждого из типов контактов\r\n        foreach($contacts_arr as $contact) {\r\n            $item_html = '''';\r\n            // ужасная проверка по строкам на русском языке, но иначе нельзя:\r\n            switch($contact->contact_type) {\r\n                case ''Телефон'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-phone"></i>'';\r\n                    $cleared_phone = $this->clearPhone($contact->contact_value);\r\n                    $item_value_wrapped = ''<a href="tel:'' . $cleared_phone . ''">'' . $contact->contact_value . ''</a>'';\r\n                    $item_type = ''phone'';\r\n                    break;\r\n                case ''Факс'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-fax"></i>'';\r\n                    $cleared_phone = $this->clearPhone($contact->contact_value);\r\n                    $item_value_wrapped = ''<a href="tel:'' . $cleared_phone . ''">'' . $contact->contact_value . ''</a>'';\r\n                    $item_type = ''fax'';\r\n                    break;\r\n                case ''E-mail'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-envelope"></i>'';\r\n                    $item_value_wrapped = $this->modx->runSnippet(''botaway'', array(''email'' => $contact->contact_value));\r\n                    //$item_value_wrapped = ''<a href="mailto:'' . $contact->contact_value . ''">'' . $contact->contact_value . ''</a>'';\r\n                    $item_type = ''email'';\r\n                    break;\r\n                case ''Адрес'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-map-marker"></i>'';\r\n                    $item_value_wrapped = $contact->contact_value;\r\n                    $item_type = ''address'';\r\n                    break;\r\n                case ''Skype'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-skype"></i>'';\r\n                    $item_value_wrapped = $contact->contact_value;\r\n                    $item_type = ''skype'';\r\n                    break;\r\n                case ''ВКонтакте'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-vk"></i>'';\r\n                    $link = $this->fixLink($contact->contact_value);\r\n                    $item_value_wrapped = ''<a target="_blank" href="'' . $link . ''">ВКонтакте</a>'';\r\n                    $item_type = ''vk'';\r\n                    break;\r\n                case ''Facebook'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-facebook-official"></i>'';\r\n                    $link = $this->fixLink($contact->contact_value);\r\n                    $item_value_wrapped = ''<a target="_blank" href="'' . $link . ''">Facebook</a>'';\r\n                    $item_type = ''facebook'';\r\n                    break;\r\n                case ''Instagram'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-instagram"></i>'';\r\n                    $link = $this->fixLink($contact->contact_value);\r\n                    $item_value_wrapped = ''<a target="_blank" href="'' . $link . ''">Instagram</a>'';\r\n                    $item_type = ''instagram'';\r\n                    break;\r\n                case ''Веб-сайт'':\r\n                    $item_icon = ''<i class="fa fa-fw fa-external-link"></i>'';\r\n                    $link = $this->fixLink($contact->contact_value);\r\n                    $item_value_wrapped = ''<a target="_blank" href="'' . $link . ''">'' . $link . ''</a>'';\r\n                    $item_type = ''website'';\r\n                    break;\r\n                case ''Текст'':\r\n                    $item_icon = '''';\r\n                    $item_value_wrapped = $contact->contact_value;\r\n                    $item_type = ''text'';\r\n                    break;\r\n            }\r\n            \r\n            $item_html = str_replace(\r\n                array(''[[+icon]]'', ''[[+value]]'', ''[[+text]]'', ''[[+class]]''), \r\n                array($item_icon, $item_value_wrapped, $contact->contact_text, $contact->css_class), \r\n                $this->contact_tpl\r\n            );\r\n    \r\n            // значения contacts.all и contacts.header\r\n            if ($contact->contact_value && !$contact->dont_show) {\r\n                $result[''set.contacts.all''] .= $item_html;\r\n                if ($contact->display_at_header) {\r\n                    $result[''set.contacts.header''] .= $item_html;\r\n                }\r\n            }\r\n    \r\n            // значения плейсхолдеров со счётчиками\r\n            $item_counter[$item_type]++;\r\n            $item_placeholder = ''set.contacts.'' . $item_type . $item_counter[$item_type];\r\n            $result[$item_placeholder] = $contact->contact_value;\r\n            // доптекст поля\r\n            $item_text_placeholder = ''set.contacts.'' . $item_type . $item_counter[$item_type] . ''.text'';\r\n            $result[$item_text_placeholder] = $contact->contact_text;\r\n            \r\n            // выкидываем лишние символы из уникального имени\r\n            $contact->unique_name = preg_replace(''/[^\\w-]/'', '''', $contact->unique_name);\r\n            // добавляем уникальное имя контакта (если оно заполнено)\r\n            if ($contact->unique_name) {\r\n                $result[''set.'' . $contact->unique_name] = $contact->contact_value;\r\n                $result[''set.'' . $contact->unique_name . ''.text''] = $contact->contact_text;\r\n            }\r\n            \r\n            // \r\n        }\r\n        return $result;\r\n    }\r\n}\r\n\r\nnew GetSiteSettings($modx, $scriptProperties);', 0, 'a:1:{s:15:"settings_res_id";a:7:{s:4:"name";s:15:"settings_res_id";s:4:"desc";s:0:"";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:2:"54";s:7:"lexicon";N;s:4:"area";s:0:"";}}', '', 0, ''),
(107, 0, 0, 'pthumb', 'Identical to phpthumbof. Better for future compatibility.\nDocumentation: https://github.com/oo12/phpThumbOf', 0, 40, 0, '/**\n * pThumb\n * Copyright 2013-2014 Jason Grant\n *\n * Please see the GitHub page for documentation or to report bugs:\n * https://github.com/oo12/phpThumbOf\n *\n * Forked from phpThumbOf 1.4.0\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\n *\n * pThumb is free software; you can redistribute it and/or modify it\n * under the terms of the GNU General Public License as published by the Free\n * Software Foundation; either version 2 of the License, or (at your option) any\n * later version.\n *\n * pThumb is distributed in the hope that it will be useful, but WITHOUT ANY\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License along with\n * phpThumbOf; if not, write to the Free Software Foundation, Inc., 59 Temple\n * Place, Suite 330, Boston, MA 02111-1307 USA\n *\n */\n/**\n *\n * @var modX $modx\n * @var array $scriptProperties\n * @var string $input\n * @var string|array $options\n *\n */\n\nif (empty($input)) {  // Exit quietly if no file name given\n	return;\n}\n\n$scriptProperties[''debug''] = isset($debug) ? $debug : false;\n\n\nstatic $pt_settings = array();\n\nif (empty($pt_settings)) {\n	if (!$modx->loadClass(''phpThumbOf'', MODX_CORE_PATH . ''components/phpthumbof/model/'', true, true)) {\n		$modx->log(modX::LOG_LEVEL_ERROR, ''[pThumb] Could not load phpThumbOf class.'');\n		return $input;\n	}\n}\n\n$pThumb = new phpThumbOf($modx, $pt_settings, $scriptProperties);\n\n$result = $pThumb->createThumbnail($input, $options);\n\nif (!empty($toPlaceholder) || $result[''outputDims'']) {\n	if ($result[''width''] === '''' && $result[''file''] && $dims = getimagesize($result[''file'']) ) {\n			$result[''width''] = $dims[0];\n			$result[''height''] = $dims[1];\n	}\n	if (!empty($toPlaceholder)) {\n		$modx->setPlaceholders(array(\n			$toPlaceholder => $result[''src''],\n			"$toPlaceholder.width" => $result[''width''],\n			"$toPlaceholder.height" => $result[''height'']\n		));\n		$output = '''';\n	}\n	if ($result[''outputDims'']) {\n		$output = "src=\\"{$result[''src'']}\\"" . ($result[''width''] ? " width=\\"{$result[''width'']}\\" height=\\"{$result[''height'']}\\"" : '''');\n	}\n}\nelse {\n	$output = $result[''src''];\n}\n\nif ($debug && $result[''success'']) {  // if debugging is on and createThumbnail was successful, log the debug info\n	$pThumb->debugmsg(isset($pThumb->phpThumb->debugmessages) ? '':: Processed ::'' : ":: Loaded from cache: {$result[''src'']}", true);\n}\n\nreturn $output;', 0, 'a:1:{s:5:"debug";a:7:{s:4:"name";s:5:"debug";s:4:"desc";s:22:"prop_pthumb.debug_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:18:"phpthumbof:default";s:4:"area";s:0:"";}}', '', 0, ''),
(108, 2, 0, 'viewCounter', '', 0, 5, 0, '$current_res = $modx->resource;\n$current_res_id = $current_res->get(''id'');\n\nif (!isset($_SESSION[''viewed-pages''])) {\n    $_SESSION[''viewed-pages''] = array();\n}\n\nif (!isset($_SESSION[''viewed-pages''][$current_res_id])) {\n    $_SESSION[''viewed-pages''][$current_res_id] = true;\n    $views = $current_res->getTVValue(''views'');\n    $current_res->setTVValue(''views'', ++$views);\n}', 0, 'a:0:{}', '', 0, ''),
