(132, 1, 0, 'BannerY', 'Show ads on your site', 0, 46, 0, '/** @var array $scriptProperties */\n/* @var pdoFetch $pdoFetch */\nif (!$modx->getService(''pdoFetch'')) {return ''You need to install pdoTools to use this snippet!'';}\n$pdoFetch = new pdoFetch($modx, $scriptProperties);\n$pdoFetch->addTime(''pdoTools loaded'');\n$modx->lexicon->load(''bannery:default'');\n$modx->addPackage(''bannery'', MODX_CORE_PATH . ''components/bannery/model/'');\n\nif (!empty($tplOuter)) {$tplWrapper = $tplOuter;}\nif (empty($outputSeparator)) {$outputSeparator = "\\n";}\n$class = ''byAd'';\n\n// Adding extra parameters into special place so we can put them in results\n/** @var modSnippet $snippet */\n$additionalPlaceholders = array();\nif ($snippet = $modx->getObject(''modSnippet'', array(''name'' => ''BannerY''))) {\n	$properties = unserialize($snippet->properties);\n	foreach ($scriptProperties as $k => $v) {\n		if (!isset($properties[$k])) {\n			$additionalPlaceholders[$k] = $v;\n		}\n	}\n}\n// ---\n\n$date = date(''Y-m-d H:i:s'');\n$where = array(\n	"({$class}.start IS NULL OR {$class}.start <= ''{$date}'') AND ({$class}.end IS NULL OR {$class}.end >= ''{$date}'')"\n);\nif (empty($showInactive)) {\n	$where[$class.''.active''] = 1;\n}\nif (!empty($position)) {\n	$where[''byAdPosition.position''] = $position;\n}\nelseif (!empty($positions)) {\n	$where[''byAdPosition.position:IN''] = array_map(''trim'', explode('','', $positions));\n}\n\nif (empty($sortby)) {\n	$sortby = ''RAND()'';\n}\nelseif ($sortby == ''idx'' || $sortby == ''index'') {\n	$sortby = ''byAdPosition.idx'';\n}\nelse {\n	$sortby = $class.''.''.$sortby;\n}\n\n$innerJoin = array(\n	''byAdPosition'' => array(\n		''alias'' => ''byAdPosition'',\n		''on'' => $class.''.id = byAdPosition.ad''\n	)\n);\n\n// Fields to select\n$select = array(\n	$class => ''all'',\n	''byAdPosition'' => ''`byAdPosition`.`id` as `adposition`, `byAdPosition`.`ad`''\n);\n\n// Add custom parameters\nforeach (array(''where'',''innerJoin'',''select'') as $v) {\n	if (!empty($scriptProperties[$v])) {\n		$tmp = $modx->fromJSON($scriptProperties[$v]);\n		if (is_array($tmp)) {\n			$$v = array_merge($$v, $tmp);\n		}\n	}\n	unset($scriptProperties[$v]);\n}\n$pdoFetch->addTime(''Conditions prepared'');\n\n$default = array(\n	''class'' => $class,\n	''innerJoin'' => $modx->toJSON($innerJoin),\n	''where'' => $modx->toJSON($where),\n	''select'' => $modx->toJSON($select),\n	''sortby'' => $sortby,\n	''groupby'' => $class.''.id'',\n	''return'' => ''data'',\n	''disableConditions'' => true,\n);\n\n$pdoFetch->setConfig(array_merge($default, $scriptProperties));\n$rows = $pdoFetch->run();\n\n$output = array();\n$default_source = $modx->getOption(''bannery_media_source'', null, $modx->getOption(''default_media_source''), true);\n$sources = array();\nforeach ($rows as $row) {\n	$source = !empty($row[''source''])\n		? $row[''source'']\n		: $default_source;\n\n	if (!isset($sources[$row[''source'']])) {\n		/** @var modMediaSource $source */\n		if ($source = $modx->getObject(''sources.modMediaSource'', $source)) {\n			$source->initialize($modx->context->key);\n		}\n		$sources[$row[''source'']] = $source;\n	}\n	else {\n		$source = $sources[$row[''source'']];\n	}\n\n	if (!empty($source) && $source instanceof modMediaSource && !empty($row[''image''])) {\n		$row[''image''] = $source->getObjectUrl($row[''image'']);\n	}\n\n	$row[''idx''] = $pdoFetch->idx++;\n	$tpl = $pdoFetch->defineChunk($row);\n	if (!empty($additionalPlaceholders)) {\n		$row = array_merge($additionalPlaceholders, $row);\n	}\n\n	$output[] = !empty($tpl)\n		? $pdoFetch->getChunk($tpl, $row, $pdoFetch->config[''fastMode''])\n		: ''<pre>''.$pdoFetch->getChunk('''', $row).''</pre>'';\n}\n\nif ($modx->user->hasSessionContext(''mgr'') && !empty($showLog)) {\n	$output[''log''] = ''<pre class="pdoUsersLog">'' . print_r($pdoFetch->getTime(), 1) . ''</pre>'';\n}\n\n// Return output\nif (!empty($toSeparatePlaceholders)) {\n	$modx->setPlaceholders($output, $toSeparatePlaceholders);\n}\nelse {\n	$output = implode($outputSeparator, $output);\n\n	if (!empty($tplWrapper) && (!empty($wrapIfEmpty) || !empty($output))) {\n		$output = $pdoFetch->getChunk($tplWrapper, array(''output'' => $output), $pdoFetch->config[''fastMode'']);\n	}\n\n	if (!empty($toPlaceholder)) {\n		$modx->setPlaceholder($toPlaceholder, $output);\n	}\n	else {\n		return $output;\n	}\n}', 0, 'a:18:{s:9:"positions";a:7:{s:4:"name";s:9:"positions";s:4:"desc";s:22:"bannery_prop_positions";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:7:"showLog";a:7:{s:4:"name";s:7:"showLog";s:4:"desc";s:20:"bannery_prop_showLog";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:8:"fastMode";a:7:{s:4:"name";s:8:"fastMode";s:4:"desc";s:21:"bannery_prop_fastMode";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:5:"limit";a:7:{s:4:"name";s:5:"limit";s:4:"desc";s:18:"bannery_prop_limit";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:5;s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:6:"offset";a:7:{s:4:"name";s:6:"offset";s:4:"desc";s:19:"bannery_prop_offset";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:0;s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:6:"sortby";a:7:{s:4:"name";s:6:"sortby";s:4:"desc";s:19:"bannery_prop_sortby";s:4:"type";s:4:"list";s:7:"options";a:7:{i:0;a:2:{s:4:"text";s:6:"Random";s:5:"value";s:6:"RAND()";}i:1;a:2:{s:4:"text";s:5:"Index";s:5:"value";s:3:"idx";}i:2;a:2:{s:4:"text";s:4:"Name";s:5:"value";s:4:"name";}i:3;a:2:{s:4:"text";s:3:"Url";s:5:"value";s:3:"url";}i:4;a:2:{s:4:"text";s:5:"Image";s:5:"value";s:5:"image";}i:5;a:2:{s:4:"text";s:6:"Active";s:5:"value";s:6:"active";}i:6;a:2:{s:4:"text";s:11:"Description";s:5:"value";s:11:"description";}}s:5:"value";s:6:"RAND()";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:7:"sortdir";a:7:{s:4:"name";s:7:"sortdir";s:4:"desc";s:20:"bannery_prop_sortdir";s:4:"type";s:4:"list";s:7:"options";a:2:{i:0;a:2:{s:4:"text";s:3:"ASC";s:5:"value";s:3:"ASC";}i:1;a:2:{s:4:"text";s:4:"DESC";s:5:"value";s:4:"DESC";}}s:5:"value";s:3:"ASC";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:15:"outputSeparator";a:7:{s:4:"name";s:15:"outputSeparator";s:4:"desc";s:28:"bannery_prop_outputSeparator";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:1:"\n";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:5:"where";a:7:{s:4:"name";s:5:"where";s:4:"desc";s:18:"bannery_prop_where";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:12:"showInactive";a:7:{s:4:"name";s:12:"showInactive";s:4:"desc";s:25:"bannery_prop_showInactive";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:16:"bannery_prop_tpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:4:"byAd";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:8:"tplFirst";a:7:{s:4:"name";s:8:"tplFirst";s:4:"desc";s:21:"bannery_prop_tplFirst";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:7:"tplLast";a:7:{s:4:"name";s:7:"tplLast";s:4:"desc";s:20:"bannery_prop_tplLast";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:6:"tplOdd";a:7:{s:4:"name";s:6:"tplOdd";s:4:"desc";s:19:"bannery_prop_tplOdd";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:10:"tplWrapper";a:7:{s:4:"name";s:10:"tplWrapper";s:4:"desc";s:23:"bannery_prop_tplWrapper";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:11:"wrapIfEmpty";a:7:{s:4:"name";s:11:"wrapIfEmpty";s:4:"desc";s:24:"bannery_prop_wrapIfEmpty";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:13:"toPlaceholder";a:7:{s:4:"name";s:13:"toPlaceholder";s:4:"desc";s:26:"bannery_prop_toPlaceholder";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}s:22:"toSeparatePlaceholders";a:7:{s:4:"name";s:22:"toSeparatePlaceholders";s:4:"desc";s:35:"bannery_prop_toSeparatePlaceholders";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:18:"bannery:properties";s:4:"area";s:0:"";}}', '', 0, 'core/components/bannery/elements/snippets/snippet.bannery.php'),
(133, 2, 0, 'allEmpty', '', 0, 5, 0, '/*\r\nСниппет реализует проверку условия "все пустые"\r\nПараметры:\r\n&p1 [, &p2...] - проверяемые значения, любое количество\r\n&then - что вывести, если все пустые\r\n[&else] - что вывести в противном случае\r\n*/\r\n\r\n$allEmpty = true;\r\n\r\nforeach ($scriptProperties as $key => $item) {\r\n    if (preg_match(''/p\\d+/'', $key)) {\r\n        if ($item !=  '''') {\r\n            $allEmpty = false;\r\n            break;\r\n        };\r\n    }\r\n}\r\n\r\nif ($allEmpty) {\r\n    return $then;\r\n} elseif (isset($else)) {\r\n    return $else;\r\n}', 0, 'a:0:{}', '', 0, ''),
(134, 2, 0, 'BasicNav', '', 0, 5, 0, '\r\n/*\r\nBasicNav-fork 1.3 (21.10.2016)\r\nЭто форк. Сниппет был доработан чтобы он принимал параметры tplPrev, tplNext и tplWrapper. (Igor Siluyanov)\r\n\r\nПример вызова (указаны значения по умолчанию):\r\n[[!BasicNav? \r\n  &sortBy=`menuindex` \r\n  &sortDir=`DESC` \r\n  &toPlaceholder=`basicnav` \r\n  &tplWrapper=`basicNav.wrapper`\r\n  &prevLink=`basicNav.prevLink`\r\n  &nextLink=`basicNav.nextLink`\r\n]]\r\n*/\r\n\r\n$toPlaceholder = $modx->getOption(''toPlaceholder'', $scriptProperties, false);\r\n\r\n$wrapper_chunk = $modx->getOption(''tplWrapper'', $scriptProperties, ''basicNav.wrapper'');\r\n$prev_link_chunk = $modx->getOption(''prevLink'', $scriptProperties, ''basicNav.prevLink'');\r\n$next_link_chunk = $modx->getOption(''nextLink'', $scriptProperties, ''basicNav.nextLink'');\r\n$sortDir = $modx->getOption(''sortDir'', $scriptProperties, ''DESC'');\r\n\r\n$siteUrl = $modx->getOption(''site_url'');\r\n\r\n$cur = $modx->resource->id;\r\n$parent = $modx->resource->parent;\r\nif (empty($parent)) {\r\n    return;\r\n}\r\n\r\n$criteria = $modx->newQuery(''modResource'', array(\r\n    ''parent'' => $parent,\r\n    ''deleted'' => false,\r\n    ''published'' => true,\r\n    ''isfolder'' => false\r\n));\r\n$criteria->select(array(''id'', ''pagetitle'', ''uri''));\r\n$criteria->sortby(''publishedon'', $sortDir);\r\n\r\n$children = array();\r\nif ($criteria->prepare() && $criteria->stmt->execute()) {\r\n    $children = $criteria->stmt->fetchAll(PDO::FETCH_ASSOC);\r\n}\r\n\r\n$prev = NULL;\r\n$next = NULL;\r\n\r\n$seen = FALSE;\r\n$now = FALSE;\r\nforeach ($children as $child) {\r\n    $now = ($child[''id''] == $cur);\r\n    if ($now) {\r\n        $seen = TRUE;\r\n    }\r\n\r\n    if (!$seen) {\r\n        $prev = $child;\r\n    }\r\n    if ($seen && empty($next) && !$now) {\r\n        $next = $child;\r\n    }\r\n}\r\n\r\n$prev_link = empty($prev) ? '''' : $modx->parseChunk($prev_link_chunk, array(\r\n    ''href'' => $siteUrl . $prev[''uri''],\r\n    ''title'' => $prev[''pagetitle'']\r\n));\r\n$next_link = empty($next) ? '''' : $modx->parseChunk($next_link_chunk, array(\r\n    ''href'' => $siteUrl . $next[''uri''],\r\n    ''title'' => $next[''pagetitle'']\r\n));\r\n$result = $modx->parseChunk($wrapper_chunk, array(\r\n    ''prev-link'' => $prev_link,\r\n    ''next-link'' => $next_link,\r\n));\r\n\r\nif ($toPlaceholder) {\r\n    $modx->setPlaceholder($toPlaceholder, $result);\r\n    return;\r\n} else {\r\n    return $result;\r\n}', 0, 'a:0:{}', '', 0, ''),
(135, 2, 0, 'domain', '', 0, 5, 0, 'return preg_replace(''/^www./'', '''', $_SERVER[''SERVER_NAME'']);', 0, 'a:0:{}', '', 0, ''),
(149, 1, 0, 'fSort', '', 0, 50, 0, '\nreturn require ''core/components/ffilter/fsort.snippet.php'';', 0, NULL, '', 0, ''),
(150, 1, 0, 'getCount', '', 0, 50, 0, '\n$count = $modx->getCount(''modResource'', array(\n    ''parent'' => $parent,\n    ''template'' => $template,\n    ''published'' => ''1'',\n    ''deleted'' => ''0''\n));\n$modx->setPlaceholders(array($toPlaceholder => $count));', 0, NULL, '', 0, ''),
(139, 1, 1, 'getProducts', '', 0, 49, 0, '/**\n * getProducts 1.4rc2\n *\n * Snippet for a print list of resources and objects from any tables. For MODX 2.x.\n *\n * @author Andchir <andchir@gmail.com>\n * @copyright Copyright 2015 http://modx-shopkeeper.ru/\n/\n\n/*\n\ngetProducts + getPage:\n\n[[!getPage?\n&elementClass=`modSnippet`\n&element=`getProducts`\n&parents=`10`\n&limit=`20`\n&tvFilters=`{"param":"value"}`\n&where=`{"param":"value"}`\n&includeTVs=`1`\n&includeTVList=`price,image,width,inventory`\n&tpl=`product`\n&pageFirstTpl=`<li class="control"><a [[+classes]] href="[[+href]]">Первая</a></li>`\n&pageLastTpl=`<li class="control"><a [[+classes]] href="[[+href]]">Последняя</a></li>`\n]]\n<br class="clear" />\n<ul class="pages">\n[[!+page.nav]]\n</ul>\n[[+total]]\n\n*/\n\nif( !empty( $scriptProperties[''debug''] ) ){\n    ini_set(''display_errors'',1);\n    error_reporting(E_ALL);\n}\n\n$cached = array();\n\n//Настройки кэширования\nif(!empty($scriptProperties[''gp_cache''])){\n    \n    if(empty($scriptProperties[''cache_key''])) $scriptProperties[''cache_key''] = $modx->getOption(''cache_resource_key'', null, ''resource'');\n    if(empty($scriptProperties[''cache_checkURL''])) $scriptProperties[''cache_checkURL''] = false;//Не рекомендуется менять значение\n    if(empty($scriptProperties[''cacheId''])) $scriptProperties[''cacheId''] = ''gpCache'';\n    if(empty($scriptProperties[''cache_handler''])) $scriptProperties[''cache_handler''] = $modx->getOption(''cache_resource_handler'', null, ''xPDOFileCache'');\n    if(empty($scriptProperties[''cache_expires''])) $scriptProperties[''cache_expires''] = 0;\n    \n    if($scriptProperties[''cache_checkURL'']){\n        $scriptProperties[''cachePageKey''] = $modx->resource->getCacheKey() . ''/'' . $scriptProperties[''cacheId''] . md5(http_build_query($modx->request->getParameters()));\n    }else{\n        $scriptProperties[''cachePageKey''] = $scriptProperties[''cacheId''];\n    }\n    $scriptProperties[''cacheOptions''] = array(\n        xPDO::OPT_CACHE_KEY => $scriptProperties[''cache_key''],\n        xPDO::OPT_CACHE_HANDLER => $scriptProperties[''cache_handler''],\n        xPDO::OPT_CACHE_EXPIRES => $scriptProperties[''cache_expires''],\n    );\n    \n    $cached = $modx->cacheManager->get($scriptProperties[''cachePageKey''], $scriptProperties[''cacheOptions'']);\n    \n    //Если есть в кэше, выводим его содержимое\n    if(!empty($cached) && isset($cached[''placeholders'']) && isset($cached[''output''])){\n        \n        $output = $cached[''output''];\n        $modx->setPlaceholders($cached[''placeholders'']);\n        \n        if($toPlaceholder){\n            $modx->setPlaceholder($toPlaceholder,$output);\n            $output = '''';\n        }\n        \n        return $output;\n        \n    }else{\n        \n        $cached = array();\n        \n    }\n    \n}\n\n$output = '''';\n\n$checkPlaceholders = $modx->placeholders;\n\nrequire_once MODX_CORE_PATH.''components/getproducts/model/getproducts.class.php'';\n$getProducts = new getProducts($modx,$scriptProperties);\n\n$noResults = $modx->getOption(''noResults'',$scriptProperties,'''');\n$toPlaceholder = $modx->getOption(''toPlaceholder'',$scriptProperties,'''');\n$returnIDs = $modx->getOption(''returnIDs'',$scriptProperties,false);\n$totalVar = $modx->getOption(''totalVar'', $scriptProperties, ''total'');\n$debug = $modx->getOption(''debug'', $scriptProperties, false);\n\n$parents_data = array();\n\n//Ищем товары по заданным условиям\n$getProducts->searchProducts();\n\n$total = $getProducts->getTotal();\n$modx->setPlaceholder( $totalVar, $total );\nif( !$total ) return $noResults;\nif( $returnIDs ) return implode( '','', $getProducts->ids_arr );\n\n//Собираем TV\n$getProducts->appendTVs();\n\n//Вытаскиваем данные от родителей, если нужно\n$getProducts->appendFromParents();\n\n//Создаём HTML код по шаблону\n$output .= $getProducts->getHTMLOutput();\n\n//Кэшируем\nif(!empty($scriptProperties[''gp_cache''])){\n    \n    $cached = array(\n        ''output'' => $output,\n        ''placeholders'' => array_diff_assoc($modx->placeholders, $checkPlaceholders)\n    );\n    unset($checkPlaceholders);\n    \n    $modx->cacheManager->set($scriptProperties[''cachePageKey''], $cached, $scriptProperties[''cache_expires''], $scriptProperties[''cacheOptions'']);\n    \n}\n\nif($toPlaceholder){\n    $modx->setPlaceholder($toPlaceholder,$output);\n    $output = '''';\n}\n\nreturn $output;', 0, 'a:28:{s:11:"activeClass";a:7:{s:4:"name";s:11:"activeClass";s:4:"desc";s:65:"Имя CSS-класса для активного ресурса.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:19:"activeParentSnippet";a:7:{s:4:"name";s:19:"activeParentSnippet";s:4:"desc";s:0:"";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:76:"Сниппет для активного контейнера-ресурса";s:7:"lexicon";N;s:4:"area";s:0:"";}s:15:"addSubItemCount";a:7:{s:4:"name";s:15:"addSubItemCount";s:4:"desc";s:147:"В чанке сниппета будет доступен плейсхолдер [[+subitemcount]] - число дочерних ресурсов.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"className";a:7:{s:4:"name";s:9:"className";s:4:"desc";s:76:"Имя класса (объекта) элементов таблицы БД.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:11:"modResource";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"debug";a:7:{s:4:"name";s:5:"debug";s:4:"desc";s:151:"Режим отладки (1|0). В журнал ошибок будут писаться SQL запросы, полученные в сниппете.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"depth";a:7:{s:4:"name";s:5:"depth";s:4:"desc";s:74:"Глубина поиска родителей. По умолчанию 1.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:14:"fromParentList";a:7:{s:4:"name";s:14:"fromParentList";s:4:"desc";s:133:"список полей через запятую, которые нужно добавить товарам от родителей.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:14:"includeContent";a:7:{s:4:"name";s:14:"includeContent";s:4:"desc";s:87:"Включать в выборку из БД значение поля "content" (1|0).";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"includeTVList";a:7:{s:4:"name";s:13:"includeTVList";s:4:"desc";s:95:"Список имён TV, которые нужно добавить через запятую.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"includeTVs";a:7:{s:4:"name";s:10:"includeTVs";s:4:"desc";s:125:"Добавить плейсхолдеры значений TV для ресурсов (1|0). Префикс для TV: "tv.".";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"noResults";a:7:{s:4:"name";s:9:"noResults";s:4:"desc";s:122:"Текст, который будет выводиться, если по запросу ничего не найдено.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:7:"orderby";a:7:{s:4:"name";s:7:"orderby";s:4:"desc";s:39:"JSON строка сортировки.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:11:"packageName";a:7:{s:4:"name";s:11:"packageName";s:4:"desc";s:59:"Имя пакета элементов таблицы БД.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"processTVList";a:7:{s:4:"name";s:13:"processTVList";s:4:"desc";s:95:"Список TV через запятую, для которых применять processTVs.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:10:"processTVs";a:7:{s:4:"name";s:10:"processTVs";s:4:"desc";s:78:"Применять параметр "Параметры ввода" для TV.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"resources";a:7:{s:4:"name";s:9:"resources";s:4:"desc";s:76:"Список ID ресурсов (товаров) через запятую.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"returnIDs";a:7:{s:4:"name";s:9:"returnIDs";s:4:"desc";s:62:"Возвращать только ID рессурсов (1|0).";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:6:"sortby";a:7:{s:4:"name";s:6:"sortby";s:4:"desc";s:89:"Поле для сортировки (только поля ресурсов, без TV).";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:9:"menuindex";s:7:"lexicon";N;s:4:"area";s:0:"";}s:8:"sortbyTV";a:7:{s:4:"name";s:8:"sortbyTV";s:4:"desc";s:55:"Сортировка по TV. Указать имя TV.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:12:"sortbyTVType";a:7:{s:4:"name";s:12:"sortbyTVType";s:4:"desc";s:44:"Тип значения TV (string|integer).";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:6:"string";s:7:"lexicon";N;s:4:"area";s:0:"";}s:7:"sortdir";a:7:{s:4:"name";s:7:"sortdir";s:4:"desc";s:44:"Направление сортировки.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:3:"ASC";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"sortdirTV";a:7:{s:4:"name";s:9:"sortdirTV";s:4:"desc";s:63:"Направление сортировки по TV (ASC|DESC).";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:3:"ASC";s:7:"lexicon";N;s:4:"area";s:0:"";}s:13:"toPlaceholder";a:7:{s:4:"name";s:13:"toPlaceholder";s:4:"desc";s:185:"Имя плейсхолдера, в который нужно отправить результат работы сниппета. По умолчанию не используется.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:8:"totalVar";a:7:{s:4:"name";s:8:"totalVar";s:4:"desc";s:86:"Имя плейсхолдера с общим количеством ресурсов.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:5:"total";s:7:"lexicon";N;s:4:"area";s:0:"";}s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:68:"Имя чанка шаблона для вывода ресурса.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"tvFilters";a:7:{s:4:"name";s:9:"tvFilters";s:4:"desc";s:49:"JSON строка фильтрации по ТВ.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}s:9:"useSmarty";a:7:{s:4:"name";s:9:"useSmarty";s:4:"desc";s:77:"Использовать в чанке шаблонизатор Smarty (1|0).";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:1:"0";s:7:"lexicon";N;s:4:"area";s:0:"";}s:5:"where";a:7:{s:4:"name";s:5:"where";s:4:"desc";s:68:"JSON строка для условия WHERE в SQL запросе.";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";N;s:4:"area";s:0:"";}}', '', 1, 'core/components/getproducts/snippet.getproducts.php'),
(147, 1, 0, 'fField', '', 0, 50, 0, '\nreturn require ''core/components/ffilter/ffield.snippet.php'';', 0, NULL, '', 0, ''),
(148, 1, 0, 'fProducts', '', 0, 50, 0, '\nreturn require ''core/components/ffilter/fproducts.snippet.php'';', 0, NULL, '', 0, ''),
(151, 1, 0, 'shk_render_tv', 'Render parameters for products as checkbox, radio, select.', 0, 22, 0, '/*\n\nshk_render_tv\n\n[[*param1:shk_render_tv=`shk_select`]]\n\n[[*param1:shk_render_tv=`shk_checkbox`]]\n\n[[*param1:shk_render_tv=`shk_radio`]]\n\n[[shk_render_tv?input=`[[+tv.param1]]`&options=`shk_select`&resourceId=`[[+id]]`]]\n\n*/\n\n$input = $modx->getOption(''input'',$scriptProperties,'''');\n$options = $modx->getOption(''options'',$scriptProperties,''shk_select'');\n$resourceId = $modx->getOption(''resourceId'',$scriptProperties,$modx->resource->id);\n$tv_name = $modx->getOption(''name'',$scriptProperties,''tv'');\n$wraptag = $modx->getOption(''wraptag'',$scriptProperties,''div'');\n$first_selected = $modx->getOption(''first_selected'',$scriptProperties,true);\n\n$output = '''';\n\nif($input){\n    \n    $tv = $modx->newObject(''modTemplateVar'');\n    $tv->set(''name'', $tv_name);\n    $tv->set(''display'', $options);\n    $tv->set(''value'', $input);\n    \n    $params = array(\n        ''id'' => $resourceId,\n        ''param_name'' => $tv_name,\n        ''wraptag'' => $wraptag,\n        ''first_selected'' => $first_selected,\n        ''function'' => ''SHK.additOpt(this)''\n    );\n    $outputRenderPaths = $tv->getRenderDirectories(''OnTVOutputRenderList'',''output'');\n    \n    $value = $tv->prepareOutput($input);\n    $output = $tv->getRender($params, $value, $outputRenderPaths, ''output'', $resourceId, $options);\n    \n}\n\nreturn $output;', 0, NULL, '', 0, ''),
(152, 2, 0, 'smarty', '', 0, 5, 0, '/*\nSmartyParser v. 1.0 (19.09.2016)\nIgor Siluyanov\n\nСниппет выполняет парсинг заданного чанка с помощью шаблонизатора smarty.\nПараметры:\n    tpl - имя чанка\nТакже можно передать любое количество других параметров - все они будут доступны в чанке как переменные smarty.\n*/\n\n$modx->getService(''smarty'', ''smarty.modSmarty'');\n\n// список параметров данного сниппета\n$snippet_params = array(''tpl''); \n// параметры, которые мы передадим в чанк\n$chunk_params = array_diff_key($scriptProperties, array_flip($snippet_params)); \n\n// получаем содержимое чанка\n$chunk_str = $modx->getChunk($tpl);\n\n$modx->smarty->assign(''modx'', $modx);\n\n// передаём параметры в чанк\nforeach ($chunk_params as $key => $val) {\n    $modx->smarty->assign($key, $val);\n}\n\nreturn $modx->smarty->display(''string:'' . $chunk_str);', 0, 'a:0:{}', '', 0, ''),
(153, 2, 0, 'botaway', '', 0, 5, 0, 'if (!empty($options)) { \n    parse_str($options); \n} \n$eml = empty($email) ? $input : $email; \n$debug = !empty($debug); \n$aslink = !(isset($aslink) && $aslink == 0); \n\nif (filter_var($eml, FILTER_VALIDATE_EMAIL) === false) { \n    return $debug ? ''incorrect email address'' : $eml; \n} \nif (!function_exists(''str2hex'')) { \n    function str2hex($string) \n    { \n        $hex = ""; \n        for ($i = 0; $i < strlen($string); $i++) { \n            $hex .= (strlen(dechex(ord($string[$i]))) < 2) ? "%0" . dechex(ord($string[$i])) : ''%'' . dechex(ord($string[$i])); \n        } \n        return $hex; \n    } \n} \n\n$enc_email = $aslink ? str2hex(''<a href="mailto:'' . $eml . ''" rel="nofollow">'' . $eml . ''</a>'') : str2hex($eml); \n$output = '' \n    <noindex> \n        <script type="text/javascript" language="javascript"> \n            document.write(unescape(\\'''' . $enc_email . ''\\'')); \n        </script> \n    </noindex>\n''; \nunset($input, $eml, $enc_email); \nreturn $output;', 0, 'a:0:{}', '', 0, '');
INSERT INTO `modx_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(154, 1, 0, 'pdoArchive', '', 0, 7, 0, '$modx->lexicon->load(''pdotools:pdoarchive'');\n\n/** @var array $scriptProperties */\n$tplWrapper = $modx->getOption(''tplWrapper'', $scriptProperties);\n$tplYear = $modx->getOption(''tplYear'', $scriptProperties);\n$tplMonth = $modx->getOption(''tplMonth'', $scriptProperties);\n$tplDay = $modx->getOption(''tplDay'', $scriptProperties);\n$tpl = $modx->getOption(''tpl'', $scriptProperties);\n$dateField = $modx->getOption(''dateField'', $scriptProperties, ''createdon'', true);\n$dateFormat = $modx->getOption(''dateFormat'', $scriptProperties, ''H:i'', true);\n$outputSeparator = $modx->getOption(''outputSeparator'', $scriptProperties, "\\n");\n\n// Adding extra parameters into special place so we can put them in a results\n/** @var modSnippet $snippet */\n$additionalPlaceholders = $properties = array();\nif (isset($this) && $this instanceof modSnippet) {\n    $properties = $this->get(''properties'');\n} elseif ($snippet = $modx->getObject(''modSnippet'', array(''name'' => ''pdoResources''))) {\n    $properties = $snippet->get(''properties'');\n}\nif (!empty($properties)) {\n    foreach ($scriptProperties as $k => $v) {\n        if (!isset($properties[$k])) {\n            $additionalPlaceholders[$k] = $v;\n        }\n    }\n}\n$scriptProperties[''additionalPlaceholders''] = $additionalPlaceholders;\nif (isset($parents) && $parents === '''') {\n    $scriptProperties[''parents''] = $modx->resource->id;\n}\n$scriptProperties[''return''] = ''data'';\n/** @var pdoFetch $pdoFetch */\n$fqn = $modx->getOption(''pdoFetch.class'', null, ''pdotools.pdofetch'', true);\n$path = $modx->getOption(''pdofetch_class_path'', null, MODX_CORE_PATH . ''components/pdotools/model/'', true);\nif ($pdoClass = $modx->loadClass($fqn, $path, false, true)) {\n    $pdoFetch = new $pdoClass($modx, $scriptProperties);\n} else {\n    return false;\n}\n$pdoFetch->addTime(''pdoTools loaded'');\n$rows = $pdoFetch->run();\n\n// Process rows\n$tree = array();\nforeach ($rows as $row) {\n    $year = date(''Y'', $row[$dateField]);\n    $month = date(''m'', $row[$dateField]);\n    $day = date(''d'', $row[$dateField]);\n    $tree[$year][$month][$day][] = $row;\n}\n\n$output = '''';\nforeach ($tree as $year => $months) {\n    $rows_year = '''';\n    $count_year = 0;\n\n    foreach ($months as $month => $days) {\n        $rows_month = '''';\n        $count_month = 0;\n\n        foreach ($days as $day => $resources) {\n            $rows_day = array();\n            $count_day = 0;\n            $idx = 1;\n\n            foreach ($resources as $resource) {\n                $resource[''day''] = $day;\n                $resource[''month''] = $month;\n                $resource[''year''] = $year;\n                $resource[''date''] = strftime($dateFormat, $resource[$dateField]);\n                $resource[''idx''] = $idx++;\n                $resource[''menutitle''] = !empty($resource[''menutitle''])\n                    ? $resource[''menutitle'']\n                    : $resource[''pagetitle''];\n                // Add placeholder [[+link]] if specified\n                if (!empty($scriptProperties[''useWeblinkUrl''])) {\n                    if (!isset($resource[''context_key''])) {\n                        $resource[''context_key''] = '''';\n                    }\n                    if (isset($resource[''class_key'']) && ($resource[''class_key''] == ''modWebLink'')) {\n                        $resource[''link''] = isset($resource[''content'']) && is_numeric(trim($resource[''content''], ''[]~ ''))\n                            ? $pdoFetch->makeUrl(intval(trim($resource[''content''], ''[]~ '')), $resource)\n                            : (isset($resource[''content'']) ? $resource[''content''] : '''');\n                    } else {\n                        $resource[''link''] = $pdoFetch->makeUrl($resource[''id''], $resource);\n                    }\n                } else {\n                    $resource[''link''] = '''';\n                }\n                $tpl = $pdoFetch->defineChunk($resource);\n                $rows_day[] = $pdoFetch->getChunk($tpl, $resource);\n                $count_year++;\n                $count_month++;\n                $count_day++;\n            }\n\n            $rows_month .= !empty($tplDay)\n                ? $pdoFetch->getChunk($tplDay, array(\n                    ''day'' => $day,\n                    ''month'' => $month,\n                    ''year'' => $year,\n                    ''count'' => $count_day,\n                    ''wrapper'' => implode($outputSeparator, $rows_day),\n                ), $pdoFetch->config[''fastMode''])\n                : implode($outputSeparator, $rows_day);\n        }\n\n        $rows_year .= !empty($tplMonth)\n            ? $pdoFetch->getChunk($tplMonth, array(\n                ''month'' => $month,\n                ''month_name'' => $modx->lexicon(''pdoarchive_month_'' . $month),\n                ''year'' => $year,\n                ''count'' => $count_month,\n                ''wrapper'' => $rows_month,\n            ), $pdoFetch->config[''fastMode''])\n            : $rows_month;\n    }\n\n    $output .= !empty($tplYear)\n        ? $pdoFetch->getChunk($tplYear, array(\n            ''year'' => $year,\n            ''count'' => $count_year,\n            ''wrapper'' => $rows_year,\n        ), $pdoFetch->config[''fastMode''])\n        : $rows_year;\n}\n$pdoFetch->addTime(''Rows processed'');\n\n// Return output\nif (!empty($tplWrapper) && (!empty($wrapIfEmpty) || !empty($output))) {\n    $output = $pdoFetch->getChunk(\n        $tplWrapper,\n        array_merge($additionalPlaceholders, array(''output'' => $output)),\n        $pdoFetch->config[''fastMode'']\n    );\n    $pdoFetch->addTime(''Rows wrapped'');\n}\n\nif ($modx->user->hasSessionContext(''mgr'') && !empty($showLog)) {\n    $output .= ''<pre class="pdoArchiveLog">'' . print_r($pdoFetch->getTime(), 1) . ''</pre>'';\n}\n\nif (!empty($toPlaceholder)) {\n    $modx->setPlaceholder($toPlaceholder, $output);\n} else {\n    return $output;\n}', 0, 'a:36:{s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:17:"pdotools_prop_tpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:65:"@INLINE <li>[[+date]] <a href="[[+link]]">[[+menutitle]]</a></li>";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:7:"tplYear";a:7:{s:4:"name";s:7:"tplYear";s:4:"desc";s:21:"pdotools_prop_tplYear";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:71:"@INLINE <h3>[[+year]] <sup>([[+count]])</sup></h3><ul>[[+wrapper]]</ul>";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:8:"tplMonth";a:7:{s:4:"name";s:8:"tplMonth";s:4:"desc";s:22:"pdotools_prop_tplMonth";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:86:"@INLINE <li><h4>[[+month_name]] <sup>([[+count]])</sup></h4><ul>[[+wrapper]]</ul></li>";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:6:"tplDay";a:7:{s:4:"name";s:6:"tplDay";s:4:"desc";s:20:"pdotools_prop_tplDay";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:79:"@INLINE <li><h5>[[+day]] <sup>([[+count]])</sup></h5><ul>[[+wrapper]]</ul></li>";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:10:"tplWrapper";a:7:{s:4:"name";s:10:"tplWrapper";s:4:"desc";s:24:"pdotools_prop_tplWrapper";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:11:"wrapIfEmpty";a:7:{s:4:"name";s:11:"wrapIfEmpty";s:4:"desc";s:25:"pdotools_prop_wrapIfEmpty";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:9:"dateField";a:7:{s:4:"name";s:9:"dateField";s:4:"desc";s:23:"pdotools_prop_dateField";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:9:"createdon";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:10:"dateFormat";a:7:{s:4:"name";s:10:"dateFormat";s:4:"desc";s:24:"pdotools_prop_dateFormat";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}