ame";s:6:"scheme";s:4:"desc";s:20:"pdotools_prop_scheme";s:4:"type";s:4:"list";s:7:"options";a:6:{i:0;a:2:{s:5:"value";s:0:"";s:4:"text";s:14:"System default";}i:1;a:2:{s:5:"value";i:-1;s:4:"text";s:25:"-1 (relative to site_url)";}i:2;a:2:{s:5:"value";s:4:"full";s:4:"text";s:40:"full (absolute, prepended with site_url)";}i:3;a:2:{s:5:"value";s:3:"abs";s:4:"text";s:39:"abs (absolute, prepended with base_url)";}i:4;a:2:{s:5:"value";s:4:"http";s:4:"text";s:38:"http (absolute, forced to http scheme)";}i:5;a:2:{s:5:"value";s:5:"https";s:4:"text";s:40:"https (absolute, forced to https scheme)";}}s:5:"value";s:0:"";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:13:"useWeblinkUrl";a:7:{s:4:"name";s:13:"useWeblinkUrl";s:4:"desc";s:27:"pdotools_prop_useWeblinkUrl";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:1;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}}', '', 0, 'core/components/pdotools/elements/snippets/snippet.pdoarchive.php'),
(155, 0, 0, 'FormItLoadSavedForm', 'Prehook to load previously saved form.', 0, 2, 0, '/**\r\n * FormIt\r\n *\r\n * Copyright 2011-12 by SCHERP Ontwikkeling <info@scherpontwikkeling.nl>\r\n * Copyright 2015 by Wieger Sloot <modx@sterc.nl>\r\n * Copyright 2016 by YJ Tso <yj@modx.com>\r\n *\r\n * FormIt is free software; you can redistribute it and/or modify it\r\n * under the terms of the GNU General Public License as published by the Free\r\n * Software Foundation; either version 2 of the License, or (at your option) any\r\n * later version.\r\n *\r\n * FormIt is distributed in the hope that it will be useful, but WITHOUT ANY\r\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\r\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public License along with\r\n * FormIt; if not, write to the Free Software Foundation, Inc., 59 Temple Place,\r\n * Suite 330, Boston, MA 02111-1307 USA\r\n *\r\n * @package formit\r\n */\r\n/**\r\n * A custom FormIt prehook for fetching saved form data. - Based on FormItSaveForm\r\n *\r\n * @var modX $modx\r\n * @var array $scriptProperties\r\n * @var FormIt $formit\r\n * @var fiHooks $hook\r\n * \r\n * @package formit\r\n */\r\n/* setup default properties */\r\n// If prehook fails do we continue?\r\n$return = $modx->getOption(''returnValueOnFail'', $formit->config, true);\r\n$formEncrypt = $modx->getOption(''formEncrypt'', $formit->config, false);\r\n$formFields = $modx->getOption(''formFields'', $formit->config, false);\r\n$fieldNames = $modx->getOption(''fieldNames'', $formit->config, false);\r\n$updateSavedForm = $modx->getOption(''updateSavedForm'', $formit->config, false); // true, false, ''1'', ''0'', or ''values''\r\n// If FormIt config says don''t update, don''t do it\r\nif (!$updateSavedForm) return $return;\r\n// In order to load form values, the user must provide the hash key somehow\r\n// Usually with a $_GET parameter, but a property in $formit->config will override.\r\n$formHashKeyField = $modx->getOption(''savedFormHashKeyField'', $formit->config, ''savedFormHashKey'');\r\n$formHashKey = '''';\r\nif (isset($_GET[$formHashKeyField])) $formHashKey = (string) $_GET[$formHashKeyField];\r\nif ($hook->getValue($formHashKeyField)) $formHashKey = (string) $hook->getValue($formHashKeyField);\r\nif (isset($formit->config[$formHashKeyField])) $formHashKey = $formit->config[$formHashKeyField];\r\n// our hashing methods return 32 chars. if no valid hash key we''re done here.\r\nif (strlen($formHashKey) !== 32) return $return;\r\n\r\n// Try to fetch the saved form\r\n$savedForm = $modx->getObject(''FormItForm'', array(''hash'' => $formHashKey));\r\nif (!$savedForm) return $return;\r\n\r\nif ($formFields) {\r\n    $formFields = explode('','', $formFields);\r\n    foreach($formFields as $k => $v) {\r\n        $formFields[$k] = trim($v);\r\n    }\r\n}\r\n\r\n// Initialize the data array\r\n// Handle encryption\r\nif ($formEncrypt) {\r\n    $data = $savedForm->decrypt();\r\n} else {\r\n    $data = $savedForm->get(''values'');\r\n}\r\nif (is_string($data)) $data = $modx->fromJSON($data);\r\nif (!is_array($data)) return $return;\r\n\r\n//Change the fieldnames\r\nif ($fieldNames) {\r\n    $newDataArray = array();\r\n    $fieldLabels = array();\r\n    $formFieldNames = explode('','', $fieldNames);\r\n    foreach($formFieldNames as $formFieldName){\r\n        list($name, $label) = explode(''=='', $formFieldName);\r\n        // reverse order from FormItSaveForm snippet\r\n        $fieldLabels[trim($label)] = trim($name);\r\n    }\r\n    foreach ($data as $key => $value) {\r\n        if ($fieldLabels[$key]) {\r\n            $newDataArray[$fieldLabels[$key]] = $value;\r\n        }else{\r\n            $newDataArray[$key] = $value;\r\n        }\r\n    }\r\n    $data = $newDataArray;\r\n}\r\n\r\n// Always pass back in the provided hash key\r\n$data[$formHashKeyField] = $formHashKey;\r\n$hook->setValues($data);\r\nreturn true;', 0, 'a:0:{}', '', 0, ''),
(156, 2, 0, 'saveOrderId', '', 0, 0, 0, '$st = $modx->prepare(''INSERT INTO cleaning_calc(info) VALUES(:d)'');\n$st->execute(array(''d'' => date(''Y.m.d_H-i-s'')));\n$modx->setPlaceholders(array(\n    ''order-id'' => $modx->lastInsertId()\n));\n\nif (!isset($_POST[''hoover''])) {\n    $modx->setPlaceholders(array(''hoover'' => ''0''));\n}\n\nreturn true;', 0, 'a:0:{}', '', 0, ''),
(157, 2, 0, 'getCleaningPriceList', '', 0, 0, 0, 'function getCleaningPrice($res_id) {\n    global $modx;\n    // byArea\n    $st = $modx->prepare(''\n        SELECT value\n        FROM modx_site_tmplvar_contentvalues\n        WHERE tmplvarid = 59 AND contentid = :id\n    '');\n    $st->execute(array(''id'' => $res_id));\n    $row = $st->fetch();\n    $byArea_raw_arr = json_decode($row[''value''], true);\n    $byArea_arr = array();\n    foreach ($byArea_raw_arr as $item) {\n        $byArea_arr[] = array(\n            ''area'' => (int)$item[''area''],\n            ''price'' => (int)$item[''price''],\n        );\n    }\n    \n    // oneQM\n    $st = $modx->prepare(''\n        SELECT value\n        FROM modx_site_tmplvar_contentvalues\n        WHERE tmplvarid = 60 AND contentid = :id\n    '');\n    $st->execute(array(''id'' => $res_id));\n    $row = $st->fetch();\n    $price_oneQM = $row[''value''];\n    \n    return array(\n        ''byArea'' => $byArea_arr,\n        ''oneQM'' => $price_oneQM,\n    );\n}\n\n// получаем стоимость доп. услуг\n$st = $modx->prepare(''\n    SELECT value\n    FROM modx_site_tmplvar_contentvalues\n    WHERE tmplvarid = 58 AND contentid = 80\n'');\n$st->execute();\n$row = $st->fetch();\n$extra_services_raw_arr = json_decode($row[''value''], true);\n$extra_services = array();\nforeach ($extra_services_raw_arr as $item) {\n    $extra_services[$item[''text_id'']] = (int)$item[''price''];\n}\n\n$out_arr = array(\n    ''cleaning'' => array(\n        ''flat'' => array(\n            ''supporting'' => getCleaningPrice(71),\n            ''general'' => getCleaningPrice(70),\n            ''afterBuilding'' => getCleaningPrice(69),\n        ),\n        ''cottage'' => array(\n            ''supporting'' => getCleaningPrice(74),\n            ''general'' => getCleaningPrice(73),\n            ''afterBuilding'' => getCleaningPrice(72),\n        ),\n    ),\n    ''extraServices'' => $extra_services,\n);\n\nreturn json_encode($out_arr);', 0, 'a:0:{}', '', 0, ''),
(158, 2, 0, 'ifNo', '', 0, 5, 0, '/*\nпод этим корявым названием следующая суть\nесли один из айдишников равен первому то выводим else, иначе then\n\n*/\n\n$oneTrue = true;\n\nforeach ($scriptProperties as $key => $item) {\n    if (preg_match(''/id\\d+/'', $key)) {\n        if ($item == $id) {\n            $oneTrue = false;\n            break;\n        };\n    }\n}\n\nif ($oneTrue) {\n    //return $then;\n    $modx->setPlaceholders(array($toPlaceholder => $then));\n\n} elseif (isset($else)) {\n    //return $else;\n    $modx->setPlaceholders(array($toPlaceholder => $else));\n}', 0, 'a:0:{}', '', 0, ''),
(159, 0, 0, 'Gallery', '', 0, 54, 0, '/**\n * Gallery\n *\n * Copyright 2010-2012 by Shaun McCormick <shaun@modx.com>\n *\n * Gallery is free software; you can redistribute it and/or modify it under the\n * terms of the GNU General Public License as published by the Free Software\n * Foundation; either version 2 of the License, or (at your option) any later\n * version.\n *\n * Gallery is distributed in the hope that it will be useful, but WITHOUT ANY\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License along with\n * Gallery; if not, write to the Free Software Foundation, Inc., 59 Temple\n * Place, Suite 330, Boston, MA 02111-1307 USA\n *\n * @package gallery\n */\n/**\n * The main Gallery snippet.\n *\n * @var modX $modx\n * @var Gallery $gallery\n * \n * @package gallery\n */\n$gallery = $modx->getService(''gallery'',''Gallery'',$modx->getOption(''gallery.core_path'',null,$modx->getOption(''core_path'').''components/gallery/'').''model/gallery/'',$scriptProperties);\nif (!($gallery instanceof Gallery)) return '''';\n$modx->lexicon->load(''gallery:web'');\n\n/* check for REQUEST vars if property set */\n$imageGetParam = $modx->getOption(''imageGetParam'',$scriptProperties,''galItem'');\n$albumRequestVar = $modx->getOption(''albumRequestVar'',$scriptProperties,''galAlbum'');\n$tagRequestVar = $modx->getOption(''tagRequestVar'',$scriptProperties,''galTag'');\nif ($modx->getOption(''checkForRequestAlbumVar'',$scriptProperties,true)) {\n    if (!empty($_REQUEST[$albumRequestVar])) $scriptProperties[''album''] = $_REQUEST[$albumRequestVar];\n}\nif ($modx->getOption(''checkForRequestTagVar'',$scriptProperties,true)) {\n    if (!empty($_REQUEST[$tagRequestVar])) $scriptProperties[''tag''] = $_REQUEST[$tagRequestVar];\n}\nif (empty($scriptProperties[''album'']) && empty($scriptProperties[''tag''])) return '''';\n\n$data = $modx->call(''galItem'',''getList'',array(&$modx,$scriptProperties));\n$totalVar = $modx->getOption(''totalVar'', $scriptProperties, ''total'');\n$modx->setPlaceholder($totalVar,$data[''total'']);\n\n/* load plugins */\n$plugin = $modx->getOption(''plugin'',$scriptProperties,'''');\nif (!empty($plugin)) {\n    $pluginPath = $modx->getOption(''pluginPath'',$scriptProperties,'''');\n    if (empty($pluginPath)) {\n        $pluginPath = $gallery->config[''modelPath''].''gallery/plugins/'';\n    }\n    /** @var GalleryPlugin $plugin */\n    if (($className = $modx->loadClass($plugin,$pluginPath,true,true))) {\n        $plugin = new $className($gallery,$scriptProperties);\n        $plugin->load();\n        $scriptProperties = $plugin->adjustSettings($scriptProperties);\n    } else {\n        return $modx->lexicon(''gallery.plugin_err_load'',array(''name'' => $plugin,''path'' => $pluginPath));\n    }\n} else {\n    if ($modx->getOption(''useCss'',$scriptProperties,true)) {\n        $modx->regClientCSS($gallery->config[''cssUrl''].''web.css'');\n    }\n}\n\n/* iterate */\n$imageProperties = $modx->getOption(''imageProperties'',$scriptProperties,'''');\n$imageProperties = !empty($imageProperties) ? $modx->fromJSON($imageProperties) : array();\n$imageProperties = array_merge(array(\n    ''w'' => (int)$modx->getOption(''imageWidth'',$scriptProperties,500),\n    ''h'' => (int)$modx->getOption(''imageHeight'',$scriptProperties,500),\n    ''zc'' => (boolean)$modx->getOption(''imageZoomCrop'',$scriptProperties,0),\n    ''far'' => (string)$modx->getOption(''imageFar'',$scriptProperties,false),\n    ''q'' => (int)$modx->getOption(''imageQuality'',$scriptProperties,90),\n),$imageProperties);\n\n$thumbProperties = $modx->getOption(''thumbProperties'',$scriptProperties,'''');\n$thumbProperties = !empty($thumbProperties) ? $modx->fromJSON($thumbProperties) : array();\n$thumbProperties = array_merge(array(\n    ''w'' => (int)$modx->getOption(''thumbWidth'',$scriptProperties,100),\n    ''h'' => (int)$modx->getOption(''thumbHeight'',$scriptProperties,100),\n    ''zc'' => (boolean)$modx->getOption(''thumbZoomCrop'',$scriptProperties,1),\n    ''far'' => (string)$modx->getOption(''thumbFar'',$scriptProperties,''C''),\n    ''q'' => (int)$modx->getOption(''thumbQuality'',$scriptProperties,90),\n),$thumbProperties);\n\n$idx = 0;\n$output = array();\n$filesUrl = $modx->call(''galAlbum'',''getFilesUrl'',array(&$modx));\n$filesPath = $modx->call(''galAlbum'',''getFilesPath'',array(&$modx));\n$itemCls = $modx->getOption(''itemCls'',$scriptProperties,''gal-item'');\n$imageAttributes = $modx->getOption(''imageAttributes'',$scriptProperties,'''');\n$linkAttributes = $modx->getOption(''linkAttributes'',$scriptProperties,'''');\n$linkToImage = $modx->getOption(''linkToImage'',$scriptProperties,false);\n$activeCls = $modx->getOption(''activeCls'',$scriptProperties,''gal-item-active'');\n$highlightItem = $modx->getOption($imageGetParam,$_REQUEST,false);\n$defaultThumbTpl = $modx->getOption(''thumbTpl'',$scriptProperties,''galItemThumb'');\n\n/** @var galItem $item */\n\nif (!is_array($data)) return '''';\n\n// prep for &thumbTpl_N\n$keys = array_keys($scriptProperties);\n$nthTpls = array();\nforeach($keys as $key) {\n    $keyBits = $gallery->explodeAndClean($key, ''_'');\n    if (isset($keyBits[0]) && $keyBits[0] === ''thumbTpl'') {\n        if ($i = (int) $keyBits[1]) $nthTpls[$i] = $scriptProperties[$key];\n    }\n}\nksort($nthTpls);\n\nforeach ($data[''items''] as $item) {\n    $itemArray = $item->toArray();\n    $itemArray[''idx''] = $idx;\n    $itemArray[''cls''] = $itemCls;\n    if ($itemArray[''id''] == $highlightItem) {\n        $itemArray[''cls''] .= '' ''.$activeCls;\n    }\n    $itemArray[''filename''] = basename($item->get(''filename''));\n    $itemArray[''image_absolute''] = $item->get(''base_url'').$filesUrl.$item->get(''filename'');\n    $itemArray[''fileurl''] = $itemArray[''image_absolute''];\n    $itemArray[''filepath''] = $filesPath.$item->get(''filename'');\n    $itemArray[''filesize''] = $item->get(''filesize'');\n    $itemArray[''thumbnail''] = $item->get(''thumbnail'',$thumbProperties);\n    $itemArray[''image''] = $item->get(''thumbnail'',$imageProperties);\n    $itemArray[''image_attributes''] = $imageAttributes;\n    $itemArray[''link_attributes''] = $linkAttributes;\n    if (!empty($scriptProperties[''album''])) $itemArray[''album''] = $scriptProperties[''album''];\n    if (!empty($scriptProperties[''tag''])) $itemArray[''tag''] = $scriptProperties[''tag''];\n    $itemArray[''linkToImage''] = $linkToImage;\n    $itemArray[''url''] = $item->get(''url'');\n    $itemArray[''imageGetParam''] = $imageGetParam;\n    $itemArray[''albumRequestVar''] = $albumRequestVar;\n    $itemArray[''tagRequestVar''] = $tagRequestVar;\n    $itemArray[''tag''] = '''';\n    if ($plugin) {\n        $plugin->renderItem($itemArray);\n    }\n\n    $thumbTpl = $defaultThumbTpl;\n    if (isset($nthTpls[$idx])) {\n        $thumbTpl = $nthTpls[$idx];\n    } else {\n        foreach ($nthTpls as $int => $tpl) {\n            if ( ($idx % $int) === 0 ) $thumbTpl = $tpl;\n        }\n    }\n\n    $output[] = $gallery->getChunk($thumbTpl,$itemArray);\n\n    $idx++;\n}\n$output = implode("\\n",$output);\n\n/* if set, place in a container tpl */\n$containerTpl = $modx->getOption(''containerTpl'',$scriptProperties,false);\nif (!empty($containerTpl)) {\n    $ct = $gallery->getChunk($containerTpl,array(\n        ''thumbnails'' => $output,\n        ''album_name'' => $data[''album''][''name''],\n        ''album_description'' => $data[''album''][''description''],\n        ''album_year'' => isset($data[''album''][''year'']) ? $data[''album''][''year''] : '''',\n        ''albumRequestVar'' => $albumRequestVar,\n        ''albumId'' => $data[''album''][''id''],\n    ));\n    if (!empty($ct)) $output = $ct;\n}\n\n/* set to placeholders or output directly */\n$toPlaceholder = $modx->getOption(''toPlaceholder'',$scriptProper