(162, 2, 0, 'himchistka', '', 0, 0, 0, 'if ($_SERVER[''REQUEST_URI''] == ''/himchistka-kovrolina-na-domu/'') $dir = ''./userfiles/him/himchistka-kovrolina-na-domu/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/himchistka-kovrov-na-domu/'') $dir = ''./userfiles/him/himchistka-kovrov-na-domu/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/himchistka-myagkoj-mebeli-na-domu/'') $dir = ''./userfiles/him/himchistka-myagkoj-mebeli-na-domu/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/himchistka-myagkoj-mebeli-na-domu/kozhanoj-mebeli/'') $dir = ''./userfiles/him/himchistka-myagkoj-mebeli-na-domu/kozhanoj-mebeli/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/himchistka-myagkoj-mebeli-na-domu/divana/'' || $_SERVER[''REQUEST_URI''] == ''/himchistka-myagkoj-mebeli-na-domu/ximchistka-divana-na-domu-otzyivyi/'') $dir = ''./userfiles/him/himchistka-myagkoj-mebeli-na-domu/divana/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/himchistka-myagkoj-mebeli-na-domu/matrasov/'') $dir = ''./userfiles/him/himchistka-myagkoj-mebeli-na-domu/matrasov/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/himchistka-myagkoj-mebeli-na-domu/kresel/'') $dir = ''./userfiles/him/himchistka-myagkoj-mebeli-na-domu/kresel/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/mojka-okon-vitrin/'') $dir = ''./userfiles/him/mojkavitrin/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/stirka-himchistka-kovrov-s-vyvozom/'') $dir = ''./userfiles/him/stirka-himchistka-kovrov-s-vyvozom/'';\nelse $dir = ''./userfiles/him/'';\n\n            $scan = scandir($dir);\n\n           for ($i=0; $i<count($scan); $i++) {\n\n             if ($scan[$i] != ''.'' && $scan[$i] != ''..'' && $scan[$i] != ''himchistka-kovrolina-na-domu'' && $scan[$i] != ''himchistka-kovrov-na-domu'' && $scan[$i] != ''himchistka-myagkoj-mebeli-na-domu'' && $scan[$i] != ''kozhanoj-mebeli'' && $scan[$i] != ''divana'' && $scan[$i] != ''matrasov'' && $scan[$i] != ''kresel'') {\n\n             echo ''\n\n<div class = "item" >\n<div class="ddo">До</div><div class="dpo">После</d