(163, 2, 0, 'uborka', '', 0, 0, 0, '$dir = ''./userfiles/kvart/'';\n\n\nif ($_SERVER[''REQUEST_URI''] == ''/uborka-domov-kottedzhej/'') $dir = ''./userfiles/kvart/kotedzh/'';\nelse if ($_SERVER[''REQUEST_URI''] == ''/uborka-ofisov/'') $dir = ''./userfiles/kvart/office/'';\nelse $dir = ''./userfiles/kvart/'';\n\n            $scan = scandir($dir);\n\n           for ($i=0; $i<count($scan); $i++) {\n\n             if ($scan[$i] != ''.'' && $scan[$i] != ''..'' && $scan[$i] != ''kotedzh'' && $scan[$i] != ''office'') {\n\n             echo ''\n\n<div class = "item" >\n<div class="ddo">До</div><div class="dpo">После</div>\n<img src="''. $dir . $scan[$i] . ''" alt="''. $scan[$i] . ''" style="height:300px;" />\n\n</div>'';\n\n             }\n\n            }', 0, 'a:0:{}', '', 1, 'uborka-snippet'),
(164, 0, 0, 'modxTalks', '[MODXTalks] Snippet.', 0, 58, 0, '/**\n * @package modxtalks\n */\nif (!isset($modx->modxtalks) || !$modx->modxtalks instanceof modxTalks) {\n    $modx->modxtalks = $modx->getService(''modxtalks'', ''modxTalks'', $modx->getOption(''modxtalks.core_path'', null, $modx->getOption(''core_path'') . ''components/modxtalks/'') . ''model/modxtalks/'', $scriptProperties);\n}\n\nreturn $modx->modxtalks->init();', 0, 'a:0:{}', '', 0, ''),
(165, 0, 0, 'modxTalksAjax', '[modxTalksAjax] Snippet.', 0, 58, 0, '/**\n * @package modxtalks\n */\nif (!isset($modx->modxtalks) || !($modx->modxtalks instanceof modxTalks)) {\n    $modx->modxtalks = $modx->getService(''modxtalks'',''modxTalks'',$modx->getOption(''modxtalks.core_path'',null,$modx->getOption(''core_path'').''components/modxtalks/'').''model/modxtalks/'',$scriptProperties);\n}\n\nif (isset($_SERVER[''HTTP_X_REQUESTED_WITH'']) && strtolower($_SERVER[''HTTP_X_REQUESTED_WITH'']) === ''xmlhttprequest'') {\n    header(''Content-Type: application/json; charset=UTF-8'');\n    if (!empty($_SERVER[''HTTP_ACTION''])) {\n        $action = $_SERVER[''HTTP_ACTION''];\n    }\n    else {\n        $action = $_POST[''action''];\n    }\n\n    switch($action) {\n        case ''preview'':\n            $action = ''web/comment/create'';\n            $_POST[''preview''] = 1;\n            break;\n        case        ''add'': $action = ''web/comment/create''; break;\n        case       ''like'': $action = ''web/comment/like''; break;\n        case      ''quote'': $action = ''web/comment/quote''; break;\n        case     ''delete'': $action = ''web/comment/remove''; break;\n        case    ''restore'': $action = ''web/comment/restore''; break;\n        case       ''edit'': $action = ''web/comment/update''; break;\n        case        ''get'': $action = ''web/comment/get''; break;\n        case       ''vote'': $action = ''web/comment/vote''; break;\n        case     ''unvote'': $action = ''web/comment/unvote''; break;\n        case ''votes_info'': $action = ''web/comment/votes_info''; break;\n        case  ''ban_email'': $action = ''web/comment/block_email''; break;\n        case     ''ban_ip'': $action = ''web/comment/block_ip''; break;\n        case       ''load'': $action = ''web/comments/load''; break;\n        case     ''latest'':\n            $_POST[''action''] = $action;\n            $action = ''web/comments/latest'';\n            break;\n        default: return; break;\n    }\n\n    /**\n     * Чистим контент комментаия от тегов MODX\n     */\n    $tags = array(''[['', '']]'',''<?'',''?>'');\n    $rTags = array(''[_['','']_]'',''&lt;?'',''?&gt;'');\n    foreach ($_POST as $key => &$value) {\n        if (!is_array($_POST[$key]))\n            $_POST[$key] = str_replace($tags, $rTags, $value);\n    }\n\n    $path = $modx->getOption(''modxtalks.core_path'',null,$modx->getOption(''core_path'').''components/modxtalks/'').''processors/'';\n\n    $modx->modxtalks->ajaxInit();\n    $config = array_merge($_POST,$modx->modxtalks->config);\n    $response = $modx->runProcessor($action,$config,array(''processors_path'' => $path));\n\n    if ($response->isError()) {\n        $output = json_encode($response->response[''message'']);\n    }\n    if (is_array($response->response)) {\n        $output = json_encode($response->response,true);\n    }\n    else {\n        $output = $response->response;\n    }\n    echo $output;die;\n}\n\n$comments = $modx->modxtalks->init();\n\nreturn $comments;', 0, NULL, '', 0, ''),
(166, 0, 0, 'modxTalksLatestComments', 'The conclusion of the latest comments on your site.', 0, 58, 0, '/**\n * @package modxtalks\n */\nif (!isset($modx->modxtalks) || !($modx->modxtalks instanceof modxTalks)) {\n    $modx->modxtalks = $modx->getService(''modxtalks'',''modxTalks'',$modx->getOption(''modxtalks.core_path'',null,$modx->getOption(''core_path'').''components/modxtalks/'').''model/modxtalks/'',$scriptProperties);\n}\n\n$comments = $modx->modxtalks->getLatestComments();\n\nreturn $comments;', 0, 'a:3:{s:16:"commentLatestTpl";a:7:{s:4:"name";s:16:"commentLatestTpl";s:4:"desc";s:36:"modxtalks.prop_commentLatestTpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:14:"comment_latest";s:7:"lexicon";s:20:"modxtalks:properties";s:4:"area";s:0:"";}s:20:"commentsLatestOutTpl";a:7:{s:4:"name";s:20:"commentsLatestOutTpl";s:4:"desc";s:40:"modxtalks.prop_commentsLatestOutTpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:19:"comments_latest_out";s:7:"lexicon";s:20:"modxtalks:properties";s:4:"area";s:0:"";}s:19:"commentsLatestLimit";a:7:{s:4:"name";s:19:"commentsLatestLimit";s:4:"desc";s:39:"modxtalks.prop_commentsLatestLimit_desc";s:4:"type";s:11:"numberfield";s:7:"options";s:0:"";s:5:"value";s:2:"20";s:7:"lexicon";s:20:"modxtalks:properties";s:4:"area";s:0:"";}}', '', 0, ''),
(167, 0, 0, 'MtCount', 'Snippet to run the page parser and display the number of comments on the resource.', 0, 58, 0, '$modx->mt_mtCount = true;\nreturn '''';', 0, NULL, '', 0, ''),
(168, 1, 0, 'ecMessages', '', 0, 59, 0, '/** @var array $scriptProperties */\n/** @var easyComm $easyComm */\nif (!$easyComm = $modx->getService(''easyComm'', ''easyComm'', $modx->getOption(''ec_core_path'', null, $modx->getOption(''core_path'') . ''components/easycomm/'') . ''model/easycomm/'', $scriptProperties)) {\n    return ''Could not load easyComm class!'';\n}\n\n/* @var pdoFetch $pdoFetch */\n$fqn = $modx->getOption(''pdoFetch.class'', null, ''pdotools.pdofetch'', true);\nif ($pdoClass = $modx->loadClass($fqn, '''', false, true)) {\n    $pdoFetch = new $pdoClass($modx, $scriptProperties);\n}\nelseif ($pdoClass = $modx->loadClass($fqn, MODX_CORE_PATH . ''components/pdotools/model/'', false, true)) {\n    $pdoFetch = new $pdoClass($modx, $scriptProperties);\n}\nelse {\n    $modx->log(modX::LOG_LEVEL_ERROR, ''Could not load pdoFetch from "MODX_CORE_PATH/components/pdotools/model/".'');\n    return false;\n}\n$pdoFetch->addTime(''pdoTools loaded'');\n$fastMode = !empty($fastMode);\n$outputSeparator = $modx->getOption(''outputSeparator'', $scriptProperties, "\\n");\n\n/* @var string $threads */\n$threads = $modx->getOption(''threads'', $scriptProperties, '''');\nif($threads == ''*'') {\n    $threads = array();\n}\nelse {\n    if(empty($threads)) {\n        $threads = $modx->getOption(''thread'', $scriptProperties, '''');\n        if(empty($threads)) {\n            $threads = ''resource-''.$modx->resource->get(''id'');\n        }\n    }\n    $threads = explode(",", $threads);\n    $threads = array_map(''trim'', $threads);\n}\n\n$class = ''ecMessage'';\n$threadClass = ''ecThread'';\n$resourceClass = ''modResource'';\n// Query conditions\n$select = array(\n    $class => $modx->getSelectColumns($class, $class),\n    $threadClass => $modx->getSelectColumns($threadClass, ''Thread'', ''thread_''),\n);\n$innerJoin = array($threadClass => array(''alias'' => ''Thread'', ''on'' => "`$class`.`thread` = `Thread`.`id`"));\n$leftJoin = array();\n\nif(!empty($resourceFields)) {\n    $resourceFields = array_merge(array(''id'', ''pagetitle''), explode(",", $resourceFields));\n    $resourceFields = array_map("trim", $resourceFields);\n\n    $select[$resourceClass] = $modx->getSelectColumns($resourceClass, ''Resource'', ''resource_'', $resourceFields);\n    $leftJoin[$resourceClass] = array(''alias'' => ''Resource'', ''on'' => "`Thread`.`resource` = `Resource`.`id`");\n}\n\n\n$where = array();\nif(count($threads) == 1) {\n    $where[''`Thread`.`name`''] = $threads[0];\n}\nif(count($threads) > 1) {\n    $where[''`Thread`.`name`:IN''] = $threads;\n}\n\n// Filter by message ids\n$messages = $modx->getOption(''messages'', $scriptProperties, '''');\nif(!empty($messages)) {\n    $messages = explode(",", $messages);\n    $messages = array_map("trim", $messages);\n    $messages = array_map("intval", $messages);\n    if(!empty($messages)) {\n        $where[$class.''.`id`:IN''] = $messages;\n    }\n}\n\nif(empty($showUnpublished)) {\n    $where[$class.''.published''] = 1;\n}\n\nif(empty($showDeleted)) {\n    $where[$class.''.deleted''] = 0;\n}\n\nif(!empty($subject)) {\n    $where[$class.''.subject''] = $subject;\n}\n\n// Add custom parameters\nforeach (array(''where'',''leftJoin'',''innerJoin'',''select'',''groupby'') as $v) {\n    if (!empty($scriptProperties[$v])) {\n        $tmp = $modx->fromJSON($scriptProperties[$v]);\n        if (is_array($tmp)) {\n            $$v = array_merge($$v, $tmp);\n        }\n    }\n    unset($scriptProperties[$v]);\n}\n$pdoFetch->addTime(''Conditions prepared'');\n\n// Default parameters\n$default = array(\n    ''class'' => $class,\n    //''loadModels'' => ''easyComm'',\n    ''disableConditions'' => true,\n    ''where'' => $modx->toJSON($where),\n    ''select'' => $modx->toJSON($select),\n    ''innerJoin'' => $modx->toJSON($innerJoin),\n    ''leftJoin'' => $modx->toJSON($leftJoin),\n    //''groupby'' => $class.''.id'',\n    ''return'' => ''data'',\n    ''nestedChunkPrefix'' => ''ec_''\n);\n\n\n// Merge all properties and run!\n$pdoFetch->addTime(''Query parameters ready'');\n$pdoFetch->setConfig(array_merge($default, $scriptProperties), false);\n\n\n$rows = $pdoFetch->run();\n\n/* @var $tmpChunk modChunk */\n$tmpChunk = $modx->newObject(''modChunk'', array(''name'' => "tmp-".uniqid()));\n$tmpChunk->setCacheable(false);\n$gravatarDefault = $tmpChunk->process(null, $modx->getOption(''ec_gravatar_default''));\n\n$gravatarSize = $modx->getOption(''ec_gravatar_size'', null, 50);\n\n$output = array();\n$idx = $pdoFetch->idx;\nforeach($rows as $row) {\n    $row[''idx''] = $idx++;\n    $row[''text_raw''] = $row[''text''];\n    $row[''text''] = nl2br($row[''text'']);\n    $row[''reply_text_raw''] = $row[''reply_text''];\n    $row[''reply_text''] = nl2br($row[''reply_text'']);\n\n    $row[''gravatar''] = $gravatarDefault;\n    if(!empty($row[''user_email''])) {\n        $row[''gravatar''] = ''https://www.gravatar.com/avatar/''.md5(strtolower($row[''user_email''])).''?s=50'';\n        if(!empty($gravatarDefault)) {\n            $row[''gravatar''] .= ''&d=''.urlencode($gravatarDefault);\n        }\n    }\n\n    $tpl = $pdoFetch->defineChunk($row);\n    if (empty($tpl)) {\n        $output[] = ''<pre>''.$pdoFetch->getChunk('''', $row).''</pre>'';\n    }\n    else {\n        $output[] = $pdoFetch->getChunk($tpl, $row, $fastMode);\n    }\n}\n$log = '''';\nif ($modx->user->hasSessionContext(''mgr'') && !empty($showLog)) {\n    $log .= ''<pre class="pdoResourcesLog">'' . print_r($pdoFetch->getTime(), 1) . ''</pre>'';\n}\n\n// Return output\nif (!empty($toSeparatePlaceholders)) {\n    $output[''log''] = $log;\n    $modx->setPlaceholders($output, $toSeparatePlaceholders);\n}\nelse {\n    if(empty($output) && !empty($tplEmpty)) {\n        $output = $pdoFetch->getChunk($tplEmpty);\n    }\n    else {\n        $output = implode($outputSeparator, $output);\n    }\n    $output .= $log;\n    if (!empty($tplWrapper) && (!empty($wrapIfEmpty) || !empty($output))) {\n        $data = array(''output'' => $output)