(172, 0, 0, 'GoogleSiteMap', 'New GoogleSiteMap Snippet—many times faster than Version 1, but with less options. If params are specified that depend on the old version, it will be called.', 0, 60, 0, '/**\n * GoogleSiteMap\n *\n * Builds the Google SiteMap XML. \n * Version 2+ of GoogleSiteMap uses code by Garry Nutting of the MODX Core Team to deliver sitemaps blazingly fast.\n *\n * @author YJ Tso <yj@modx.com>, Garry Nutting <garry@modx.com>\n *\n *\n * GoogleSiteMap is free software; you can redistribute it and/or modify it\n * under the terms of the GNU General Public License as published by the Free\n * Software Foundation; either version 2 of the License, or (at your option) any\n * later version.\n *\n * GoogleSiteMap is distributed in the hope that it will be useful, but WITHOUT ANY\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License along with\n * GoogleSiteMap; if not, write to the Free Software Foundation, Inc., 59 Temple\n * Place, Suite 330, Boston, MA 02111-1307 USA\n *\n * @package googlesitemap\n */\n\n// "300 lives of men I''ve walked this earth and now I have no time"\nini_set(''max_execution_time'', 0);\n\n// Set cache options\n// set $cacheKey prefix to be appended later\n$cacheKey = $modx->getoption(''cachePrefix'', $scriptProperties, ''googlesitemap'');\n// subfolder of core/cache/\n$cachePartition = $modx->getoption(''cachePartition'', $scriptProperties, ''googlesitemap'');\n$expires = $modx->getOption(''cacheExpires'', $scriptProperties, 86400);\n$options = array(\n  xPDO::OPT_CACHE_KEY => $cachePartition,\n);\n\n// Set context(s)\n$context = array_filter(array_map(''trim'', explode('','', $modx->getOption(''context'', $scriptProperties, $modx->context->get(''key''), true))));\n$cacheKey .= ''.'' . md5($modx->toJSON($scriptProperties));\n\n// Fetch from cache\n$output = null;\n$output = $modx->cacheManager->get($cacheKey, $options);\nif ($output !== null) return $output;\n\n/* Legacy Snippet handling */\n$legacyProps = $modx->getOption(''legacyProps'', $scriptProperties, ''allowedtemplates, excludeResources, excludeChildrenOf, sortByAlias, templateFilter, itemTpl, maxDepth, startId, where'');\n$legacyProps = array_flip(array_filter(array_map(''trim'', explode('','', $legacyProps))));\n$legacyProps = array_intersect_key($scriptProperties, $legacyProps);\n$legacySnippet = $modx->getOption(''legacySnippet'', $scriptProperties, ''GoogleSiteMapVersion1'');\n\nif (!empty($legacyProps) && $modx->getCount(''modSnippet'', array(''name'' => $legacySnippet))) {\n    \n    $output = $modx->runSnippet($legacySnippet, $scriptProperties);\n    if ($output !== null) {\n        $modx->cacheManager->set($cacheKey, $output, $expires, $options);\n        return $output;\n    }\n    \n}\n\n/* Begin new Snippet scope */\n$googleSchema = $modx->getOption(''googleSchema'',$scriptProperties,''http://www.sitemaps.org/schemas/sitemap/0.9'');\n\n/* Map specified filter properties to new variables for convenience */\n$filters = array();\nif ($modx->getOption(''hideDeleted'', $scriptProperties, true)) $filters[] =  ''s.deleted = 0'';\nif (!$modx->getOption(''showHidden'', $scriptProperties, false)) $filters[] = ''s.hidemenu = 0'';\nif ($modx->getOption(''published'', $scriptProperties, true)) $filters[] = ''s.published = 1'';\nif ($modx->getOption(''searchable'', $scriptProperties, true)) $filters[] = ''s.searchable = 1'';\n\n/* Defaults from legacy snippet */\n$sortBy = $modx->getOption(''sortBy'', $scriptProperties, ''menuindex'');\n$sortDir = $modx->getOption(''sortDir'', $scriptProperties, ''ASC'');\n$orderby = ''s.'' . strtolower($sortBy) . '' '' . strtoupper($sortDir);\n\n$containerTpl = $modx->getOption(''containerTpl'', $scriptProperties, ''gContainer'');\n$priorityTV = $modx->getOption(''priorityTV'', $scriptProperties, '''');\n\n/* Fetch TV ID if string provided */\nif (!is_numeric($priorityTV)) {\n    \n    $c = $modx->newQuery(''modTemplateVar'');\n    $c->select(''id'');\n    $c->where(array(''name'' => $priorityTV));\n    $priorityTV = $modx->getValue($c->prepare());\n    \n}\n\n/* Query by Context and set site_url / site_start */\n$items = '''';\n// Set today''s date for homepage lastmod\n$today = date(''Y-m-d'');\nforeach ($context as $ctx) {\n    \n    $siteUrl = '''';\n    // Fetch current context object for site_url\n    $currentCtx = $modx->getContext($ctx);\n    if ($currentCtx) {\n        $siteUrl = $currentCtx->getOption(''site_url'');\n        // Add site_url to output\n        $items .= "<url><loc>{$siteUrl}</loc><lastmod>{$today}</lastmod></url>" . PHP_EOL;\n    } \n    if (empty($siteUrl)) {\n        // We need something to build the links with, even if no context setting\n        $siteUrl = $modx->getOption(''site_url'', null, MODX_SITE_URL);\n    }\n    \n    $tablePrefix = $modx->getOption(''table_prefix'');\n    \n    $filters[] = "s.context_key = ''{$ctx}''";\n    $criteria = implode('' AND '', $filters);\n    $tvQuery = '''';\n    if ($priorityTV) $tvQuery = "IFNULL(\n        CONCAT(''<priority>'',(\n            SELECT value\n            FROM " . $tablePrefix . "site_tmplvar_contentvalues\n            USE INDEX (tv_cnt)\n            WHERE contentid = s.id AND tmplvarid = " . $priorityTV . "\n        ),''</priority>''),''''),";\n        \n    // Add all resources that meet criteria\n    $stmt = $modx->query("\n        SELECT\n    	    GROUP_CONCAT(\n                ''<url>'',        \n                CONCAT(''<loc>" . $siteUrl . "'',uri,''</loc>''),\n                CONCAT(''<lastmod>'',CASE editedon WHEN 0 THEN FROM_UNIXTIME(publishedon, ''%Y-%m-%d'') ELSE FROM_UNIXTIME(editedon, ''%Y-%m-%d'') END,''</lastmod>''),\n                " . $tvQuery . "\n                ''</url>''\n                SEPARATOR ''''\n            ) AS node\n        FROM " . $tablePrefix . "site_content AS s\n        WHERE " . $criteria . "\n        GROUP BY s.id\n        ORDER BY " . $orderby . "\n    ");\n\n    // Add to output\n    if ($stmt) {\n        $rows = $stmt->fetchAll(PDO::FETCH_COLUMN);\n        $items .= implode(PHP_EOL, $rows);\n    }\n    \n}\n\n/* get container tpl and content */\n$output = $modx->getChunk($containerTpl, array(\n    ''schema'' => $googleSchema,\n    ''items'' => $items,\n));\n\nif ($output !== null) {\n    $modx->cacheManager->set($cacheKey, $output, $expires, $options);\n    return $output;\n} else {\n    $modx->log(modX::LOG_LEVEL_WARN, ''GoogleSiteMap could not generate nor fetch a sitemap.'');\n}', 0, 'a:15:{s:11:"cachePrefix";a:7:{s:4:"name";s:11:"cachePrefix";s:4:"desc";s:25:"prop_gsm.cacheprefix_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:13:"googlesitemap";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:14:"cachePartition";a:7:{s:4:"name";s:14:"cachePartition";s:4:"desc";s:28:"prop_gsm.cachepartition_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:13:"googlesitemap";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:12:"cacheExpires";a:7:{s:4:"name";s:12:"cacheExpires";s:4:"desc";s:26:"prop_gsm.cacheexpires_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:5:"86400";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:7:"context";a:7:{s:4:"name";s:7:"context";s:4:"desc";s:21:"prop_gsm.context_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:11:"hideDeleted";a:7:{s:4:"name";s:11:"hideDeleted";s:4:"desc";s:25:"prop_gsm.hidedeleted_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:10:"showHidden";a:7:{s:4:"name";s:10:"showHidden";s:4:"desc";s:24:"prop_gsm.showhidden_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:12:"googleSchema";a:7:{s:4:"name";s:12:"googleSchema";s:4:"desc";s:26:"prop_gsm.googleschema_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:43:"http://www.sitemaps.org/schemas/sitemap/0.9";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:9:"published";a:7:{s:4:"name";s:9:"published";s:4:"desc";s:23:"prop_gsm.published_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:10:"searchable";a:7:{s:4:"name";s:10:"searchable";s:4:"desc";s:24:"prop_gsm.searchable_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:6:"sortBy";a:7:{s:4:"name";s:6:"sortBy";s:4:"desc";s:20:"prop_gsm.sortby_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:9:"menuindex";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:7:"sortDir";a:7:{s:4:"name";s:7:"sortDir";s:4:"desc";s:21:"prop_gsm.sortdir_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:3:"ASC";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:12:"containerTpl";a:7:{s:4:"name";s:12:"containerTpl";s:4:"desc";s:26:"prop_gsm.containertpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:10:"gContainer";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:10:"priorityTV";a:7:{s:4:"name";s:10:"priorityTV";s:4:"desc";s:24:"prop_gsm.prioritytv_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:11:"legacyProps";a:7:{s:4:"name";s:11:"legacyProps";s:4:"desc";s:25:"prop_gsm.legacyprops_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:117:"allowedtemplates, excludeResources, excludeChildrenOf, sortByAlias, templateFilter, itemTpl, maxDepth, startId, where";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:13:"legacySnippet";a:7:{s:4:"name";s:13:"legacySnippet";s:4:"desc";s:27:"prop_gsm.legacysnippet_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:21:"GoogleSiteMapVersion1";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}}', '', 0, ''),
(173, 0, 0, 'GoogleSiteMapVersion1', 'Old GoogleSiteMap Snippet—many times SLOWER than new version, but with more options. Beware potential server errors trying to execute this Snippet.', 0, 60, 0, '/**\n * GoogleSiteMap (Version 1x)\n *\n * Copyright 2009-2010 by Shaun McCormick <shaun@modx.com>\n *\n * - Based on Michal Till''s MODx Evolution GoogleSiteMap_XML snippet\n *\n * GoogleSiteMap is free software; you can redistribute it and/or modify it\n * under the terms of the GNU General Public License as published by the Free\n * Software Foundation; either version 2 of the License, or (at your option) any\n * later version.\n *\n * GoogleSiteMap is distributed in the hope that it will be useful, but WITHOUT ANY\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License along with\n * GoogleSiteMap; if not, write to the Free Software Foundation, Inc., 59 Temple\n * Place, Suite 330, Boston, MA 02111-1307 USA\n *\n * @package googlesitemap\n */\n/**\n * GoogleSiteMap for MODx Revolution\n *\n * @package googlesitemap\n */\nrequire_once $modx->getOption(''googlesitemap.core_path'',null,$modx->getOption(''core_path'').''components/googlesitemap/'').''model/googlesitemap/googlesitemap.class.php'';\n$GoogleSiteMap = new GoogleSiteMap($modx,$scriptProperties);\n\n/* setup default properties */\n$googleSchema = $modx->getOption(''googleSchema'',$scriptProperties,''http://www.sitemaps.org/schemas/sitemap/0.9'');\n$containerTpl = $modx->getOption(''containerTpl'',$scriptProperties,''gContainer'');\n$startId = (int)$modx->getOption(''startId'',$scriptProperties,0);\n\n/* get container tpl and content */\nreturn $GoogleSiteMap->getChunk($containerTpl,array(\n    ''schema'' => $googleSchema,\n    ''items'' => $GoogleSiteMap->run($startId),\n));', 0, 'a:19:{s:16:"allowedtemplates";a:7:{s:4:"name";s:16:"allowedtemplates";s:4:"desc";s:30:"prop_gsm.allowedtemplates_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:7:"context";a:7:{s:4:"name";s:7:"context";s:4:"desc";s:21:"prop_gsm.context_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:8:"maxDepth";a:7:{s:4:"name";s:8:"maxDepth";s:4:"desc";s:22:"prop_gsm.maxdepth_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";i:0;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:11:"hideDeleted";a:7:{s:4:"name";s:11:"hideDeleted";s:4:"desc";s:25:"prop_gsm.hidedeleted_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:10:"showHidden";a:7:{s:4:"name";s:10:"showHidden";s:4:"desc";s:24:"prop_gsm.showhidden_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:0;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:12:"googleSchema";a:7:{s:4:"name";s:12:"googleSchema";s:4:"desc";s:26:"prop_gsm.googleschema_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:43:"http://www.sitemaps.org/schemas/sitemap/0.9";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:9:"published";a:7:{s:4:"name";s:9:"published";s:4:"desc";s:23:"prop_gsm.published_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:10:"searchable";a:7:{s:4:"name";s:10:"searchable";s:4:"desc";s:24:"prop_gsm.searchable_desc";s:4:"type";s:13:"combo-boolean";s:7:"options";s:0:"";s:5:"value";b:1;s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:16:"excludeResources";a:7:{s:4:"name";s:16:"excludeResources";s:4:"desc";s:30:"prop_gsm.excluderesources_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:17:"excludeChildrenOf";a:7:{s:4:"name";s:17:"excludeChildrenOf";s:4:"desc";s:31:"prop_gsm.excludechildrenof_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:6:"sortBy";a:7:{s:4:"name";s:6:"sortBy";s:4:"desc";s:20:"prop_gsm.sortby_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:9:"menuindex";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:11:"sortByAlias";a:7:{s:4:"name";s:11:"sortByAlias";s:4:"desc";s:25:"prop_gsm.sortbyalias_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:11:"modResource";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:7:"sortDir";a:7:{s:4:"name";s:7:"sortDir";s:4:"desc";s:21:"prop_gsm.sortdir_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:3:"ASC";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:14:"templateFilter";a:7:{s:4:"name";s:14:"templateFilter";s:4:"desc";s:28:"prop_gsm.templatefilter_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:2:"id";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:7:"itemTpl";a:7:{s:4:"name";s:7:"itemTpl";s:4:"desc";s:21:"prop_gsm.itemtpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:5:"gItem";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:12:"containerTpl";a:7:{s:4:"name";s:12:"containerTpl";s:4:"desc";s:26:"prop_gsm.containertpl_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:10:"gContainer";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:7:"startId";a:7:{s:4:"name";s:7:"startId";s:4:"desc";s:21:"prop_gsm.startid_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:5:"where";a:7:{s:4:"name";s:5:"where";s:4:"desc";s:19:"prop_gsm.where_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}s:10:"priorityTV";a:7:{s:4:"name";s:10:"priorityTV";s:4:"desc";s:24:"prop_gsm.prioritytv_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:0:"";s:7:"lexicon";s:24:"googlesitemap:properties";s:4:"area";s:0:"";}}', '', 0, ''),
(174, 0, 0, 'UltimateParent', 'Return the "ultimate" parent of a resource.', 0, 0, 0, '/**\n * @name UltimateParent\n * @version 1.3\n * @author Susan Ottwell <sottwell@sottwell.com> March 2006\n * @author Al B <> May 18, 2007\n * @author S. Hamblett <shamblett@cwazy.co.uk>\n * @author Shaun McCormick <shaun@modx.com>\n * @author Jason Coward <modx@modx.com>\n *\n * @param &id The id of the document whose parent you want to find.\n * @param &top The top node for the search.\n * @param &topLevel The top level node for the search (root = level 1)\n *\n * @license Public Domain, use as you like.\n *\n * @example [[UltimateParent? &id=`45` &top=`6`]]\n * Will find the ultimate parent of document 45 if it is a child of document 6;\n * otherwise it will return 45.\n *\n * @example [[UltimateParent? &topLevel=`2`]]\n * Will find the ultimate parent of the current document at a depth of 2 levels\n * in the document hierarchy, with the root level being level 1.\n *\n * This snippet travels up the document tree from a specified document and\n * returns the "ultimate" parent.  Version 2.0 was rewritten to use the new\n * getParentIds function features available only in MODx 0.9.5 or later.\n *\n * Based on the original UltimateParent 1.x snippet by Susan Ottwell\n * <sottwell@sottwell.com>.  The topLevel parameter was introduced by staed and\n * adopted here.\n */\nif (!isset($modx)) return '''';\n\n$top = isset($top) && intval($top) ? $top : 0;\n$id= isset($id) && intval($id) ? intval($id) : $modx->resource->get(''id'');\n$topLevel= isset($topLevel) && intval($topLevel) ? intval($topLevel) : 0;\nif ($id && $id != $top) {\n    $pid = $id;\n    $pids = $modx->getParentIds($id);\n    if (!$topLevel || count($pids) >= $topLevel) {\n        while ($parentIds= $modx->getParentIds($id, 1)) {\n            $pid = array_pop($parentIds);\n            if ($pid == $top) {\n                break;\n            }\n            $id = $pid;\n            $parentIds = $modx->getParentIds($id);\n            if ($topLevel && count($parentIds) < $topLevel) {\n                break;\n            }\n        }\n    }\n}\nreturn $id;', 0, NULL, '', 0, ''),
(175, 1, 0, 'TicketForm', '', 0, 61, 0, '/** @var array $scriptProperties */\n/** @var Tickets $Tickets */\n$Tickets = $modx->getService(''tickets'', ''Tickets'', $modx->getOption(''tickets.core_path'', null,\n        $modx->getOption(''core_path'') . ''components/tickets/'') . ''model/tickets/'', $scriptProperties);\n$Tickets->initialize($modx->context->key, $scriptProperties);\n\nif (!$Tickets->authenticated) {\n    return $modx->lexicon(''ticket_err_no_auth'');\n}\n\n$tplSectionRow = $modx->getOption(''tplSectionRow'', $scriptProperties, ''tpl.Tickets.sections.row'');\n$tplFormCreate = $modx->getOption(''tplFormCreate'', $scriptProperties, ''tpl.Tickets.form.create'');\n$tplFormUpdate = $modx->getOption(''tplFormUpdate'', $scriptProperties, ''tpl.Tickets.form.update'');\n$tplFiles = $modx->getOption(''tplFiles'', $scriptProperties, ''tpl.Tickets.form.files'');\n$tplFile = $Tickets->config[''tplFile''] = $modx->getOption(''tplFile'', $scriptProperties, ''tpl.Tickets.form.file'', true);\n$tplImage = $Tickets->config[''tplImage''] = $modx->getOption(''tplImage'', $scriptProperties, ''tpl.Tickets.form.image'',\n    true);\nif (empty($source)) {\n    $source = $Tickets->config[''source''] = $modx->getOption(''tickets.source_default'', null,\n        $modx->getOption(''default_media_source''));\n}\n$tid = !empty($_REQUEST[''tid''])\n    ? (int)$_REQUEST[''tid'']\n    : 0;\n$parent = !empty($_REQUEST[''parent''])\n    ? $_REQUEST[''parent'']\n    : '''';\n$data = array();\n\n// Update of ticket\nif (!empty($tid)) {\n    $tplWrapper = $tplFormUpdate;\n    /** @var Ticket $ticket */\n    if ($ticket = $modx->getObject(''Ticket'', array(''class_key'' => ''Ticket'', ''id'' => $tid))) {\n        if ($ticket->get(''createdby'') != $modx->user->id && !$modx->hasPermission(''edit_document'')) {\n            return $modx->lexicon(''ticket_err_wrong_user'');\n        }\n        $charset = $modx->getOption(''modx_charset'');\n        $allowedFields = array_map(''trim'', explode('','', $scriptProperties[''allowedFields'']));\n        $allowedFields = array_unique(array_merge($allowedFields, array(''parent'', ''pagetitle'', ''content'')));\n\n        $fields = array_keys($modx->getFieldMeta(''Ticket''));\n        foreach ($allowedFields as $field) {\n            $value = in_array($field, $fields)\n                ? $ticket->get($field)\n                : $ticket->getTVValue($field);\n            if (is_string($value)) {\n                $value = html_entity_decode($value, ENT_QUOTES, $charset);\n                $value = str_replace(\n                    array(''[^'', ''^]'', ''['', '']'', ''{'', ''}''),\n                    array(''&#91;^'', ''^&#93;'', ''*(*(*(*(*(*'', ''*)*)*)*)*)*'', ''~(~(~(~(~(~'', ''~)~)~)~)~)~''),\n                    $value\n                );\n                $value = htmlentities($value, ENT_QUOTES, $charset);\n            }\n            $data[$field] = $value;\n        }\n        $data[''id''] = $ticket->id;\n        $data[''published''] = $ticket->published;\n        if (empty($parent)) {\n            $parent = $ticket->get(''parent'');\n        }\n    } else {\n        return $modx->lexicon(''ticket_err_id'', array(''id'' => $tid));\n    }\n} else {\n    $tplWrapper = $tplFormCreate;\n}\n\n// Get available sections for ticket create\n$data[''sections''] = '''';\n/** @var modProcessorResponse $response */\n$response = $Tickets->runProcessor(''web/section/getlist'', array(\n    ''parents'' => $scriptProperties[''parents''],\n    ''resources'' => $scriptProperties[''resources''],\n    ''sortby'' => !empty($scriptProperties[''sortby''])\n        ? $scriptProperties[''sortby'']\n        : ''pagetitle'',\n    ''sortdir'' => !empty($scriptProperties[''sortdir''])\n        ? $scriptProperties[''sortdir'']\n        : ''asc'',\n    ''depth'' => isset($scriptProperties[''depth''])\n        ? $scriptProperties[''depth'']\n        : 0,\n    ''context'' => !empty($scriptProperties[''context''])\n        ? $scriptProperties[''context'']\n        : $modx->context->key,\n    ''limit'' => 0,\n));\n$response = json_decode($response->getResponse(), true);\n\nif (!empty($response[''results''])) {\n    $Tickets->config[''sections''] = array();\n    foreach ($response[''results''] as $v) {\n        $v[''selected''] = $parent == $v[''id''] || $parent == $v[''alias'']\n            ? ''selected''\n            : '''';\n        $data[''sections''] .= $Tickets->getChunk($tplSectionRow, $v);\n        $Tickets->config[''sections''][] = $v[''id''];\n    }\n}\n\nif (!empty($allowFiles)) {\n    $q = $modx->newQuery(''TicketFile'');\n    $q->where(array(''class'' => ''Ticket''));\n    $q->andCondition(array(''parent'' => 0, ''createdby'' => $modx->user->id), null, 1);\n    if (!empty($tid)) {\n        $q->orCondition(array(''parent'' => $tid), null, 1);\n    }\n    $q->sortby(''createdon'', ''ASC'');\n    $collection = $modx->getIterator(''TicketFile'', $q);\n    $files = '''';\n    /** @var TicketFile $item */\n    foreach ($collection as $item) {\n        if ($item->get(''deleted'') && !$item->get(''parent'')) {\n            $item->remove();\n        } else {\n            $item = $item->toArray();\n            $item[''size''] = round($item[''size''] / 1024, 2);\n            $item[''new''] = empty($item[''parent'']);\n            $tpl = $item[''type''] == ''image''\n                ? $tplImage\n                : $tplFile;\n            $files .= $Tickets->getChunk($tpl, $item);\n        }\n    }\n    $data[''files''] = $Tickets->getChunk($tplFiles, array(\n        ''files'' => $files,\n    ));\n    /** @var modMediaSource $source */\n    if ($source = $modx->getObject(''sources.modMediaSource'', $source)) {\n        $properties = $source->getPropertyList();\n        $config = array(\n            ''size'' => !empty($properties[''maxUploadSize''])\n                ? $properties[''maxUploadSize'']\n                : 3145728,\n            ''height'' => !empty($properties[''maxUploadHeight''])\n                ? $properties[''maxUploadHeight'']\n                : 1080,\n            ''width'' => !empty($properties[''maxUploadWidth''])\n                ? $properties[''maxUploadWidth'']\n                : 1920,\n            ''extensions'' => !empty($properties[''allowedFileTypes''])\n                ? $properties[''allowedFileTypes'']\n                : ''jpg,jpeg,png,gif'',\n        );\n        $modx->regClientStartupScript(''<script type="text/javascript">TicketsConfig.source='' . json_encode($config) . '';</script>'',\n            true);\n    }\n    $modx->regClientScript($Tickets->config[''jsUrl''] . ''web/lib/plupload/plupload.full.min.js'');\n    $modx->regClientScript($Tickets->config[''jsUrl''] . ''web/files.js'');\n\n    $lang = $modx->getOption(''cultureKey'');\n    if ($lang != ''en'' && file_exists($Tickets->config[''jsPath''] . ''web/lib/plupload/i18n/'' . $lang . ''.js'')) {\n        $modx->regClientScript($Tickets->config[''jsUrl''] . ''web/lib/plupload/i18n/'' . $lang . ''.js'');\n    }\n}\n\n$output = $Tickets->getChunk($tplWrapper, $data);\n$key = md5(json_encode($Tickets->config));\n$_SESSION[''TicketForm''][$key] = $Tickets->config;\n$output = str_ireplace(''</form>'',\n    "\\n<input type=\\"hidden\\" name=\\"form_key\\" value=\\"{$key}\\" class=\\"disable-sisyphus\\" />\\n</form>", $output);\n\nreturn $output;', 0, 'a:20:{s:13:"tplFormCreate";a:7:{s:4:"name";s:13:"tplFormCreate";s:4:"desc";s:26:"tickets_prop_tplFormCreate";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:23:"tpl.Tickets.form.create";s:7:"lexicon";s:18:"tickets:properties";s:4:"area";s:0:"";}s:13:"tplFormUpdate";a:7:{s:4:"name";s:13:"tplFormUpdate";s:4:"desc";s:26:"tickets_prop_tplFormUpdate";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:23:"tpl.Tickets.form.update";s:7:"lexicon";s:18:"tickets:properties";s:4:"area";s:0:"";}s:10:"tplPreview";a:7:{s:4:"name";s:10:"tplPreview";s:4:"desc";s:23:"tickets_prop_tplPreview";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s